package com.anvil;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * The plugin's "Sign in with Discord" — the home-native device-code flow (site: /api/plugin/auth/*).
 * Start → open the home's /link-device page in the member's browser → poll until approved → hand the
 * account token to the caller to store. Asynchronous: every step runs on the scheduler (approval polls
 * paced by delayed rescheduling, never a sleeping thread) and BOTH callbacks arrive on that executor
 * thread — marshal to the EDT before touching Swing. {@code done} fires exactly once.
 *
 * <p><b>Security:</b> no local listener — completion is detected purely by polling the home. The
 * browser URL is pinned to the CONFIGURED home origin (the one host the member explicitly typed
 * into the plugin config) + the fixed {@code /link-device} path: same anti-phishing shape as the
 * federation broker pin, anchored to user intent instead of a hardcoded host, which is what lets
 * this work for hosted, self-hosted, and fully-standalone sites alike.</p>
 */
@Slf4j
public final class DeviceSignIn
{
	/** Fixed path of the approval page on the home site — the only page this flow will ever open. */
	static final String LINK_PATH = "/link-device";

	/** Fallback pacing/deadline when the server response omits them. */
	private static final int DEFAULT_INTERVAL_S = 5;
	private static final int DEFAULT_EXPIRES_S = 600;

	public enum Outcome
	{
		SIGNED_IN, DENIED, EXPIRED, UNAVAILABLE
	}

	/** Result: outcome + the account token when {@link Outcome#SIGNED_IN}. */
	public static final class Result
	{
		public final Outcome outcome;
		public final String token;

		Result(Outcome outcome, String token)
		{
			this.outcome = outcome;
			this.token = token;
		}
	}

	private final BingoApiClient apiClient;
	private final FederationSidebarDataSource.BrowserOpener browserOpener;
	private final FederationSidebarDataSource.PollScheduler scheduler;

	/** Production binding — real system browser + delayed steps on the shared client executor. */
	public DeviceSignIn(BingoApiClient apiClient, ScheduledExecutorService executor)
	{
		this(apiClient, DeviceSignIn::browse,
			(step, delayMs) -> executor.schedule(step, delayMs, TimeUnit.MILLISECONDS));
	}

	/** Test seam — injectable browser opener + scheduler so the flow runs offline and fast. */
	DeviceSignIn(BingoApiClient apiClient, FederationSidebarDataSource.BrowserOpener browserOpener,
		FederationSidebarDataSource.PollScheduler scheduler)
	{
		this.apiClient = apiClient;
		this.browserOpener = browserOpener;
		this.scheduler = scheduler;
	}

	/**
	 * Ask the desktop to open the sign-in page.
	 *
	 * <p>Returns whether we ASKED without throwing, which is all RuneLite lets us know:
	 * LinkBrowser.browse is void, so a browser that never appeared and one that opened fine are the
	 * same call from here. Everything downstream is written so that distinction doesn't matter — the
	 * address and the code go on screen either way.
	 */
	private static boolean browse(String url)
	{
		LinkBrowser.browse(url);
		return true;
	}

	/** Run the whole flow. {@code status} receives short human-readable progress lines for the UI;
	 * {@code done} the terminal {@link Result}. Both called on the executor thread. */
	public void run(Consumer<String> status, Consumer<Result> done)
	{
		// The first step runs on the executor too — authStart is network I/O, keep it off the EDT.
		schedule(() -> start(status, done), 0, status, done);
	}

	private void start(Consumer<String> status, Consumer<Result> done)
	{
		BingoApiClient.DeviceAuthStart start = apiClient.authStart();
		if (start == null || start.device_code == null || start.device_code.isEmpty())
		{
			status.accept("Couldn't reach the site — check the Site URL.");
			done.accept(new Result(Outcome.UNAVAILABLE, null));
			return;
		}

		String url = start.verification_url_complete != null && !start.verification_url_complete.isEmpty()
			? start.verification_url_complete : start.verification_url;
		if (!isConfiguredHomeUrl(apiClient.getApiUrl(), url))
		{
			// A response steering the browser anywhere but the member's own configured site is hostile.
			log.warn("refusing sign-in URL not on the configured home: {}", url);
			status.accept("Sign-in blocked — the site returned a suspicious login page.");
			done.accept(new Result(Outcome.UNAVAILABLE, null));
			return;
		}
		// The address is on screen whether or not the browser opened. We can't tell the difference
		// (see browse), and the failure mode of assuming success is a player staring at a code with
		// nowhere to type it — while the cost of saying both is one extra clause.
		if (!browserOpener.open(url))
		{
			status.accept("Couldn't open your browser — visit " + url + " and enter " + start.user_code + ".");
		}
		else
		{
			status.accept("Approve code " + start.user_code + " in your browser. If it didn't open: " + url);
		}

		long intervalMs = Math.max(1, start.interval > 0 ? start.interval : DEFAULT_INTERVAL_S) * 1000L;
		long deadline = System.currentTimeMillis()
			+ (start.expires_in > 0 ? start.expires_in : DEFAULT_EXPIRES_S) * 1000L;
		poll(status, done, start.device_code, intervalMs, deadline);
	}

	/** One scheduled approval poll; reschedules itself (server {@code slow_down} stretches the delay)
	 * until a terminal status or the deadline. */
	private void poll(Consumer<String> status, Consumer<Result> done, String deviceCode, long intervalMs, long deadline)
	{
		if (System.currentTimeMillis() >= deadline)
		{
			status.accept("The code expired — try again.");
			done.accept(new Result(Outcome.EXPIRED, null));
			return;
		}
		schedule(() ->
		{
			long nextIntervalMs = intervalMs;
			BingoApiClient.DeviceAuthPoll poll = apiClient.authPoll(deviceCode);
			if (poll != null && poll.status != null)
			{
				switch (poll.status)
				{
					case "complete":
						if (poll.token != null && !poll.token.isEmpty())
						{
							status.accept("Signed in.");
							done.accept(new Result(Outcome.SIGNED_IN, poll.token));
						}
						else
						{
							done.accept(new Result(Outcome.UNAVAILABLE, null));
						}
						return;
					case "denied":
						status.accept("Sign-in denied on the site.");
						done.accept(new Result(Outcome.DENIED, null));
						return;
					case "expired":
						status.accept("The code expired — try again.");
						done.accept(new Result(Outcome.EXPIRED, null));
						return;
					case "slow_down":
						nextIntervalMs = Math.max(intervalMs, Math.max(1, poll.interval) * 1000L);
						break;
					default: // pending (a null/blank poll is a transient blip — keep polling until the deadline)
						break;
				}
			}
			poll(status, done, deviceCode, nextIntervalMs, deadline);
		}, intervalMs, status, done);
	}

	/** Schedule a flow step; an escaped {@link RuntimeException} would otherwise vanish inside the
	 * executor, so surface it as the terminal failure. */
	private void schedule(Runnable step, long delayMs, Consumer<String> status, Consumer<Result> done)
	{
		scheduler.schedule(() ->
		{
			try
			{
				step.run();
			}
			catch (RuntimeException e)
			{
				log.debug("sign-in flow failed", e);
				status.accept("Sign-in failed — try again.");
				done.accept(new Result(Outcome.UNAVAILABLE, null));
			}
		}, delayMs);
	}

	/**
	 * True only for an HTTPS/HTTP URL on the EXACT configured home origin (scheme + host + port all
	 * matching the member-typed Site URL) with the fixed {@link #LINK_PATH} path. No credentials.
	 * HTTP is tolerated only when the configured home itself is HTTP (self-host dev setups).
	 */
	static boolean isConfiguredHomeUrl(String configuredApiUrl, String url)
	{
		if (configuredApiUrl == null || configuredApiUrl.isEmpty() || url == null || url.isEmpty())
		{
			return false;
		}
		final URI home;
		final URI target;
		try
		{
			home = new URI(configuredApiUrl);
			target = new URI(url);
		}
		catch (URISyntaxException e)
		{
			return false;
		}
		if (target.getScheme() == null || target.getHost() == null || target.getUserInfo() != null)
		{
			return false;
		}
		if (!target.getScheme().equalsIgnoreCase(home.getScheme()))
		{
			return false;
		}
		if (!target.getHost().equalsIgnoreCase(home.getHost()) || target.getPort() != home.getPort())
		{
			return false;
		}
		String path = target.getPath();
		return path != null && path.startsWith(LINK_PATH);
	}
}

package com.anvil;

/**
 * Binomial-probability helpers for multi-roll drop rarity.
 *
 * Adapted from Dink (pajlads/DinkPlugin), BSD-2-Clause — see THIRD_PARTY_NOTICES.md. Trimmed to the
 * methods the rarity service needs and rewritten to avoid the Guava dependency.
 */
final class MathUtils {
    static final double EPSILON = 0.00001;

    // Precomputed factorials 0..9 — max rolls in npc_drops.json is 9.
    private static final int[] FACTORIALS;

    static {
        int n = 10;
        int[] facts = new int[n];
        facts[0] = 1;
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }

    private MathUtils() {
    }

    static boolean lessThanOrEqual(double a, double b) {
        return a < b || Math.abs(a - b) <= EPSILON;
    }

    static double binomialProbability(double p, int nTrials, int kSuccess) {
        // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
        return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
    }

    private static int binomialCoefficient(int n, int k) {
        return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]);
    }
}

package com.anvil;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One collection-log page as the game drew it: the entry name, every item the account has obtained
 * on it, and the counters the log prints under the title ("Abyssal Sire kills: 1,204").
 *
 * <p>Deliberately RuneLite-free so the accumulator and its tests never need a client. Reading the
 * widgets is {@link ClogPageReader}'s job; deciding what to send is {@link ClogSync}'s.
 *
 * <p><b>Only obtained items are carried.</b> The site already ships the full 1,712-item catalogue
 * (src/data/clog.json), so the missing half is derivable — sending it would double every payload to
 * say "still nothing here".
 */
final class ClogPage
{
	/** Entry title as the log prints it — "Abyssal Sire". The site maps it to its own page id. */
	final String name;
	/** Obtained item ids, in the order the log lists them. Parallel to {@link #quantities}. */
	final int[] itemIds;
	final int[] quantities;
	/** The log's own "Obtained: 5/9" pair — the site shows progress without owning the catalogue. */
	final int obtained;
	final int total;
	/** The counter lines under the title, label → value. Empty for pages that print none. */
	final Map<String, Integer> counts;
	/** 64-bit content hash — what makes "has this page changed?" a comparison, not a diff. */
	final long hash;

	ClogPage(String name, int[] itemIds, int[] quantities, int obtained, int total, Map<String, Integer> counts)
	{
		this.name = name;
		this.itemIds = itemIds;
		this.quantities = quantities;
		this.obtained = obtained;
		this.total = total;
		this.counts = counts == null || counts.isEmpty()
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new LinkedHashMap<>(counts));
		this.hash = computeHash();
	}

	/**
	 * FNV-1a over the page's contents.
	 *
	 * <p>Hand-rolled rather than {@code Objects.hash} / a JSON round-trip because this runs on the
	 * client thread every time the log redraws — which is every keystroke while a player scrolls the
	 * log. No boxing, no allocation, no string building; a page is folded in a few hundred nanoseconds
	 * and the result is what stops us re-sending 125 identical pages.
	 */
	private long computeHash()
	{
		long h = 0xcbf29ce484222325L;
		h = fold(h, name == null ? 0 : name.hashCode());
		h = fold(h, obtained);
		h = fold(h, total);
		for (int i = 0; i < itemIds.length; i++)
		{
			h = fold(h, itemIds[i]);
			h = fold(h, quantities[i]);
		}
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			h = fold(h, e.getKey().hashCode());
			h = fold(h, e.getValue());
		}
		return h;
	}

	private static long fold(long h, int value)
	{
		h ^= value;
		return h * 0x100000001b3L;
	}
}

package com.anvil;

import java.awt.Color;

/**
 * Single source of truth for every fragile collection-log interface id the plugin pokes at.
 *
 * The in-game collection log is built by Jagex CS2 scripts; the script / widget / varbit ids
 * below shift whenever those scripts are reshuffled in a game update. Keeping them all here
 * (rather than sprinkled through {@link ClogTabController}) means a post-update fix is a
 * one-file edit. Verified against RuneLite api 1.12.24 — see plugin_clog_plan.md §6.
 *
 * Named RuneLite constants we rely on elsewhere (resolved at compile time, listed for the
 * next maintainer):
 *   net.runelite.api.ScriptID.COLLECTION_DRAW_LIST            = 2731
 *   net.runelite.api.widgets.InterfaceID.COLLECTION_LOG       = 621
 *   net.runelite.api.widgets.InterfaceID.ADVENTURE_LOG        = 187
 *   net.runelite.api.widgets.ComponentID.COLLECTION_LOG_{TABS,ENTRY_HEADER,ENTRY_ITEMS}
 */
final class ClogIds
{
	private ClogIds() {}

	// Varbits tracking the player's active native tab / page inside the clog. No named
	// RuneLite constant exists in 1.12.24, so they're read raw via client.getVarbitValue().
	static final int VARBIT_ACTIVE_TAB = 6905;
	static final int VARBIT_ACTIVE_PAGE = 6906;

	// Label shown on the injected category tab. Branded "Anvil" (not "Bingo") so it can be reused
	// for other Anvil content (schedule, weekly comps) when no bingo event is running.
	static final String BINGO_TAB_NAME = "Anvil";

	// ---- Live geometry, measured from the real clog via the debug dump (RuneLite 1.12.28) ----
	// Native tab row: COLLECTION_LOG_TABS is 500 wide, 20 tall, with 5 static tabs at width 97 /
	// step 100. We re-space all of them to width 80 / step 83 to fit a 6th "Bingo" tab.
	static final int TAB_HEIGHT = 20;
	static final int TAB_STEP = 83;
	static final int TAB_WIDTH = 80;
	static final int BINGO_TAB_INDEX = 5; // 6th slot (after the 5 natives)
	// Tab background is a 3-slice sprite (left cap / stretched middle / right cap). Measured
	// from the live clog: a SELECTED tab uses 2283/2284, an UNSELECTED tab uses 2285/2286.
	static final int TAB_CAP_SELECTED = 2283;
	static final int TAB_MID_SELECTED = 2284;
	static final int TAB_CAP_UNSELECTED = 2285;
	static final int TAB_MID_UNSELECTED = 2286;
	static final int TAB_CAP_W = 20;
	// Left column (where the native category list lives) — we hide that list while the Bingo
	// tab is active and drop our filter column here instead. Container path: ROOT.s[0].s[2].
	static final int LEFT_LIST_CHILD = 1;
	static final int LEFT_COL_W = 200;

	// Item grid inside COLLECTION_LOG_ENTRY_ITEMS: 36x32 cells, 42px x-step, 36px y-step, 6 cols.
	static final int ITEM_CELL_W = 36;
	static final int ITEM_CELL_H = 32;
	static final int ITEM_STEP_X = 42;
	static final int ITEM_STEP_Y = 36;
	static final int ITEM_COLS = 6;
	// Reserve a strip at the top of the items pane for the Leagues-style filter toggles.
	static final int FILTER_ROW_H = 18;

	// Leagues-style vertical task rows: [icon] [name / "Reward: N points"].
	static final int ROW_H = 36;
	static final int ROW_ICON = 32;
	static final int ROW_TEXT_X = 40;

	// A sprite to stand in for stat tiles (which have no inventory item icon): the
	// collection-log book icon. Confirmed present as SpriteID.HISCORE_COLLECTIONS_LOGGED.
	static final int STAT_TILE_SPRITE = 6390;

	// Entry colours mirroring the real clog palette (orange title, green obtained, red missing).
	static final Color TITLE_COLOR = new Color(255, 152, 31);
	static final Color COMPLETE_COLOR = new Color(0, 255, 128);
	static final Color IN_PROGRESS_COLOR = new Color(255, 215, 0);
	static final Color NOT_STARTED_COLOR = new Color(255, 60, 60);
}

package com.anvil;

/**
 * The collection log's rank title for a given number of unique slots obtained.
 *
 * The game shows this next to the log's completion count, and it's the one number that makes a clog
 * post mean something to a reader who doesn't know how many slots exist — "855/1712" is arithmetic,
 * "Black" is a standing.
 *
 * The thresholds live here, alone, so there is exactly one place to correct if Jagex moves them.
 * Deliberately returns null below the first threshold and for an unreadable count rather than
 * inventing a rank: a missing field in a clan post is unremarkable, a wrong one gets repeated.
 */
final class ClogRank
{
	/** Fixed slot requirements, ascending. Gilded is NOT here — see {@link #gildedThreshold}. */
	private static final int[] THRESHOLDS = {100, 300, 500, 700, 900, 1000, 1100, 1200};
	private static final String[] NAMES = {
		"Bronze", "Iron", "Steel", "Black", "Mithril", "Adamant", "Rune", "Dragon"
	};

	private static final String GILDED = "Gilded";

	/**
	 * Gilded is defined as a PROPORTION, not a number: 90% of the log's total slots, rounded down to
	 * the nearest 25. So it moves every time Jagex adds slots — hardcoding today's value would go
	 * quietly wrong on the next content update. At the current 1712 slots this is 1525.
	 */
	static int gildedThreshold(int totalSlots)
	{
		return totalSlots <= 0 ? Integer.MAX_VALUE : (int) (totalSlots * 0.9) / 25 * 25;
	}

	/**
	 * Rank title for {@code obtained} of {@code totalSlots} unique slots, or null when it earns none
	 * / the counts are bogus. {@code totalSlots} is only needed to place Gilded; pass the log's own
	 * maximum (the client reports it alongside the count).
	 */
	static String forSlots(int obtained, int totalSlots)
	{
		if (obtained <= 0)
		{
			return null;
		}
		if (obtained >= gildedThreshold(totalSlots))
		{
			return GILDED;
		}
		String rank = null;
		for (int i = 0; i < THRESHOLDS.length; i++)
		{
			if (obtained >= THRESHOLDS[i])
			{
				rank = NAMES[i];
			}
		}
		return rank;
	}

	private ClogRank()
	{
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The queue behind the clan's highlight feed: pets, uniques, big hauls and deaths, held until the
 * next push.
 *
 * <p>WHAT THIS DOES NOT DO is decide whether any of it matters. The client cannot know which
 * competition is running, what counts as a unique at this clan, or which pets belong to which skill
 * — all of that lives on the site (src/lib/moments.ts), so a clan can change its mind without
 * waiting on a plugin release. This sends what it saw, generously, and expects most of it to be
 * thrown away.
 *
 * <p>EVERY MOMENT IS RECORDED AT THE EVENT, never inside a notification gate. A member with the
 * drops channel switched off still gets their pet on the site's feed — the two settings are about
 * different things, and tying them together is exactly the bug that once captioned every saved clip
 * "Clip saved".
 *
 * <p>Each entry carries its own idempotency key, because the game says everything twice: one pet
 * fires up to three chat lines, one kill fires two loot events, and a retry after a timeout is a
 * third copy on purpose. The key is derived from what happened rather than from a counter, so all
 * of those collapse into one row server-side.
 *
 * <p>Bounded and lossy by design. If a session outruns the pushes, the OLDEST entries go: a feed
 * that drops the pet you just got to keep a 200k loot pile would be worse than useless. Touched
 * from the client thread (game events) and drained on the executor, so every method is synchronized.
 */
class AnvilMoments
{
	/**
	 * A session's backlog, not a history. The site takes 25 per push and the pushes are debounced to
	 * seconds, so this only fills at all when the site is unreachable.
	 */
	static final int MAX_QUEUED = 50;

	/** How many go in one request — matches the site's own cap. */
	static final int BATCH = 25;

	/** Below this a drop isn't worth reporting on price alone. The site's floors are stricter. */
	static final long MIN_REPORTABLE_GP = 100_000L;

	static final class Moment
	{
		/** 'pet' | 'drop' | 'death' | 'ca'. */
		final String kind;
		final Integer itemId;
		final String itemName;
		final int quantity;
		final Long valueGp;
		final String source;
		final String sourceKind;
		final Integer kc;
		/** 'ca' only: the task the completion line named, and the tier it claimed. */
		final String taskName;
		final String tier;
		final long at;
		final String key;

		Moment(String kind, Integer itemId, String itemName, int quantity, Long valueGp,
			   String source, String sourceKind, Integer kc, long at, String key)
		{
			this(kind, itemId, itemName, quantity, valueGp, source, sourceKind, kc, null, null, at, key);
		}

		Moment(String kind, Integer itemId, String itemName, int quantity, Long valueGp,
			   String source, String sourceKind, Integer kc, String taskName, String tier, long at, String key)
		{
			this.kind = kind;
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
			this.valueGp = valueGp;
			this.source = source;
			this.sourceKind = sourceKind;
			this.kc = kc;
			this.taskName = taskName;
			this.tier = tier;
			this.at = at;
			this.key = key;
		}

		/** A completed combat task. The site decides which boss it belongs to and whether it's news. */
		static Moment combatTask(String taskName, String tier, long at)
		{
			return new Moment("ca", null, null, 1, null, null, null, null, taskName, tier, at,
				keyFor("ca", taskName, null, at));
		}
	}

	/** Keyed so a duplicate observation replaces rather than repeats; insertion-ordered for the batch. */
	private final Map<String, Moment> pending = new LinkedHashMap<>();

	/**
	 * Queue one. A repeat of a key already waiting REPLACES it — the second sighting of the same pet
	 * is the one that knows its name.
	 */
	synchronized void record(Moment moment)
	{
		if (moment == null || moment.key == null || moment.key.isEmpty())
		{
			return;
		}
		pending.remove(moment.key);
		pending.put(moment.key, moment);
		while (pending.size() > MAX_QUEUED)
		{
			pending.remove(pending.keySet().iterator().next());
		}
	}

	/**
	 * Fill in the name of something already queued — a pet is announced by one chat line and named
	 * by the next, and the feed wants the name.
	 *
	 * @return true when there was something to name
	 */
	synchronized boolean nameQueued(String key, String itemName, Integer itemId)
	{
		Moment existing = pending.get(key);
		if (existing == null || itemName == null || itemName.isEmpty())
		{
			return false;
		}
		pending.put(key, new Moment(existing.kind, itemId != null ? itemId : existing.itemId, itemName,
			existing.quantity, existing.valueGp, existing.source, existing.sourceKind, existing.kc,
			existing.at, existing.key));
		return true;
	}

	synchronized boolean isEmpty()
	{
		return pending.isEmpty();
	}

	synchronized int size()
	{
		return pending.size();
	}

	/** The next batch to send. Stays queued until {@link #onSent} confirms it — a failed push retries. */
	synchronized List<Moment> nextBatch()
	{
		List<Moment> batch = new ArrayList<>();
		for (Moment m : pending.values())
		{
			batch.add(m);
			if (batch.size() >= BATCH)
			{
				break;
			}
		}
		return batch;
	}

	/** Drop what the site has taken. */
	synchronized void onSent(List<Moment> batch)
	{
		if (batch == null)
		{
			return;
		}
		for (Moment m : batch)
		{
			pending.remove(m.key);
		}
	}

	/** Forget everything — a different account logging in doesn't inherit this one's moments. */
	synchronized void reset()
	{
		pending.clear();
	}

	/**
	 * A key for one thing that happened.
	 *
	 * <p>Built from WHAT happened rather than from a counter, so the two loot events and three chat
	 * lines the game fires for a single occurrence all produce the same string. Time is bucketed to
	 * ten seconds so the copies — which arrive within a tick or two of each other — agree, while a
	 * second genuine drop of the same item minutes later does not.
	 */
	static String keyFor(String kind, String source, Integer itemId, long at)
	{
		long bucket = at / 10_000L;
		return kind + "|" + (source == null ? "" : source.toLowerCase()) + "|"
			+ (itemId == null ? "" : itemId) + "|" + bucket;
	}
}

package com.anvil;

/**
 * One entry in the always-on sidebar's live team feed — the plugin-side mirror of the Site's
 * {@code /api/plugin/activity} JSON (see {@code Anvil.Site/src/lib/pluginActivity.ts}). RuneLite-free
 * and immutable, in the value-object style of {@link ClogTaskModel.TaskRow} / {@link ConnectionView}.
 */
public final class ActivityEntry
{
	/** Kind of feed event. Mirrors the server's {@code "progress" | "complete" | "reveal"}. */
	public enum Kind
	{
		PROGRESS, COMPLETE, REVEAL;

		/** Map the lowercase wire value to a {@link Kind}; unknown/blank → {@link #PROGRESS} (Gson bypasses this). */
		public static Kind fromWire(String s)
		{
			String v = s == null ? "" : s.trim();
			if ("complete".equalsIgnoreCase(v))
			{
				return COMPLETE;
			}
			// Reveal-policy events (showdown / lucky draw / bounty): a hidden tile just went live.
			if ("reveal".equalsIgnoreCase(v))
			{
				return REVEAL;
			}
			return PROGRESS;
		}
	}

	/** Namespaced id ({@code s<submissionId>}/{@code c<completionId>}) — globally unique, the dedup key. */
	public final String id;

	/** ISO timestamp of the underlying event (submission created / tile completed). */
	public final String ts;

	/** Crediting RSN, or {@code null} for an unattributed (stat/manual) completion. */
	public final String player;

	public final int tileId;
	public final String tileLabel;
	public final Kind kind;

	/** Units credited by this event (drops/kills/gains); 0 for a completion. */
	public final int amount;

	/** True when the caller themselves credited this — the panel styles/labels its own actions ("You"). */
	public final boolean self;

	public ActivityEntry(String id, String ts, String player, int tileId, String tileLabel,
		Kind kind, int amount, boolean self)
	{
		this.id = id == null ? "" : id;
		this.ts = ts == null ? "" : ts;
		this.player = player;
		this.tileId = tileId;
		this.tileLabel = tileLabel == null ? "" : tileLabel;
		this.kind = kind == null ? Kind.PROGRESS : kind;
		this.amount = amount;
		this.self = self;
	}

	public boolean isCompletion()
	{
		return kind == Kind.COMPLETE;
	}

	/**
	 * A short, member-facing one-line feed summary. Kept here (not the renderer) so it's unit-testable:
	 * {@code "Kayle completed …"}/{@code "Team completed …"} for completions, {@code "You +3 · …"} for progress.
	 */
	public String summary()
	{
		if (kind == Kind.REVEAL)
		{
			return "New tile revealed: " + tileLabel;
		}
		String who = self ? "You" : (player == null || player.isEmpty() ? null : player);
		if (kind == Kind.COMPLETE)
		{
			return (who == null ? "Team" : who) + " completed " + tileLabel;
		}
		String amt = amount > 0 ? "+" + amount : "+1";
		if (who == null)
		{
			return tileLabel + " " + amt; // teammate partial with no attribution — lead with the tile
		}
		return who + " " + amt + " · " + tileLabel;
	}
}

package com.anvil;

import java.util.function.Consumer;

/**
 * The site-relay federation capability on top of {@link SidebarDataSource}: the last-observed
 * {@link FederationState} and a one-click {@link #connectFederation connect}. Implemented by
 * {@link FederationSidebarDataSource}; the panel discovers it via {@code instanceof}, else hides "Connect".
 */
public interface FederationStatusSource
{
	/** Outcome of a {@link #connectFederation} run — drives the panel's status line + a follow-up refresh. */
	enum ConnectOutcome
	{
		/** The home reported (or became) connected — clans will render on the next refresh. */
		CONNECTED,
		/** A self-host login was opened in the browser; still waiting on the member to finish it. */
		LOGIN_PENDING,
		/** Federation isn't reachable/enabled, or the connect call failed — nothing to show. */
		UNAVAILABLE
	}

	/** Most recent {@link FederationState} seen by {@code fetchConnections()} — never {@code null} ({@link FederationState#disabled()} sentinel pre-poll). */
	FederationState federationStatus();

	/** Kick the §10.2 connect handshake: {@code POST /connect}. Trusted home returns {@code connected} (zero-click);
	 * self-host returns {@code login} + a broker URL opened then polled via {@code /state}. Asynchronous — returns
	 * immediately; every step runs on a background executor, and BOTH callbacks arrive on that executor thread
	 * (never the EDT — marshal before touching Swing). {@code done} fires exactly once with the terminal outcome. */
	void connectFederation(Consumer<String> status, Consumer<ConnectOutcome> done);

	/** Federation logout: {@code POST /disconnect} clears the durable signed-in marker, so {@code /state} reverts
	 * to {@code signedIn:false} and the panel re-offers "Connect clans". Idempotent; {@code true} once acknowledged. */
	boolean disconnectFederation();
}

package com.anvil;

import net.runelite.api.gameval.VarbitID;

/**
 * The six Combat Achievement tiers, with the point value awarded for a task at that tier and the
 * varbit holding the cumulative points needed to unlock the tier's rewards. Used to detect both
 * individual task completions (chat message gives the tier name) and tier unlocks (a task pushing
 * total points across a threshold).
 */
public enum CombatAchievementTier
{
	EASY("Easy", 1, VarbitID.CA_THRESHOLD_EASY),
	MEDIUM("Medium", 2, VarbitID.CA_THRESHOLD_MEDIUM),
	HARD("Hard", 3, VarbitID.CA_THRESHOLD_HARD),
	ELITE("Elite", 4, VarbitID.CA_THRESHOLD_ELITE),
	MASTER("Master", 5, VarbitID.CA_THRESHOLD_MASTER),
	GRANDMASTER("Grandmaster", 6, VarbitID.CA_THRESHOLD_GRANDMASTER);

	private final String displayName;
	private final int points;
	private final int thresholdVarbitId;

	CombatAchievementTier(String displayName, int points, int thresholdVarbitId)
	{
		this.displayName = displayName;
		this.points = points;
		this.thresholdVarbitId = thresholdVarbitId;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getPoints()
	{
		return points;
	}

	public int getThresholdVarbitId()
	{
		return thresholdVarbitId;
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	/** Resolves the tier from the word used in the completion message ("easy", "elite", …). */
	public static CombatAchievementTier byName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (CombatAchievementTier t : values())
		{
			if (t.displayName.equalsIgnoreCase(name) || t.name().equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}
}

package com.anvil;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Collection-log "unlock" banner. 178x100 base panel (source PNG is 3x), three centred lines at
 * text-tops y=10/40/64, all 16px with a 1px black shadow and no font smoothing. Open animation:
 * a 1px line draws out horizontally, the background unsquishes to full height, holds, then reverses.
 */
public class BingoClogBannerOverlay extends Overlay
{
	// Design space (matches Skeldoor's .collection-log-panel). 1.0 = original asset size.
	private static final int BASE_W = 178;
	private static final int BASE_H = 100;
	private static final float DISPLAY_SCALE = 1f;

	// Text tops (design px) + size. Tuned for even vertical rhythm on the small panel: the header sits
	// just under the top of the frame (11), the "Tile complete!/Progress:" line clears the divider (36),
	// and the label sits close under it (52) so the middle→label gap matches the ~15px gap between the
	// two wrapped label lines — otherwise the body reads as two disconnected zones.
	private static final float TOP_Y = 11f;
	private static final float MID_Y = 36f;
	private static final float BOTTOM_Y = 52f;
	private static final float FONT_PX = 16f;
	// The bottom label wraps onto a second line at full size when it's too wide — the RS font is a
	// bitmap face that pixelates when scaled, so we never shrink glyphs. WRAP_LINE_H is the vertical
	// advance (design px) between the two lines, kept tight so both clear the 100px panel.
	private static final float WRAP_LINE_H = 15f;
	private static final int BOTTOM_MAX_LINES = 2;

	// Horizontal padding (design px) kept clear inside the panel; text wider than the inner width wraps
	// onto up to BOTTOM_MAX_LINES lines (bottom label) and is ellipsised only if it overflows the last.
	private static final int TEXT_MARGIN_X = 12;

	// Animation (matches the reference gif): a thin line grows to full WIDTH, then the whole
	// background unsquishes to full HEIGHT; close reverses it. Linear motion, no fade.
	private static final long H_EXPAND_MS = 800;    // line grows to full width
	private static final long V_EXPAND_MS = 800;    // unsquish to full height
	private static final long HOLD_MS = 2500;
	private static final long V_COLLAPSE_MS = 650;  // squish back down to the line
	private static final long H_COLLAPSE_MS = 650;  // line shrinks to nothing
	private static final float LINE_H = 1f;         // design-px height of the thin opening line

	private static final Color ORANGE = new Color(255, 152, 31);
	private static final Color WHITE = new Color(255, 255, 255);
	private static final Color SHADOW = new Color(0, 0, 0, 255);
	private static final Color LINE_COLOR = Color.BLACK; // the thin opening/closing line

	private static final class Banner
	{
		final String top;
		final String middle;
		final String bottom;

		Banner(String top, String middle, String bottom)
		{
			this.top = top;
			this.middle = middle;
			this.bottom = bottom;
		}
	}

	private final ConcurrentLinkedQueue<Banner> queue = new ConcurrentLinkedQueue<>();
	private final BufferedImage background;
	private final Font headerFont;
	private final Font bodyFont;
	private Banner active;
	private long startedAt;

	@Inject
	public BingoClogBannerOverlay(AnvilPlugin plugin)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_CENTER);
		setPriority(OverlayPriority.HIGHEST);
		this.background = loadBackground();
		this.headerFont = FontManager.getRunescapeBoldFont().deriveFont(FONT_PX * DISPLAY_SCALE);
		// Detail lines use the natively-smaller RS bitmap (the XP-counter/minimap face) at its own
		// crisp size — the standard chat font read too large on the small panel. No deriveFont: scaling
		// a bitmap font off its native grid pixelates (see the wrap-not-shrink note above).
		this.bodyFont = FontManager.getRunescapeSmallFont();
	}

	private static BufferedImage loadBackground()
	{
		try (InputStream in = BingoClogBannerOverlay.class.getResourceAsStream("/com/anvil/clog_banner.png"))
		{
			return in == null ? null : ImageIO.read(in);
		}
		catch (IOException e)
		{
			return null;
		}
	}

	/** Backwards-compatible entry point used by the existing drop call site. */
	public void show(String label, int current, int required)
	{
		boolean complete = current >= required;
		String middle = complete ? "Tile complete!" : "Progress:";
		String bottom = required > 1 ? label + " (" + current + "/" + required + ")" : label;
		show("Anvil Bingo", middle, bottom);
	}

	/** Full three-line control. */
	public void show(String top, String middle, String bottom)
	{
		queue.add(new Banner(top, middle, bottom));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (background == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		long hEnd = H_EXPAND_MS;
		long vEnd = hEnd + V_EXPAND_MS;
		long holdEnd = vEnd + HOLD_MS;
		long vCollapseEnd = holdEnd + V_COLLAPSE_MS;
		long total = vCollapseEnd + H_COLLAPSE_MS;

		if (active == null || now - startedAt >= total)
		{
			active = queue.poll();
			if (active == null)
			{
				return null;
			}
			startedAt = now;
			now = System.currentTimeMillis();
		}

		long e = now - startedAt;

		int fullW = Math.round(BASE_W * DISPLAY_SCALE);
		int fullH = Math.round(BASE_H * DISPLAY_SCALE);
		int lineH = Math.max(1, Math.round(LINE_H * DISPLAY_SCALE));

		// w/h = current panel size; line=true draws just the thin opening line (no bg/text yet).
		float w;
		float h;
		boolean line;
		if (e < hEnd)
		{
			// P1: thin line grows to full width.
			w = fullW * (e / (float) H_EXPAND_MS);
			h = lineH;
			line = true;
		}
		else if (e < vEnd)
		{
			// P2: whole background unsquishes from the line up to full height.
			float t = (e - hEnd) / (float) V_EXPAND_MS;
			w = fullW;
			h = lineH + (fullH - lineH) * t;
			line = false;
		}
		else if (e < holdEnd)
		{
			w = fullW;
			h = fullH;
			line = false;
		}
		else if (e < vCollapseEnd)
		{
			// P4: squish back down to the line.
			float t = (e - holdEnd) / (float) V_COLLAPSE_MS;
			w = fullW;
			h = fullH - (fullH - lineH) * t;
			line = false;
		}
		else
		{
			// P5: line shrinks horizontally to nothing.
			float t = (e - vCollapseEnd) / (float) H_COLLAPSE_MS;
			w = fullW * (1f - t);
			h = lineH;
			line = true;
		}

		int iw = Math.max(1, Math.round(w));
		int ih = Math.max(1, Math.round(h));
		int x = (fullW - iw) / 2; // centre the (partly-open) panel within the reserved area
		int y = (fullH - ih) / 2;

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

		if (line)
		{
			// Opening/closing line: a plain strip in the banner's interior tone (not the bg, no text).
			g2.setColor(LINE_COLOR);
			g2.fillRect(x, y, iw, ih);
		}
		else
		{
			// Squish the WHOLE background into the current height (full width); it unsquishes to full.
			g2.drawImage(background, x, y, iw, ih, null);

			// Text only while opening/holding (e < holdEnd). On close it's dropped immediately so the
			// panel collapses cleanly instead of a centre sliver of text lingering. Full-size, fixed
			// in place, clipped to the opened region so it's revealed centre-out as the bg unsquishes.
			if (e < holdEnd)
			{
				g2.clipRect(x, y, iw, ih);
				int maxTextW = fullW - 2 * TEXT_MARGIN_X;
				drawCentered(g2, active.top, headerFont, ORANGE, fullW, maxTextW, TOP_Y * DISPLAY_SCALE);
				drawCentered(g2, active.middle, bodyFont, ORANGE, fullW, maxTextW, MID_Y * DISPLAY_SCALE);
				drawWrapped(g2, active.bottom, bodyFont, WHITE, fullW, maxTextW, BOTTOM_Y * DISPLAY_SCALE);
			}
		}

		g2.dispose();

		return new Dimension(fullW, fullH);
	}

	/** Draws text centred horizontally, with {@code topY} being the CSS-style top of the line (line-height 1). */
	private static void drawCentered(Graphics2D g, String text, Font font, Color color, int width, int maxWidth, float topY)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		String shown = truncate(text, fm, maxWidth);
		int x = (width - fm.stringWidth(shown)) / 2;
		int baseline = Math.round(topY) + fm.getAscent();
		g.setColor(SHADOW);
		g.drawString(shown, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(shown, x, baseline);
	}

	/** Like {@link #drawCentered} but wraps a long label onto up to {@link #BOTTOM_MAX_LINES} lines at the
	 *  full font size (the RS bitmap font pixelates when scaled, so we wrap rather than shrink), ellipsising
	 *  only the final line if it still overflows. A single-line label renders identically to
	 *  {@code drawCentered}; extra lines advance downward by {@link #WRAP_LINE_H}. */
	private static void drawWrapped(Graphics2D g, String text, Font font, Color color, int width, int maxWidth, float topY)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		List<String> lines = wrap(text, fm, maxWidth, BOTTOM_MAX_LINES);
		int step = Math.round(WRAP_LINE_H * DISPLAY_SCALE);
		int top = Math.round(topY);
		for (int i = 0; i < lines.size(); i++)
		{
			String shown = lines.get(i);
			int x = (width - fm.stringWidth(shown)) / 2;
			int baseline = top + i * step + fm.getAscent();
			g.setColor(SHADOW);
			g.drawString(shown, x + 1, baseline + 1);
			g.setColor(color);
			g.drawString(shown, x, baseline);
		}
	}

	/** Greedy word-wrap into at most {@code maxLines} lines that each fit {@code maxWidth}; any overflow
	 *  past the last line is folded into it, and every kept line is ellipsised if it still overflows
	 *  (covers a lone over-long word too). */
	private static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines)
	{
		List<String> lines = new ArrayList<>();
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth)
		{
			lines.add(text);
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String trial = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(trial) <= maxWidth)
			{
				line.setLength(0);
				line.append(trial);
				continue;
			}
			if (line.length() > 0)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			line.append(word);
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		if (lines.size() > maxLines)
		{
			// Fold every line past the cap into the last kept line (it gets ellipsised below).
			StringBuilder tail = new StringBuilder(lines.get(maxLines - 1));
			for (int i = maxLines; i < lines.size(); i++)
			{
				tail.append(' ').append(lines.get(i));
			}
			lines = new ArrayList<>(lines.subList(0, maxLines - 1));
			lines.add(tail.toString());
		}
		for (int i = 0; i < lines.size(); i++)
		{
			if (fm.stringWidth(lines.get(i)) > maxWidth)
			{
				lines.set(i, truncate(lines.get(i), fm, maxWidth));
			}
		}
		return lines;
	}

	/** Trims {@code text} with a trailing ellipsis so it fits within {@code maxWidth} px. */
	private static String truncate(String text, FontMetrics fm, int maxWidth)
	{
		if (maxWidth <= 0 || fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final String ellipsis = "...";
		int ellipsisW = fm.stringWidth(ellipsis);
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end)) + ellipsisW > maxWidth)
		{
			end--;
		}
		return end <= 0 ? ellipsis : text.substring(0, end).trim() + ellipsis;
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Where an account sits in a boss's vestige rotation.
 *
 * <p>The DT2 bosses don't hand out their vestige at random: rolls of the unique table go
 * non-vestige, non-vestige, VESTIGE. So counting uniques since the last vestige tells a player
 * something they can act on — "that's roll 2, the next unique is the vestige" — which is worth far
 * more than another "you got a Virtus mask" line. The roll tables themselves (which items count,
 * which one is the vestige, how long the cycle is) come from the server, so a game change is an
 * edit there rather than a plugin release.
 *
 * <p>Honesty about what we can know: the cycle is account state on Jagex's side, and this plugin
 * only sees drops it was running for. A count is therefore ESTIMATED until a vestige is actually
 * observed — after that the cycle is anchored and the count is EXACT. The estimate is still worth
 * showing (it's right whenever the player has been running the plugin), it just says so.
 *
 * <p>RuneLite-free so it can be unit-tested; {@link AnvilPlugin} owns persistence.
 */
final class VestigeRolls
{
	/** One boss's cycle state. */
	static final class State
	{
		/** Rolls seen since the last vestige — 0 means "a vestige is 3 rolls away". */
		final int rolls;
		/** True once a vestige has been observed, which anchors the cycle. */
		final boolean exact;

		State(int rolls, boolean exact)
		{
			this.rolls = rolls;
			this.exact = exact;
		}
	}

	/** What a drop did to the cycle, and what to say about it. */
	static final class Result
	{
		final State state;
		/** True when this drop WAS the vestige. */
		final boolean vestige;
		/** True when the next unique from this boss is guaranteed to be the vestige. */
		final boolean vestigeNext;
		/** One line for chat and the drop post, or null when there's nothing worth saying. */
		final String line;

		Result(State state, boolean vestige, boolean vestigeNext, String line)
		{
			this.state = state;
			this.vestige = vestige;
			this.vestigeNext = vestigeNext;
			this.line = line;
		}
	}

	private final Map<String, State> byBoss = new HashMap<>();

	static String key(String boss)
	{
		return boss == null ? "" : boss.trim().toLowerCase(Locale.ROOT);
	}

	State get(String boss)
	{
		return byBoss.getOrDefault(key(boss), new State(0, false));
	}

	void put(String boss, State state)
	{
		byBoss.put(key(boss), state);
	}

	/**
	 * Fold one unique-table drop into the boss's cycle. Returns null when the item isn't part of
	 * this boss's roll table (nothing to count) or the table is unusable.
	 */
	Result record(PluginConfigResponse.RollTable table, int itemId)
	{
		if (table == null || table.rollItemIds == null || !table.rollItemIds.contains(itemId))
		{
			return null;
		}
		int cycle = Math.max(2, table.rollsPerVestige);
		State was = get(table.boss);
		Result r = advance(was, itemId == table.vestigeItemId, cycle, table.vestigeName);
		put(table.boss, r.state);
		return r;
	}

	/**
	 * The rule, in one place: a vestige resets the cycle and anchors it; anything else advances it.
	 * A non-vestige arriving where the vestige was due means our count was off (drops taken while
	 * the plugin wasn't watching) — start the cycle over from this drop and stop claiming exact.
	 */
	static Result advance(State was, boolean isVestige, int rollsPerVestige, String vestigeName)
	{
		String vestige = vestigeName == null || vestigeName.isEmpty() ? "vestige" : vestigeName;
		if (isVestige)
		{
			return new Result(new State(0, true), true, false,
				vestige + "! The cycle resets — the next one is " + rollsPerVestige + " rolls away.");
		}

		int next = was.rolls + 1;
		if (next >= rollsPerVestige)
		{
			// We thought the vestige was due and it wasn't: the count was wrong, not the game.
			return new Result(new State(1, false), false, false,
				"Roll 1 of " + rollsPerVestige + " (estimated — the count was off, re-anchoring)");
		}

		boolean vestigeNext = next == rollsPerVestige - 1;
		String line = "Roll " + next + " of " + rollsPerVestige
			+ (vestigeNext ? " — the next unique is the " + vestige + "!" : "")
			+ (was.exact ? "" : " (estimated)");
		return new Result(new State(next, was.exact), false, vestigeNext, line);
	}

	/** Serialised as "boss=rolls:exact;…" for the RuneLite config, so the cycle survives a restart. */
	String serialise()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, State> e : byBoss.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append('=').append(e.getValue().rolls).append(':').append(e.getValue().exact ? 1 : 0);
		}
		return sb.toString();
	}

	static VestigeRolls parse(String raw)
	{
		VestigeRolls out = new VestigeRolls();
		if (raw == null || raw.trim().isEmpty())
		{
			return out;
		}
		for (String part : raw.split(";"))
		{
			String[] kv = part.split("=", 2);
			if (kv.length != 2)
			{
				continue;
			}
			String[] v = kv[1].split(":", 2);
			try
			{
				int rolls = Integer.parseInt(v[0].trim());
				boolean exact = v.length > 1 && "1".equals(v[1].trim());
				out.byBoss.put(key(kv[0]), new State(Math.max(0, rolls), exact));
			}
			catch (NumberFormatException ignored)
			{
				// A corrupted entry just loses that boss's count — it re-estimates from the next drop.
			}
		}
		return out;
	}
}

package com.anvil;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * In-memory, bounded, deduplicated store behind the sidebar's live team feed. Consumes cursor-paginated
 * batches from {@code GET /api/plugin/activity}, keeping the most recent {@link #capacity} entries, newest-first.
 *
 * <p><b>Why bounded + dedup:</b> lives for the whole session — an unbounded append would leak memory, and a
 * re-ingested overlapping batch (the client resends its cursor until it advances) would double rows. The ring
 * caps at {@link #capacity}; the id set rejects repeats. Thread-safe: every method synchronizes on {@code this},
 * reads return an immutable snapshot.</p>
 */
public final class AnvilActivityLog
{
	/** Default ring size — enough scrollback to feel live without holding a session's worth of rows. */
	public static final int DEFAULT_CAPACITY = 50;

	/** The empty starting cursor the first poll sends (mirrors the server's {@code s0_c0}). */
	public static final String EMPTY_CURSOR = "s0_c0";

	private final int capacity;

	/** Newest-first. Head = most recent entry. */
	private final Deque<ActivityEntry> entries = new ArrayDeque<>();

	/** Mirrors {@link #entries} by id for O(1) dedup; kept in lock-step on add/evict. */
	private final Set<String> seenIds = new HashSet<>();

	private String cursor = EMPTY_CURSOR;

	public AnvilActivityLog()
	{
		this(DEFAULT_CAPACITY);
	}

	public AnvilActivityLog(int capacity)
	{
		this.capacity = Math.max(1, capacity);
	}

	/**
	 * Merge a server batch (ascending oldest→newest): new entries push to the head (newest on top), seen ids skipped, excess beyond {@link #capacity} evicted.
	 *
	 * @param newCursor the cursor for the next poll; {@code null}/blank leaves the cursor as-is
	 * @param batch     the entries returned by this poll (may be null/empty)
	 * @return how many entries were actually new — the panel can flash/notify on a positive count
	 */
	public synchronized int ingest(String newCursor, List<ActivityEntry> batch)
	{
		int added = 0;
		if (batch != null)
		{
			for (ActivityEntry e : batch)
			{
				if (e == null || e.id.isEmpty() || seenIds.contains(e.id))
				{
					continue;
				}
				entries.addFirst(e); // ascending input → head ends up newest
				seenIds.add(e.id);
				added++;
			}
		}
		if (newCursor != null && !newCursor.isEmpty())
		{
			cursor = newCursor;
		}
		trimToCapacity();
		return added;
	}

	/** Evict oldest (tail) entries until within capacity, keeping {@link #seenIds} in sync. */
	private void trimToCapacity()
	{
		while (entries.size() > capacity)
		{
			ActivityEntry evicted = entries.removeLast();
			if (evicted != null)
			{
				seenIds.remove(evicted.id);
			}
		}
	}

	/** Immutable snapshot, newest-first — safe to iterate on the EDT while the poller ingests. */
	public synchronized List<ActivityEntry> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(entries));
	}

	/**
	 * Collapse a newest-first feed: each run of PROGRESS on the same tile by the same worker folds into ONE
	 * summed entry (a grind reads "Kayle +14 · …" not fourteen "+1" rows), keeping the newest occurrence's
	 * metadata. Completions/lone events pass through; order preserved; "You" and a teammate stay separate lines.
	 */
	public static List<ActivityEntry> aggregateForDisplay(List<ActivityEntry> feed)
	{
		if (feed == null || feed.isEmpty())
		{
			return Collections.emptyList();
		}
		Map<String, Integer> groupIndex = new HashMap<>();
		List<ActivityEntry> order = new ArrayList<>();
		List<Integer> summed = new ArrayList<>(); // parallel to order; MIN_VALUE = pass-through (completion)
		for (ActivityEntry e : feed)
		{
			if (e.kind != ActivityEntry.Kind.PROGRESS)
			{
				order.add(e);
				summed.add(Integer.MIN_VALUE);
				continue;
			}
			String key = (e.self ? "�you" : (e.player == null ? "" : e.player)) + "�" + e.tileId;
			Integer at = groupIndex.get(key);
			if (at == null)
			{
				groupIndex.put(key, order.size());
				order.add(e); // newest occurrence keeps its metadata
				summed.add(e.amount);
			}
			else
			{
				summed.set(at, summed.get(at) + e.amount);
			}
		}
		List<ActivityEntry> out = new ArrayList<>(order.size());
		for (int i = 0; i < order.size(); i++)
		{
			ActivityEntry e = order.get(i);
			int total = summed.get(i);
			out.add(total == Integer.MIN_VALUE || total == e.amount
				? e
				: new ActivityEntry(e.id, e.ts, e.player, e.tileId, e.tileLabel, e.kind, total, e.self));
		}
		return Collections.unmodifiableList(out);
	}

	/** The cursor to send as {@code ?since=} on the next poll. */
	public synchronized String getCursor()
	{
		return cursor;
	}

	public synchronized int size()
	{
		return entries.size();
	}

	public synchronized boolean isEmpty()
	{
		return entries.isEmpty();
	}

	/** Drop everything and reset the cursor when the active event changes (its feed must not inherit the old one). */
	public synchronized void reset()
	{
		entries.clear();
		seenIds.clear();
		cursor = EMPTY_CURSOR;
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Quest points, combat-achievement points and tier, and achievement diaries — the account progress
 * the hiscores never publish (site: lib/memberProgress).
 *
 * <p>The plugin already SEES all of it: it parses every quest, diary and combat-task completion line
 * to credit tiles and post to Discord. It just spent each one and forgot it, so the site could never
 * answer "how many quest points does this member have" — a thing the game knows exactly.
 *
 * <p>Reads varbits, so it must run on the client thread. What it produces is a small map of key →
 * value; the caller diffs it against what it last sent and pushes only the difference, which is
 * usually nothing.
 */
final class AccountProgress
{
	/** Diary completion varbits, region by region, in tier order: easy, medium, hard, elite. */
	private static final int[][] DIARY_VARBITS = {
		{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
	};

	/**
	 * Karamja is the odd one out: only its ELITE tier has a completion varbit. Easy, medium and hard
	 * are tracked as task COUNTS whose totals we would have to hardcode — and would then be wrong
	 * about after any update that adds a task — so they are left out rather than guessed at. The site
	 * says as much next to the number.
	 */
	private static final int KARAMJA_ELITE = VarbitID.KARAMJA_DIARY_ELITE_COMPLETE;

	private static final String[] DIARY_KEYS = {"diaryEasy", "diaryMedium", "diaryHard", "diaryElite"};

	/**
	 * The key each region's tier mask is stored under, in the same order as {@link #DIARY_VARBITS},
	 * with Karamja last — it only contributes its elite bit. Matches DIARY_REGIONS on the site.
	 */
	private static final String[] DIARY_REGION_KEYS = {
		"diaryArdougne", "diaryDesert", "diaryFalador", "diaryFremennik", "diaryKandarin",
		"diaryKourend", "diaryLumbridge", "diaryMorytania", "diaryVarrock", "diaryWestern",
		"diaryWilderness",
	};

	private static final String KARAMJA_KEY = "diaryKaramja";

	private AccountProgress()
	{
	}

	/**
	 * Sample everything, right now. Client thread only.
	 *
	 * <p>Returns an empty map when the varbits read as an empty account — a few ticks after login the
	 * client has the values zeroed, and sending that would be a push claiming somebody lost their
	 * quest cape. The server max-merges as a second line of defence, but not sending nonsense is the
	 * first one.
	 */
	static Map<String, Integer> sample(Client client)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		if (client == null)
		{
			return out;
		}

		int questPoints = client.getVarpValue(VarPlayerID.QP);
		int caPoints = client.getVarbitValue(VarbitID.CA_POINTS);

		// Everything zero is what an unpopulated client looks like, not what an account looks like:
		// even a fresh account has quest points from the tutorial's first quest soon enough, and a
		// real one never has all of these at zero at once.
		int[] diaries = countDiaries(client);
		int diaryTotal = diaries[0] + diaries[1] + diaries[2] + diaries[3];
		if (questPoints <= 0 && caPoints <= 0 && diaryTotal <= 0)
		{
			return out;
		}

		out.put("questPoints", questPoints);
		out.put("questsCompleted", countQuests(client));
		out.put("caPoints", caPoints);
		out.put("caTier", highestTier(client, caPoints));
		// Every tier cleared rather than only the highest, so a profile can light them cumulatively.
		out.put("caTiers", tierMask(client, caPoints));
		for (int tier = 0; tier < DIARY_KEYS.length; tier++)
		{
			out.put(DIARY_KEYS[tier], diaries[tier]);
		}
		// Per region as well as per tier: the counts say how many, these say which.
		for (int region = 0; region < DIARY_VARBITS.length; region++)
		{
			out.put(DIARY_REGION_KEYS[region], regionMask(client, DIARY_VARBITS[region]));
		}
		out.put(KARAMJA_KEY, client.getVarbitValue(KARAMJA_ELITE) > 0 ? DIARY_ELITE_BIT : 0);
		return out;
	}

	/** Tier bits inside a region mask — the same numbering the site uses. */
	private static final int DIARY_EASY_BIT = 1;
	private static final int DIARY_MEDIUM_BIT = 2;
	private static final int DIARY_HARD_BIT = 4;
	private static final int DIARY_ELITE_BIT = 8;

	/** One region's four tiers, as a mask. */
	private static int regionMask(Client client, int[] region)
	{
		int mask = 0;
		int[] bits = {DIARY_EASY_BIT, DIARY_MEDIUM_BIT, DIARY_HARD_BIT, DIARY_ELITE_BIT};
		for (int tier = 0; tier < region.length; tier++)
		{
			if (client.getVarbitValue(region[tier]) > 0)
			{
				mask |= bits[tier];
			}
		}
		return mask;
	}

	/**
	 * Quests finished, out of everything this client build knows about.
	 *
	 * <p>An enum walk of ~200 quests, each a varp read — cheap enough for the half-minute tick that
	 * calls it, and the only way to the number: the game keeps no "quests completed" counter, only
	 * quest points, and those weight quests differently.
	 */
	private static int countQuests(Client client)
	{
		int done = 0;
		for (Quest quest : Quest.values())
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				done++;
			}
		}
		return done;
	}

	/**
	 * The raw combat-achievement varps, exactly as the game holds them.
	 *
	 * <p>Completion is bit-packed across these: task `i` is bit `i % 32` of the `i / 32`-th varp in
	 * the order the site sent. Which bit is which task is the site's business — it has the task
	 * catalogue — so this reads integers and understands none of them, and a game update that adds a
	 * varp costs a data change there rather than a release here.
	 *
	 * <p>Client thread.
	 */
	static java.util.Map<Integer, Integer> combatVarps(Client client, java.util.List<Integer> varps)
	{
		java.util.Map<Integer, Integer> out = new LinkedHashMap<>();
		if (client == null || varps == null)
		{
			return out;
		}
		for (Integer varpId : varps)
		{
			if (varpId == null || varpId <= 0)
			{
				continue;
			}
			out.put(varpId, client.getVarpValue(varpId));
		}
		return out;
	}

	/** One quest, as the site lists it: the game's own id and name, and which of the three states. */
	static final class Item
	{
		final int id;
		final String name;
		final int state;

		Item(int id, String name, int state)
		{
			this.id = id;
			this.name = name;
			this.state = state;
		}
	}

	/**
	 * EVERY quest with its state, not just the finished ones.
	 *
	 * <p>"Which of these haven't I done" is the question a quest list gets opened for, and a list of
	 * completions can't answer it. Names travel with the ids so the site never needs a quest dataset
	 * of its own — one released next month lists itself.
	 *
	 * <p>Client thread, like everything else here.
	 */
	static java.util.List<Item> quests(Client client)
	{
		java.util.List<Item> out = new java.util.ArrayList<>();
		if (client == null)
		{
			return out;
		}
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			int code = state == QuestState.FINISHED ? 2 : state == QuestState.IN_PROGRESS ? 1 : 0;
			out.add(new Item(quest.getId(), quest.getName(), code));
		}
		return out;
	}

	/** Bit per combat-achievement tier cleared: bit 0 Easy … bit 5 Grandmaster. */
	private static int tierMask(Client client, int caPoints)
	{
		int mask = 0;
		int index = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values())
		{
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && caPoints >= threshold)
			{
				mask |= 1 << index;
			}
			index++;
		}
		return mask;
	}

	/** Regions complete at each tier: easy, medium, hard, elite. */
	private static int[] countDiaries(Client client)
	{
		int[] counts = new int[4];
		for (int[] region : DIARY_VARBITS)
		{
			for (int tier = 0; tier < region.length; tier++)
			{
				if (client.getVarbitValue(region[tier]) > 0)
				{
					counts[tier]++;
				}
			}
		}
		if (client.getVarbitValue(KARAMJA_ELITE) > 0)
		{
			counts[3]++;
		}
		return counts;
	}

	/**
	 * The highest combat-achievement tier this account has cleared, 0 (none) through 6 (Grandmaster).
	 *
	 * <p>Read from POINTS against each tier's threshold varbit rather than from the tier-status
	 * varbits: the thresholds are what the game itself compares, they're the same numbers the
	 * completion post already uses, and a tier the player cleared but never claimed the reward for
	 * still counts as cleared.
	 */
	private static int highestTier(Client client, int caPoints)
	{
		int highest = 0;
		int tier = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values())
		{
			tier++;
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && caPoints >= threshold)
			{
				highest = tier;
			}
		}
		return highest;
	}
}

package com.anvil;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.File;
import java.io.IOException;
import java.time.Duration;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Uploads an on-demand OBS replay clip straight to a Discord webhook URL that the USER pastes into
 * the plugin config (Clips section). Nothing else posts to Discord from the plugin: deaths, kills,
 * rare drops and CAs all go through {@link BingoApiClient#postNotification} to our own server, which
 * forwards them. Clips are the one exception because a multi-MB video can't be proxied through the
 * site's request-body limit — and a user-supplied webhook URL is allowed by the plugin hub (unlike a
 * URL handed to us inside a server response).
 *
 * Kept deliberately separate from {@link BingoApiClient}: this talks to discord.com, carries no
 * site auth, and never persists — the upload is throwaway, unlike bingo drops.
 *
 * The upload uses OkHttp's async dispatcher so the round-trip runs off both the game thread and the
 * plugin's executor. Nothing here can stall the client.
 *
 * Rate limits: on a 429 we re-enqueue with the server's Retry-After plus randomized jitter, so
 * simultaneous clients don't retry in lockstep and re-collide (thundering herd).
 */
@Slf4j
@Singleton
public class DiscordWebhookClient
{
	// Discord hard-caps webhook message content at 2000 chars.
	private static final int MAX_CONTENT = 2000;
	// A throwaway notification isn't worth hammering Discord over — a couple of polite retries is plenty.
	private static final int MAX_RETRIES = 2;
	private static final long MAX_RETRY_MS = 10_000L;
	private static final long DEFAULT_RETRY_MS = 1_000L;
	private static final long MAX_JITTER_MS = 500L;

	// Clips are multi-MB video uploads; the shared RuneLite client's short write timeout aborts them
	// mid-upload on slower connections. Give file posts their own generous timeouts (pool/dispatcher
	// are still shared via newBuilder, so this is cheap).
	private final OkHttpClient uploadClient;

	/** RuneLite's shared client-lifetime scheduler — paces 429 retries; nothing to shut down here. */
	private final ScheduledExecutorService retryScheduler;

	@Inject
	public DiscordWebhookClient(OkHttpClient client, ScheduledExecutorService retryScheduler)
	{
		this.retryScheduler = retryScheduler;
		this.uploadClient = client.newBuilder()
			.callTimeout(Duration.ofSeconds(120))
			.writeTimeout(Duration.ofSeconds(120))
			.readTimeout(Duration.ofSeconds(60))
			.build();
	}

	/**
	 * Post a text message with a file attached (e.g. a video clip) via Discord multipart, streaming
	 * straight from disk on the long-timeout upload client. {@code onComplete} receives true only on a
	 * 2xx (after any retries) so the caller can report real success/failure instead of guessing.
	 * Discord infers preview from the filename extension; {@code contentType} is the part's media type.
	 */
	public void sendWithFile(String webhookUrl, String content, File file, String filename, String contentType, Consumer<Boolean> onComplete)
	{
		if (isBlank(webhookUrl) || file == null || !file.exists() || file.length() == 0)
		{
			if (onComplete != null)
			{
				onComplete.accept(false);
			}
			return;
		}
		MediaType type = MediaType.parse(contentType != null ? contentType : "application/octet-stream");
		JsonObject payload = buildPayload(content, null);
		MultipartBody multipart = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", payload.toString())
			.addFormDataPart("files[0]", filename, RequestBody.create(type, file))
			.build();
		enqueue(uploadClient, new Request.Builder().url(webhookUrl).post(multipart).build(), onComplete);
	}

	private JsonObject buildPayload(String content, JsonObject embed)
	{
		JsonObject payload = new JsonObject();
		if (!isBlank(content))
		{
			payload.addProperty("content", truncate(content));
		}
		if (embed != null)
		{
			JsonArray embeds = new JsonArray();
			embeds.add(embed);
			payload.add("embeds", embeds);
		}
		return payload;
	}

	private void enqueue(OkHttpClient client, Request request, Consumer<Boolean> onComplete)
	{
		enqueueWithRetry(client, request, 0, onComplete);
	}

	private void enqueueWithRetry(OkHttpClient client, Request request, int attempt, Consumer<Boolean> onComplete)
	{
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Anvil webhook post failed: {}", e.getMessage());
				complete(onComplete, false);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				// Drain + close so the connection can be reused.
				try (Response r = response)
				{
					if (r.code() == 429 && attempt < MAX_RETRIES)
					{
						long delayMs = retryDelayMs(r);
						log.debug("Anvil webhook rate-limited, retry {} in {}ms", attempt + 1, delayMs);
						retryScheduler.schedule(
							() -> enqueueWithRetry(client, request, attempt + 1, onComplete),
							delayMs, TimeUnit.MILLISECONDS);
						return;
					}
					if (!r.isSuccessful())
					{
						log.debug("Anvil webhook returned HTTP {}", r.code());
						complete(onComplete, false);
						return;
					}
					complete(onComplete, true);
				}
			}
		});
	}

	private static void complete(Consumer<Boolean> onComplete, boolean ok)
	{
		if (onComplete != null)
		{
			onComplete.accept(ok);
		}
	}

	/** Honor Discord's Retry-After (seconds, may be fractional), capped, plus jitter to de-sync clients. */
	private static long retryDelayMs(Response r)
	{
		long base = DEFAULT_RETRY_MS;
		String header = r.header("Retry-After");
		if (header != null && !header.isEmpty())
		{
			try
			{
				base = (long) Math.ceil(Double.parseDouble(header.trim()) * 1000.0);
			}
			catch (NumberFormatException ignored)
			{
				// Header wasn't a number — stick with the default.
			}
		}
		base = Math.max(0L, Math.min(base, MAX_RETRY_MS));
		return base + ThreadLocalRandom.current().nextLong(MAX_JITTER_MS + 1);
	}

	private static String truncate(String s)
	{
		return s.length() <= MAX_CONTENT ? s : s.substring(0, MAX_CONTENT);
	}

	private static boolean isBlank(String s)
	{
		return s == null || s.isEmpty();
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class BingoApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");

	private final Gson gson;
	private final OkHttpClient httpClient;
	// Clip relay uploads are multi-MB video. The normal client's 30s write timeout aborts those
	// mid-upload on a slow connection, so file posts get their own generous timeouts (the pool and
	// dispatcher are still shared via newBuilder, so an extra client is cheap).
	private final OkHttpClient uploadClient;
	private String apiUrl;
	private String playerToken;
	// In-game RSN of the locally logged-in account. Sent as `X-RSN` on every player-token
	// request so the server can scope the per-user plugin token to the correct clan_member
	// (and reject drops on accounts that aren't signed up for the active event).
	private volatile String currentRsn;
	// Stable Jagex account hash (client.getAccountHash()) of the locally logged-in account.
	// Sent as `X-Account-Hash` so the server can anchor auto-verification to the account even
	// across in-game renames. Null when logged out / unavailable.
	private volatile String accountHash;
	/** True while the logged-in world is a seasonal (Leagues) world. Set from the plugin on login/hop. */
	private volatile boolean seasonal;

	@Inject
	public BingoApiClient(Gson gson, OkHttpClient client)
	{
		this.gson = gson;
		// Read timeout is generous because some server reads do several round-trips to Turso
		// and can take a while; tighter timeouts here will trip even on healthy servers.
		this.httpClient = client.newBuilder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(90, TimeUnit.SECONDS)
			.writeTimeout(30, TimeUnit.SECONDS)
			.build();
		this.uploadClient = client.newBuilder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.callTimeout(120, TimeUnit.SECONDS)
			.writeTimeout(120, TimeUnit.SECONDS)
			.readTimeout(60, TimeUnit.SECONDS)
			.build();
	}

	public void configure(String apiUrl, String playerToken)
	{
		this.apiUrl = normalizeBaseUrl(apiUrl);
		this.playerToken = playerToken;
	}

	/** The configured site base URL (normalized, no trailing slash), or "" when unconfigured. */
	public String getApiUrl()
	{
		return apiUrl == null ? "" : apiUrl;
	}

	/**
	 * Sets the in-game RSN of the locally logged-in account. The plugin should call this
	 * on every login (and clear it on logout). Null/empty values are tolerated — the
	 * server will fall back to "any active event" matching, but cross-account safety
	 * degrades.
	 */
	public void setCurrentRsn(String rsn)
	{
		this.currentRsn = (rsn == null || rsn.isEmpty()) ? null : rsn;
	}

	/** The RSN currently stamped on requests (the logged-in character), or null. Thread-safe read. */
	public String getCurrentRsn()
	{
		return currentRsn;
	}

	/**
	 * Sets the stable Jagex account hash of the locally logged-in account. Call alongside
	 * {@link #setCurrentRsn} on login (and clear on logout). Pass the raw value from
	 * {@code client.getAccountHash()}; values that mean "not logged in" (null or -1) are
	 * treated as cleared.
	 */
	public void setAccountHash(long hash)
	{
		this.accountHash = hash == -1L ? null : Long.toString(hash);
	}

	/** Called when the world changes: seasonal posts route to the clan's Leagues channel server-side. */
	public void setSeasonal(boolean seasonal)
	{
		this.seasonal = seasonal;
	}

	/** True when a Site URL is set but no Account Token yet — the state the Sign-in button serves. */
	public boolean needsSignIn()
	{
		return apiUrl != null && !apiUrl.isEmpty() && (playerToken == null || playerToken.isEmpty());
	}

	// ---- Device-code sign-in (home-native RFC 8628; see the site's /api/plugin/auth/*) ----------

	/** POST /api/plugin/auth/start response. */
	public static class DeviceAuthStart
	{
		public String device_code;
		public String user_code;
		public String verification_url;
		public String verification_url_complete;
		public int interval;
		public int expires_in;
	}

	/** POST /api/plugin/auth/poll response — status: pending | slow_down | expired | denied | complete. */
	public static class DeviceAuthPoll
	{
		public String status;
		public String token;
		public int interval;
	}

	/** Begin the device sign-in. Deliberately UNAUTHENTICATED (the whole point is no token yet) —
	 * only the Site URL must be configured. Null on transport/HTTP failure. */
	public DeviceAuthStart authStart()
	{
		if (apiUrl == null || apiUrl.isEmpty())
		{
			return null;
		}
		RequestBody empty = RequestBody.create(null, new byte[0]);
		Request request = new Request.Builder().url(apiUrl + "/api/plugin/auth/start")
			.header("X-Anvil-Plugin-Version", PLUGIN_VERSION).post(empty).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return null;
			}
			return gson.fromJson(response.body().charStream(), DeviceAuthStart.class);
		}
		catch (IOException | com.google.gson.JsonParseException e)
		{
			log.debug("auth/start failed: {}", e.getMessage());
			return null;
		}
	}

	/** Poll the device sign-in. Null on transport failure (caller treats as a pending tick). */
	public DeviceAuthPoll authPoll(String deviceCode)
	{
		if (apiUrl == null || apiUrl.isEmpty() || deviceCode == null || deviceCode.isEmpty())
		{
			return null;
		}
		RequestBody body = RequestBody.create(MediaType.parse("application/json"),
			gson.toJson(java.util.Collections.singletonMap("device_code", deviceCode)));
		Request request = new Request.Builder().url(apiUrl + "/api/plugin/auth/poll")
			.header("X-Anvil-Plugin-Version", PLUGIN_VERSION).post(body).build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return null;
			}
			return gson.fromJson(response.body().charStream(), DeviceAuthPoll.class);
		}
		catch (IOException | com.google.gson.JsonParseException e)
		{
			log.debug("auth/poll failed: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * Outcome of a share toggle. The server REFUSES a share for reasons the member can act on — the
	 * account isn't verified on the site yet, they're not logged into it, the clan isn't connected —
	 * so the message has to survive back to the UI. Returning a bare boolean here silently turned
	 * every refusal into what looked like success.
	 */
	public static class ShareResult
	{
		public final boolean ok;
		/** Server-supplied reason, or a generic line. Null when {@link #ok}. */
		public final String error;

		public ShareResult(boolean ok, String error)
		{
			this.ok = ok;
			this.error = error;
		}
	}

	/** Share (or stop sharing) the CURRENT account's RSN with one connected clan. Authed + carries the
	 * X-RSN/X-Account-Hash headers, so the server scopes the share to the exact playing account. */
	public ShareResult federationShare(String instanceId, boolean share)
	{
		if (!isConfigured() || instanceId == null || instanceId.isEmpty())
		{
			return new ShareResult(false, "Not connected to a site.");
		}
		java.util.Map<String, String> payload = new java.util.HashMap<>();
		payload.put("instanceId", instanceId);
		payload.put("action", share ? "share" : "unshare");
		Request request = authedRequest(apiUrl + "/api/plugin/federation/share")
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				return new ShareResult(true, null);
			}
			// Every refusal ships { error } — surface it verbatim; it's written for the member.
			String message = null;
			try
			{
				if (response.body() != null)
				{
					com.google.gson.JsonObject o = gson.fromJson(response.body().charStream(), com.google.gson.JsonObject.class);
					if (o != null && o.has("error") && o.get("error").isJsonPrimitive())
					{
						message = o.get("error").getAsString();
					}
				}
			}
			catch (com.google.gson.JsonParseException ignored)
			{
				// Non-JSON error body (proxy/HTML) — fall through to the generic line.
			}
			log.debug("federation/share refused ({}): {}", response.code(), message);
			return new ShareResult(false, message != null && !message.isEmpty()
				? message
				: "The site refused the change (" + response.code() + ").");
		}
		catch (IOException e)
		{
			log.debug("federation/share failed: {}", e.getMessage());
			return new ShareResult(false, "Couldn't reach the site — check your connection.");
		}
	}

	/**
	 * Plugin semver, read from the same resource build.gradle uses as its version source
	 * (src/main/resources/com/anvil/version.txt). Sent on every site call as
	 * X-Anvil-Plugin-Version so sites can see which plugin versions their members run.
	 */
	static final String PLUGIN_VERSION = loadPluginVersion();

	private static String loadPluginVersion()
	{
		try (InputStream in = BingoApiClient.class.getResourceAsStream("version.txt"))
		{
			if (in == null)
			{
				return "unknown";
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
		catch (IOException e)
		{
			return "unknown";
		}
	}

	private Request.Builder authedRequest(String url)
	{
		Request.Builder b = new Request.Builder().url(url)
			.header("Authorization", "Bearer " + playerToken)
			.header("X-Anvil-Plugin-Version", PLUGIN_VERSION);
		String rsn = currentRsn;
		if (rsn != null && !rsn.isEmpty()) b.header("X-RSN", rsn);
		String hash = accountHash;
		if (hash != null && !hash.isEmpty()) b.header("X-Account-Hash", hash);
		return b;
	}

	/**
	 * Trim whitespace and strip any trailing slashes so callers can safely append
	 * "/api/..." without producing "//" or other malformed URLs. Returns "" for
	 * null/blank input so isConfigured() can detect it.
	 */
	static String normalizeBaseUrl(String raw)
	{
		if (raw == null) return "";
		String s = raw.trim();
		while (s.endsWith("/")) s = s.substring(0, s.length() - 1);
		if (s.isEmpty()) return "";
		// If the user left the scheme off (e.g. "your-clan.vercel.app"), assume https:// — that's the
		// common case and, without it, the checks below would treat the whole URL as unconfigured. We
		// only PREPEND when there's no scheme at all; an explicit http:// is left untouched (we never
		// silently "upgrade" a deliberate http:// host), so the HTTPS gate below still governs it.
		String lower = s.toLowerCase();
		if (!lower.startsWith("http://") && !lower.startsWith("https://"))
		{
			s = "https://" + s;
			lower = s.toLowerCase();
		}
		// Require HTTPS: the account token rides as an Authorization: Bearer header on every request,
		// so a plaintext http:// host would leak it on the wire. Permit http only for local dev hosts.
		// Anything else is treated as unconfigured (returns "") rather than sending the token in clear.
		boolean https = lower.startsWith("https://");
		boolean localHttp = lower.startsWith("http://localhost") || lower.startsWith("http://127.0.0.1");
		if (!https && !localHttp)
		{
			return "";
		}
		return s;
	}

	public boolean isConfigured()
	{
		return apiUrl != null && !apiUrl.isEmpty()
			&& playerToken != null && !playerToken.isEmpty();
	}

	/**
	 * Fire-and-forget: POST a clan notification to our own site, which forwards it to the Discord
	 * channel configured server-side. {@code channel} is one of "deaths", "pvpKills", "rareDrops",
	 * "combatAchievements". Either {@code content} or {@code embed} may be null; {@code png} may be
	 * null (text/embed-only). The plugin never holds or calls the Discord webhook URL itself — the
	 * server owns it — which keeps every plugin request pointed at the one configured base URL
	 * (RuneLite plugin-hub rule). Never blocks the caller: uses OkHttp's async dispatcher.
	 */
	public void postNotification(String channel, String content, JsonObject embed, byte[] png, String filename)
	{
		if (!isConfigured() || channel == null || channel.isEmpty())
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.addProperty("channel", channel);
		// The player is on a Leagues world. The plugin reports only that fact — whether the clan has a
		// separate Leagues channel, and what a seasonal post looks like, is the server's decision, so
		// either can change without waiting for a plugin release. Carried as ambient state like the RSN
		// and account hash, so every notification path gets it without threading a flag through each.
		if (seasonal)
		{
			payload.addProperty("seasonal", true);
		}
		if (content != null && !content.isEmpty())
		{
			payload.addProperty("content", content);
		}
		if (embed != null)
		{
			payload.add("embed", embed);
		}

		RequestBody body;
		if (png != null && png.length > 0)
		{
			body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", payload.toString())
				.addFormDataPart("file", filename != null && !filename.isEmpty() ? filename : "image.png",
					RequestBody.create(PNG, png))
				.build();
		}
		else
		{
			body = RequestBody.create(JSON, payload.toString());
		}

		Request request = authedRequest(apiUrl + "/api/plugin/notify").post(body).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("notify post failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.debug("notify returned HTTP {}", r.code());
					}
				}
			}
		});
	}

	/** Outcome of a clip relay attempt, so the caller can tell the player something true. */
	public enum ClipRelayResult
	{
		/** Posted to the clan's clips channel. */
		POSTED,
		/** This site is too old for the relay, or isn't configured — fall back to a user webhook. */
		UNSUPPORTED,
		/** The clan has no clips channel set up (server said 501). */
		NO_CHANNEL,
		/** Too big for the server to post anywhere (413). */
		TOO_LARGE,
		/** Rate-limited, Discord refused, or the upload failed. */
		FAILED
	}

	/**
	 * POST /api/plugin/clip — upload a saved clip and let the SERVER post it to the clan's clips
	 * channel. This is the one file upload that goes through the site rather than straight to
	 * Discord: it means members don't each have to paste a webhook URL into their plugin config,
	 * and it still never involves a URL a server response handed us — this is the same configured
	 * base URL every other request uses.
	 *
	 * Streams the file from disk on the long-timeout upload client. Blocking, so callers run it off
	 * the client thread; {@code moment} is the plugin's own summary of what the clip caught.
	 */
	public ClipRelayResult postClip(File file, String moment, String eventName, int seconds, String contentType)
	{
		return postClip(file, moment, eventName, seconds, contentType, 0, 0);
	}

	/**
	 * As above, plus the clipper's current standing — which the plugin already holds for its own
	 * sidebar, so sending it costs nothing and saves the server re-deriving the board on an upload.
	 */
	public ClipRelayResult postClip(File file, String moment, String eventName, int seconds, String contentType,
		int rank, long points)
	{
		if (!isConfigured() || file == null || !file.exists() || file.length() == 0)
		{
			return ClipRelayResult.UNSUPPORTED;
		}
		JsonObject payload = new JsonObject();
		if (moment != null && !moment.isEmpty())
		{
			payload.addProperty("moment", moment);
		}
		if (eventName != null && !eventName.isEmpty())
		{
			payload.addProperty("eventName", eventName);
		}
		if (seconds > 0)
		{
			payload.addProperty("seconds", seconds);
		}
		if (rank > 0)
		{
			payload.addProperty("rank", rank);
			payload.addProperty("points", points);
		}
		MediaType type = MediaType.parse(contentType != null ? contentType : "application/octet-stream");
		MultipartBody multipart = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", payload.toString())
			.addFormDataPart("file", file.getName(), RequestBody.create(type, file))
			.build();
		Request request = authedRequest(apiUrl + "/api/plugin/clip").post(multipart).build();
		try (Response response = uploadClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				return ClipRelayResult.POSTED;
			}
			switch (response.code())
			{
				// 404 = a site that predates the route. Capability gating should have caught it, but
				// a stale config poll can race a downgrade, so treat it as "not available here".
				case 404:
					return ClipRelayResult.UNSUPPORTED;
				case 501:
					return ClipRelayResult.NO_CHANNEL;
				case 413:
					return ClipRelayResult.TOO_LARGE;
				default:
					log.debug("clip relay returned HTTP {}", response.code());
					return ClipRelayResult.FAILED;
			}
		}
		catch (IOException e)
		{
			log.debug("clip relay failed: {}", e.getMessage());
			return ClipRelayResult.FAILED;
		}
	}

	/**
	 * GET /api/plugin/config — fetches event, team, player, codeword, tracked drops.
	 */
	// Conditional-GET cache for the config poll. The plugin GETs /api/plugin/config every 30s, but a
	// clan's board rarely changes between polls, so we keep the last ETag + parsed config and send
	// If-None-Match. A 304 means "unchanged" — we reuse the cached config and the server sends no body,
	// so an unchanged poll costs a few header bytes instead of the whole board.
	private volatile String lastConfigEtag;
	private volatile PluginConfigResponse lastConfig;

	public PluginConfigResponse fetchConfig() throws IOException
	{
		Request.Builder rb = authedRequest(apiUrl + "/api/plugin/config").get();
		String etag = lastConfigEtag;
		PluginConfigResponse cached = lastConfig;
		if (etag != null && cached != null)
		{
			rb.header("If-None-Match", etag);
		}

		try (Response response = httpClient.newCall(rb.build()).execute())
		{
			if (response.code() == 304 && cached != null)
			{
				return cached; // unchanged since the last poll — reuse it, no body transferred
			}
			if (!response.isSuccessful())
			{
				throw new IOException("Config fetch failed: HTTP " + response.code());
			}
			PluginConfigResponse parsed = gson.fromJson(response.body().string(), PluginConfigResponse.class);
			lastConfigEtag = response.header("ETag");
			lastConfig = parsed;
			return parsed;
		}
	}

	/**
	 * GET /api/plugin/board — full board for the caller's active event (every tile + grid slot +
	 * all-team completion state). Player-token authed. Never throws — returns null on any failure
	 * so the clog view can show a graceful "couldn't load" message.
	 */
	// Conditional-GET cache for the board, mirroring fetchConfig. The clog re-fetches the board on
	// tab-open / view-switch but it rarely changes between opens, so we send If-None-Match and reuse
	// the cached board on a 304 (no body transferred — a big board is tens of KB).
	private volatile String lastBoardEtag;
	private volatile BoardResponse lastBoard;

	public BoardResponse fetchBoard()
	{
		if (!isConfigured())
		{
			return null;
		}
		Request.Builder rb = authedRequest(apiUrl + "/api/plugin/board").get();
		String etag = lastBoardEtag;
		BoardResponse cached = lastBoard;
		if (etag != null && cached != null)
		{
			rb.header("If-None-Match", etag);
		}
		try (Response response = httpClient.newCall(rb.build()).execute())
		{
			if (response.code() == 304 && cached != null)
			{
				return cached; // board unchanged since the last fetch — reuse it, no body transferred
			}
			if (!response.isSuccessful() || response.body() == null)
			{
				return null;
			}
			BoardResponse parsed = gson.fromJson(response.body().string(), BoardResponse.class);
			lastBoardEtag = response.header("ETag");
			lastBoard = parsed;
			return parsed;
		}
		catch (IOException e)
		{
			log.debug("board fetch failed: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * GET /api/plugin/activity?since=&lt;cursor&gt; — the always-on sidebar's live team feed (submissions +
	 * completions after the cursor, attributed and bounded). Player-token authed. Never throws — returns
	 * null on any failure so the sidebar degrades gracefully.
	 *
	 * <p>Conditional-GET with its OWN ETag (separate from config/board so the caches never interfere):
	 * while the cursor is stable (nothing new), an unchanged payload returns 304 and we reuse the cached
	 * response — an idle team costs a few header bytes. A 304's cached body carries an empty
	 * {@code activity}, so re-ingesting it is a no-op.</p>
	 */
	private volatile String lastActivityEtag;
	private volatile ActivityResponse lastActivity;

	public ActivityResponse fetchActivity(String since)
	{
		if (!isConfigured())
		{
			return null;
		}
		String url = apiUrl + "/api/plugin/activity"
			+ (since == null || since.isEmpty() ? "" : "?since=" + since);
		Request.Builder rb = authedRequest(url).get();
		String etag = lastActivityEtag;
		ActivityResponse cached = lastActivity;
		if (etag != null && cached != null)
		{
			rb.header("If-None-Match", etag);
		}
		try (Response response = httpClient.newCall(rb.build()).execute())
		{
			if (response.code() == 304 && cached != null)
			{
				return cached; // no new activity since this cursor — reuse it, no body transferred
			}
			if (!response.isSuccessful() || response.body() == null)
			{
				return null;
			}
			ActivityResponse parsed = gson.fromJson(response.body().string(), ActivityResponse.class);
			lastActivityEtag = response.header("ETag");
			lastActivity = parsed;
			return parsed;
		}
		catch (IOException e)
		{
			log.debug("activity fetch failed: {}", e.getMessage());
			return null;
		}
	}

	// ---- Site-relayed federation (FEDERATION_WIRE.md §10.2) --------------------------------------
	//
	// The ONLY two federation endpoints the plugin calls, both on its own home site with the same
	// account-token auth as everything else. The broker and all inter-site fan-out are server-to-server;
	// the plugin holds no clan tokens and opens no clan connections on this path.

	/**
	 * §1/§9 response-size cap on the federated {@code /state} body — we never materialize an unbounded
	 * payload into memory. Generous headroom for many clans; a body over this is dropped (single-home fallback).
	 */
	private static final int MAX_STATE_BYTES = 512 * 1024;

	/**
	 * GET {@code /api/plugin/federation/state} — the site-relay sidebar's whole feed: whether federation
	 * is on, whether this member's home is connected, and one ready-shaped board summary per federated
	 * clan (§10.2). Account-token authed. Never throws — returns {@code null} on any failure (unconfigured,
	 * transport, non-2xx, unparseable), so the sidebar falls back to its single-home render.
	 *
	 * <p>A {@code null} return (older server with no such route ⇒ 404, or offline) is indistinguishable to
	 * the caller from "federation disabled" — both mean "render the single home", which is exactly today's
	 * behaviour on the default path.</p>
	 */
	public FederationState fetchFederationState()
	{
		return fetchFederationState(false);
	}

	/** As above; {@code force} = a member-initiated Refresh, asking the home to bypass its re-sync throttle. */
	public FederationState fetchFederationState(boolean force)
	{
		if (!isConfigured())
		{
			return null;
		}
		Request request = authedRequest(apiUrl + "/api/plugin/federation/state" + (force ? "?force=1" : "")).get().build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				return null;
			}
			String json = readBounded(response.body(), MAX_STATE_BYTES);
			if (json == null)
			{
				// Over the size cap — drop it (single-home fallback) rather than buffer a hostile payload.
				log.debug("federation/state body exceeded {} bytes; ignoring", MAX_STATE_BYTES);
				return null;
			}
			return FederationState.parse(gson, json);
		}
		catch (IOException e)
		{
			log.debug("federation/state fetch failed: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * Read at most {@code maxBytes} of a response body into a UTF-8 string; returns {@code null} when the
	 * body is larger than the cap so the caller can bail (§9 parser DoS — a federated payload is never
	 * materialized unbounded). Reads {@code maxBytes + 1} then checks, so an oversize body is detected
	 * without ever holding more than the cap +1.
	 */
	private static String readBounded(ResponseBody body, int maxBytes) throws IOException
	{
		byte[] buf = new byte[maxBytes + 1];
		int total = 0;
		try (InputStream in = body.byteStream())
		{
			int r;
			while (total < buf.length && (r = in.read(buf, total, buf.length - total)) != -1)
			{
				total += r;
			}
		}
		if (total > maxBytes)
		{
			return null;
		}
		return new String(buf, 0, total, StandardCharsets.UTF_8);
	}

	/** Result of {@code POST /api/plugin/federation/connect} (§10.2). Exactly one of the two flags is set. */
	public static final class FederationConnect
	{
		/** {@code status:"connected"} — a trusted home vouched for the member server-to-server (zero-click). */
		public final boolean connected;
		/** {@code status:"login"} — a self-host home needs the member's Discord login in the browser. */
		public final boolean login;
		/** The broker verification page to open when {@link #login}; {@code null} otherwise. */
		public final String verificationUrl;
		/** The short device code the member types into the verification page ({@link #login} only); null otherwise. */
		public final String userCode;

		FederationConnect(boolean connected, boolean login, String verificationUrl, String userCode)
		{
			this.connected = connected;
			this.login = login;
			this.verificationUrl = verificationUrl == null || verificationUrl.isEmpty() ? null : verificationUrl;
			this.userCode = userCode == null || userCode.isEmpty() ? null : userCode;
		}

		/** Neither connected nor a usable login — the connect call failed or returned something unexpected. */
		static FederationConnect unavailable()
		{
			return new FederationConnect(false, false, null, null);
		}
	}

	/**
	 * POST {@code /api/plugin/federation/connect} — ask the home site to establish federation for this
	 * member (§10.2). A trusted home returns {@code {status:"connected"}} (the site minted assertions
	 * server-to-server); a self-host returns {@code {status:"login", verificationUrl}} for the member to
	 * complete a one-time Discord login. Account-token authed. Never throws — returns an
	 * {@link FederationConnect#unavailable() unavailable} result on any failure.
	 */
	public FederationConnect federationConnect()
	{
		if (!isConfigured())
		{
			return FederationConnect.unavailable();
		}
		Request request = authedRequest(apiUrl + "/api/plugin/federation/connect")
			.post(RequestBody.create(JSON, "{}"))
			.build();
		try (Response response = httpClient.newCall(request).execute())
		{
			String body = response.body() != null ? response.body().string() : "";
			if (!response.isSuccessful())
			{
				log.debug("federation/connect returned HTTP {}", response.code());
				return FederationConnect.unavailable();
			}
			JsonObject o = new JsonParser().parse(body).getAsJsonObject();
			String status = o.has("status") && o.get("status").isJsonPrimitive() ? o.get("status").getAsString() : "";
			if ("connected".equals(status))
			{
				return new FederationConnect(true, false, null, null);
			}
			if ("login".equals(status))
			{
				String url = o.has("verificationUrl") && o.get("verificationUrl").isJsonPrimitive()
					? o.get("verificationUrl").getAsString() : null;
				String code = o.has("userCode") && o.get("userCode").isJsonPrimitive()
					? o.get("userCode").getAsString() : null;
				return new FederationConnect(false, true, url, code);
			}
			return FederationConnect.unavailable();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("federation/connect failed: {}", e.getMessage());
			return FederationConnect.unavailable();
		}
	}

	/**
	 * POST {@code /api/plugin/federation/disconnect} — federation logout (§10.2). Asks the home site to
	 * discard the member's cached remote-clan tokens and clear the durable signed-in marker. Account-token
	 * authed, idempotent. Returns {@code true} on a 2xx acknowledgement; never throws.
	 */
	public boolean federationDisconnect()
	{
		if (!isConfigured())
