	/**
	 * The same push, carrying the raw combat-achievement varps.
	 *
	 * <p>We send the numbers and the game's own point total; the site decodes which task each bit is
	 * and refuses the lot if the points don't reconcile. Nothing here knows what a combat task is,
	 * which is the point: the catalogue lives where it can be updated without a release.
	 */
	public void submitProgress(java.util.Map<String, Integer> progress, String itemCategory,
		java.util.List<AccountProgress.Item> items, java.util.Map<Integer, Integer> caVarps,
		int caPoints) throws IOException
	{
		boolean hasItems = itemCategory != null && items != null && !items.isEmpty();
		boolean hasVarps = caVarps != null && !caVarps.isEmpty() && caPoints > 0;
		if ((progress == null || progress.isEmpty()) && !hasItems && !hasVarps)
		{
			return;
		}
		if (progress == null)
		{
			progress = java.util.Collections.emptyMap();
		}
		JsonArray rows = new JsonArray();
		for (java.util.Map.Entry<String, Integer> e : progress.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			JsonObject row = new JsonObject();
			row.addProperty("key", e.getKey());
			row.addProperty("value", e.getValue());
			rows.add(row);
		}
		if (rows.size() == 0 && !hasItems && !hasVarps)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("progress", rows);
		if (hasItems)
		{
			JsonArray itemRows = new JsonArray();
			for (AccountProgress.Item item : items)
			{
				if (item == null || item.name == null || item.name.isEmpty())
				{
					continue;
				}
				JsonObject row = new JsonObject();
				row.addProperty("id", item.id);
				row.addProperty("name", item.name);
				row.addProperty("state", item.state);
				itemRows.add(row);
			}
			JsonObject set = new JsonObject();
			set.addProperty("category", itemCategory);
			set.add("items", itemRows);
			JsonArray sets = new JsonArray();
			sets.add(set);
			payload.add("items", sets);
		}
		if (hasVarps)
		{
			JsonObject varpObj = new JsonObject();
			for (java.util.Map.Entry<Integer, Integer> e : caVarps.entrySet())
			{
				varpObj.addProperty(String.valueOf(e.getKey()), e.getValue());
			}
			payload.add("caVarps", varpObj);
			payload.addProperty("caPoints", caPoints);
		}

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(apiUrl + "/api/plugin/progress")
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			String responseBody = response.body() != null ? response.body().string() : "";
			if (!response.isSuccessful())
			{
				throw new IOException("Progress push failed: HTTP " + response.code() + " — "
					+ (responseBody.isEmpty() ? "no body" : responseBody));
			}
			// The reply says what the server made of it — including, for combat achievements, whether
			// the bits reconciled against the point total and how many tasks it couldn't name. Logged
			// at INFO because when this feature is quiet the only alternative is guessing which half
			// went wrong, which has cost a day already.
			log.info("Anvil progress pushed ({} key(s), {} varps): {}", rows.size(),
				hasVarps ? caVarps.size() : 0, responseBody);
		}
	}

	/**
	 * POST /api/plugin/clog — collection-log pages the player has actually opened.
	 *
	 * <p>Sends ONLY obtained items, and only pages whose contents changed since the last successful
	 * push ({@link ClogSync} owns that decision). The site already ships the full item catalogue, so
	 * the missing half is derivable — transmitting it would double every payload to say "still
	 * nothing here".
	 *
	 * <p>Idempotent: the server keys on (member, page) and replaces, so a retry or a client restart
	 * mid-sync costs nothing. Profile data only — never scoring.
	 */
	public void submitClogPages(java.util.List<ClogPage> pages, int syncedPages) throws IOException
	{
		if (pages == null || pages.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (ClogPage page : pages)
		{
			if (page == null || page.name == null || page.name.isEmpty())
			{
				continue;
			}
			JsonArray items = new JsonArray();
			for (int i = 0; i < page.itemIds.length; i++)
			{
				JsonObject item = new JsonObject();
				item.addProperty("id", page.itemIds[i]);
				item.addProperty("q", page.quantities[i]);
				items.add(item);
			}
			JsonObject p = new JsonObject();
			p.addProperty("name", page.name);
			p.addProperty("obtained", page.obtained);
			p.addProperty("total", page.total);
			p.add("items", items);
			if (!page.counts.isEmpty())
			{
				JsonObject counts = new JsonObject();
				for (java.util.Map.Entry<String, Integer> e : page.counts.entrySet())
				{
					counts.addProperty(e.getKey(), e.getValue());
				}
				p.add("counts", counts);
			}
			out.add(p);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("pages", out);
		// How much of the log this account has opened at all — drives the site's "68% synced" note.
		payload.addProperty("syncedPages", syncedPages);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(apiUrl + "/api/plugin/clog")
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Collection log push failed", response.code(), responseBody);
			}
			log.debug("Collection log pushed: {} page(s), {} synced", out.size(), syncedPages);
		}
	}

	/**
	 * POST /api/plugin/pb — the account's best times, in centiseconds.
	 *
	 * <p>Centiseconds because the game separates runs by hundredths; whole seconds would tie times
	 * the game itself doesn't. The server keeps the FASTEST of stored and pushed, so a retry, a
	 * stale client or an out-of-order request can never raise somebody's record.
	 */
	public void submitPersonalBests(java.util.Map<String, Integer> bests) throws IOException
	{
		if (bests == null || bests.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (java.util.Map.Entry<String, Integer> e : bests.entrySet())
		{
			if (e.getKey() == null || e.getKey().isEmpty() || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			JsonObject b = new JsonObject();
			b.addProperty("activity", e.getKey());
			b.addProperty("centis", e.getValue());
			out.add(b);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("bests", out);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(apiUrl + "/api/plugin/pb")
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Personal best push failed", response.code(), responseBody);
			}
			log.debug("Personal bests pushed: {}", out.size());
		}
	}

	/**
	 * POST /api/plugin/moments — the clan's highlight feed: pets, uniques, big hauls and deaths.
	 *
	 * <p>Reports what the client SAW; the site decides what it meant. It knows which competition
	 * week or board is running, what counts as a unique, and which pets belong to which skill — so
	 * most of what goes up here is discarded there, on purpose, and a clan changing its mind about
	 * any of it costs no plugin release.
	 *
	 * <p>Idempotent: every entry carries a key derived from what happened, so the two loot events
	 * and three chat lines one occurrence fires — and a retry after a timeout — collapse into one
	 * row. A failure therefore just retries with the queue intact.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitMoments(java.util.List<AnvilMoments.Moment> batch) throws IOException
	{
		if (batch == null || batch.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (AnvilMoments.Moment m : batch)
		{
			if (m == null || m.kind == null || m.key == null)
			{
				continue;
			}
			JsonObject o = new JsonObject();
			o.addProperty("kind", m.kind);
			o.addProperty("key", m.key);
			o.addProperty("at", java.time.Instant.ofEpochMilli(m.at).toString());
			o.addProperty("quantity", Math.max(1, m.quantity));
			// Everything below is best-effort — a skilling pet has no source, no KC and no price, and
			// inventing any of them would be worse than a shorter line on the feed.
			if (m.itemId != null)
			{
				o.addProperty("itemId", m.itemId);
			}
			if (m.itemName != null && !m.itemName.isEmpty())
			{
				o.addProperty("itemName", m.itemName);
			}
			if (m.valueGp != null && m.valueGp > 0)
			{
				o.addProperty("valueGp", m.valueGp);
			}
			if (m.source != null && !m.source.isEmpty())
			{
				o.addProperty("source", m.source);
			}
			if (m.taskName != null && !m.taskName.isEmpty())
			{
				o.addProperty("taskName", m.taskName);
			}
			if (m.tier != null && !m.tier.isEmpty())
			{
				o.addProperty("tier", m.tier);
			}
			if (m.sourceKind != null && !m.sourceKind.isEmpty())
			{
				o.addProperty("sourceKind", m.sourceKind);
			}
			if (m.kc != null && m.kc > 0)
			{
				o.addProperty("kc", m.kc);
			}
			out.add(o);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("moments", out);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(apiUrl + "/api/plugin/moments")
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw new IOException("Moment push failed: HTTP " + response.code() + " — " + responseBody);
			}
			log.debug("Moments pushed: {}", out.size());
		}
	}

	/**
	 * POST /api/events/{eventId}/submissions — submits a timed-clear with image proof.
	 * amount is fixed at 1; the clear time (seconds) rides in durationSeconds. The server
	 * completes the tile when durationSeconds ≤ the tile's threshold.
	 */
	public void submitTimed(int eventId, int tileId, int teamId, int durationSeconds, String imageUrl, String note, int creditPlayerId) throws IOException
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("tileId", tileId);
		payload.addProperty("teamId", teamId);
		payload.addProperty("amount", 1);
		payload.addProperty("durationSeconds", durationSeconds);
		payload.addProperty("imageUrl", imageUrl);
		payload.addProperty("note", note);
		payload.addProperty("creditPlayerId", creditPlayerId);

		RequestBody body = RequestBody.create(JSON, payload.toString());

		Request request = authedRequest(apiUrl + "/api/events/" + eventId + "/submissions")
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Timed submission failed", response.code(), responseBody);
			}
			log.info("Timed clear submitted successfully for tile {}", tileId);
		}
	}

}

package com.anvil;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * The live {@link SidebarDataSource} behind the sidebar: renders the plugin's one home — a view over the
 * already-polled {@link PluginConfigResponse} plus the injected {@link BingoApiClient} — into a single
 * {@link ConnectionView}. Board summary + nearest tiles come from the polled config (no extra request); the
 * feed is the source's only network call (one conditional GET to {@code /api/plugin/activity}, 304 while idle).
 *
 * <p><b>"Active now"</b> fuses three signals so it works for every tile kind: config-count deltas (the only
 * signal for stat grinds, and the unnamed "a teammate" fallback for any kind), the local stat signal
 * ({@code AnvilPlugin::localStatProgress}, which attributes a rise to "You"), and the feed (submission tiles
 * by name). Signals merge by tile (deduped, "You" first), newest-first, capped.</p>
 *
 * <p>Called off the EDT by the panel's worker (one at a time), so the delta state needs no locking.</p>
 */
@Slf4j
public class AnvilSidebarDataSource implements SidebarDataSource
{
	/** Stable id for the plugin's one home. */
	static final String LOCAL_INSTANCE_ID = "local";

	private static final int NEAREST_LIMIT = 10;
	private static final int MAX_ACTIVE = 4;

	/** How recent a signal counts as "active now" — matched to the Site's 5-min stat-worker window. */
	private static final long ACTIVE_WINDOW_MS = 5 * 60_000L;

	/** How long a weekly's standings stay good. Way slacker than the 15 s panel poll — weekly gains are
	 *  swept by the site's 15-min stats cron, so re-reading a leaderboard every refresh is pure noise. */
	private static final long WEEKLY_STANDINGS_TTL_MS = 60_000L;

	/** Leaderboard rows kept per weekly — the sidebar shows the head of the board, not all 50. */
	private static final int WEEKLY_TOP_LIMIT = 10;

	private final Supplier<PluginConfigResponse> configSupplier;

	/** The plugin's injected client — the sidebar's one network call (the activity feed) rides on it. */
	private final BingoApiClient apiClient;

	/** Stat tiles this account recently progressed (tileId → millis) — the "You" attribution for stat grinds. */
	private final Supplier<Map<Integer, Long>> localStatProgress;

	/** The playing account's RSN — flags "you" in a weekly's standings. Null/blank while logged out. */
	private final Supplier<String> localRsn;

	/** Is this account a real member of the HOME clan? {@code null} until the login handshake answers. */
	private final Supplier<Boolean> homeMembership;

	// Weekly standings cache (compId → last leaderboard read), the comps already read this generation,
	// and when the generation opened — so the panel's 15 s poll doesn't re-read the same board four
	// times a minute (nor hammer a failing one). See refreshWeeklyBoards.
	private final Map<Integer, BingoApiClient.WeeklyLeaderboard> weeklyBoards = new HashMap<>();
	private final java.util.Set<Integer> weeklyBoardsTried = new java.util.HashSet<>();
	private long weeklyBoardsAt;

	// Live-sidebar state, scoped to the active event.
	private final AnvilActivityLog activityLog = new AnvilActivityLog();
	private int scopedEventId = -1;

	// Config-delta signal state (per instance id): last-seen amount per tile + when each rose. Cleared on event change.
	private final Map<String, Map<Integer, Integer>> lastAmounts = new HashMap<>();
	private final Map<String, Map<Integer, Long>> roseAt = new HashMap<>();

	/** Single-home binding — the plugin's live config + injected client. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient)
	{
		this(configSupplier, apiClient, Collections::emptyMap);
	}

	/** Single-home binding with the local stat signal (drives attribution in tests). */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress)
	{
		this(configSupplier, apiClient, localStatProgress, () -> null);
	}

	/** Adds the playing account's RSN for the weekly standings' "you" row. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress, Supplier<String> localRsn)
	{
		this(configSupplier, apiClient, localStatProgress, localRsn, () -> null);
	}

	/** The real plugin binding — also carries whether this account is a member (not a guest) at home. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress, Supplier<String> localRsn,
		Supplier<Boolean> homeMembership)
	{
		this.configSupplier = configSupplier;
		this.apiClient = apiClient;
		this.localStatProgress = localStatProgress == null ? Collections::emptyMap : localStatProgress;
		this.localRsn = localRsn == null ? () -> null : localRsn;
		this.homeMembership = homeMembership == null ? () -> null : homeMembership;
	}

	/**
	 * The starting-shot action, bound by the plugin after construction (Guice builds this source
	 * before the plugin's own fields exist, so it can't be a constructor argument). Null in tests and
	 * anywhere the panel is driven without a live plugin — the sidebar then simply shows no button.
	 */
	private volatile Runnable startProofCapture;

	/** Bind the capture action. Idempotent; passing null unbinds. */
	public void setStartProofCapture(Runnable capture)
	{
		this.startProofCapture = capture;
	}

	/** The plugin behind the panel's buttons, bound after construction like the capture above. */
	private volatile AnvilPlugin plugin;

	public void setPlugin(AnvilPlugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public PanelActions actionsFor(String instanceId)
	{
		AnvilPlugin p = plugin;
		if (p == null || !LOCAL_INSTANCE_ID.equals(instanceId))
		{
			// Another clan's card. A roster sync there is impossible (you can only read the clan
			// channel you're in) and a profile sync has nowhere to go yet, so the panel offers
			// neither rather than offering something that would fail.
			return new PanelActions(false, false, null);
		}
		boolean profile = p.supportsProfileSync();
		if (!p.isAdmin())
		{
			return new PanelActions(false, profile, null);
		}
		// Admin, at home — but the roster comes from the clan channel, so it has to be readable. The
		// CACHED answer: this runs while the panel paints, on the EDT, where asking the client
		// directly is a thread violation.
		boolean scrape = p.isClanRosterReadable();
		return new PanelActions(scrape, profile, scrape ? null : "Join your clan channel to sync the roster");
	}

	@Override
	public void syncRoster()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.syncClanRosterFromPanel();
		}
	}

	@Override
	public void syncProfile()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.syncProfileNow();
		}
	}

	@Override
	public java.util.List<String> bannerSounds()
	{
		AnvilPlugin p = plugin;
		return p == null ? java.util.Collections.emptyList() : p.bannerSoundClips();
	}

	@Override
	public boolean bannerSoundOn(String clip)
	{
		AnvilPlugin p = plugin;
		return p != null && p.bannerSoundSelected(clip);
	}

	@Override
	public void toggleBannerSound(String clip)
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.toggleBannerSound(clip);
		}
	}

	@Override
	public void copyBannerSoundsPath()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.copyBannerSoundsPath();
		}
	}

	@Override
	public void importBannerSounds()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.importBannerSounds();
		}
	}

	@Override
	public PluginConfigResponse.StartProof startProof()
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null || cfg.startProof == null || !cfg.startProof.required
			|| !cfg.startProof.drawn || !cfg.startProof.needsUpload)
		{
			return null;
		}
		// Only while the event is actually live — the same gate the in-game overlay uses, so the
		// panel can't ask for a shot of an event that has ended.
		return AnvilOverlay.isEventActive(cfg.event) ? cfg.startProof : null;
	}

	@Override
	public void captureStartProof()
	{
		Runnable capture = startProofCapture;
		if (capture != null)
		{
			capture.run();
		}
	}

	@Override
	public List<ConnectionView> fetchConnections() throws SidebarDataException
	{
		return fetchConnections(false);
	}

	/** {@code force} = the member clicked Refresh — bypasses the weekly-standings throttle too. */
	@Override
	public List<ConnectionView> fetchConnections(boolean force) throws SidebarDataException
	{
		ConnectionView view = buildView(force);
		return view == null ? Collections.emptyList() : Collections.singletonList(view);
	}

	private ConnectionView buildView(boolean force)
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null)
		{
			if (scopedEventId != -1)
			{
				resetLiveState();
			}
			return null; // no config at all (site unreachable / bad token) — nothing to anchor a card on
		}

		// SOTW/BOTW ride alongside the board as events of their own, so they show up whether or not the
		// member is in a live bingo — a weekly-only clan still has something on the card. The clan's
		// other/coming bingos ride along the same way, so "what's next" needs no site visit.
		List<ConnectionView.WeeklyView> weeklies = buildWeeklies(cfg, force);
		List<ConnectionView.ScheduledView> scheduled = buildScheduled(cfg);

		if (cfg.event == null)
		{
			if (scopedEventId != -1)
			{
				resetLiveState();
			}
			// No member-scoped event: either the clan genuinely has no live event, or one IS running
			// but this account can't be resolved right now (logged out / unlinked RSN). Still render a
			// home card — without it, a federated sidebar shows only the OTHER clans, which reads as
			// "my main clan disappeared".
			PluginConfigResponse.HomeBoard hb = cfg.homeBoard;
			if (hb != null)
			{
				// The site resolved the user's live enrollment server-side (token → linked member →
				// team), so the board summary renders even at the login screen; the live layers
				// (nearest tiles, active-now) still wait for a playing account.
				return new ConnectionView(LOCAL_INSTANCE_ID, homeClanName(cfg), hb.eventName,
					null, hb.tilesComplete, hb.tilesTotal, null, null, null, null, hb.pointsScored,
					"Log in in-game for live tracking.", null, null, weeklies, scheduled, homeMembership.get());
			}
			String note = cfg.unlinkedActiveEvent != null && !cfg.unlinkedActiveEvent.isEmpty()
				? "Log in in-game to load your board."
				: null; // null → the panel's "No active event yet."
			return new ConnectionView(LOCAL_INSTANCE_ID, homeClanName(cfg), cfg.unlinkedActiveEvent,
				null, 0, 0, null, null, null, null, false, note, null, null, weeklies, scheduled, homeMembership.get());
		}

		if (cfg.event.id != scopedEventId)
		{
			resetLiveState(); // a new event's deltas must not inherit the old board's amounts
			scopedEventId = cfg.event.id;
		}

		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.build(cfg);
		// Optional tiles are bonus: excluded from BOTH the total and the earned/complete tally, exactly
		// like the website's scoredTiles filter (else a completed optional tile inflates the numerator
		// and every optional tile inflates the denominator).
		java.util.Set<Integer> optionalIds = cfg.optionalTileIds == null
			? java.util.Collections.emptySet()
			: new java.util.HashSet<>(cfg.optionalTileIds);
		// Leagues (scoringMode=points) ranks by summed tile WEIGHT, so the summary reads earned/total
		// POINTS (matching the website + board banner); classic bingo + tile race stay tile counts.
		// Guard the degenerate no-points board so a mis-tagged event still shows a sane count.
		boolean pointsScored = "points".equalsIgnoreCase(cfg.event.scoringMode)
			&& ClogTaskModel.totalPoints(rows, optionalIds) > 0;
		int tilesTotal = pointsScored
			? ClogTaskModel.totalPoints(rows, optionalIds)
			: ClogTaskModel.scoredCount(rows, optionalIds);
		int tilesComplete = pointsScored
			? ClogTaskModel.earnedPoints(rows, optionalIds)
			: ClogTaskModel.completedCount(rows, optionalIds);
		List<ConnectionView.TileProgressView> nearest = nearestTiles(rows);

		// One conditional GET for the feed. A failure leaves the log as-is (partial failure), surfaced inline.
		String error = null;
		try
		{
			BingoApiClient.ActivityResponse ar = apiClient.fetchActivity(activityLog.getCursor());
			if (ar != null && !ar.noActiveEvent)
			{
				activityLog.ingest(ar.cursor, toEntries(ar.activity));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("activity fetch failed", e);
			error = "Live feed unavailable";
		}

		List<ActivityEntry> feed = activityLog.snapshot();
		// Raw feed drives "Active now"; the display list folds a grind's "+1" rows into one "+N" (Team activity).
		List<ConnectionView.ActiveTask> activeNow = buildActiveNow(cfg, rows, feed);

		// Ladder events render a DMM-All-Stars-style missions board instead of the tile-count reveal note:
		// a live countdown, the open missions with their live grow/decay value, and your rank.
		ConnectionView.Ladder ladder = buildLadder(cfg.event);

		// The clan filter is a CLAN switcher, so the label is the clan name (site-provided) — the
		// event name lives on the card itself. Falls back to team/event for pre-clanName sites;
		// ConnectionView maps "" → "(unnamed clan)".
		return new ConnectionView(
			LOCAL_INSTANCE_ID, homeClanName(cfg), cfg.event.name, error,
			tilesComplete, tilesTotal, nearest, AnvilActivityLog.aggregateForDisplay(feed), activeNow, boardUrlFor(cfg), pointsScored,
			null, ladder != null && ladder.ladderFormat ? null : revealNote(cfg.event),
			ladder, weeklies, scheduled, homeMembership.get());
	}

	// ---- Weekly competitions (SOTW/BOTW) as sidebar events ----------------------------------------

	/**
	 * The clan's weeklies — live ones folded with the caller's standing, upcoming ones as an
	 * announcement. The comps themselves come from the config the plugin already polls (no extra
	 * request); a LIVE comp's standings are one throttled read ({@link #WEEKLY_STANDINGS_TTL_MS}) that
	 * degrades to a comp-only card when unreachable, and an upcoming one is never read at all (nothing
	 * has happened yet). Live first, then soonest-starting.
	 */
	private List<ConnectionView.WeeklyView> buildWeeklies(PluginConfigResponse cfg, boolean force)
	{
		List<BingoApiClient.ScheduledWeekly> weeklies = scheduledWeeklies(cfg);
		if (weeklies.isEmpty())
		{
			weeklyBoards.clear();
			weeklyBoardsTried.clear();
			return Collections.emptyList();
		}
		List<BingoApiClient.ScheduledWeekly> live = new ArrayList<>();
		for (BingoApiClient.ScheduledWeekly w : weeklies)
		{
			if (isLive(w.status))
			{
				live.add(w);
			}
		}
		refreshWeeklyBoards(live, force);

		String me = normalizeRsn(localRsn.get());
		List<ConnectionView.WeeklyView> out = new ArrayList<>(weeklies.size());
		for (BingoApiClient.ScheduledWeekly w : weeklies)
		{
			out.add(toWeeklyView(w, weeklyBoards.get(w.id), me));
		}
		return out;
	}

	/**
	 * Every weekly the site is advertising (live AND upcoming), deduped by id, live first then by
	 * soonest start. Reads the schedule — which carries both comps when a SOTW and a BOTW overlap —
	 * and falls back to the single {@code activeWeekly} field so an older site still surfaces its one
	 * live comp. The site only ships non-completed comps, so nothing here is over.
	 */
	private static List<BingoApiClient.ScheduledWeekly> scheduledWeeklies(PluginConfigResponse cfg)
	{
		List<BingoApiClient.ScheduledWeekly> out = new ArrayList<>();
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		if (cfg.schedule != null && cfg.schedule.weeklies != null)
		{
			for (BingoApiClient.ScheduledWeekly w : cfg.schedule.weeklies)
			{
				if (w != null && seen.add(w.id))
				{
					out.add(w);
				}
			}
		}
		BingoApiClient.ActiveWeekly a = cfg.activeWeekly;
		if (a != null && seen.add(a.id))
		{
			BingoApiClient.ScheduledWeekly w = new BingoApiClient.ScheduledWeekly();
			w.id = a.id;
			w.title = a.title;
			w.type = a.type;
			w.metric = a.metric;
			w.metricLabel = a.metricLabel;
			w.status = "active";
			w.startDate = a.startDate;
			w.endDate = a.endDate;
			out.add(w);
		}
		out.sort(SCHEDULE_ORDER);
		return out;
	}

	/**
	 * Bingo events on the clan's schedule other than the caller's own board — live ones they aren't in,
	 * plus what's coming up. Straight off the polled config; the caller's own event is dropped because
	 * the board card already IS that event.
	 */
	private List<ConnectionView.ScheduledView> buildScheduled(PluginConfigResponse cfg)
	{
		if (cfg.schedule == null || cfg.schedule.bingos == null)
		{
			return Collections.emptyList();
		}
		int ownEventId = cfg.event != null ? cfg.event.id : -1;
		List<BingoApiClient.ScheduledBingo> bingos = new ArrayList<>();
		for (BingoApiClient.ScheduledBingo b : cfg.schedule.bingos)
		{
			if (b != null && b.id != ownEventId)
			{
				bingos.add(b);
			}
		}
		bingos.sort((x, y) -> SCHEDULE_ORDER.compare(
			asEntry(x.status, x.startDate), asEntry(y.status, y.startDate)));

		String base = apiClient.getApiUrl();
		List<ConnectionView.ScheduledView> out = new ArrayList<>(bingos.size());
		for (BingoApiClient.ScheduledBingo b : bingos)
		{
			out.add(new ConnectionView.ScheduledView(b.id, b.title, b.startDate, b.endDate,
				isLive(b.status), b.tileCount == null ? 0 : b.tileCount,
				b.boardSize == null ? 0 : b.boardSize, b.format, b.scoringMode,
				base == null || base.isEmpty() ? null : base + "/events/" + b.id));
		}
		return out;
	}

	/** Live first, then soonest start (ISO strings sort chronologically); undated last. */
	private static final Comparator<BingoApiClient.ScheduledWeekly> SCHEDULE_ORDER = (a, b) ->
	{
		boolean la = isLive(a.status);
		boolean lb = isLive(b.status);
		if (la != lb)
		{
			return la ? -1 : 1;
		}
		String sa = a.startDate == null ? "" : a.startDate;
		String sb = b.startDate == null ? "" : b.startDate;
		if (sa.isEmpty() != sb.isEmpty())
		{
			return sa.isEmpty() ? 1 : -1;
		}
		return sa.compareTo(sb);
	};

	/** Adapter so the bingo list can reuse {@link #SCHEDULE_ORDER} (same status/start ordering). */
	private static BingoApiClient.ScheduledWeekly asEntry(String status, String startDate)
	{
		BingoApiClient.ScheduledWeekly w = new BingoApiClient.ScheduledWeekly();
		w.status = status;
		w.startDate = startDate;
		return w;
	}

	private static boolean isLive(String status)
	{
		return "active".equalsIgnoreCase(status);
	}

	/**
	 * One standings read per live comp per {@link #WEEKLY_STANDINGS_TTL_MS} window (a member-forced
	 * Refresh opens a new window immediately) — including a comp whose read FAILED, so an unreachable
	 * leaderboard is retried on the same slow cadence instead of every poll. A comp that stopped
	 * running is dropped, so the cache can't outlive it.
	 */
	private void refreshWeeklyBoards(List<BingoApiClient.ScheduledWeekly> live, boolean force)
	{
		final long now = System.currentTimeMillis();
		if (force || now - weeklyBoardsAt >= WEEKLY_STANDINGS_TTL_MS)
		{
			weeklyBoardsTried.clear();
			weeklyBoardsAt = now;
		}
		java.util.Set<Integer> liveIds = new java.util.HashSet<>();
		for (BingoApiClient.ScheduledWeekly w : live)
		{
			liveIds.add(w.id);
			if (!weeklyBoardsTried.add(w.id))
			{
				continue; // already read this window — the cached board stands
			}
			try
			{
				BingoApiClient.WeeklyLeaderboard lb = apiClient.fetchWeeklyLeaderboard(w.id);
				if (lb != null)
				{
					weeklyBoards.put(w.id, lb);
				}
			}
			catch (RuntimeException e)
			{
				// A weekly board is a nice-to-have: keep whatever we had and render the comp without it.
				log.debug("weekly leaderboard fetch failed for {}", w.id, e);
			}
		}
		weeklyBoards.keySet().retainAll(liveIds);
		weeklyBoardsTried.retainAll(liveIds);
	}

	/** Fold one comp + its (possibly absent) leaderboard into the panel's weekly card. */
	private ConnectionView.WeeklyView toWeeklyView(BingoApiClient.ScheduledWeekly w,
		BingoApiClient.WeeklyLeaderboard lb, String me)
	{
		List<ConnectionView.Standing> top = new ArrayList<>();
		int yourRank = 0;
		long yourGained = 0;
		int participants = 0;
		if (lb != null && isLive(w.status))
		{
			participants = lb.total;
			if (lb.entries != null)
			{
				for (BingoApiClient.LeaderboardEntry e : lb.entries)
				{
					if (e == null)
					{
						continue;
					}
					// Match on whitespace-normalized names — OSRS display names carry non-breaking
					// spaces, so a raw equalsIgnoreCase both misses and mis-flags the local player.
					boolean self = !me.isEmpty() && me.equals(normalizeRsn(e.rsn));
					if (self)
					{
						yourRank = e.rank;
						yourGained = e.gained;
					}
					if (top.size() < WEEKLY_TOP_LIMIT || self)
					{
						top.add(new ConnectionView.Standing(e.rank, e.rsn, e.gained, self));
					}
				}
			}
		}
		return new ConnectionView.WeeklyView(w.id, w.title, w.type, w.metric, w.metricLabel,
			w.startDate, w.endDate, !isLive(w.status), yourRank, yourGained, participants, top,
			weeklyUrlFor(w.id));
	}

	/** The comp's page on the site, or null when the base URL is unknown (offline / unconfigured). */
	private String weeklyUrlFor(int competitionId)
	{
		String base = apiClient.getApiUrl();
		return base == null || base.isEmpty() ? null : base + "/weekly/" + competitionId;
	}

	/** Lower-cased, whitespace-collapsed RSN for robust comparisons (OSRS names use U+00A0). */
	private static String normalizeRsn(String rsn)
	{
		return rsn == null ? "" : rsn.replaceAll("[\\s\\u00a0]+", " ").trim().toLowerCase();
	}

	/**
	 * Fold missions into the sidebar's {@link ConnectionView.Ladder} view-model: the countdown target,
	 * the caller's month + all-time rank, and the open missions.
	 *
	 * Built for a ladder (where it REPLACES the board summary) and, since a normal bingo can drop
	 * hidden missions mid-event too, for any board that currently has missions — there it renders as
	 * a strip under the usual summary. Null when neither applies, and the plain summary + reveal note
	 * render on their own.
	 */
	static ConnectionView.Ladder buildLadder(PluginConfigResponse.EventInfo event)
	{
		if (event == null)
		{
			return null;
		}
		boolean ladder = LadderMissions.isLadder(event.format);
		boolean hasMissions = event.missions != null && !event.missions.isEmpty();
		if (!ladder && !hasMissions)
		{
			return null;
		}
		List<ConnectionView.Ladder.Mission> missions = new ArrayList<>();
		if (event.missions != null)
		{
			for (PluginConfigResponse.Mission m : event.missions)
			{
				if (m != null)
				{
					missions.add(new ConnectionView.Ladder.Mission(m.tileId, m.label, m.points, m.revealedAt));
				}
			}
		}
		int monthRank = event.monthlyStandings != null ? event.monthlyStandings.yourRank : 0;
		long monthPoints = event.monthlyStandings != null ? event.monthlyStandings.yourPoints : 0;
		int allTimeRank = event.standings != null ? event.standings.yourRank : 0;
		return new ConnectionView.Ladder(event.nextRevealAt, monthRank, monthPoints, allTimeRank,
			event.decay, missions, ladder);
	}

	/**
	 * Reveal-policy boards: the "still hidden" one-liner under the board summary, or null on classic
	 * boards / older servers (no field). Bounty draws on claim, the others on a clock the server sends.
	 */
	static String revealNote(PluginConfigResponse.EventInfo event)
	{
		if (event == null || event.revealPolicy == null || event.revealPolicy.isEmpty() || event.hiddenTileCount <= 0)
		{
			return null;
		}
		boolean bounty = "bounty".equalsIgnoreCase(event.revealPolicy);
		String what = bounty
			? event.hiddenTileCount + (event.hiddenTileCount == 1 ? " bounty" : " bounties") + " left"
			: event.hiddenTileCount + (event.hiddenTileCount == 1 ? " tile" : " tiles") + " hidden";
		String next = bounty ? "next on claim" : nextRevealLabel(event.nextRevealAt);
		return what + (next == null ? "" : " · " + next);
	}

	/** "next in 42m" / "next in 3h 10m" from the server's ISO next-reveal stamp; null when absent/past. */
	private static String nextRevealLabel(String nextRevealAt)
	{
		if (nextRevealAt == null || nextRevealAt.isEmpty())
		{
			return null;
		}
		try
		{
			long at = java.time.Instant.parse(nextRevealAt).toEpochMilli();
			long mins = Math.max(0, (at - System.currentTimeMillis()) / 60_000);
			if (mins < 1)
			{
				return "next any minute";
			}
			if (mins < 60)
			{
				return "next in " + mins + "m";
			}
			return "next in " + (mins / 60) + "h " + (mins % 60) + "m";
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** The home entry's clan-filter label: the site's clan name, else the old team/event fallback. */
	private static String homeClanName(PluginConfigResponse cfg)
	{
		if (cfg.clanName != null && !cfg.clanName.isEmpty())
		{
			return cfg.clanName;
		}
		return primaryDisplayName(cfg);
	}

	/** The site's public board/standings page for the active event, or null when the base URL is unknown. */
	private String boardUrlFor(PluginConfigResponse cfg)
	{
		String base = apiClient.getApiUrl();
		if (base == null || base.isEmpty() || cfg.event == null)
		{
			return null;
		}
		return base + "/events/" + cfg.event.id;
	}

	/** Reset the feed + delta state when the active event changes (or clears). */
	private void resetLiveState()
	{
		activityLog.reset();
		scopedEventId = -1;
		forgetDeltas(LOCAL_INSTANCE_ID);
	}

	/** The clan/event label for the header: team name ?? event name ?? "". */
	private static String primaryDisplayName(PluginConfigResponse cfg)
	{
		if (cfg.team != null && cfg.team.name != null && !cfg.team.name.isEmpty())
		{
			return cfg.team.name;
		}
		if (cfg.event != null && cfg.event.name != null && !cfg.event.name.isEmpty())
		{
			return cfg.event.name;
		}
		return "";
	}

	private void forgetDeltas(String instanceId)
	{
		lastAmounts.remove(instanceId);
		roseAt.remove(instanceId);
	}

	/** Fuse the feed, named stat workers, the local stat signal, and config deltas into "Active now". */
	private List<ConnectionView.ActiveTask> buildActiveNow(PluginConfigResponse cfg,
		List<ClogTaskModel.TaskRow> rows, List<ActivityEntry> feed)
	{
		final long now = System.currentTimeMillis();
		Map<Integer, ClogTaskModel.TaskRow> incompleteById = new HashMap<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (!r.isCompleted())
			{
				incompleteById.put(r.tileId, r);
			}
		}

		// Server-computed named teammates per stat tile (tileId → RSNs); absent on an older server (unnamed fallback).
		Map<Integer, List<String>> namedByTile = new HashMap<>();
		if (cfg.trackedStats != null)
		{
			for (PluginConfigResponse.TrackedStat s : cfg.trackedStats)
			{
				if (s != null && s.activeWorkers != null)
				{
					namedByTile.put(s.tileId, s.activeWorkers);
				}
			}
		}
		Map<Integer, Acc> acc = new HashMap<>();

		// 1. Feed — submission tiles, named. Newest-first.
		for (ActivityEntry e : feed)
		{
			if (e.kind != ActivityEntry.Kind.PROGRESS)
			{
				continue;
			}
			long t = parseTsMillis(e.ts);
			if (t >= 0 && now - t > ACTIVE_WINDOW_MS)
			{
				continue;
			}
			String worker = e.self ? "You" : (e.player == null || e.player.isEmpty() ? null : e.player);
			add(acc, incompleteById, e.tileId, worker, e.self, t < 0 ? now : t);
		}

		// 2. Local stat signal — "You" on stat tiles this account is grinding.
		Map<Integer, Long> local = localStatProgress.get();
		if (local != null)
		{
			for (Map.Entry<Integer, Long> en : local.entrySet())
			{
				long t = en.getValue() == null ? 0 : en.getValue();
				if (now - t > ACTIVE_WINDOW_MS)
				{
					continue;
				}
				add(acc, incompleteById, en.getKey(), "You", true, t);
			}
		}

		// 2b. Named teammates on stat tiles (server-computed) — the good version of "a teammate".
		for (Map.Entry<Integer, List<String>> en : namedByTile.entrySet())
		{
			for (String name : en.getValue())
			{
				add(acc, incompleteById, en.getKey(), name, false, now);
			}
		}

		// 3. Config-count deltas → an UNNAMED "a teammate" for ANY tile kind — the only signal for a teammate
		//    grinding before the feed ships. Suppressed where the server named the tile (2b) or you're on it (2).
		Map<Integer, Integer> last = lastAmounts.computeIfAbsent(LOCAL_INSTANCE_ID, k -> new HashMap<>());
		Map<Integer, Long> rose = roseAt.computeIfAbsent(LOCAL_INSTANCE_ID, k -> new HashMap<>());
		Map<Integer, Integer> current = new HashMap<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			current.put(r.tileId, r.current);
			if (r.isCompleted())
			{
				continue;
			}
			Integer prev = last.get(r.tileId);
			if (prev != null && r.current > prev)
			{
				rose.put(r.tileId, now); // first call has no prev → seeds silently, never a false "active"
			}
		}
		for (Map.Entry<Integer, Long> en : rose.entrySet())
		{
			if (now - en.getValue() > ACTIVE_WINDOW_MS || !incompleteById.containsKey(en.getKey()))
			{
				continue;
			}
			if (namedByTile.containsKey(en.getKey()))
			{
				continue; // the server named this tile's teammates (stat tile) — don't add an unnamed one
			}
			Acc a = acc.get(en.getKey());
			if (a != null && a.self)
			{
				continue; // you're already credited on this tile — don't also tag a teammate
			}
			add(acc, incompleteById, en.getKey(), "a teammate", false, en.getValue());
		}
		lastAmounts.put(LOCAL_INSTANCE_ID, current);

		// Newest-active first, capped; "You" leads each row's workers.
		List<Map.Entry<Integer, Acc>> ordered = new ArrayList<>(acc.entrySet());
		ordered.sort((x, y) -> Long.compare(y.getValue().recency, x.getValue().recency));
		List<ConnectionView.ActiveTask> out = new ArrayList<>();
		for (Map.Entry<Integer, Acc> en : ordered)
		{
			if (out.size() >= MAX_ACTIVE)
			{
				break;
			}
			Acc a = en.getValue();
			List<String> workers = new ArrayList<>();
			if (a.self)
			{
				workers.add("You");
			}
			for (String w : a.workers)
			{
				if (!"You".equals(w))
				{
					workers.add(w);
				}
			}
			out.add(new ConnectionView.ActiveTask(incompleteById.get(en.getKey()), workers, a.self));
		}
		return out;
	}

	/** Per-tile accumulator while fusing signals. */
	private static final class Acc
	{
		final LinkedHashSet<String> workers = new LinkedHashSet<>();
		boolean self;
		long recency;
	}

	private static void add(Map<Integer, Acc> acc, Map<Integer, ClogTaskModel.TaskRow> incompleteById,
		int tileId, String worker, boolean self, long recency)
	{
		if (worker == null || !incompleteById.containsKey(tileId))
		{
			return;
		}
		Acc a = acc.computeIfAbsent(tileId, k -> new Acc());
		a.workers.add(worker);
		a.self |= self;
		a.recency = Math.max(a.recency, recency);
	}

	/** Incomplete tiles, nearest-to-done first (highest completion fraction), capped at {@link #NEAREST_LIMIT}. */
	private static List<ConnectionView.TileProgressView> nearestTiles(List<ClogTaskModel.TaskRow> rows)
	{
		List<ClogTaskModel.TaskRow> incomplete = new ArrayList<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (!r.isCompleted())
			{
				incomplete.add(r);
			}
		}
		incomplete.sort(Comparator.comparingDouble(AnvilSidebarDataSource::fraction).reversed()
			.thenComparingInt(r -> r.position));

		List<ConnectionView.TileProgressView> out = new ArrayList<>();
		for (int i = 0; i < incomplete.size() && i < NEAREST_LIMIT; i++)
		{
			ClogTaskModel.TaskRow r = incomplete.get(i);
			out.add(new ConnectionView.TileProgressView(r.label, r.current, r.goal, false));
		}
		return out;
	}

	private static double fraction(ClogTaskModel.TaskRow r)
	{
		return r.goal > 0 ? Math.min(1.0, (double) r.current / r.goal) : 0.0;
	}

	/** Parse the server's {@code "yyyy-MM-dd HH:mm:ss"} UTC timestamp to epoch millis, or -1 if unparseable. */
	private static long parseTsMillis(String ts)
	{
		if (ts == null || ts.isEmpty())
		{
			return -1;
		}
		String s = ts.trim().replace(' ', 'T');
		if (s.endsWith("Z"))
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return java.time.LocalDateTime.parse(s).toInstant(java.time.ZoneOffset.UTC).toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}

	private static List<ActivityEntry> toEntries(List<BingoApiClient.ActivityItem> items)
	{
		if (items == null || items.isEmpty())
		{
			return Collections.emptyList();
		}
		List<ActivityEntry> out = new ArrayList<>(items.size());
		for (BingoApiClient.ActivityItem it : items)
		{
			if (it == null)
			{
				continue;
			}
			out.add(new ActivityEntry(it.id, it.ts, it.player, it.tileId, it.tileLabel,
				ActivityEntry.Kind.fromWire(it.kind), it.amount, it.isSelf));
		}
		return out;
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The plugin-side view of {@code GET /api/plugin/federation/state} — the ONE federation read the plugin
 * makes on the <b>site-relay</b> (auto) path ({@code FEDERATION_WIRE.md} §10.2): the home site does broker
 * + inter-site work server-to-server and hands the plugin ready per-clan boards, so the plugin never dials a
 * broker or another clan's site ({@link #verificationUrl} = a self-host's Discord identity proof in the
 * broker's page, §10.3). Immutable/RuneLite-free/unit-testable; {@link #parse} never throws — a bad body yields a {@link #disabled()} sentinel.
 */
public final class FederationState
{
	public final boolean enabled;
	public final boolean connected;
	/** Established federation identity (broker device login done), even with zero remote clans; durable across
	 * reloads. Drives "Disconnect" (a signed-in member isn't re-offered "Connect"); implied by {@link #connected}. */
	public final boolean signedIn;
	public final boolean needsLogin;
	/** Broker device-login page for a self-host home (§10.3), or {@code null}. */
	public final String verificationUrl;
	/** One row per federated clan, ready to render. Never {@code null}. */
	public final List<ConnectionView> clans;

	/** True when the CURRENT in-game account resolved server-side — per-account RSN sharing is offered. */
	public final boolean shareEligible;

	/** Instance ids the current account's RSN is shared with ("Share my RSN"). Never {@code null}. */
	public final java.util.Set<String> sharedInstanceIds;

	public FederationState(boolean enabled, boolean connected, boolean signedIn, boolean needsLogin,
		String verificationUrl, List<ConnectionView> clans)
	{
		this(enabled, connected, signedIn, needsLogin, verificationUrl, clans, false, Collections.emptySet());
	}

	public FederationState(boolean enabled, boolean connected, boolean signedIn, boolean needsLogin,
		String verificationUrl, List<ConnectionView> clans, boolean shareEligible,
		java.util.Set<String> sharedInstanceIds)
	{
		this.enabled = enabled;
		this.connected = connected;
		this.signedIn = signedIn || connected; // connected always implies signed in
		this.needsLogin = needsLogin;
		this.verificationUrl = verificationUrl == null || verificationUrl.isEmpty() ? null : verificationUrl;
		this.clans = clans == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(clans));
		this.shareEligible = shareEligible;
		this.sharedInstanceIds = sharedInstanceIds == null
			? Collections.emptySet()
			: Collections.unmodifiableSet(new java.util.HashSet<>(sharedInstanceIds));
	}

	/** Inert sentinel (federation off, nothing connected, no clans), used when {@code /state} is absent/
	 * unreachable/unparseable or the plugin isn't set up: the sidebar falls back to today's single-home render. */
	public static FederationState disabled()
	{
		return new FederationState(false, false, false, false, null, Collections.emptyList());
	}

	/** "Connect" is offered when federation is on but not yet signed in. Keyed on {@link #signedIn} not
	 * {@link #connected} — a member federated into no other clan is still signed in (gets "Disconnect"). */
	public boolean needsConnect()
	{
		return enabled && !signedIn;
	}

	// ---- Defensive parser limits (§9 payload DoS + §2 length/shape caps) --------------------------
	// All federated input is untrusted (a "trusted" home may relay self-host data): bound size+nesting BEFORE
	// Gson (a JSON bomb exhausts the parser / blows the stack), clamp strings, cap arrays — a hostile /state can only hide federation.

	/** Hard ceiling on the {@code /state} text we will parse (matches the client's byte cap). */
	static final int MAX_JSON_CHARS = 512 * 1024;
	/** Reject JSON nested deeper than this. The real shape is ~6 levels; 32 is a generous JSON-bomb guard. */
	static final int MAX_JSON_DEPTH = 32;
	static final int MAX_STRING = 256;
	/** Array caps — a hostile home can't make the sidebar allocate/render an unbounded list. */
	static final int MAX_CLANS = 64;
	static final int MAX_NEAREST = 64;
	static final int MAX_ACTIVITY = 128;
	static final int MAX_ACTIVE = 64;
	static final int MAX_WORKERS = 32;

	/** Parse a {@code /api/plugin/federation/state} body. Never throws; a null/garbage/oversized/over-nested
	 * body (§9) or per-field surprise degrades to {@link #disabled()} (or as much as parsed) — bad responses
	 * hide federation, never crash the sidebar. */
	public static FederationState parse(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return disabled();
		}
		// §9 parser DoS: bound total size and nesting up front — a JSON bomb must never reach Gson.
		if (json.length() > MAX_JSON_CHARS || !withinDepthLimit(json, MAX_JSON_DEPTH))
		{
			return disabled();
		}
		try
		{
			JsonObject o = new JsonParser().parse(json).getAsJsonObject();
			boolean enabled = boolAt(o, "enabled");
			boolean connected = boolAt(o, "connected");
			boolean signedIn = boolAt(o, "signedIn");
			boolean needsLogin = boolAt(o, "needsLogin");
			String verificationUrl = strAt(o, "verificationUrl");
			boolean shareEligible = boolAt(o, "shareEligible");
			java.util.Set<String> shared = new java.util.HashSet<>();
			List<ConnectionView> clans = new ArrayList<>();
			JsonElement clansEl = o.get("clans");
			if (clansEl != null && clansEl.isJsonArray())
			{
				for (JsonElement el : clansEl.getAsJsonArray())
				{
					if (clans.size() >= MAX_CLANS)
					{
						break;
					}
					if (el != null && el.isJsonObject())
					{
						JsonObject co = el.getAsJsonObject();
						ConnectionView view = parseClan(co);
						if (view != null)
						{
							clans.add(view);
							if (boolAt(co, "shared"))
							{
								shared.add(view.instanceId);
							}
						}
					}
				}
			}
			return new FederationState(enabled, connected, signedIn, needsLogin, verificationUrl, clans,
				shareEligible, shared);
		}
		catch (RuntimeException e)
		{
			return disabled();
		}
	}

	// ---- Per-clan mapping (JSON → the sidebar's ConnectionView) -----------------------------------

	private static ConnectionView parseClan(JsonObject c)
	{
		String id = strAt(c, "id");
		String name = strAt(c, "name");
		if (id.isEmpty() && name.isEmpty())
		{
			return null; // a row with no identity at all — skip it rather than render "(unnamed clan)"
		}
		String eventName = strAt(c, "eventName");
		String error = strAt(c, "error");

		int tilesComplete = 0;
		int tilesTotal = 0;
		List<ConnectionView.TileProgressView> nearest = new ArrayList<>();
		JsonElement boardEl = c.get("board");
		if (boardEl != null && boardEl.isJsonObject())
		{
			JsonObject board = boardEl.getAsJsonObject();
			tilesComplete = intAt(board, "tilesComplete");
			tilesTotal = intAt(board, "tilesTotal");
			JsonElement nearestEl = board.get("nearest");
			if (nearestEl != null && nearestEl.isJsonArray())
			{
				for (JsonElement el : nearestEl.getAsJsonArray())
				{
					if (nearest.size() >= MAX_NEAREST)
					{
						break;
					}
					if (el != null && el.isJsonObject())
					{
						JsonObject t = el.getAsJsonObject();
						nearest.add(new ConnectionView.TileProgressView(
							strAt(t, "name"), intAt(t, "current"), intAt(t, "target"), boolAt(t, "complete")));
					}
				}
			}
		}

		List<ActivityEntry> activity = parseActivity(c.get("activity"));
		List<ConnectionView.ActiveTask> active = parseActive(c.get("active"));

		return new ConnectionView(id, name, eventName.isEmpty() ? null : eventName,
			error.isEmpty() ? null : error, tilesComplete, tilesTotal, nearest,
			AnvilActivityLog.aggregateForDisplay(activity), active, null, false, null, null, null, null, null,
			nullableBool(c, "member"));
	}

	/**
	 * A tri-state boolean field: {@code null} when the home didn't send it (an older site) rather than
	 * {@code false}. Load-bearing for {@code member} — "we weren't told" must not read as "you're a
	 * guest there", which would move the sidebar's landing clan on no evidence at all.
	 */
	private static Boolean nullableBool(JsonObject o, String key)
	{
		try
		{
			JsonElement el = o.get(key);
			// Only a REAL JSON boolean counts. Gson happily coerces a string primitive
			// (getAsBoolean("yes") == false), which would turn a malformed/hostile payload into a
			// confident "you're a guest here" — the one reading that moves the sidebar.
			if (el == null || !el.isJsonPrimitive() || !el.getAsJsonPrimitive().isBoolean())
			{
				return null;
			}
			return el.getAsBoolean();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static List<ActivityEntry> parseActivity(JsonElement el)
	{
		List<ActivityEntry> out = new ArrayList<>();
		if (el == null || !el.isJsonArray())
		{
			return out;
		}
		for (JsonElement e : el.getAsJsonArray())
		{
			if (out.size() >= MAX_ACTIVITY)
			{
				break;
			}
			if (e == null || !e.isJsonObject())
			{
				continue;
			}
			JsonObject a = e.getAsJsonObject();
			// Build via constructor + Kind.fromWire; a direct Gson populate bypasses field normalization + enum casing.
			out.add(new ActivityEntry(strAt(a, "id"), strAt(a, "ts"), nullableStr(a, "player"),
				intAt(a, "tileId"), strAt(a, "tileLabel"), ActivityEntry.Kind.fromWire(strAt(a, "kind")),
				intAt(a, "amount"), boolAt(a, "self")));
		}
		return out;
	}

	private static List<ConnectionView.ActiveTask> parseActive(JsonElement el)
	{
		List<ConnectionView.ActiveTask> out = new ArrayList<>();
		if (el == null || !el.isJsonArray())
		{
			return out;
		}
		for (JsonElement e : el.getAsJsonArray())
		{
			if (out.size() >= MAX_ACTIVE)
			{
				break;
			}
			if (e == null || !e.isJsonObject())
			{
				continue;
			}
			JsonObject a = e.getAsJsonObject();
			List<String> workers = new ArrayList<>();
			JsonElement w = a.get("workers");
			if (w != null && w.isJsonArray())
			{
				for (JsonElement wn : w.getAsJsonArray())
				{
					if (workers.size() >= MAX_WORKERS)
					{
						break;
					}
					if (wn != null && wn.isJsonPrimitive())
					{
						String name = clamp(wn.getAsString());
						if (!name.isEmpty())
						{
							workers.add(name);
						}
					}
				}
			}
			boolean self = boolAt(a, "self");
			// Row only reads label/current/goal/tileId; Type is render-irrelevant, so STAT is a placeholder.
			ClogTaskModel.TaskRow tile = new ClogTaskModel.TaskRow(
				intAt(a, "tileId"), strAt(a, "label"), ClogTaskModel.Type.STAT,
				intAt(a, "current"), intAt(a, "goal"), -1);
			out.add(new ConnectionView.ActiveTask(tile, workers, self));
		}
		return out;
	}

	// ---- JSON helpers (tolerant; a missing/typed-wrong field is its zero value) -------------------

	private static boolean boolAt(JsonObject o, String key)
	{
		try
		{
			JsonElement el = o.get(key);
			return el != null && el.isJsonPrimitive() && el.getAsBoolean();
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private static int intAt(JsonObject o, String key)
	{
		try
		{
			JsonElement el = o.get(key);
			return el != null && el.isJsonPrimitive() ? el.getAsInt() : 0;
		}
		catch (RuntimeException e)
		{
			return 0;
		}
	}

	private static String strAt(JsonObject o, String key)
	{
		JsonElement el = o.get(key);
		return el != null && el.isJsonPrimitive() ? clamp(el.getAsString()) : "";
	}

	/** Clamp a federated string to {@link #MAX_STRING} chars (§2 length caps); null → "". */
	private static String clamp(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.length() <= MAX_STRING ? s : s.substring(0, MAX_STRING);
	}

	/** §9 JSON-bomb guard: one O(n) pass over the raw text, run <b>before</b> Gson, rejecting the moment
	 * nesting exceeds {@code maxDepth} so a deep body can't overflow the recursive parser. Skips string literals. */
	static boolean withinDepthLimit(String json, int maxDepth)
	{
		int depth = 0;
		boolean inString = false;
		boolean escaped = false;
		for (int i = 0; i < json.length(); i++)
		{
			char ch = json.charAt(i);
			if (inString)
			{
				if (escaped)
				{
					escaped = false;
				}
				else if (ch == '\\')
				{
					escaped = true;
				}
				else if (ch == '"')
				{
					inString = false;
				}
				continue;
			}
			if (ch == '"')
			{
				inString = true;
			}
			else if (ch == '{' || ch == '[')
			{
				if (++depth > maxDepth)
				{
					return false;
				}
			}
			else if (ch == '}' || ch == ']')
			{
				if (depth > 0)
				{
					depth--;
				}
			}
		}
		return true;
	}

	/** Like {@link #strAt} but returns {@code null} (not "") for an absent/blank value — for {@code player}. */
	private static String nullableStr(JsonObject o, String key)
	{
		String s = strAt(o, key);
		return s.isEmpty() ? null : s;
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Immutable UI view-model for one connected clan/instance in the sidebar ({@link AnvilSidebarPanel}),
 * folding the {@code /meta} + {@code /board} reads (see {@code FEDERATION_WIRE.md} §7). RuneLite-free so
 * it's unit-testable and the panel binds to this shape, not an HTTP client; value-object style like
 * {@link ClogTaskModel.TaskRow}.
 */
public final class ConnectionView
{
	/**
	 * Milli-hours per hour. EHP/EHB weeklies travel as hours × 1000 (the site's EFFICIENCY_SCALE) so a
	 * week's gain survives the integer columns it's stored in — divide before showing one.
	 */
	static final double EFFICIENCY_SCALE = 1000.0;

	/** Compact count for display: {@code 1.2M} / {@code 340K} / {@code 850}. */
	static String formatCount(long n)
	{
		if (n >= 1_000_000)
		{
			double m = n / 1_000_000.0;
			return (m == Math.floor(m) ? String.valueOf((int) m) : String.format(java.util.Locale.ROOT, "%.1f", m)) + "M";
		}
		if (n >= 10_000)
		{
			return (n / 1000) + "K";
		}
		return String.valueOf(n);
	}

	/** Stable instance id ({@code federation_instance_id}) — the selection key. */
	public final String instanceId;

	/** Human clan/instance name — the label shown in the clan filter. */
	public final String clanName;

	/** Active event name, or {@code null} when there's no live event. */
	public final String eventName;

	/** Per-connection error, or {@code null} when reached cleanly — lets one home fail inline while siblings render. */
	public final String error;

	/** Tiles your team has completed on this board. */
	public final int tilesComplete;

	/** Total tiles on this board. */
	public final int tilesTotal;

	/** Tiles closest to completion, ordered nearest-first by the data source. Never {@code null}. */
	public final List<TileProgressView> nearestTiles;

	/** Newest-first team activity feed (the {@link AnvilActivityLog} snapshot). Never {@code null}. */
	public final List<ActivityEntry> recentActivity;

	/** Tiles being actively worked right now — yours and teammates', deduped by tile. Never {@code null}. */
	public final List<ActiveTask> activeNow;

	/** Site page to open for this board ({@code <baseUrl>/events/<id>}), or {@code null} when unknown. */
	public final String boardUrl;

	/**
	 * True when this board is scored by summed tile POINTS (Leagues — {@code scoringMode=points})
	 * rather than tile count. When set, {@link #tilesComplete}/{@link #tilesTotal} hold earned/total
	 * points and {@link #unitNoun()} reads "pts". Classic bingo + tile race stay count-based ("tiles").
	 */
	public final boolean pointsScored;

	/**
	 * Benign inline status for a board-less card ({@code tilesTotal == 0}) — e.g. the logged-out home's
	 * "Log in in-game to load your board." Unlike {@link #error} it never marks the clan filter with
	 * "(!)". {@code null} → the panel's generic "No active event yet." line.
	 */
	public final String statusNote;

	/**
	 * Reveal-policy boards (showdown / lucky draw / bounty) only: the one-line "still hidden" status
	 * rendered under the board summary — e.g. {@code "🙈 4 tiles hidden · next 19:00"} or
	 * {@code "🎯 4 bounties left · next on claim"}. {@code null} on classic boards (no line).
	 */
	public final String revealNote;

	/**
	 * Ladder events (DMM-All-Stars-style missions board): the live countdown target, the caller's rank,
	 * and the active missions with their face points + reveal times. {@code null} on every non-ladder
	 * board — the panel renders the normal summary + {@link #revealNote} instead. See {@link LadderMissions}
	 * for the per-second value/countdown math this feeds.
	 */
	public final Ladder ladder;

	/**
	 * Live weekly competitions on this clan (SOTW/BOTW) — events in their own right alongside the board,
	 * so a clan running only a weekly still has something to show. The panel lists them next to the board
	 * and drills into one on click. Never {@code null}; empty on federated clans (the wire carries boards only).
	 */
	public final List<WeeklyView> weeklies;

	/**
	 * Other bingo events on this clan's schedule — starting soon, or live but not the caller's own
	 * board. Listed after the live stuff so members can see what's coming without leaving the game.
	 * Never {@code null}; empty on federated clans.
	 */
	public final List<ScheduledView> scheduled;

	/**
	 * Is the playing account a real member of this clan, or just a federation guest?
	 * {@code TRUE} member · {@code FALSE} guest · {@code null} <b>unknown</b> — logged out, or a home
	 * that predates the wire's {@code member} field. Deliberately tri-state: the panel only moves its
	 * landing clan off the configured home on POSITIVE evidence both ways (guest here, member there),
	 * so an old site or a login screen keeps today's behaviour instead of guessing.
	 */
	public final Boolean member;

	/** Canonical constructor — the live layer (feed + active tasks) alongside the board summary. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow, null, false);
	}

	/** As canonical, plus {@link #boardUrl} + {@link #pointsScored}. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow, boardUrl, pointsScored, null);
	}

	/** As above, plus {@link #statusNote}. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow, boardUrl, pointsScored, statusNote, null);
	}

	/** As above, plus {@link #revealNote}; delegates to the full base with no ladder view. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote, String revealNote)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow, boardUrl, pointsScored, statusNote, revealNote, null);
	}

	/** As above, plus {@link #ladder}; delegates to the full base with no weeklies. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote, String revealNote, Ladder ladder)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow, boardUrl, pointsScored, statusNote, revealNote, ladder, null, null, null);
	}

	/** As above, plus the clan's other events ({@link #weeklies}, {@link #scheduled}) and {@link #member}.
	 *  The base that sets every field. */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow, String boardUrl, boolean pointsScored,
		String statusNote, String revealNote, Ladder ladder, List<WeeklyView> weeklies,
		List<ScheduledView> scheduled, Boolean member)
	{
		this.instanceId = instanceId == null ? "" : instanceId;
		this.clanName = clanName == null || clanName.isEmpty() ? "(unnamed clan)" : clanName;
		this.eventName = eventName;
		this.error = error;
		this.tilesComplete = Math.max(0, tilesComplete);
		this.tilesTotal = Math.max(0, tilesTotal);
		this.nearestTiles = copyOrEmpty(nearestTiles);
		this.recentActivity = copyOrEmpty(recentActivity);
		this.activeNow = copyOrEmpty(activeNow);
		this.boardUrl = boardUrl;
		this.pointsScored = pointsScored;
		this.statusNote = statusNote;
		this.revealNote = revealNote;
		this.ladder = ladder;
		this.weeklies = copyOrEmpty(weeklies);
		this.scheduled = copyOrEmpty(scheduled);
		this.member = member;
	}

	/** True only on positive evidence that this account is a guest here (never on "we don't know"). */
	public boolean isGuestHere()
	{
		return Boolean.FALSE.equals(member);
	}

	/** True only on positive evidence that this account is a real member here. */
	public boolean isMemberHere()
	{
		return Boolean.TRUE.equals(member);
	}

	/** Healthy connection (no error) with the live layer. */
	public ConnectionView(String instanceId, String clanName, String eventName,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles,
		List<ActivityEntry> recentActivity, List<ActiveTask> activeNow)
	{
		this(instanceId, clanName, eventName, null, tilesComplete, tilesTotal, nearestTiles,
			recentActivity, activeNow);
	}

	/** Board-only connection with a per-connection error (no live layer). */
	public ConnectionView(String instanceId, String clanName, String eventName, String error,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles)
	{
		this(instanceId, clanName, eventName, error, tilesComplete, tilesTotal, nearestTiles, null, null);
	}

	/** Healthy, board-only connection (no error, no live layer). */
	public ConnectionView(String instanceId, String clanName, String eventName,
		int tilesComplete, int tilesTotal, List<TileProgressView> nearestTiles)
	{
		this(instanceId, clanName, eventName, null, tilesComplete, tilesTotal, nearestTiles, null, null);
	}

	private static <T> List<T> copyOrEmpty(List<T> src)
	{
		return src == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(src));
	}

	public boolean hasError()
	{
		return error != null && !error.isEmpty();
	}

	/** Board completion as 0..100, or 0 when the board has no tiles. Points-weighted for Leagues. */
	public int completionPercent()
	{
		return tilesTotal > 0 ? Math.min(100, (int) Math.round(tilesComplete * 100.0 / tilesTotal)) : 0;
	}

	/** The noun for {@link #tilesComplete}/{@link #tilesTotal}: "pts" for a points board, else "tiles". */
	public String unitNoun()
	{
		return pointsScored ? "pts" : "tiles";
	}

	/**
	 * One tile's progress ("nearest tiles" rows) — mirrors the {@code current}/{@code goal} pair used elsewhere
	 * ({@link ClogTaskModel.TaskRow}), so the future {@code /board} binding is a straight copy.
	 */
	public static final class TileProgressView
	{
		public final String name;
		public final int current;
		public final int target;
		public final boolean complete;

		public TileProgressView(String name, int current, int target, boolean complete)
		{
			this.name = name == null ? "" : name;
			this.current = Math.max(0, current);
			this.target = Math.max(0, target);
			// A team-level completion is authoritative even if current < target (a teammate finished it).
			this.complete = complete || (target > 0 && this.current >= target);
		}

		/** Progress as 0..100. An untargeted tile (target ≤ 0) is 100 when complete, else 0. */
		public int percent()
		{
			if (target > 0)
			{
				return Math.min(100, (int) Math.round(current * 100.0 / target));
			}
			return complete ? 100 : 0;
		}
	}

	/**
	 * One tile someone's actively working ("Active now") — the tile's progress ({@link ClogTaskModel.TaskRow})
	 * plus who's on it ({@code "You"} for the local player, teammates by RSN, deduped).
	 */
	public static final class ActiveTask
	{
		public final ClogTaskModel.TaskRow tile;
		/** Distinct workers, "You" first when the local player is among them. Never null/empty. */
		public final List<String> workers;
		public final boolean includesSelf;

		public ActiveTask(ClogTaskModel.TaskRow tile, List<String> workers, boolean includesSelf)
		{
			this.tile = tile;
			this.workers = copyOrEmpty(workers);
			this.includesSelf = includesSelf;
		}

		/** "You", "Kayle", or "You + Kayle" / "You + 2 others" for the row's byline. */
		public String workersLabel()
		{
			if (workers.isEmpty())
			{
				return "";
			}
			if (workers.size() == 1)
			{
				return workers.get(0);
			}
			if (workers.size() == 2)
			{
				return workers.get(0) + " + " + workers.get(1);
			}
			return workers.get(0) + " + " + (workers.size() - 1) + " others";
		}
	}

	/**
	 * One live weekly competition (Skill / Boss of the Week) as the sidebar shows it: the comp itself,
	 * the caller's standing, and the head of the leaderboard. Every display string is derived here so
	 * the panel just renders — and so the shaping is unit-testable without Swing.
	 */
	public static final class WeeklyView
	{
		public final int id;
		public final String title;
		/** {@code "skill"} | {@code "boss"} — picks the kind label and the gain's unit. */
		public final String type;
		/** Raw metric key as the site stores it ({@code "mining"}, {@code "chambers_of_xeric"}). */
		public final String metric;
		/** What the site calls that metric, when it sends one. Read through {@link #metricLabel()}. */
		private final String sentLabel;
		public final String startDate;
		public final String endDate;
		/** True for a comp that hasn't started yet — it has no standings, just a start time. */
		public final boolean upcoming;
		/** Caller's rank, or 0 when they aren't on the board (not enrolled / no gain yet / unknown). */
		public final int yourRank;
		public final long yourGained;
		/** Ranked participants, or 0 when the standings couldn't be read. */
		public final int participants;
		/** Head of the leaderboard, rank order, capped by the source. Never {@code null}. */
		public final List<Standing> top;
		/** The comp's page on the Anvil site ({@code <baseUrl>/weekly/<id>}), or {@code null} when unknown. */
		public final String url;

		public WeeklyView(int id, String title, String type, String metric, String startDate, String endDate,
			int yourRank, long yourGained, int participants, List<Standing> top, String url)
		{
			this(id, title, type, metric, startDate, endDate, false, yourRank, yourGained, participants, top, url);
		}

		public WeeklyView(int id, String title, String type, String metric, String startDate, String endDate,
			boolean upcoming, int yourRank, long yourGained, int participants, List<Standing> top, String url)
		{
			this(id, title, type, metric, null, startDate, endDate, upcoming, yourRank, yourGained,
				participants, top, url);
		}

		public WeeklyView(int id, String title, String type, String metric, String sentLabel, String startDate,
			String endDate, boolean upcoming, int yourRank, long yourGained, int participants,
			List<Standing> top, String url)
		{
			this.sentLabel = sentLabel;
			this.id = id;
			this.title = title == null || title.isEmpty() ? kindLabel(type) : title;
			this.type = type == null ? "" : type;
			this.metric = metric == null ? "" : metric;
			this.startDate = startDate;
			this.endDate = endDate;
			this.upcoming = upcoming;
			this.yourRank = Math.max(0, yourRank);
			this.yourGained = Math.max(0, yourGained);
			this.participants = Math.max(0, participants);
			this.top = copyOrEmpty(top);
			this.url = url;
		}

		/** True for an EHP/EHB comp — ranked by efficient hours, not one skill's XP or one boss's KC. */
		public boolean isEfficiency()
		{
			return "efficiency".equalsIgnoreCase(type);
		}

		/**
		 * "Skill of the Week" / "Boss of the Week" / "Efficiency of the Week" — the card's kind line and
		 * the list row's subtitle. Public so the callers that hold only a raw type string (the clog tab's
		 * leaderboard + schedule, the login greeting) name a comp the same way this card does.
		 */
		public String kindLabel()
		{
			return kindLabel(type);
		}

		public static String kindLabel(String type)
		{
			if ("skill".equalsIgnoreCase(type))
			{
				return "Skill of the Week";
			}
			// Efficiency comps are a THIRD type, not a fallback: matching only "skill" and letting
			// everything else read as boss labelled every EHP/EHB week "Boss of the Week".
			return "efficiency".equalsIgnoreCase(type) ? "Efficiency of the Week" : "Boss of the Week";
		}

		/** The tracked metric, spelled for a person: {@code "phosanisNightmare"} → "Phosani's Nightmare". */
		public String metricLabel()
		{
			return metricLabel(type, metric, sentLabel);
		}

		/**
		 * The site's own name for the metric, falling back to what the key can be made to look like.
		 *
		 * <p>Prefer what was sent, always. Boss keys are hiscores keys, and no amount of splitting
		 * "phosanisNightmare" recovers the apostrophe in "Phosani's Nightmare" or turns
		 * "chambersOfXericChallengeMode" into the clan's "CoX: CM". The fallback exists for sites
		 * older than the field, not as an equal option.
		 */
		public static String metricLabel(String type, String metric, String sentLabel)
		{
			if (sentLabel != null && !sentLabel.trim().isEmpty())
			{
				return sentLabel.trim();
			}
			return metricLabel(type, metric);
		}

		public static String metricLabel(String type, String metric)
		{
			// "ehp"/"ehb" are initialisms — humanise would title-case them to "Ehp".
			return "efficiency".equalsIgnoreCase(type)
				? (metric == null ? "" : metric.toUpperCase(java.util.Locale.ROOT))
				: humanise(metric);
		}

		/** What a gain counts in: XP for a skill comp, kills for a boss one, hours for EHP/EHB. */
		public String unitNoun()
		{
			return unitNoun(type);
		}

		public static String unitNoun(String type)
		{
			if ("efficiency".equalsIgnoreCase(type))
			{
				return "hrs";
			}
			return "skill".equalsIgnoreCase(type) ? "xp" : "kc";
		}

		/** A gain as the UI shows it — "1.2M xp", "184 kc", "12.40 hrs". */
		public String formatGain(long gained)
		{
			return formatGain(type, gained);
		}

		public static String formatGain(String type, long gained)
		{
			long safe = Math.max(0, gained);
			return formatGainValue(type, safe) + " " + unitNoun(type);
		}

		/** The number alone, for callers that place the unit themselves. */
		public static String formatGainValue(String type, long gained)
		{
			long safe = Math.max(0, gained);
			// Efficiency comps travel in MILLI-hours (the site's EFFICIENCY_SCALE): the weekly's
			// integer columns would round 12.4 EHB down to 12 and throw away most of a week's gain.
			// Rendered raw that arrives as "+12,400 kc".
			return "efficiency".equalsIgnoreCase(type)
				? String.format(java.util.Locale.ROOT, "%.2f", safe / EFFICIENCY_SCALE)
				: formatCount(safe);
		}

		/** Underscored/hyphenated metric keys → title case, keeping the small joining words lowercase. */
		static String humanise(String key)
		{
			if (key == null || key.isEmpty())
			{
				return "";
			}
			// Boss keys arrive camel-cased ("phosanisNightmare"), so a split on separators alone left
			// them as one word and title-case made it "PhosanisNightmare" — which is what the in-game
			// banner printed. A word boundary is also lower→upper (and letter→digit, for "theatreOfBlood2").
			String spaced = key.replace('_', ' ').replace('-', ' ')
				.replaceAll("(?<=[a-z0-9])(?=[A-Z])", " ")
				.replaceAll("(?<=[A-Za-z])(?=[0-9])", " ");
			String[] words = spaced.trim().split("\\s+");
			StringBuilder out = new StringBuilder();
			for (int i = 0; i < words.length; i++)
			{
				String w = words[i];
				if (w.isEmpty())
				{
					continue;
				}
				if (out.length() > 0)
				{
					out.append(' ');
				}
				// Case-insensitively, because the camel split hands these over capitalised ("Of").
				boolean small = i > 0 && ("of".equalsIgnoreCase(w) || "the".equalsIgnoreCase(w)
					|| "and".equalsIgnoreCase(w) || "at".equalsIgnoreCase(w));
				out.append(small ? w.toLowerCase(java.util.Locale.ROOT)
					: Character.toUpperCase(w.charAt(0)) + w.substring(1));
			}
			return out.toString();
		}
	}

	/**
	 * A bingo event on the clan's schedule that ISN'T the caller's own board — one starting soon, or a
	 * live one they aren't enrolled in. Read-only: there's no progress to show, so the card is the
	 * pitch (what, when, how big) plus a link to sign up on the site.
	 */
	public static final class ScheduledView
	{
		public final int id;
		public final String title;
		public final String startDate;
		public final String endDate;
		/** True when it's already running (the caller just isn't in it); false = still upcoming. */
		public final boolean live;
		/** Tiles configured, or 0 when the site didn't say. */
		public final int tileCount;
		/**
		 * The site's `boardSize`, whose MEANING depends on the format: N for a classic N×N grid, the
		 * tile COUNT for every list format (Leagues, tile race, ladder). See {@link #squareGrid()}.
		 */
		public final int boardSize;
		public final String format;
		public final String scoringMode;
		/** The event's page on the Anvil site, or {@code null} when the base URL is unknown. */
		public final String url;

		public ScheduledView(int id, String title, String startDate, String endDate, boolean live,
			int tileCount, int boardSize, String format, String scoringMode, String url)
		{
			this.id = id;
			this.title = title == null || title.isEmpty() ? "Bingo" : title;
			this.startDate = startDate;
			this.endDate = endDate;
			this.live = live;
			this.tileCount = Math.max(0, tileCount);
			this.boardSize = Math.max(0, boardSize);
			this.format = format;
			this.scoringMode = scoringMode;
			this.url = url;
		}

		/** "Bingo" / "Bingo (points)" / "Tile race" / "Ladder" — same wording as the in-game schedule. */
		public String kindLabel()
		{
			if (LadderMissions.isLadder(format))
			{
				return "Ladder";
			}
			if ("tilerace".equalsIgnoreCase(format))
			{
				return "Tile race";
			}
			return "points".equalsIgnoreCase(scoringMode) ? "Bingo (points)" : "Bingo";
		}

		/**
		 * Whether {@code boardSize} is a grid SIDE or a tile COUNT.
		 *
		 * <p>Only a classic bingo is square. Every other format — Leagues and its reveal-policy
		 * variants, tile race, ladder — is a task LIST whose boardSize is simply how many tiles it
		 * has, so treating it as a side length turns a 240-task Leagues board into a "240×240"
		 * claim about 57,600 tiles.
		 */
		private boolean squareGrid()
		{
			if (format != null && !format.isEmpty())
			{
				return "bingo".equalsIgnoreCase(format) && !"points".equalsIgnoreCase(scoringMode);
			}
			// A site too old to tell us. Believe the geometry instead: a square board's tile count is
			// its side squared, and anything that doesn't add up is a list.
			return tileCount > 0 && boardSize > 0 && boardSize * boardSize == tileCount;
		}

		/** "5×5 · 25 tiles" for a grid, "240 tiles" for a list, or "" when the site said nothing. */
		public String sizeLabel()
		{
			if (squareGrid())
			{
				// Deliberately NOT derived from boardSize² — a board that is still being authored has
				// fewer tiles than its grid has cells, and the honest thing is to say so.
				String tiles = tileCount > 0 ? tileCount + (tileCount == 1 ? " tile" : " tiles") : "";
				if (boardSize <= 0)
				{
					return tiles;
				}
				return tiles.isEmpty() ? boardSize + "×" + boardSize : boardSize + "×" + boardSize + " · " + tiles;
			}
			// A list: boardSize IS the tile count, so it stands in when the authored count is absent.
			int count = tileCount > 0 ? tileCount : boardSize;
			return count > 0 ? count + (count == 1 ? " tile" : " tiles") : "";
		}
	}

	/** One row of a weekly leaderboard, with the caller's own row flagged. */
	public static final class Standing
	{
		public final int rank;
		public final String rsn;
		public final long gained;
		public final boolean self;

		public Standing(int rank, String rsn, long gained, boolean self)
		{
			this.rank = Math.max(0, rank);
			this.rsn = rsn == null ? "" : rsn;
			this.gained = Math.max(0, gained);
			this.self = self;
		}
	}

	/**
	 * The ladder missions-board view-model for the sidebar card: the countdown target, the caller's
	 * rank (this month + all-time), and the currently-open missions. Display strings (live value,
	 * m:ss countdown) are computed at tick time from these raw values via {@link LadderMissions}.
	 */
	public static final class Ladder
	{
		/** ISO time of the next reveal — the per-second countdown target. Null when none is scheduled. */
		public final String nextRevealAtIso;
		public final int monthRank;      // caller's rank this month; 0 when unranked
		public final long monthPoints;   // caller's points this month
		public final int allTimeRank;    // caller's all-time rank; 0 when unranked
		/** The points ramp (may be null) — lets each mission show a live grow/decay value. */
		public final PluginConfigResponse.Decay decay;
		/** Currently-open missions (revealed, not yet claimed/expired), board order. Never null. */
		public final List<Mission> missions;
		/**
		 * True for a real ladder event, false for an ordinary bingo that merely carries missions.
		 *
		 * Both surface a mission strip — a bingo can drop hidden missions mid-event too, and those
		 * deserve the same countdown and live values rather than being left to show up as "New tile
		 * revealed" lines in the activity feed. Only a ladder REPLACES the board summary with this
		 * card and carries a personal rank; a bingo keeps its board summary and gets the strip
		 * underneath.
		 */
		public final boolean ladderFormat;

		public Ladder(String nextRevealAtIso, int monthRank, long monthPoints, int allTimeRank,
			PluginConfigResponse.Decay decay, List<Mission> missions, boolean ladderFormat)
		{
			this.nextRevealAtIso = nextRevealAtIso;
			this.monthRank = Math.max(0, monthRank);
			this.monthPoints = Math.max(0, monthPoints);
			this.allTimeRank = Math.max(0, allTimeRank);
			this.decay = decay;
			this.missions = copyOrEmpty(missions);
			this.ladderFormat = ladderFormat;
		}

		/** One open mission: its label, face value, and reveal time (for the live grow/decay value). */
		public static final class Mission
		{
			public final int tileId;
			public final String label;
			public final int face;
			public final String revealedAtIso;

			public Mission(int tileId, String label, int face, String revealedAtIso)
			{
				this.tileId = tileId;
				this.label = label == null ? "" : label;
				this.face = Math.max(0, face);
				this.revealedAtIso = revealedAtIso;
			}
		}
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/**
 * Pure (client-free) adapter that turns the plugin's tracked drops + stats into a single,
 * sortable, filterable list of task rows for the in-game collection-log "Bingo" tab.
 *
 * Deliberately has no RuneLite dependencies so it is fully unit-testable. The
 * {@link ClogTabController} renders {@link TaskRow}s into the real collection-log widgets;
 * this class owns only the data shaping (status derivation, filtering, sorting).
 */
public final class ClogTaskModel
{
	private ClogTaskModel() {}

	/** Coarse data shape — drives only the icon fallback (DROP → item icon, STAT → sprite). */
	public enum Type { DROP, STAT }

	/**
	 * Fine-grained tile mechanic, mirroring the web admin's kind filter (standard / skill /
	 * boss / drop / collection / kill / timed / diary / lms / value). Drives the in-clog Type
	 * filter. STANDARD never originates from the plugin config today (manual tiles aren't
	 * synced) but is kept for parity with the web so the cycle order matches.
	 */
	public enum Kind { STANDARD, SKILL, BOSS, DROP, COLLECTION, KILL, PVP, TIMED, DIARY, COMBAT_TASK, LMS, VALUE, GAIN, DEATHLESS }

	public enum Status
	{
		// Order matters: used as the primary sort key so incomplete tasks surface first.
		IN_PROGRESS,
		NOT_STARTED,
		COMPLETED
	}

	/** Status filter options exposed by the in-clog filter bar (Phase 4). */
	public enum StatusFilter { ALL, COMPLETED, IN_PROGRESS, NOT_STARTED }

	/**
	 * Type filter options — ALL plus the seven {@link Kind}s, in the same order the web admin
	 * cycles them. Cycling steps through these on the in-clog "Type" chip.
	 */
	public enum TypeFilter { ALL, STANDARD, SKILL, BOSS, DROP, COLLECTION, KILL, PVP, TIMED, DIARY, COMBAT_TASK, LMS, VALUE, GAIN, DEATHLESS }

	/**
	 * Difficulty-tier bands are no longer hardcoded — the server sends them (admin-configurable) in
	 * the config/board payload. The Tier filter is the selected band's key, or "" for all tiers.
	 * {@link #defaultTierBands()} is the baked-in fallback for older/offline servers.
	 */
	public static List<PluginConfigResponse.TierBand> defaultTierBands()
	{
		List<PluginConfigResponse.TierBand> bands = new ArrayList<>();
		bands.add(tierBand("troll", "Troll", 0));
		bands.add(tierBand("easy", "Easy", 11));
		bands.add(tierBand("medium", "Medium", 100));
		bands.add(tierBand("hard", "Hard", 350));
		bands.add(tierBand("ultra", "Ultra", 700));
		return bands;
	}

	private static PluginConfigResponse.TierBand tierBand(String key, String label, int min)
	{
		PluginConfigResponse.TierBand b = new PluginConfigResponse.TierBand();
		b.key = key;
		b.label = label;
		b.min = min;
		return b;
	}

	/** Served bands with blanks dropped, falling back to the baked-in defaults when empty/null. */
	public static List<PluginConfigResponse.TierBand> tierBandsOrDefault(List<PluginConfigResponse.TierBand> bands)
	{
		if (bands == null)
		{
			return defaultTierBands();
		}
		List<PluginConfigResponse.TierBand> clean = new ArrayList<>();
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b != null && b.key != null && !b.key.isEmpty())
			{
				clean.add(b);
			}
		}
		return clean.isEmpty() ? defaultTierBands() : clean;
	}

	/**
	 * The key of the band a point value falls into — the highest band whose {@code min} it meets,
	 * with the lowest band as the floor. Returns null only when there are no bands.
	 */
	public static String tierKeyOf(int points, List<PluginConfigResponse.TierBand> bands)
	{
		if (bands == null || bands.isEmpty())
		{
			return null;
		}
		PluginConfigResponse.TierBand chosen = null;
		PluginConfigResponse.TierBand lowest = null;
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b == null)
			{
				continue;
			}
			if (lowest == null || b.min < lowest.min)
			{
				lowest = b;
			}
			if (points >= b.min && (chosen == null || b.min >= chosen.min))
			{
				chosen = b;
			}
		}
		if (chosen == null)
		{
			chosen = lowest; // points below every band's min → fall back to the lowest band
		}
		return chosen == null ? null : chosen.key;
	}

	/** Human label for a band key (falls back to "" when not found). */
	public static String tierLabel(String key, List<PluginConfigResponse.TierBand> bands)
	{
		if (key == null || key.isEmpty() || bands == null)
		{
			return "";
		}
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b != null && key.equalsIgnoreCase(b.key))
			{
				return b.label != null ? b.label : b.key;
			}
		}
		return "";
	}

	/** The coarse {@link Type} implied by a {@link Kind} — DROP-family kinds show an item icon. */
	private static Type typeOf(Kind kind)
	{
		return (kind == Kind.DROP || kind == Kind.COLLECTION || kind == Kind.VALUE || kind == Kind.GAIN) ? Type.DROP : Type.STAT;
	}

	/** Default {@link Kind} for the legacy constructors (board previews / tests) that only know Type. */
	private static Kind kindOf(Type type)
	{
		return type == Type.DROP ? Kind.DROP : Kind.SKILL;
	}

	/**
	 * A single renderable task. Immutable. {@code itemId < 0} means "no item icon" (stat tiles);
	 * {@code points} is the tile's Leagues-style reward value (0 when the event isn't points-scored
	 * or the value isn't known to the plugin yet).
	 */
	public static final class TaskRow
	{
		public final int tileId;
		public final String label;
		public final Type type;
		public final Kind kind;
		public final int current;
		public final int goal;
		public final int itemId;
		public final int points;
		public final String description;
		public final String category; // free-text grouping (boss/skill); "" = uncategorised
		public final String skillName; // hiscores skill for SKILL tiles ("mining"); null otherwise
		// Pre-formatted "current/goal" for tiles whose progress isn't a plain count — a cumulative
		// value tile is measured in gp, and "12500000/50000000" is a number nobody reads. Null on
		// every other kind, which means the renderer prints current/goal itself.
		public final String progressText;
		public final Status status;
		// Board position — the within-status-group sort key, so the in-game list mirrors the
		// site's tile order (difficulty sort, shuffle). Set after construction (0 on old
		// servers, where the sort falls through to the label tiebreak — the old behavior).
		public int position;

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId)
		{
			this(tileId, label, type, current, goal, itemId, 0, null, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points)
		{
			this(tileId, label, type, current, goal, itemId, points, null, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description)
		{
			this(tileId, label, type, current, goal, itemId, points, description, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description, String category)
		{
			this(tileId, label, type, current, goal, itemId, points, description, category, false);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted)
		{
			// Legacy entry point (board previews / tests): infer the fine-grained kind from Type.
			this(tileId, label, kindOf(type), current, goal, itemId, points, description, category, forceCompleted);
		}

		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted)
		{
			this(tileId, label, kind, current, goal, itemId, points, description, category, forceCompleted, null);
		}

		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted, String skillName)
		{
			this(tileId, label, kind, current, goal, itemId, points, description, category, forceCompleted,
				skillName, null);
		}

		/** Canonical constructor — callers that know the precise {@link Kind} (e.g. {@link #build}) use this. */
		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted, String skillName, String progressText)
		{
			this.progressText = progressText;
			this.tileId = tileId;
			this.label = label == null ? "" : label;
			this.kind = kind == null ? Kind.STANDARD : kind;
			this.type = typeOf(this.kind);
			this.current = current;
			this.goal = goal;
			this.itemId = itemId;
			this.points = points;
			this.description = description == null ? "" : description;
			this.category = category == null ? "" : category.trim();
			this.skillName = skillName;
			// A team-level completion (any member / manual) is authoritative even when this client's
			// own current < goal — e.g. an individual-mode tile a teammate finished first.
			this.status = forceCompleted ? Status.COMPLETED : statusOf(current, goal);
		}

		public boolean isCompleted()
		{
			return status == Status.COMPLETED;
		}
	}

	/**
	 * Derive completion status from progress. A goal of {@code <= 0} (an untargeted tile)
	 * counts as completed the moment there's any progress, otherwise not-started.
	 */
	public static Status statusOf(int current, int goal)
	{
		if (goal > 0)
		{
			if (current >= goal)
			{
				return Status.COMPLETED;
			}
			return current > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED;
		}
		return current > 0 ? Status.COMPLETED : Status.NOT_STARTED;
	}

	/** Build the full task list from the plugin config (drops + stats). Null-safe. */
	public static List<TaskRow> build(PluginConfigResponse cfg)
	{
		List<TaskRow> rows = new ArrayList<>();
		if (cfg == null)
		{
			return rows;
		}

		java.util.Set<Integer> completed = new java.util.HashSet<>();
		if (cfg.completedTiles != null)
		{
			for (PluginConfigResponse.CompletedTile c : cfg.completedTiles)
			{
				if (c != null)
				{
					completed.add(c.tileId);
				}
			}
		}

		if (cfg.trackedDrops != null)
		{
			for (PluginConfigResponse.TrackedDrop d : cfg.trackedDrops)
			{
				if (d == null)
				{
					continue;
				}
				// A per-item requirement list means "collect each of these" → a COLLECTION tile;
				// otherwise it's a simple drop pool. Mirrors the web's drop-vs-collection split.
				Kind kind = (d.itemRequirements != null && !d.itemRequirements.isEmpty())
					? Kind.COLLECTION : Kind.DROP;
				int current = d.currentAmount;
				int goal = d.requiredAmount;
				boolean done = completed.contains(d.tileId);
				if (kind == Kind.COLLECTION)
				{
					// A collection completes when its SETS are satisfied — not when the summed submission
					// count reaches requiredAmount (the server stores that as a shortest-path total, often
					// 1, so a 3-of-4 rings set read as 3/1 = done). Drive progress off the per-item
					// requirements, their sets, and how the tile says those sets combine.
					int[] pg = collectionProgress(d.itemRequirements, d.groupMode);
					current = pg[0];
					goal = pg[1];
					done = done || pg[2] == 1;
				}
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, kind, current, goal,
					representativeItemId(d), d.points, d.description, d.category, done));
			}
		}

		if (cfg.trackedStats != null)
		{
			for (PluginConfigResponse.TrackedStat s : cfg.trackedStats)
			{
				if (s == null)
				{
					continue;
				}
				// Stat tiles have no inventory item to show; the controller substitutes a
				// skill/boss sprite. -1 signals "no item icon". Category falls back to the stat
				// name (e.g. "zulrah", "mining") so stat tiles group sensibly even without one set.
				String statCategory = (s.category != null && !s.category.trim().isEmpty())
					? s.category : s.statName;
				boolean isBoss = "boss".equalsIgnoreCase(s.statType) || "kc".equalsIgnoreCase(s.statType);
				// statName doubles as the skill identifier ("mining") for the renderer's skill
				// icon; boss tiles carry the server-picked representative item instead.
				addAt(rows, s.position, new TaskRow(s.tileId, s.label, isBoss ? Kind.BOSS : Kind.SKILL, s.currentAmount,
					s.goalAmount, isBoss ? s.itemId : -1, s.points, s.description, statCategory,
					completed.contains(s.tileId), isBoss ? null : s.statName));
			}
		}

		if (cfg.trackedKills != null)
		{
			for (PluginConfigResponse.TrackedKill k : cfg.trackedKills)
			{
				if (k == null)
				{
					continue;
				}
				// No inventory icon for a kill-count tile; the controller shows the stat sprite.
				addAt(rows, k.position, new TaskRow(k.tileId, k.label, Kind.KILL, k.currentAmount, k.requiredAmount, -1,
					k.points, k.description, k.category, completed.contains(k.tileId)));
			}
		}

		if (cfg.trackedPvp != null)
		{
			for (PluginConfigResponse.TrackedPvp p : cfg.trackedPvp)
			{
				if (p == null)
				{
					continue;
				}
				// No inventory icon for a PvP-kill tile; the controller shows the stat sprite.
				addAt(rows, p.position, new TaskRow(p.tileId, p.label, Kind.PVP, p.currentAmount, p.requiredAmount, -1,
					p.points, p.description, p.category, completed.contains(p.tileId)));
			}
		}

		if (cfg.trackedDiaries != null)
		{
			for (PluginConfigResponse.TrackedDiary d : cfg.trackedDiaries)
			{
				if (d == null)
				{
					continue;
				}
				// Diary tiles count completions exactly like kills; no inventory icon.
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, Kind.DIARY, d.currentAmount, d.requiredAmount, -1,
					d.points, d.description, d.category, completed.contains(d.tileId)));
			}
		}

		if (cfg.trackedCombatTasks != null)
		{
			for (PluginConfigResponse.TrackedCombatTask t : cfg.trackedCombatTasks)
			{
				if (t == null)
				{
					continue;
				}
				// Combat Achievement tiles count completions exactly like diaries; no inventory icon.
				addAt(rows, t.position, new TaskRow(t.tileId, t.label, Kind.COMBAT_TASK, t.currentAmount, t.requiredAmount, -1,
					t.points, t.description, t.category, completed.contains(t.tileId)));
			}
		}

		if (cfg.trackedTimed != null)
		{
			for (PluginConfigResponse.TrackedTimed t : cfg.trackedTimed)
			{
				if (t == null)
				{
					continue;
				}
				// Timed tiles are pass/fail (no running count): completed flag drives status; goal 1.
				// The server sends the activity's signature reward as the icon (quiver, capes…).
				boolean done = t.completed || completed.contains(t.tileId);
				addAt(rows, t.position, new TaskRow(t.tileId, t.label, Kind.TIMED, done ? 1 : 0, 1, t.itemId,
					t.points, t.description, t.category, done));
			}
		}

		if (cfg.trackedLms != null)
		{
			for (PluginConfigResponse.TrackedLms l : cfg.trackedLms)
			{
				if (l == null)
				{
					continue;
				}
				// LMS tiles count qualifying games toward requiredAmount, exactly like kills.
				addAt(rows, l.position, new TaskRow(l.tileId, l.label, Kind.LMS, l.currentAmount,
					Math.max(1, l.requiredAmount), -1, l.points, l.description, l.category,
					completed.contains(l.tileId)));
			}
		}

		if (cfg.trackedValues != null)
		{
			for (PluginConfigResponse.TrackedValue v : cfg.trackedValues)
			{
				if (v == null)
				{
					continue;
				}
				// Coins as the icon — a gp-threshold tile has no single representative item.
				boolean done = v.completed || completed.contains(v.tileId);
				if (isTotalValue(v))
				{
					// A cumulative tile ("bank 50m between you") has real progress the server already
					// tracks, and showing it as pass/fail threw that away — the one tile on the board
					// that could say how far along the team was, saying only "not yet". Bars are drawn
					// from current/goal, so those carry the gp (clamped, since a target can exceed an
					// int) while the label gets the readable form.
					int goal = clampGp(v.thresholdGp);
					int current = Math.min(clampGp(v.currentGp), goal);
					addAt(rows, v.position, new TaskRow(v.tileId, v.label, Kind.VALUE, current, goal, COINS_ITEM_ID,
						v.points, v.description, v.category, done, null,
						formatGp(v.currentGp) + "/" + formatGp(v.thresholdGp)));
				}
				else
				{
					// Single-haul tiles are genuinely pass/fail — one qualifying drop or nothing — so
					// there's no partial progress to show and the completed flag drives status.
					addAt(rows, v.position, new TaskRow(v.tileId, v.label, Kind.VALUE, done ? 1 : 0, 1, COINS_ITEM_ID,
						v.points, v.description, v.category, done));
				}
			}
		}

		if (cfg.trackedGains != null)
		{
			for (PluginConfigResponse.TrackedGain g : cfg.trackedGains)
			{
				if (g == null)
				{
					continue;
				}
				// Gain tiles count like kills; the first pool item doubles as the icon.
				int icon = (g.itemIds != null && !g.itemIds.isEmpty() && g.itemIds.get(0) != null)
					? g.itemIds.get(0) : -1;
				addAt(rows, g.position, new TaskRow(g.tileId, g.label, Kind.GAIN, g.currentAmount,
					Math.max(1, g.requiredAmount), icon, g.points, g.description, g.category,
					completed.contains(g.tileId)));
			}
		}

		if (cfg.trackedDeathless != null)
		{
			for (PluginConfigResponse.TrackedDeathless d : cfg.trackedDeathless)
			{
				if (d == null)
				{
					continue;
				}
				// Deathless runs count like kills; the server sends the raid's signature reward icon.
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, Kind.DEATHLESS, d.currentAmount,
					Math.max(1, d.requiredAmount), d.itemId, d.points, d.description, d.category,
					completed.contains(d.tileId)));
			}
		}

		return rows;
	}

	/**
	 * True when a value tile accumulates toward its target rather than needing one qualifying haul.
	 * An older server sends no mode at all, which means single — the only behaviour it had.
	 */
	static boolean isTotalValue(PluginConfigResponse.TrackedValue v)
	{
		return v != null && "total".equalsIgnoreCase(v.mode);
	}

	/**
	 * Squeeze a gp amount into the int the progress bar is drawn from. A gp target is a long because
	 * a clan-wide one can pass 2.1b; the bar only needs the ratio, and both ends clamp together so a
	 * clamped tile still fills at the right rate rather than looking finished early.
	 */
	private static int clampGp(long gp)
	{
		if (gp <= 0)
		{
			return 0;
		}
		return gp > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) gp;
	}

	/**
	 * Short gp for a progress line: 999, 12.5K, 3.4M, 2.15B. Trailing ".0" is dropped so a round
	 * number reads "50M" rather than "50.0M", and the unit is only attached once — this sits in
	 * "12.5M/50M", where repeating it on both sides is noise.
	 */
	static String formatGp(long gp)
	{
		long v = Math.max(0, gp);
		if (v < 1_000)
		{
			return Long.toString(v);
		}
		String unit;
		double scaled;
		if (v < 1_000_000)
		{
			unit = "K";
			scaled = v / 1_000d;
		}
		else if (v < 1_000_000_000L)
		{
			unit = "M";
			scaled = v / 1_000_000d;
		}
		else
		{
			unit = "B";
			scaled = v / 1_000_000_000d;
		}
		// One decimal, but only when it says something — truncated rather than rounded so a tile
		// never reads as finished ("50M/50M") while the server still counts it short.
		double truncated = Math.floor(scaled * 10) / 10d;
		if (truncated == Math.floor(truncated))
		{
			return (long) truncated + unit;
		}
		return String.format(java.util.Locale.ROOT, "%.1f%s", truncated, unit);
	}

	/** Adds the row with its board position stamped — the within-status-group sort key. */
	private static void addAt(List<TaskRow> rows, int position, TaskRow row)
	{
		row.position = position;
		rows.add(row);
	}

	/** Inventory item id for coins — the stand-in icon for loot-value (gp threshold) tiles. */
	static final int COINS_ITEM_ID = 995;

	/**
	 * Pick the icon to show for a drop tile: the first per-item requirement if present,
	 * else the first raw tracked item id, else -1.
	 */
	private static int representativeItemId(PluginConfigResponse.TrackedDrop d)
	{
		if (d.itemRequirements != null && !d.itemRequirements.isEmpty()
			&& d.itemRequirements.get(0) != null)
		{
			return d.itemRequirements.get(0).itemId;
		}
		if (d.itemIds != null && !d.itemIds.isEmpty() && d.itemIds.get(0) != null)
		{
			return d.itemIds.get(0);
		}
		return -1;
	}

	/**
	 * Set-aware collection progress, mirroring the site's lib/collectionSets (which owns the rule and
	 * decides completion server-side — this is the in-game read of the same tile).
	 *
	 * <p>Ungrouped requirements are ALWAYS required. Items sharing a {@code group} form one set, and a
	 * set counts as satisfied once {@code groupRequire} distinct items in it are obtained (0 = all of
	 * them, a full set). {@code groupMode} decides how the sets combine:
	 *
	 * <ul>
	 *   <li>{@code "any"} (default) — the sets are alternatives; satisfying ONE completes the tile.
	 *       Progress reports the set the player is CLOSEST to finishing, so a two-set tile shows real
	 *       progress toward one set instead of the inflated sum across every set.</li>
	 *   <li>{@code "all"} — every set must be satisfied. Progress sums what each set needs, so
	 *       "a unique from each of 4 bosses" reads 2/4 rather than pretending one boss finished it.</li>
	 * </ul>
	 *
	 * <p>Returns {current, goal, done}. An older server sends no groupMode/groupRequire, which lands
	 * on exactly the previous behaviour: OR-ed full sets.
	 */
	static int[] collectionProgress(List<PluginConfigResponse.ItemRequirement> reqs)
	{
		return collectionProgress(reqs, null);
	}

	static int[] collectionProgress(List<PluginConfigResponse.ItemRequirement> reqs, String groupMode)
	{
		List<PluginConfigResponse.ItemRequirement> ungrouped = new ArrayList<>();
		java.util.LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> groups = new java.util.LinkedHashMap<>();
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r == null)
			{
				continue;
			}
			String g = r.group == null ? "" : r.group.trim();
			if (g.isEmpty())
			{
				ungrouped.add(r);
			}
			else
			{
				// Case-insensitive, like the server's grouping — "Duke" and "duke" are one set.
				groups.computeIfAbsent(g.toLowerCase(java.util.Locale.ROOT), k -> new ArrayList<>()).add(r);
			}
		}

		int ungroupedSat = satisfied(ungrouped);
		int ungroupedSize = ungrouped.size();
		if (groups.isEmpty())
		{
			int goal = Math.max(1, ungroupedSize);
			return new int[]{ ungroupedSat, goal, ungroupedSat >= ungroupedSize && ungroupedSize > 0 ? 1 : 0 };
		}

		if ("all".equalsIgnoreCase(groupMode))
		{
			// Every set must be satisfied: the tile's goal is the always-required items plus each set's
			// own requirement, and progress is what's been met toward that, capped per set so a fifth
			// Duke unique can't paper over a missing Leviathan one.
			int sat = ungroupedSat;
			int goal = ungroupedSize;
			boolean allSetsDone = true;
			for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
			{
				int need = requireCount(grp);
				int met = Math.min(satisfied(grp), need);
				sat += met;
				goal += need;
				if (met < need)
				{
					allSetsDone = false;
				}
			}
			return new int[]{ sat, Math.max(1, goal), allSetsDone && ungroupedSat >= ungroupedSize ? 1 : 0 };
		}

		// "any": each set, combined with the always-required items, is one alternative.
		int bestSat = 0;
		int bestGoal = 1;
		int bestRemaining = Integer.MAX_VALUE;
		for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
		{
			int need = requireCount(grp);
			int sat = ungroupedSat + Math.min(satisfied(grp), need);
			int size = ungroupedSize + need;
			if (size <= 0)
			{
				continue;
			}
			if (sat >= size)
			{
				return new int[]{ size, size, 1 }; // this set is satisfied — the tile is complete
			}
			int remaining = size - sat;
			if (remaining < bestRemaining || (remaining == bestRemaining && sat > bestSat))
			{
				bestRemaining = remaining;
				bestSat = sat;
				bestGoal = size;
			}
		}
		return new int[]{ bestSat, Math.max(1, bestGoal), 0 };
	}

	/** How many of these requirements the player has met. */
	private static int satisfied(List<PluginConfigResponse.ItemRequirement> reqs)
	{
		int n = 0;
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r.currentAmount >= Math.max(1, r.requiredAmount))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * How many distinct items a set needs. Rows of a set should agree; if they don't (hand-edited
	 * config) the strictest wins, clamped to the set's size so a stale "any 4 of" on a set that has
	 * since shrunk to 3 items stays satisfiable. Same resolution as the server's.
	 */
	private static int requireCount(List<PluginConfigResponse.ItemRequirement> grp)
	{
		int declared = 0;
		for (PluginConfigResponse.ItemRequirement r : grp)
		{
			if (r.groupRequire > declared)
			{
				declared = r.groupRequire;
			}
		}
		if (declared <= 0)
		{
			declared = grp.size();
		}
		return Math.min(Math.max(1, declared), grp.size());
	}

	/**
	 * Apply the active filters and return a new list (incomplete-first, then by label).
	 * {@code search} is a case-insensitive substring match on the label; null/blank = no
	 * text filter.
	 */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search)
	{
		return filter(rows, statusFilter, typeFilter, search, null, "", null);
	}

	/** As {@link #filter} but also restricts to a category ({@code null}/blank = all categories). */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search, String category)
	{
		return filter(rows, statusFilter, typeFilter, search, category, "", null);
	}

	/**
	 * As {@link #filter} but also restricts to a difficulty tier — {@code tierKey} blank = every
	 * tier; otherwise a tile matches when its points-derived band (per {@code tierBands}) equals it.
	 */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search, String category, String tierKey,
		List<PluginConfigResponse.TierBand> tierBands)
	{
		final String needle = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);
		final StatusFilter sf = statusFilter == null ? StatusFilter.ALL : statusFilter;
		final TypeFilter tf = typeFilter == null ? TypeFilter.ALL : typeFilter;
		final String tier = tierKey == null ? "" : tierKey.trim();
		final String cat = category == null ? "" : category.trim();

		List<TaskRow> out = new ArrayList<>();
		for (TaskRow r : rows)
		{
			if (!matchesStatus(r, sf) || !matchesType(r, tf) || !matchesTier(r, tier, tierBands))
			{
				continue;
			}
			if (!cat.isEmpty() && !hasCategory(r, cat))
			{
				continue;
			}
			if (!needle.isEmpty() && !r.label.toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}
			out.add(r);
		}

		// Actionable first (in progress → not started → completed), then the site's board
		// order within each group — matching however the host sorted or shuffled the board.
		out.sort(Comparator
			.comparingInt((TaskRow r) -> r.status.ordinal())
			.thenComparingInt(r -> r.position)
			.thenComparing(r -> r.label, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static boolean matchesStatus(TaskRow r, StatusFilter sf)
	{
		switch (sf)
		{
			case COMPLETED:
				return r.status == Status.COMPLETED;
			case IN_PROGRESS:
				return r.status == Status.IN_PROGRESS;
			case NOT_STARTED:
				return r.status == Status.NOT_STARTED;
			case ALL:
			default:
				return true;
		}
	}

	private static boolean matchesType(TaskRow r, TypeFilter tf)
	{
		switch (tf)
		{
			case STANDARD:
				return r.kind == Kind.STANDARD;
			case SKILL:
				return r.kind == Kind.SKILL;
			case BOSS:
				return r.kind == Kind.BOSS;
			case DROP:
				return r.kind == Kind.DROP;
			case COLLECTION:
				return r.kind == Kind.COLLECTION;
			case KILL:
				return r.kind == Kind.KILL;
			case PVP:
				return r.kind == Kind.PVP;
			case TIMED:
				return r.kind == Kind.TIMED;
			case DIARY:
				return r.kind == Kind.DIARY;
			case COMBAT_TASK:
				return r.kind == Kind.COMBAT_TASK;
			case LMS:
				return r.kind == Kind.LMS;
			case VALUE:
				return r.kind == Kind.VALUE;
			case GAIN:
				return r.kind == Kind.GAIN;
			case DEATHLESS:
				return r.kind == Kind.DEATHLESS;
			case ALL:
			default:
				return true;
		}
	}

	private static boolean matchesTier(TaskRow r, String tierKey, List<PluginConfigResponse.TierBand> bands)
	{
		if (tierKey == null || tierKey.isEmpty())
		{
			return true;
		}
		return tierKey.equalsIgnoreCase(tierKeyOf(r.points, bands));
	}

	/**
	 * True when one of the row's comma-separated category tags equals {@code cat}
	 * (case-insensitive). A tile can carry several tags (e.g. "Inferno, PvM") and
	 * should surface under every one of them.
	 */
	private static boolean hasCategory(TaskRow r, String cat)
	{
		for (String part : r.category.split(","))
		{
			if (cat.equalsIgnoreCase(part.trim()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Distinct, case-insensitively-deduped category tags present (sorted); blanks excluded.
	 * Comma-separated multi-tag categories contribute each tag individually.
	 */
	public static List<String> categories(List<TaskRow> rows)
	{
		List<String> out = new ArrayList<>();
		for (TaskRow r : rows)
		{
			if (r.category == null || r.category.isEmpty())
			{
				continue;
			}
			for (String part : r.category.split(","))
			{
				String tag = part.trim();
				if (tag.isEmpty())
				{
					continue;
				}
				boolean seen = false;
				for (String c : out)
				{
					if (c.equalsIgnoreCase(tag))
					{
						seen = true;
						break;
					}
				}
				if (!seen)
				{
					out.add(tag);
				}
			}
		}
		out.sort(String.CASE_INSENSITIVE_ORDER);
		return out;
	}

	/** Count completed rows (for the header "{done}/{total}" summary). */
	public static int completedCount(List<TaskRow> rows)
	{
		return completedCount(rows, java.util.Collections.emptySet());
	}

	/** As {@link #completedCount(List)} but excluding optional tiles — they're bonus, off the score. */
	public static int completedCount(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int n = 0;
		for (TaskRow r : rows)
		{
			if (r.isCompleted() && !optionalTileIds.contains(r.tileId))
			{
				n++;
			}
		}
		return n;
	}

	/** Points earned so far (sum of points of completed rows) — the Leagues-style banner number. */
	public static int earnedPoints(List<TaskRow> rows)
	{
		return earnedPoints(rows, java.util.Collections.emptySet());
	}

	/** As {@link #earnedPoints(List)} but excluding optional tiles (bonus tiles don't add to the score). */
	public static int earnedPoints(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int p = 0;
		for (TaskRow r : rows)
		{
			if (r.isCompleted() && !optionalTileIds.contains(r.tileId))
			{
				p += r.points;
			}
		}
		return p;
	}

	/** Total points available across all rows. */
	public static int totalPoints(List<TaskRow> rows)
	{
		return totalPoints(rows, java.util.Collections.emptySet());
	}

	/** As {@link #totalPoints(List)} but excluding optional tiles — they're not part of the denominator. */
	public static int totalPoints(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int p = 0;
		for (TaskRow r : rows)
		{
			if (!optionalTileIds.contains(r.tileId))
			{
				p += r.points;
			}
		}
		return p;
	}

	/** Number of SCORED (non-optional) rows — the count-mode denominator (classic/race "x / y"). */
	public static int scoredCount(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int n = 0;
		for (TaskRow r : rows)
		{
			if (!optionalTileIds.contains(r.tileId))
			{
				n++;
			}
		}
		return n;
	}
}

package com.anvil;

import java.util.List;

/**
 * The single seam between the always-on progress sidebar ({@link AnvilSidebarPanel}) and whatever
 * supplies its data. The panel depends only on this interface, so the multi-home federation layer
 * can drop in the real implementation with <strong>no panel changes</strong>.
 *
 * <p><b>Contract</b></p>
 * <ul>
 *   <li>{@link #fetchConnections()} is <em>blocking</em> — implementations do network I/O. The panel
 *       always calls it off the Swing EDT (via a {@code SwingWorker}) and marshals the result back.</li>
 *   <li>Returns the full set of the member's connected clans/instances, each already shaped as a
 *       {@link ConnectionView} (one {@code /meta} + {@code /board} fold per instance). Order is the
 *       display order of the clan filter.</li>
 *   <li>Never returns {@code null}. An <em>empty</em> list is a valid, distinct state (the member has
 *       no connected clans) and drives the panel's empty view.</li>
 *   <li>A <em>total</em> failure (no reachable homes at all, auth broken, etc.) throws
 *       {@link SidebarDataException}, which drives the panel's error view + retry. A <em>partial</em>
 *       failure (one home down, others fine) is expressed per-connection via
 *       {@link ConnectionView#error} instead — do not throw for that.</li>
 * </ul>
 *
 * <p>Bound to the site-relay {@link FederationSidebarDataSource} over a single-home
 * {@link AnvilSidebarDataSource} delegate (see {@code FEDERATION_WIRE.md} §10).</p>
 */
public interface SidebarDataSource
{
	/**
	 * Fetch every connected clan and its board progress. Blocking; call off the EDT. Never {@code null}.
	 *
	 * @throws SidebarDataException on a total load failure (drives the panel's error state)
	 */
	List<ConnectionView> fetchConnections() throws SidebarDataException;

	/**
	 * As {@link #fetchConnections()}; {@code forceFederationRefresh} marks a member-initiated Refresh, so a
	 * source may bypass whatever it normally throttles — the federated source asks the home to skip its
	 * re-sync throttle, the single-home source re-reads the weekly standings it otherwise caches. Default
	 * ignores the flag (a source with nothing throttled has nothing to bypass).
	 */
	default List<ConnectionView> fetchConnections(boolean forceFederationRefresh) throws SidebarDataException
	{
		return fetchConnections();
	}

	/**
	 * The STARTING SHOT this account still owes on its HOME clan's live event (site lib/startProof),
	 * or {@code null} when nothing is owed — which is the case on every event that doesn't ask for
	 * one, on sites that predate the feature, and the moment one is filed.
	 *
	 * <p>Deliberately NOT a {@link ConnectionView} field: it is about the one home this plugin is
	 * authenticated against, not about each connected clan, and the view's constructors are already
	 * positional enough to make an eighth optional field a hazard.</p>
	 */
	default PluginConfigResponse.StartProof startProof()
	{
		return null;
	}

	/** Take + file the starting shot. No-op where {@link #startProof()} is null. Never blocks the EDT. */
	default void captureStartProof()
	{
	}

	/**
	 * What the panel may DO for one connection, which is not the same question for every clan.
	 *
	 * <p>A roster sync scrapes the clan channel you are standing in, so it is only ever offered for
	 * the clan you are actually a member of — an admin elsewhere still cannot see a roster they
	 * aren't in. A profile sync goes to the site the plugin is authenticated against, so it is
	 * offered for the home clan alone until there is a wire for relaying one.
	 */
	class PanelActions
	{
		public static final PanelActions NONE = new PanelActions(false, false, null);

		/** Show "Sync clan roster": admin, at home, with a readable clan channel. */
		public final boolean canSyncRoster;
		/** Show "Sync profile": the site takes profile data and it's the one we're signed in to. */
		public final boolean canSyncProfile;
		/** Why the roster button is absent, when the reason is worth saying. Null when it isn't. */
		public final String rosterNote;

		public PanelActions(boolean canSyncRoster, boolean canSyncProfile, String rosterNote)
		{
			this.canSyncRoster = canSyncRoster;
			this.canSyncProfile = canSyncProfile;
			this.rosterNote = rosterNote;
		}
	}

	/** Actions available for the clan currently on screen. Never null. */
	default PanelActions actionsFor(String instanceId)
	{
		return PanelActions.NONE;
	}

	/** Push the in-game clan roster to the home site. No-op unless {@code canSyncRoster}. */
	default void syncRoster()
	{
	}

	/** Send this account's collection log + bests to the home site. No-op unless {@code canSyncProfile}. */
	default void syncProfile()
	{
	}

	/** Local banner-sound clips, newest listing each call. Empty when the folder has none. */
	default java.util.List<String> bannerSounds()
	{
		return java.util.Collections.emptyList();
	}

	/** Is this clip in the play cycle? */
	default boolean bannerSoundOn(String clip)
	{
		return false;
	}

	/** Flip one clip in or out of the cycle. */
	default void toggleBannerSound(String clip)
	{
	}

	/** Open the local clips folder — these live on this machine, not on any account. */
	/** Copy the sounds folder's path — hub releases may not open a file manager (see Clipboards). */
	default void copyBannerSoundsPath()
	{
	}

	/** Import a .wav into the local clips folder. */
	default void importBannerSounds()
	{
	}

	/** Total-failure signal for {@link #fetchConnections()} — carries a member-facing message for the error view. */
	class SidebarDataException extends Exception
	{
		public SidebarDataException(String message)
		{
			super(message);
		}

		public SidebarDataException(String message, Throwable cause)
		{
			super(message, cause);
		}
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * How a drop should be *talked about*: was it lucky, was it a long-overdue grind, or is it a rare
 * roll on something worthless?
 *
 * Rarity alone can't answer that. A 1/5000 roll on a player's second kill is a spoon; the same roll
 * at 20,000 kills is the opposite. So everything here is expressed against the kill count: with a
 * per-kill probability p, the share of players who would already hold the drop after kc kills is
 *
 *     P(at least one by now) = 1 - (1 - p)^kc
 *
 * A small share means you beat almost everyone to it (spooned); a large one means you were dry.
 *
 * Pure static logic with no RuneLite dependencies, so it's unit-tested directly (DropLuckTest).
 */
public final class DropLuck
{
	private DropLuck()
	{
	}

	/** Beat ~90% of players to it. */
	private static final double SPOONED_SHARE = 0.10;
	/** Ahead of the pack, but not absurd. */
	private static final double LUCKY_SHARE = 0.35;
	/** Most players already had it by this point — the grind was real. */
	private static final double DRY_SHARE = 0.85;

	/**
	 * A drop this rare that's worth less than this is a punchline, not a prize — the 1/10,000 roll
	 * that hands you a Dragon spear. Above it, it's simply a rare drop.
	 */
	public static final long TROLL_VALUE_CEILING = 250_000L;

	/**
	 * Awards you're GIVEN for finishing something, not rolled for: the cape you get for clearing the
	 * Inferno, the quiver for the Colosseum. Calling these "spooned" reads as an insult to the run,
	 * so the reaction lines are suppressed for them. Substring-matched, lowercased — the same style
	 * as the always-notify allowlist, so "Infernal cape (broken)" still matches.
	 */
	private static final List<String> EARNED_AWARDS = Arrays.asList(
		"infernal cape",
		"fire cape",
		"dizana's quiver",
		"champion's cape",
		"quest point cape",
		"music cape",
		"achievement diary cape",
		"max cape");

	public enum Verdict
	{
		/** Well ahead of the drop rate. */
		SPOONED,
		/** Ahead of the drop rate. */
		LUCKY,
		/** About when you'd expect it. */
		TYPICAL,
		/** Long past due. */
		DRY,
		/** No rate or no kill count — say nothing. */
		UNKNOWN
	}

	/** True when this item is handed out for completing content rather than rolled for. */
	public static boolean isEarnedAward(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		String n = itemName.toLowerCase(Locale.ROOT);
		for (String award : EARNED_AWARDS)
		{
			if (n.contains(award))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Share of players (0..1) who would already hold a drop of probability {@code p} after
	 * {@code kc} kills. Computed as 1-(1-p)^kc, via expm1/log1p so tiny rates don't lose precision.
	 */
	public static double obtainedShare(double p, int kc)
	{
		if (p <= 0 || kc <= 0)
		{
			return 0;
		}
		if (p >= 1)
		{
			return 1;
		}
		// 1 - exp(kc * ln(1-p)); log1p/expm1 keep this accurate for p in the 1e-5 range.
		return -Math.expm1(kc * Math.log1p(-p));
	}

	/** Where this drop sits against the grind. UNKNOWN when either input is missing. */
	public static Verdict classify(Double dropRate, Integer killCount)
	{
		if (dropRate == null || dropRate <= 0 || killCount == null || killCount <= 0)
		{
			return Verdict.UNKNOWN;
		}
		double share = obtainedShare(dropRate, killCount);
		if (share < SPOONED_SHARE)
		{
			return Verdict.SPOONED;
		}
		if (share < LUCKY_SHARE)
		{
			return Verdict.LUCKY;
		}
		if (share >= DRY_SHARE)
		{
			return Verdict.DRY;
		}
		return Verdict.TYPICAL;
	}

	/**
	 * The "Luck" field value, e.g. {@code "Top 8%"} or {@code "Dry — 93% had it by now"}. Null for a
	 * typical or unknown result, which is the common case and shouldn't add a field.
	 */
	public static String luckLabel(Double dropRate, Integer killCount)
	{
		Verdict verdict = classify(dropRate, killCount);
		if (verdict == Verdict.UNKNOWN || verdict == Verdict.TYPICAL)
		{
			return null;
		}
		int pct = (int) Math.max(1, Math.round(obtainedShare(dropRate, killCount) * 100));
		switch (verdict)
		{
			case SPOONED:
				return "Top " + pct + "% — spooned";
			case LUCKY:
				return "Top " + pct + "%";
			case DRY:
				return "Dry — " + pct + "% had it by now";
			default:
				return null;
		}
	}

	/**
	 * A "troll": rare enough to trip the rarity gate, but worth almost nothing. Worth calling out as
	 * a joke rather than dressing up as treasure.
	 *
	 * @param dropRate     per-kill probability, or null when the drop qualified on value alone
	 * @param value        the drop's gp value
	 * @param rarityFloor  1-in-N the drop must beat to count as troll-rare (the clan's rarity floor)
	 */
	public static boolean isTrollDrop(Double dropRate, long value, int rarityFloor)
	{
		if (dropRate == null || dropRate <= 0 || rarityFloor <= 0)
		{
			return false;
		}
		if (value >= TROLL_VALUE_CEILING)
		{
			return false;
		}
		return MathUtils.lessThanOrEqual(dropRate, 1.0 / rarityFloor);
	}

	/**
	 * Whether to append a lucky-drop reaction line. Earned awards never qualify (see
	 * {@link #EARNED_AWARDS}); otherwise it's a genuine spoon against the kill count, or a drop
	 * valuable enough to be a moment regardless of how long it took.
	 */
	public static boolean deservesSpoonLine(String itemName, long value, Double dropRate, Integer killCount, long bigValue)
	{
		if (isEarnedAward(itemName))
		{
			return false;
		}
		if (classify(dropRate, killCount) == Verdict.SPOONED)
		{
			return true;
		}
		// No kill count to judge against (untracked NPC, or the clan hides KC): fall back to value.
		return value >= bigValue;
	}
}

package com.anvil;

import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * Pure, RuneLite-free helpers for the in-game "missions board" of a ladder / rotating event: the live
 * grow-or-decay value of a mission, the per-second countdown to the next reveal, and their display
 * strings. Kept side-effect-free so both surfaces (the Swing sidebar and the collection-log tab) share
 * one implementation and it's unit-testable. No threads, no I/O — just clock math.
 */
final class LadderMissions
{
	private LadderMissions()
	{
	}

	/** True for the ladder format (individual-primary random-task leaderboard). Null/other → false. */
	static boolean isLadder(String format)
	{
		return "ladder".equalsIgnoreCase(format);
	}

	/**
	 * A mission's live value = face scaled by the decay ramp: {@code face * (1 - (1 - target) * frac)},
	 * where {@code target = targetPct/100} and {@code frac} is the elapsed fraction of the ramp window
	 * (0 at reveal → 1 after {@code hours}). {@code targetPct < 100} decays, {@code > 100} grows. Returns
	 * the plain face when there's no decay rule or the reveal time is unknown/unparseable.
	 */
	static long liveValue(long face, String revealedAtIso, PluginConfigResponse.Decay decay, long nowMs)
	{
		if (decay == null || decay.hours <= 0)
		{
			return face;
		}
		long revealedAt = parseUtcMillis(revealedAtIso);
		if (revealedAt < 0)
		{
			return face;
		}
		double target = decay.targetPct / 100.0;
		double frac = Math.min(1.0, Math.max(0.0, (nowMs - revealedAt) / (decay.hours * 3_600_000.0)));
		double value = face * (1.0 - (1.0 - target) * frac);
		return Math.round(Math.max(0.0, value));
	}

	/** True when the live value differs enough from face to be worth showing the "face → current" form. */
	static boolean valueMoved(long face, long current)
	{
		return current != face;
	}

	/**
	 * "120 -> 90" (decay) / "120 -> 200" (grow) when the value has moved, else just "120". ASCII arrow:
	 * the OSRS chat + collection-log widget fonts don't carry Unicode arrows/emoji.
	 */
	static String valueLabel(long face, long current)
	{
		if (current == face)
		{
			return Long.toString(face);
		}
		return face + " -> " + current;
	}

	/**
	 * Per-second countdown to the next reveal: {@code "12:34"} (m:ss), {@code "1:02:03"} (h:mm:ss for
	 * long waits), {@code "now"} once due, or {@code null} when there's no scheduled reveal (e.g. a
	 * bounty board draws on claim, not a clock).
	 */
	static String countdown(String nextRevealAtIso, long nowMs)
	{
		if (nextRevealAtIso == null || nextRevealAtIso.isEmpty())
		{
			return null;
		}
		long at = parseUtcMillis(nextRevealAtIso);
		if (at < 0)
		{
			return null;
		}
		long secs = Math.max(0, (at - nowMs) / 1000);
		if (secs == 0)
		{
			return "now";
		}
		long h = secs / 3600;
		long m = (secs % 3600) / 60;
		long s = secs % 60;
		if (h > 0)
		{
			return h + ":" + two(m) + ":" + two(s);
		}
		return m + ":" + two(s);
	}

	private static String two(long v)
	{
		return v < 10 ? "0" + v : Long.toString(v);
	}

	/**
	 * Parse the server's UTC timestamp — either ISO ({@code 2026-07-29T12:00:00.000Z}) or the
	 * space-separated {@code yyyy-MM-dd HH:mm:ss} SQLite form — to epoch millis, or -1 if unparseable.
	 */
	static long parseUtcMillis(String ts)
	{
		if (ts == null || ts.isEmpty())
		{
			return -1;
		}
		String s = ts.trim().replace(' ', 'T');
		if (s.endsWith("Z"))
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return LocalDateTime.parse(s).toInstant(ZoneOffset.UTC).toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}
}

