package com.anvil;

/**
 * The client-side half of the STARTING SHOT rule (site lib/startProof).
 *
 * <p>Two things the site can ask for beyond the screenshot itself, both of which only this client can
 * answer, and both of which are far more useful checked BEFORE the frame is grabbed than filed and
 * argued about afterwards:
 *
 * <ul>
 *   <li><b>Where you are.</b> A drawn spot the host pinned on the map comes down as coordinates, so
 *       "go to Edgeville bank" stops being an instruction nobody can verify.</li>
 *   <li><b>How old this session is.</b> Hiscores only flush on LOGOUT, so a player who has been
 *       logged in since before the event started has a stale start baseline — every gain they made
 *       beforehand lands in the event's first sweep. Making them log out and back in right before
 *       the shot is what actually stops that, and the screenshot is just the receipt.</li>
 * </ul>
 *
 * <p>Pure and static so it unit-tests without a client: the plugin supplies the numbers.
 */
final class StartProofRules
{
	/** {@code sessionLoginAtMs} when we never saw the login — a plugin enabled mid-session. */
	static final long UNKNOWN_LOGIN = 0L;

	private StartProofRules()
	{
	}

	/**
	 * Squares from the drawn spot, the way OSRS measures "within N squares" — the longer axis, not
	 * the diagonal. -1 when there is nothing to measure (no pin, or no position to compare).
	 */
	static int distance(PluginConfigResponse.StartProof proof, Integer x, Integer y)
	{
		if (proof == null || proof.spot == null || x == null || y == null)
		{
			return -1;
		}
		return Math.max(Math.abs(x - proof.spot.x), Math.abs(y - proof.spot.y));
	}

	/**
	 * Why this shot can't be filed yet, as a sentence for chat — or null when it can.
	 *
	 * <p>Every check fails OPEN: an older site sends no spot and no window, an unpinned location has
	 * no coordinates, and a client that can't read its own position skips the distance test. The
	 * rule only ever blocks on something we positively know is wrong.
	 */
	static String blockReason(
		PluginConfigResponse.StartProof proof,
		long sessionLoginAtMs,
		long nowMs,
		Integer x,
		Integer y)
	{
		if (proof == null)
		{
			return null;
		}

		if (proof.maxSessionMinutes > 0)
		{
			if (sessionLoginAtMs == UNKNOWN_LOGIN)
			{
				// The plugin was switched on (or the client reconnected) mid-session, so we can't
				// vouch for the logout that flushed the hiscores. One relog settles it.
				return "Log out and back in before your starting shot — that's what saves your hiscores"
					+ " so your starting totals are right.";
			}
			long minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
			if (minutes > proof.maxSessionMinutes)
			{
				return "You've been logged in for " + describeMinutes(minutes) + " — log out and back in,"
					+ " then take your starting shot within " + proof.maxSessionMinutes + " min."
					+ " Hiscores only save on logout, so this is what sets your starting totals.";
			}
		}

		int away = distance(proof, x, y);
		if (away >= 0 && away > proof.spot.radius)
		{
			return "You're " + away + " squares from " + (proof.location != null ? proof.location : "the start spot")
				+ " — go there, then take your starting shot.";
		}

		return null;
	}

	/**
	 * How long is left before the site stops asking for a shot, as a sentence fragment — or null
	 * when there is no deadline to quote (an older site that doesn't send one, or an unreadable
	 * stamp). The window closing is not a failure state: the ask simply expires, so this reads as a
	 * countdown rather than a threat.
	 */
	static String describeWindow(PluginConfigResponse.StartProof proof, long nowMs)
	{
		if (proof == null || proof.windowEndsAt == null || proof.windowEndsAt.isEmpty())
		{
			return null;
		}
		long endsMs;
		try
		{
			endsMs = java.time.Instant.parse(proof.windowEndsAt).toEpochMilli();
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
		long minutes = (endsMs - nowMs) / 60_000L;
		return minutes <= 0 ? null : describeMinutes(minutes);
	}

	/** "12 min" / "2h 05m" — a session age a player reads at a glance. */
	static String describeMinutes(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + " min";
		}
		return (minutes / 60) + "h " + String.format("%02dm", minutes % 60);
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Decides what of the collection log is worth sending, and when.
 *
 * <p>The game redraws a log page on every scroll, filter and tab click, so the naive "push what's on
 * screen" would be hundreds of identical requests per session. This keeps a hash per page and only
 * queues one that actually changed, then batches the queue behind a quiet period.
 *
 * <p>The hashes of pages we've already sent are persisted (see {@link #serializeState}), so logging
 * back in and opening the log doesn't re-send a log that hasn't moved. That's the difference between
 * a sync that costs one request a week and one that costs a request a minute forever.
 *
 * <p>RuneLite-free on purpose: the flush policy is the part with edge cases, and this way it's
 * unit-testable without a client. The plugin owns the widget hook, the scheduler and the HTTP.
 */
final class ClogSync
{
	/** Wait this long after the last change before sending — a player paging through settles first. */
	static final long QUIET_MS = 2_500;
	/** Send at most this many pages per request; a full first sync becomes a handful of them. */
	static final int BATCH_PAGES = 25;
	/** Queue this many and go early — a bulk sync shouldn't sit waiting on the quiet timer. */
	private static final int EAGER_AT = BATCH_PAGES;

	/** Last hash we successfully sent, per page name. The persisted half of the state. */
	private final Map<String, Long> sent = new HashMap<>();
	/** Changed pages awaiting a push, newest write wins. Insertion-ordered so batches are stable. */
	private final Map<String, ClogPage> pending = new LinkedHashMap<>();

	private long lastChangeAt;
	private boolean stateLoaded;

	/**
	 * Offer the page currently on screen. Cheap and idempotent — the common case is a hash compare
	 * against what we already sent, and no allocation at all.
	 *
	 * @return true when the page was queued (i.e. it's new or changed)
	 */
	boolean offer(ClogPage page, long now)
	{
		if (page == null || page.name == null || page.name.isEmpty())
		{
			return false;
		}
		Long alreadySent = sent.get(page.name);
		if (alreadySent != null && alreadySent == page.hash)
		{
			return false;
		}
		ClogPage queued = pending.get(page.name);
		if (queued != null && queued.hash == page.hash)
		{
			return false;
		}
		pending.put(page.name, page);
		lastChangeAt = now;
		return true;
	}

	/** Whether a flush should run now: the queue has settled, or it's big enough to go early. */
	boolean isDue(long now)
	{
		if (pending.isEmpty())
		{
			return false;
		}
		return pending.size() >= EAGER_AT || now - lastChangeAt >= QUIET_MS;
	}

	/** Pages to send in the next request, oldest first. Does NOT clear them — see {@link #onSent}. */
	List<ClogPage> nextBatch()
	{
		List<ClogPage> batch = new ArrayList<>(Math.min(BATCH_PAGES, pending.size()));
		for (ClogPage page : pending.values())
		{
			batch.add(page);
			if (batch.size() >= BATCH_PAGES)
			{
				break;
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Only called after the server has accepted it, so a failed push leaves
	 * the pages queued and the next flush retries them — no bookkeeping, no lost pages.
	 */
	void onSent(Collection<ClogPage> batch)
	{
		for (ClogPage page : batch)
		{
			ClogPage queued = pending.get(page.name);
			// Left queued if it changed again while the request was in flight.
			if (queued != null && queued.hash == page.hash)
			{
				pending.remove(page.name);
			}
			sent.put(page.name, page.hash);
		}
	}

	int pendingCount()
	{
		return pending.size();
	}

	/** How many distinct pages we've delivered — the numerator of the "68% synced" nudge. */
	int syncedPages()
	{
		return sent.size();
	}

	boolean hasState()
	{
		return stateLoaded;
	}

	/** Forget everything. Called when the account changes — one player's log is not another's. */
	void reset()
	{
		sent.clear();
		pending.clear();
		lastChangeAt = 0;
		stateLoaded = false;
	}

	/**
	 * The sent-hash map as one config string: {@code <hex hash>|<page name>} per line.
	 *
	 * <p>Hash first, split on the first pipe: page names contain colons ("Chambers of Xeric:
	 * Challenge Mode") and spaces, so a name-first format would need escaping. A hex hash can't
	 * contain a pipe, which makes the parse total.
	 */
	String serializeState()
	{
		StringBuilder out = new StringBuilder(sent.size() * 24);
		for (Map.Entry<String, Long> e : sent.entrySet())
		{
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('\n');
			}
			out.append(Long.toHexString(e.getValue())).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/** Restore from {@link #serializeState}. Junk lines are skipped, never fatal. */
	void restoreState(String raw)
	{
		sent.clear();
		stateLoaded = true;
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		for (String line : raw.split("\n"))
		{
			int pipe = line.indexOf('|');
			if (pipe <= 0 || pipe == line.length() - 1)
			{
				continue;
			}
			try
			{
				sent.put(line.substring(pipe + 1), Long.parseUnsignedLong(line.substring(0, pipe), 16));
			}
			catch (NumberFormatException e)
			{
				// A truncated or hand-edited config line: drop it and re-sync that page.
			}
		}
	}
}

package com.anvil;

import java.net.URI;
import java.net.URISyntaxException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * The <b>site-relay</b> sidebar data source — the plugin's only federation path
 * ({@code FEDERATION_WIRE.md} §10). Its entire federation footprint is its own home site: it polls
 * {@code GET /api/plugin/federation/state} (rendering the per-clan boards the site shaped) and connects via
 * {@code POST /api/plugin/federation/connect}, never contacting a broker or another clan's site (all
 * server-to-server). Off/no-clans → single-home render ({@link #delegate}, {@link AnvilSidebarDataSource}), byte-for-byte today's sidebar; the self-host {@code /connect} login opens the broker's page then polls {@code /state}.
 */
@Slf4j
public class FederationSidebarDataSource implements SidebarDataSource, FederationStatusSource
{
	/** Opens a URL in the member's system browser (RuneLite {@link LinkBrowser}); swapped for a no-op in tests. */
	@FunctionalInterface
	public interface BrowserOpener
	{
		boolean open(String url);
	}

	/** Schedules each connect-flow step off the EDT; production binds the shared RuneLite
	 * {@link ScheduledExecutorService}, tests run the step inline. */
	@FunctionalInterface
	public interface PollScheduler
	{
		void schedule(Runnable step, long delayMs);
	}

	/** §8 anti-phishing — the ONE broker fact the plugin keeps: the pinned Anvil broker host, used <b>only</b> to
	 * validate a self-host {@code verificationUrl} before opening it in the member's browser. The plugin never dials
	 * the broker (all traffic server-to-server); a rogue home's fake login URL on another host is refused. */
	static final String PINNED_BROKER_HOST = "anvilosrs.com";

	/** §8 path pin: the ONLY broker page the plugin will ever open — the device-login page. */
	static final String PINNED_BROKER_LOGIN_PATH = "/federation/device";

	/** How long to wait between {@code /state} polls while a self-host Discord login is in the browser. */
	private static final long LOGIN_POLL_INTERVAL_MS = 3_000L;

	/** Cap on the login poll loop (~2 min) so a browser the member never finishes doesn't spin forever. */
	private static final int LOGIN_POLL_MAX_ATTEMPTS = 40;

	private final BingoApiClient apiClient;

	/** The single-home render — a direct {@link AnvilSidebarDataSource} over the plugin's own live config. */
	private final SidebarDataSource delegate;

	private final BrowserOpener browserOpener;
	private final PollScheduler scheduler;

	/** Last {@code /state} seen (or a disabled sentinel) — read by the panel for the connect affordance. */
	private volatile FederationState lastState = FederationState.disabled();

	/** Production binding — real system browser + delayed steps on the shared client executor. */
	public FederationSidebarDataSource(BingoApiClient apiClient, SidebarDataSource delegate,
		ScheduledExecutorService executor)
	{
		this(apiClient, delegate, FederationSidebarDataSource::browseWithLinkBrowser,
			(step, delayMs) -> executor.schedule(step, delayMs, TimeUnit.MILLISECONDS));
	}

	/** Test seam — injectable browser opener + scheduler so the connect/login flow runs offline and fast. */
	FederationSidebarDataSource(BingoApiClient apiClient, SidebarDataSource delegate,
		BrowserOpener browserOpener, PollScheduler scheduler)
	{
		this.apiClient = apiClient;
		this.delegate = delegate;
		this.browserOpener = browserOpener;
		this.scheduler = scheduler;
	}

	private static boolean browseWithLinkBrowser(String url)
	{
		LinkBrowser.browse(url);
		return true;
	}

	@Override
	public List<ConnectionView> fetchConnections() throws SidebarDataException
	{
		return fetchConnections(false);
	}

	// The starting shot belongs to the HOME clan we're authenticated against — federation relays a
	// view of other clans' boards, never an obligation on this account — so both halves pass straight
	// through to the single-home delegate.
	@Override
	public PluginConfigResponse.StartProof startProof()
	{
		return delegate.startProof();
	}

	@Override
	public void captureStartProof()
	{
		delegate.captureStartProof();
	}

	// Panel actions belong to the HOME clan — the roster comes from the channel this account is in,
	// and the profile goes to the site it is signed in to. The delegate answers for both, and for a
	// relayed clan it answers "neither", which is the truth rather than a disabled-looking button.
	@Override
	public PanelActions actionsFor(String instanceId)
	{
		return delegate.actionsFor(instanceId);
	}

	@Override
	public void syncRoster()
	{
		delegate.syncRoster();
	}

	@Override
	public void syncProfile()
	{
		delegate.syncProfile();
	}

	@Override
	public java.util.List<String> bannerSounds()
	{
		return delegate.bannerSounds();
	}

	@Override
	public boolean bannerSoundOn(String clip)
	{
		return delegate.bannerSoundOn(clip);
	}

	@Override
	public void toggleBannerSound(String clip)
	{
		delegate.toggleBannerSound(clip);
	}

	@Override
	public void copyBannerSoundsPath()
	{
		delegate.copyBannerSoundsPath();
	}

	@Override
	public void importBannerSounds()
	{
		delegate.importBannerSounds();
	}

	@Override
	public List<ConnectionView> fetchConnections(boolean forceFederationRefresh) throws SidebarDataException
	{
		FederationState state = apiClient.fetchFederationState(forceFederationRefresh);
		lastState = state != null ? state : FederationState.disabled();
		if (state == null || !state.enabled || state.clans.isEmpty())
		{
			// Federation off / absent / no clans yet → single-home render (today's default, unchanged).
			// The flag rides along: the home render throttles its own reads (weekly standings) and a
			// member-initiated Refresh should bypass those too.
			return delegate.fetchConnections(forceFederationRefresh);
		}
		// Federated: HOME FIRST, then the relayed clans. Returning only `state.clans` here made the
		// member's own board vanish the moment a second clan appeared (and with one remote clan the
		// panel's clan filter never showed). The home render must stay the rich local one (nearest
		// tiles, live feed) — the site-shaped federated entries only cover the OTHER homes.
		List<ConnectionView> merged = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		try
		{
			for (ConnectionView home : delegate.fetchConnections(forceFederationRefresh))
			{
				merged.add(home);
				if (home.instanceId != null)
				{
					seen.add(home.instanceId);
				}
			}
		}
		catch (SidebarDataException e)
		{
			// A broken home must not blank the whole panel when the federated clans ARE renderable.
			log.warn("home sidebar fetch failed; rendering federated clans only", e);
		}
		for (ConnectionView clan : state.clans)
		{
			if (clan.instanceId == null || seen.add(clan.instanceId))
			{
				merged.add(clan);
			}
		}
		return merged;
	}

	@Override
	public FederationState federationStatus()
	{
		return lastState;
	}

	@Override
	public void connectFederation(Consumer<String> status, Consumer<ConnectOutcome> done)
	{
		// The first step runs on the executor too — the /connect POST is network I/O, keep it off the EDT.
		schedule(() -> startConnect(status, done), 0, status, done);
	}

	/** The §10.2 handshake: {@code POST /connect}; a self-host login opens the browser then schedules
	 * {@code /state} polls. Runs on the executor. */
	private void startConnect(Consumer<String> status, Consumer<ConnectOutcome> done)
	{
		notify(status, "Connecting…");
		BingoApiClient.FederationConnect result = apiClient.federationConnect();
		if (result.connected)
		{
			refreshState();
			notify(status, "Connected.");
			finish(done, ConnectOutcome.CONNECTED);
			return;
		}
		if (result.login && result.verificationUrl != null)
		{
			// §8 anti-phishing: this login opens in the member's browser, so a rogue home could hand back a
			// fake Discord-login URL. Only open HTTPS on the pinned Anvil broker host; refuse anything else.
			if (!isPinnedBrokerUrl(result.verificationUrl))
			{
				log.warn("refusing to open a verification URL that isn't the Anvil broker: {}", result.verificationUrl);
				notify(status, "Login blocked — that login page isn't on the Anvil broker.");
				finish(done, ConnectOutcome.UNAVAILABLE);
				return;
			}
			// Self-host Discord login runs on the BROKER's own page in the member's browser; the plugin only
			// polls its home /state back to connected (no broker traffic). Hand the page the code PREFILLED
			// (RFC 8628 verification_uri_complete) off the already-pinned base, so it stays on the broker (§8).
			openInBrowser(withUserCode(result.verificationUrl, result.userCode));
			// Still SHOW the code: the member confirms it matches, and it's the fallback if the browser drops the query.
			notify(status, result.userCode != null
				? "Opening your browser — confirm code " + result.userCode + " and sign in with Discord."
				: "Finish the login in your browser…");
			pollLogin(status, done, 0, false);
			return;
		}
		notify(status, "Federation isn't available right now.");
		finish(done, ConnectOutcome.UNAVAILABLE);
	}

	/**
	 * One scheduled {@code /state} poll (NOT the rate-limited {@code /connect}): its server-side
	 * advanceSelfHost drives the broker device-poll to completion, so {@code /state} both advances AND
	 * observes the login. Terminal: connected (≥1 clan), or resolved with the member in NO other clan
	 * (login OK but nothing to attach to). {@code sawPending} = an earlier poll saw {@code needsLogin}.
	 */
	private void pollLogin(Consumer<String> status, Consumer<ConnectOutcome> done, int attempt, boolean sawPending)
	{
		if (attempt >= LOGIN_POLL_MAX_ATTEMPTS)
		{
			notify(status, "Still waiting on the browser login — try Connect again.");
			finish(done, ConnectOutcome.LOGIN_PENDING);
			return;
		}
		schedule(() ->
		{
			FederationState s = refreshState();
			if (s.connected)
			{
				notify(status, "Connected.");
				finish(done, ConnectOutcome.CONNECTED);
				return;
			}
			// Site still needs the browser login → member hasn't finished; note pending to recognise it resolving.
			if (s.enabled && s.needsLogin)
			{
				pollLogin(status, done, attempt + 1, true);
				return;
			}
			// Was pending, now on + no login needed + not connected → login done, member in no OTHER clan. Success.
			if (sawPending && s.enabled && !s.needsLogin)
			{
				notify(status, "Signed in — no other Anvil clans are linked to yours yet.");
				finish(done, ConnectOutcome.CONNECTED);
				return;
			}
			pollLogin(status, done, attempt + 1, sawPending);
		}, LOGIN_POLL_INTERVAL_MS, status, done);
	}

	/** Schedule a flow step; an escaped {@link RuntimeException} would otherwise vanish inside the
	 * executor, so surface it as the terminal failure the old blocking flow reported. */
	private void schedule(Runnable step, long delayMs, Consumer<String> status, Consumer<ConnectOutcome> done)
	{
		scheduler.schedule(() ->
		{
			try
			{
				step.run();
			}
			catch (RuntimeException e)
			{
				log.debug("site-relay connect flow failed", e);
				notify(status, "Connect failed — try again.");
				finish(done, ConnectOutcome.UNAVAILABLE);
			}
		}, delayMs);
	}

	private static void finish(Consumer<ConnectOutcome> done, ConnectOutcome outcome)
	{
		if (done != null)
		{
			done.accept(outcome);
		}
	}

	@Override
	public boolean disconnectFederation()
	{
		boolean ok = apiClient.federationDisconnect();
		// Re-read /state either way so cached status reflects server truth (signedIn now false); panel re-offers "Connect".
		refreshState();
		return ok;
	}

	/** Force a fresh {@code /state} read and cache it, so the panel's status reflects the newest server truth. */
	private FederationState refreshState()
	{
		FederationState s = apiClient.fetchFederationState();
		FederationState resolved = s != null ? s : FederationState.disabled();
		lastState = resolved;
		return resolved;
	}

	/** §8 verificationUrl pinning: true only for a well-formed <b>HTTPS</b> URL whose host is exactly the
	 * {@link #PINNED_BROKER_HOST pinned Anvil broker} — no {@code creds@}, off-standard port, or {@code http};
	 * a phish or look-alike like {@code anvilosrs.com.evil.com} is false ({@link URI} host parsing resolves authority tricks). */
	static boolean isPinnedBrokerUrl(String url)
	{
		if (url == null || url.isEmpty())
		{
			return false;
		}
		final URI uri;
		try
		{
			uri = new URI(url);
		}
		catch (URISyntaxException e)
		{
			return false; // illegal characters (backslash, whitespace, control) never parse — refuse
		}
		String scheme = uri.getScheme();
		String host = uri.getHost();
		if (scheme == null || host == null || uri.getUserInfo() != null)
		{
			return false; // opaque URI, non-server authority, or embedded credentials
		}
		if (!"https".equalsIgnoreCase(scheme))
		{
			return false;
		}
		int port = uri.getPort();
		if (port != -1 && port != 443)
		{
			return false;
		}
		if (!PINNED_BROKER_HOST.equalsIgnoreCase(host))
		{
			return false;
		}
		// Path pin: only the broker's device-login page may be opened — a hostile home handing back
		// some OTHER legitimate broker URL (portal, future redirect endpoints, …) is refused too.
		String path = uri.getPath();
		return path != null && path.startsWith(PINNED_BROKER_LOGIN_PATH);
	}

	/** The {@code verification_uri_complete} (RFC 8628): the broker page with {@code user_code} prefilled as a
	 * query param (approve + Discord sign-in only). {@code base} is already {@link #isPinnedBrokerUrl pinned} and
	 * the code URL-encoded, so it stays on the pinned broker (§8); with no code returns {@code base} (bare page). */
	static String withUserCode(String base, String userCode)
	{
		if (base == null || userCode == null || userCode.isEmpty())
		{
			return base;
		}
		String sep = base.indexOf('?') >= 0 ? "&" : "?";
		return base + sep + "user_code=" + URLEncoder.encode(userCode, StandardCharsets.UTF_8);
	}

	private boolean openInBrowser(String url)
	{
		if (url == null || url.isEmpty())
		{
			return false;
		}
		try
		{
			return browserOpener.open(url);
		}
		catch (RuntimeException e)
		{
			log.debug("could not open system browser: {}", e.getMessage());
			return false;
		}
	}

	private static void notify(Consumer<String> status, String message)
	{
		if (status != null)
		{
			status.accept(message);
		}
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

/**
 * Reads the collection-log page the game is currently showing.
 *
 * <p>The client only ever holds ONE page — the log is drawn on demand, so an unopened page has no
 * items anywhere in memory. That's why a full sync means the player paging through their log once,
 * and why this is a read-what's-on-screen routine rather than a dump.
 *
 * <p><b>Self-verifying.</b> The header prints "Obtained: 5/9"; we count the items we believe are
 * obtained and only return a page when the two agree. A game update that changes how unobtained
 * items are drawn therefore makes this return null — the sync stalls and says so — instead of
 * quietly reporting that everybody lost half their collection log.
 *
 * <p>Runs on the client thread (its only caller is the COLLECTION_DRAW_LIST script hook), so it
 * allocates nothing beyond the page it returns and never blocks.
 */
final class ClogPageReader
{
	private ClogPageReader() {}

	/** "Obtained: 5/9" — the log's own progress line, and our correctness check. */
	private static final Pattern OBTAINED = Pattern.compile("obtained:\\s*(\\d+)\\s*/\\s*(\\d+)");
	/** "Abyssal Sire kills: 1,204" / "Chest openings: 87" — label and value, commas stripped. */
	private static final Pattern COUNT_LINE = Pattern.compile("^(.+?):\\s*([\\d,]+)$");
	/** Widget tags: the log wraps names in colour tags we don't want in the payload. */
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	/**
	 * The page on screen, or null when it isn't readable yet (mid-draw, empty, or the obtained
	 * count disagrees with what we read — see the class note).
	 */
	static ClogPage read(Client client)
	{
		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (header == null || items == null)
		{
			return null;
		}

		String name = null;
		int obtained = -1;
		int total = -1;
		// Allocated only if the page actually prints counters — most don't, and this runs on every
		// redraw of every page the player scrolls past.
		Map<String, Integer> counts = null;

		Widget[] lines = header.getStaticChildren();
		if (lines == null)
		{
			return null;
		}
		for (Widget line : lines)
		{
			if (line == null)
			{
				continue;
			}
			String text = strip(line.getText());
			if (text.isEmpty())
			{
				continue;
			}
			// First non-empty line is the entry title; the rest are progress and counters.
			if (name == null)
			{
				name = text;
				continue;
			}
			Matcher progress = OBTAINED.matcher(text.toLowerCase());
			if (progress.find())
			{
				obtained = parseInt(progress.group(1));
				total = parseInt(progress.group(2));
				continue;
			}
			Matcher count = COUNT_LINE.matcher(text);
			if (count.matches())
			{
				int value = parseInt(count.group(2).replace(",", ""));
				if (value >= 0)
				{
					if (counts == null)
					{
						counts = new LinkedHashMap<>(4);
					}
					counts.put(count.group(1).trim(), value);
				}
			}
		}

		if (name == null || name.isEmpty() || obtained < 0 || total <= 0)
		{
			return null;
		}

		Widget[] cells = items.getDynamicChildren();
		if (cells == null)
		{
			return null;
		}

		// Two passes so the arrays are exactly sized — a page is at most a few dozen items, and this
		// avoids both an ArrayList's boxing and a grow-and-copy on every redraw.
		int found = 0;
		for (Widget cell : cells)
		{
			if (isObtained(cell))
			{
				found++;
			}
		}
		// The log's own count is the authority. Disagreeing means we misread the page (or Jagex
		// changed the drawing); either way, committing it would corrupt a synced log.
		if (found != obtained)
		{
			return null;
		}

		int[] ids = new int[found];
		int[] quantities = new int[found];
		int i = 0;
		for (Widget cell : cells)
		{
			if (!isObtained(cell))
			{
				continue;
			}
			ids[i] = cell.getItemId();
			// A quantity of 0 on an obtained item means "one, uncounted" for the handful of log
			// entries that predate stack tracking; storing 0 would read as "you don't have it".
			quantities[i] = Math.max(1, cell.getItemQuantity());
			i++;
		}

		return new ClogPage(name, ids, quantities, obtained, total, counts);
	}

	/**
	 * Whether a cell is an item the account has.
	 *
	 * <p>The log draws unobtained items dimmed (non-zero opacity) with no quantity; obtained ones are
	 * fully opaque and carry their count. Either signal alone has an edge case, so both are accepted
	 * and the header's "Obtained: N" arbitrates — see {@link #read}.
	 */
	private static boolean isObtained(Widget cell)
	{
		if (cell == null || cell.getItemId() <= 0)
		{
			return false;
		}
		return cell.getOpacity() == 0 || cell.getItemQuantity() > 0;
	}

	private static String strip(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		// The regex is the expensive part and most lines carry no tags at all — one scan for '<'
		// saves building a Matcher on every header line of every redraw.
		if (raw.indexOf('<') < 0)
		{
			return raw.trim();
		}
		return TAGS.matcher(raw).replaceAll("").trim();
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

