	/**
	 * Clears every task filter (status/type/category/tier) and the search query back to defaults.
	 * Called whenever the user leaves our tab or closes the log, so a fiddly filter (e.g. a category
	 * cycled deep into a long list) never lingers into the next open. Doesn't re-render on its own —
	 * exit-point callers are already tearing the view down.
	 */
	private void resetFilters()
	{
		statusFilter = ClogTaskModel.StatusFilter.ALL;
		typeFilter = ClogTaskModel.TypeFilter.ALL;
		categoryFilter = "";
		tierFilter = "";
		searchText = "";
	}

	// ---- tab injection ----

	private void injectBingoTab()
	{
		Widget tabs = client.getWidget(ComponentID.COLLECTION_LOG_TABS);
		if (tabs == null)
		{
			return;
		}

		// Re-space + restyle the 5 native tabs so a 6th fits. While our tab is active we force the
		// natives to the unselected sprites; otherwise we leave their sprites (native selection)
		// alone and only reposition.
		Widget[] natives = tabs.getStaticChildren();
		if (natives != null)
		{
			for (int i = 0; i < natives.length; i++)
			{
				layoutTab(natives[i], i * ClogIds.TAB_STEP, ClogIds.TAB_WIDTH,
					bingoTabActive ? Boolean.FALSE : null, null, false);
			}
		}

		// Our Bingo tab — a real 3-slice sprite tab, selected when active.
		Widget tab = findBingoTab(tabs);
		if (tab == null)
		{
			tab = tabs.createChild(-1, WidgetType.LAYER);
			tab.setName(ClogIds.BINGO_TAB_NAME);
			tab.setHasListener(true);
			tab.setAction(0, "View");
			tab.setOnOpListener((JavaScriptCallback) this::onBingoTabClicked);
		}
		layoutTab(tab, ClogIds.BINGO_TAB_INDEX * ClogIds.TAB_STEP, ClogIds.TAB_WIDTH,
			bingoTabActive ? Boolean.TRUE : Boolean.FALSE, ClogIds.BINGO_TAB_NAME, true);
		// Make our tab's slices render exactly like Jagex's by copying their render flags.
		if (natives != null && natives.length > 0)
		{
			copyTabRenderFlags(natives[0], tab);
		}
		tabs.revalidate();
	}

	/** Copy sprite-render flags (tiling/border/flip) from a native tab's 3 slices onto ours. */
	private void copyTabRenderFlags(Widget fromTab, Widget toTab)
	{
		Widget[] from = fromTab.getDynamicChildren();
		Widget[] to = toTab.getDynamicChildren();
		if (from == null || to == null)
		{
			return;
		}
		int n = Math.min(3, Math.min(from.length, to.length));
		for (int i = 0; i < n; i++)
		{
			if (from[i] == null || to[i] == null)
			{
				continue;
			}
			to[i].setSpriteTiling(from[i].getSpriteTiling());
			to[i].setBorderType(from[i].getBorderType());
			to[i].setFlippedVertically(from[i].isFlippedVertically());
			to[i].setFlippedHorizontally(from[i].isFlippedHorizontally());
			to[i].revalidate();
		}
	}

	/**
	 * Lay out a clog tab as a 3-slice sprite (left cap / stretched middle / right cap) + centred
	 * label at the given x/width. {@code selected} null = leave the background sprites untouched
	 * (keep native selection); true/false = force selected/unselected sprites. {@code ensure}
	 * creates the 4 children for our own tab.
	 */
	private void layoutTab(Widget tab, int x, int w, Boolean selected, String label, boolean ensure)
	{
		if (tab == null)
		{
			return;
		}
		place(tab, x, 0, w, ClogIds.TAB_HEIGHT);

		Widget[] kids = tab.getDynamicChildren();
		Widget cap0, mid, cap1, text;
		if (ensure && (kids == null || kids.length < 4))
		{
			cap0 = tab.createChild(-1, WidgetType.GRAPHIC);
			mid = tab.createChild(-1, WidgetType.GRAPHIC);
			cap1 = tab.createChild(-1, WidgetType.GRAPHIC);
			text = tab.createChild(-1, WidgetType.TEXT);
		}
		else if (kids != null && kids.length >= 4)
		{
			cap0 = kids[0];
			mid = kids[1];
			cap1 = kids[2];
			text = kids[3];
		}
		else
		{
			tab.revalidate();
			return;
		}

		// The middle slice is laid out FIRST and tucked under the rounded end-caps (like the native
		// tabs: their mid spans ~18..w-18 beneath the caps). Butting the slices edge-to-edge instead
		// lets the caps' transparent corners reveal the striped clog background — that was the bug.
		int overlap = 4;
		place(mid, ClogIds.TAB_CAP_W - overlap, 0, w - 2 * (ClogIds.TAB_CAP_W - overlap), ClogIds.TAB_HEIGHT);
		place(cap0, 0, 0, ClogIds.TAB_CAP_W, ClogIds.TAB_HEIGHT);
		place(cap1, w - ClogIds.TAB_CAP_W, 0, ClogIds.TAB_CAP_W, ClogIds.TAB_HEIGHT);

		if (selected != null)
		{
			// Only swap the sprite ids here; the render flags (tiling/border/flip) are copied
			// verbatim from a real native tab in copyTabRenderFlags so ours looks identical.
			int cap = selected ? ClogIds.TAB_CAP_SELECTED : ClogIds.TAB_CAP_UNSELECTED;
			int m = selected ? ClogIds.TAB_MID_SELECTED : ClogIds.TAB_MID_UNSELECTED;
			mid.setSpriteId(m);
			cap0.setSpriteId(cap);
			cap1.setSpriteId(cap);
		}

		if (label != null)
		{
			text.setText(label);
			text.setTextColor(COL_ORANGE);
			text.setFontId(FONT_PLAIN);
			text.setTextShadowed(true);
		}
		place(text, 0, 0, w, ClogIds.TAB_HEIGHT);
		text.setXTextAlignment(ALIGN_CENTER);
		text.setYTextAlignment(ALIGN_CENTER);

		cap0.revalidate();
		mid.revalidate();
		cap1.revalidate();
		text.revalidate();
		tab.revalidate();
	}

	/**
	 * Position + size a widget in absolute coordinates. Forcing absolute position/size MODES is
	 * essential: native clog widgets use relative/minus modes, so setting originalX/Width without
	 * this makes them land in the wrong place (which mangled the native tab bar).
	 */
	private static void place(Widget w, int x, int y, int width, int height)
	{
		w.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		w.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		w.setWidthMode(WidgetSizeMode.ABSOLUTE);
		w.setHeightMode(WidgetSizeMode.ABSOLUTE);
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(height);
	}

	private static final int DESC_LINE_H = 14;
	private static final int DESC_COLOR = 0xc0c0c0;
	// Second title line on expanded rows — 15px matches the title(y+3) → subtext(y+18) rhythm.
	private static final int TITLE_LINE_H = 15;

	/**
	 * Renders a tile description as one TEXT widget per wrapped line. The client's own
	 * multi-line text path is unusable here: raw newlines are dropped (words run together),
	 * {@code <col>} tags don't survive its line splitting (lines fall back to the widget's
	 * base color, i.e. black), and it draws past a fixed-height widget. So we wrap with the
	 * real font metrics and lay each line out ourselves — color, spacing and total height
	 * are then exact. Returns the height consumed.
	 */
	private int renderDescription(Widget items, String description, int x, int y, int width)
	{
		Widget first = items.createChild(-1, WidgetType.TEXT);
		first.setFontId(FONT_PLAIN);
		List<String> lines = wrapText(first.getFont(), description, width);

		for (int i = 0; i < lines.size(); i++)
		{
			Widget w = i == 0 ? first : items.createChild(-1, WidgetType.TEXT);
			w.setFontId(FONT_PLAIN);
			w.setText(lines.get(i));
			w.setTextColor(DESC_COLOR);
			w.setTextShadowed(true);
			place(w, x, y + i * DESC_LINE_H, width, DESC_LINE_H);
			w.revalidate();
		}
		return lines.size() * DESC_LINE_H + 2;
	}

	/** Like {@link #renderDescription} but in an arbitrary colour / line height — wraps long "what
	 *  counts" requirement text instead of clipping or ellipsizing it. Returns the height consumed. */
	private int renderWrappedColored(Widget items, String text, int color, int x, int y, int width, int lineH)
	{
		Widget first = items.createChild(-1, WidgetType.TEXT);
		first.setFontId(FONT_PLAIN);
		List<String> lines = wrapText(first.getFont(), text, width);
		for (int i = 0; i < lines.size(); i++)
		{
			Widget w = i == 0 ? first : items.createChild(-1, WidgetType.TEXT);
			w.setFontId(FONT_PLAIN);
			w.setText(lines.get(i));
			w.setTextColor(color);
			w.setTextShadowed(true);
			place(w, x, y + i * lineH, width, lineH);
			w.revalidate();
		}
		return lines.size() * lineH + 2;
	}

	/** A grey "label" on its own line, then the gold value wrapped + indented under it (the website's
	 *  "Any of:" / "Only from:" rows). Returns the height consumed. */
	private int labeledWrapped(Widget items, String label, String value, int x, int y, int width)
	{
		Widget lbl = items.createChild(-1, WidgetType.TEXT);
		lbl.setText("<col=8a8a8a>" + label + "</col>");
		lbl.setFontId(FONT_PLAIN);
		lbl.setTextShadowed(true);
		place(lbl, x, y, width, 14);
		lbl.revalidate();
		return 15 + renderWrappedColored(items, value, 0xffcc33, x + 8, y + 15, width - 8, DESC_LINE_H) + 3;
	}

	/** Resolve an OSRS item id to its name via ItemManager (client thread only); null on miss. */
	private String itemName(int id)
	{
		if (id <= 0)
		{
			return null;
		}
		try
		{
			net.runelite.api.ItemComposition c = itemManager.getItemComposition(id);
			return c != null ? c.getName() : null;
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/** Greedy word-wrap using font metrics; explicit newlines become hard breaks. */
	private static List<String> wrapText(FontTypeFace font, String text, int width)
	{
		List<String> lines = new ArrayList<>();
		for (String paragraph : text.replace("\r\n", "\n").replace('\r', '\n').split("\n", -1))
		{
			StringBuilder line = new StringBuilder();
			for (String word : paragraph.split(" "))
			{
				String candidate = line.length() == 0 ? word : line + " " + word;
				if (line.length() > 0 && textWidth(font, candidate) > width)
				{
					lines.add(line.toString());
					line.setLength(0);
					line.append(word);
				}
				else
				{
					line.setLength(0);
					line.append(candidate);
				}
			}
			lines.add(line.toString());
		}
		return lines;
	}

	private static int textWidth(FontTypeFace font, String text)
	{
		// ~6px/char fallback keeps the wrap sane if the font ever fails to resolve.
		return font != null ? font.getTextWidth(text) : text.length() * 6;
	}

	/**
	 * The stats-tab icon sprite for a hiscores skill name (as the server sends it, e.g.
	 * "mining"), or -1 when there's no such sprite (bosses, and skills newer than the
	 * pinned runelite-api like sailing) — callers fall back to the clog-book sprite.
	 */
	private static int skillSpriteId(String skill)
	{
		if (skill == null)
		{
			return -1;
		}
		switch (skill.toLowerCase(java.util.Locale.ROOT))
		{
			case "attack": return SpriteID.SKILL_ATTACK;
			case "strength": return SpriteID.SKILL_STRENGTH;
			case "defence": return SpriteID.SKILL_DEFENCE;
			case "ranged": return SpriteID.SKILL_RANGED;
			case "prayer": return SpriteID.SKILL_PRAYER;
			case "magic": return SpriteID.SKILL_MAGIC;
			case "hitpoints": return SpriteID.SKILL_HITPOINTS;
			case "agility": return SpriteID.SKILL_AGILITY;
			case "herblore": return SpriteID.SKILL_HERBLORE;
			case "thieving": return SpriteID.SKILL_THIEVING;
			case "crafting": return SpriteID.SKILL_CRAFTING;
			case "fletching": return SpriteID.SKILL_FLETCHING;
			case "mining": return SpriteID.SKILL_MINING;
			case "smithing": return SpriteID.SKILL_SMITHING;
			case "fishing": return SpriteID.SKILL_FISHING;
			case "cooking": return SpriteID.SKILL_COOKING;
			case "firemaking": return SpriteID.SKILL_FIREMAKING;
			case "woodcutting": return SpriteID.SKILL_WOODCUTTING;
			case "runecraft":
			case "runecrafting": return SpriteID.SKILL_RUNECRAFT;
			case "slayer": return SpriteID.SKILL_SLAYER;
			case "farming": return SpriteID.SKILL_FARMING;
			case "hunter": return SpriteID.SKILL_HUNTER;
			case "construction": return SpriteID.SKILL_CONSTRUCTION;
			case "overall": return SpriteID.SKILL_TOTAL;
			default: return -1;
		}
	}

	private Widget findBingoTab(Widget tabs)
	{
		Widget[] dyn = tabs.getDynamicChildren();
		if (dyn != null)
		{
			for (Widget c : dyn)
			{
				if (c != null && ClogIds.BINGO_TAB_NAME.equals(c.getName()))
				{
					return c;
				}
			}
		}
		return null;
	}

	private void onBingoTabClicked(ScriptEvent e)
	{
		bingoTabActive = true;
		setBossListHidden(true);
		hideHeaderBook(true);
		injectBingoTab();
		hubView = HubView.SCHEDULE;
		renderHub();
	}

	// ---- hub: Schedule home ⇄ drilled-in event view ----

	/** Re-render the left column + right content for the current view. */
	private void renderHub()
	{
		// Never paint our content unless our tab is actually the active view — otherwise a stray
		// re-render (e.g. a late search callback after the user clicked a native tab) bleeds the
		// Anvil panel over native content.
		if (!clogOpen || !bingoTabActive)
		{
			return;
		}
		hideHeaderBook(true);
		// Switching views (drill in / back / open a tile) starts at the top, not the old scroll offset.
		// Only reset when the view IDENTITY actually changed — a plain live re-render (the 30s
		// onConfigRefreshed → renderHub) must keep the player's scroll position, not snap them up.
		String navSig = hubView + "|" + viewingEventId + "|" + selectedGridTileId;
		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (items != null && !navSig.equals(lastRenderedView))
		{
			items.setScrollY(0);
		}
		lastRenderedView = navSig;
		renderLeftColumn();
		switch (hubView)
		{
			case EVENT:
				renderBingoPage();
				break;
			case GRID:
				renderBingoGrid();
				break;
			case GRID_TILE:
				renderGridTileDetail();
				break;
			case RACE:
				renderTileRace();
				break;
			case LEADERBOARD:
				renderLeaderboardView();
				break;
			case POINTS:
				renderPointsPreview();
				break;
			case LADDER:
				renderLadderView();
				break;
			case SCHEDULE:
			default:
				renderScheduleHome();
				break;
		}
	}

	/**
	 * Open the player's own active event in the right view: a tile race goes to the track, a
	 * points bingo keeps the Leagues accordion, and a classic (tile-scored) bingo opens the grid.
	 */
	private void openBingo()
	{
		if (LadderMissions.isLadder(eventFormat()))
		{
			hubView = HubView.LADDER;
			clientThread.invokeLater(this::renderHub);
		}
		else if ("tilerace".equalsIgnoreCase(eventFormat()))
		{
			openRace();
		}
		else if ("points".equalsIgnoreCase(eventScoringMode()))
		{
			hubView = HubView.EVENT;
			clientThread.invokeLater(this::renderHub);
		}
		else
		{
			openGrid();
		}
	}

	private void openGrid()
	{
		viewingEventId = activeEventId();
		viewingTitle = eventName();
		hubView = HubView.GRID;
		selectedGridTileId = -1;
		loadBoard();
		clientThread.invokeLater(this::renderHub);
	}

