	private void renderHeader()
	{
		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		if (header == null)
		{
			return;
		}

		// Clear the native title/obtained/kills text lines (restored by the native redraw on
		// leave) and lay down our own banner — avoids the stale-pileup + wrong-order overlap from
		// reusing the native widgets.
		header.deleteAllChildren();

		List<ClogTaskModel.TaskRow> all = tasks();
		java.util.Set<Integer> optionalIds = optionalTileIds();
		int done = ClogTaskModel.completedCount(all, optionalIds);
		int earned = ClogTaskModel.earnedPoints(all, optionalIds);
		int totalPts = ClogTaskModel.totalPoints(all, optionalIds);
		String subtitle = eventName() != null ? eventName()
			: "No active event";

		// Two lines (event name + progress) so the header breathes, like the detail header — three
		// lines don't fit the clog header height without clipping.
		bannerTitle(header, subtitle);
		String prog = done + "/" + ClogTaskModel.scoredCount(all, optionalIds) + " done";
		String line2 = totalPts > 0
			? "<col=ffff00>" + earned + "</col> / " + totalPts + " points  <col=666666>·</col>  " + prog
			: "<col=ffff00>" + prog + "</col>";
		bannerLine(header, line2, 0xaaaaaa, BANNER_LINE_H);
		header.revalidate();
	}

	private static final int BANNER_TOP = 3; // top margin so the header isn't flush against the divider
	private static final int BANNER_LINE_H = 16; // per-line step for 2-line headers, which have room to breathe
	private static final int BANNER_LINE_3 = 13; // tighter step for the few 3-line headers (grid/race/points/
	// leaderboard) — the clog header only fits ~3 lines at this spacing, so they stay compact by necessity
	private static final int BANNER_LEFT = 6; // left indent so header text lines up with the body content
	private static final int BANNER_TEXT_H = 14; // one line's box; the plain font draws ~12 inside it
	private static final int BANNER_LINE_MIN = 11; // tightest step before two lines start to touch
	private static final int BANNER_FALLBACK_H = 40; // what the clog header measures when it can't say

	/**
	 * The banner's first line — the one that names what you're looking at.
	 *
	 * <p>It used to be the same font, weight and size as the two lines under it, so a header read as
	 * three equal sentences and nothing announced itself as the title. It now uses the game's own
	 * heading font with a gold bar down its left edge (the site's section marker, brought in-game),
	 * which gives the banner a top without costing it a line of height — the clog header only fits
	 * three, and every one of them is spoken for.
	 */
	private Widget bannerTitle(Widget header, String text)
	{
		Widget bar = header.createChild(-1, WidgetType.RECTANGLE);
		bar.setFilled(true);
		bar.setTextColor(COL_ORANGE);
		bar.setOpacity(40);
		place(bar, 1, BANNER_TOP + 2, 2, 12);
		bar.revalidate();

		Widget line = header.createChild(-1, WidgetType.TEXT);
		line.setFontId(FONT_BOLD);
		int avail = header.getWidth() > 40 ? header.getWidth() - BANNER_LEFT - 12 : 280;
		place(line, BANNER_LEFT, bannerLineTop(header, 0), avail, 16);
		// Bold is wider than plain, so a title that just fitted before can now run off the pane.
		// Coloured markup is left alone: cutting a string mid-tag prints the tag.
		line.setText(text != null && text.indexOf('<') < 0
			? fitValue(line.getFont(), "", text, avail) : text);
		line.setTextColor(COL_ORANGE);
		line.setTextShadowed(true);
		line.revalidate();
		return line;
	}

	private Widget bannerLine(Widget header, String text, int color, int y)
	{
		Widget line = header.createChild(-1, WidgetType.TEXT);
		place(line, BANNER_LEFT, bannerLineTop(header, y), 280, BANNER_TEXT_H);
		line.setFontId(FONT_PLAIN);
		line.setText(text);
		line.setTextColor(color);
		line.setTextShadowed(true);
		line.revalidate();
		return line;
	}

	/**
	 * Where a banner line actually goes, given how tall the header REALLY is.
	 *
	 * <p>The spacing used to be a constant, and three lines at that constant needed 44 pixels in a
	 * header the game gives about 40 — so the third line, which is the one carrying the countdown and
	 * the player count, was drawn half outside its own box and clipped mid-glyph. Deriving the step
	 * from the measured height instead means the stack compresses to fit whatever it's given, and the
	 * last line is pinned inside the box no matter what: a line can be tight, but it is never a row of
	 * severed letters.
	 */
	private static int bannerLineTop(Widget header, int y)
	{
		int headerH = header.getHeight() > 0 ? header.getHeight() : BANNER_FALLBACK_H;
		int top = BANNER_TOP + y;
		if (top + BANNER_TEXT_H <= headerH)
		{
			return top; // it fits as asked — every header that was already fine is untouched
		}
		// It doesn't. Compress the stack evenly rather than letting the last line hang out of the
		// box: the caller's y is a multiple of the three-line step, so it doubles as the line index.
		int index = Math.max(1, y / BANNER_LINE_3);
		int step = Math.max(BANNER_LINE_MIN, (headerH - BANNER_TOP - BANNER_TEXT_H) / index);
		top = BANNER_TOP + index * step;
		return Math.max(0, Math.min(top, headerH - BANNER_TEXT_H));
	}

	private void renderItems()
	{
		if (!clogOpen || !bingoTabActive)
		{
			return;
		}
		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (items == null)
		{
			return;
		}
		items.deleteAllChildren();

		int paneWidth = items.getWidth() > 0 ? items.getWidth() : 250;
		int top = renderBodyFilters(items, paneWidth);
		// A classic bingo carrying announced missions shows them in a live strip above the task list.
		top += renderActiveMissionsStrip(items, System.currentTimeMillis(), top, paneWidth);
		List<PluginConfigResponse.TierBand> bands = tierBands();
		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.filter(tasks(), statusFilter, typeFilter, searchText,
			categoryFilter, effectiveTier(bands), bands);

		if (rows.isEmpty())
		{
			Widget empty = items.createChild(-1, WidgetType.TEXT);
			empty.setText("No bingo tasks match the current filters.");
			empty.setTextColor(0xaaaaaa);
			empty.setFontId(FONT_PLAIN);
			place(empty, 2, top, paneWidth - 4, 20);
			empty.revalidate();
			items.setScrollHeight(top + ClogIds.ROW_H);
			items.revalidateScroll();
			updateScrollbar(items);
			return;
		}

		int y = top;
		// Leave room for the scrollbar on the right so long sub-lines (Reward + cur/goal) don't run
		// under it and clip.
		int textWidth = Math.max(60, paneWidth - ClogIds.ROW_TEXT_X - 14);
		for (ClogTaskModel.TaskRow row : rows)
		{
			y += renderTaskRow(items, row, y, textWidth);
		}

		items.setScrollHeight(y + 4);
		items.revalidateScroll();
		updateScrollbar(items);
	}

	/** Compact filter strip at the top of the Bingo body; returns the y where the task list starts. */
	private int renderBodyFilters(Widget items, int paneWidth)
	{
		int y = BODY_TOP;

		// Search bar (full width): left-click opens a chatbox text input; right-click clears.
		String query = searchText.trim();
		boolean hasQuery = !query.isEmpty();
		Widget search = items.createChild(-1, WidgetType.TEXT);
		search.setText(hasQuery
			? "<col=999999>Search:</col> <col=ffcc33>" + query + "</col>"
			: "<col=777777>Search tasks...</col>");
		search.setFontId(FONT_PLAIN);
		search.setTextShadowed(true);
		place(search, 2, y, paneWidth - 4, 14);
		search.setHasListener(true);
		search.setAction(0, "Search");
		if (hasQuery)
		{
			search.setAction(1, "Clear");
		}
		search.setOnOpListener((JavaScriptCallback) e ->
		{
			if (e.getOp() == 2)
			{
				setSearchText("");
			}
			else
			{
				promptSearch();
			}
		});
		search.revalidate();
		y += 16;

		// Filter chips: Status + Type always, Category when any tile is categorised, Tier on
		// points events (tiers derive from point values). Laid out up to 3 per row so the labels
		// stay legible even with all four present.
		List<ClogTaskModel.TaskRow> all = tasks();
		boolean hasCats = !ClogTaskModel.categories(all).isEmpty();
		List<PluginConfigResponse.TierBand> bands = tierBands();
		boolean showTier = ClogTaskModel.totalPoints(all) > 0 && !bands.isEmpty();

		List<String> chipLabels = new ArrayList<>();
		List<String> chipValues = new ArrayList<>();
		List<JavaScriptCallback> chipActions = new ArrayList<>();
		// Per-chip right-click reset: left-click cycles forward, right-click jumps straight back to
		// "All" so you don't have to cycle the whole way around a long list. null = already at All.
		List<Runnable> chipResets = new ArrayList<>();

		chipLabels.add("Status");
		chipValues.add(pretty(statusFilter.name()));
		chipActions.add(e -> cycleStatusFilter());
		chipResets.add(statusFilter == ClogTaskModel.StatusFilter.ALL ? null
			: () -> setStatusFilter(ClogTaskModel.StatusFilter.ALL));
		chipLabels.add("Type");
		chipValues.add(pretty(typeFilter.name()));
		chipActions.add(e -> cycleTypeFilter());
		chipResets.add(typeFilter == ClogTaskModel.TypeFilter.ALL ? null
			: () -> setTypeFilter(ClogTaskModel.TypeFilter.ALL));
		if (hasCats)
		{
			chipLabels.add("Category");
			chipValues.add(categoryFilter.isEmpty() ? "All" : categoryFilter);
			chipActions.add(e -> cycleCategoryFilter());
			chipResets.add(categoryFilter.isEmpty() ? null : () ->
			{
				categoryFilter = "";
				refreshIfActive();
			});
		}
		if (showTier)
		{
			String tier = effectiveTier(bands);
			chipLabels.add("Tier");
			chipValues.add(tier.isEmpty() ? "All" : ClogTaskModel.tierLabel(tier, bands));
			chipActions.add(e -> cycleTierFilter());
			chipResets.add(tier.isEmpty() ? null : () -> setTierFilter(""));
		}

		int perRow = 3;
		int cols = Math.min(perRow, chipLabels.size());
		int gap = 6;
		// Inset 2px each side so the leftmost chip lines up with the search bar + task-row icons.
		int colW = (paneWidth - 4 - gap * (cols - 1)) / cols;
		for (int i = 0; i < chipLabels.size(); i++)
		{
			int cx = 2 + (i % perRow) * (colW + gap);
			int cy = y + (i / perRow) * 16;
			bodyFilterChip(items, chipLabels.get(i), chipValues.get(i), cx, cy, colW,
				chipActions.get(i), chipResets.get(i));
		}
		int numRows = (chipLabels.size() + perRow - 1) / perRow;
		y += 16 * numRows;

		// One-tap "Reset filters" clears everything at once (search + every chip). Shown only when
		// something is actually filtering; right-clicking individual chips still resets them one at a
		// time — this is the shortcut when several are active.
		boolean anyActive = statusFilter != ClogTaskModel.StatusFilter.ALL
			|| typeFilter != ClogTaskModel.TypeFilter.ALL
			|| !categoryFilter.isEmpty()
			|| !effectiveTier(bands).isEmpty()
			|| !searchText.trim().isEmpty();
		if (anyActive)
		{
			Widget reset = items.createChild(-1, WidgetType.TEXT);
			reset.setText("<col=ff9040>Reset filters</col>");
			reset.setFontId(FONT_PLAIN);
			reset.setTextShadowed(true);
			place(reset, 2, y, paneWidth - 4, 14);
			reset.setXTextAlignment(ALIGN_RIGHT);
			reset.setHasListener(true);
			reset.setAction(0, "Reset");
			reset.setOnOpListener((JavaScriptCallback) e ->
			{
				resetFilters();
				refreshIfActive();
			});
			reset.revalidate();
			y += 16;
		}

		return y + 4;
	}

	/** Opens the chatbox text input to set the task-name search query. Filters live as you type. */
	private void promptSearch()
	{
		searchInputOpen = true;
		chatboxPanelManager.openTextInput("Search bingo tasks")
			.value(searchText)
			// Live: re-filter on every keystroke so results react as you type.
			.onChanged((String v) -> setSearchText(v))
			.onDone((String v) ->
			{
				searchInputOpen = false;
				setSearchText(v);
			})
			.onClose(() -> searchInputOpen = false)
			.build();
	}

	/** Closes our search prompt if it's open (e.g. when the user navigates away from the tab). */
	private void closeSearchInput()
	{
		if (searchInputOpen)
		{
			searchInputOpen = false;
			chatboxPanelManager.close();
		}
	}

	private void bodyFilterChip(Widget items, String label, String value, int x, int y, int w,
		JavaScriptCallback onCycle, Runnable onReset)
	{
		Widget chip = items.createChild(-1, WidgetType.TEXT);
		chip.setFontId(FONT_PLAIN);
		chip.setTextShadowed(true);
		// Fit "Label: value" inside this chip's column — long free-text values (category names)
		// otherwise draw over the neighbouring chip or off the pane edge.
		String fitted = fitValue(chip.getFont(), label + ": ", value, w);
		chip.setText("<col=999999>" + label + ":</col> <col=ffcc33>" + fitted + "</col>");
		place(chip, x, y, w, 14);
		chip.setHasListener(true);
		chip.setAction(0, "Cycle");
		// Only offer "Reset" when this chip is off its default (mirrors the search bar's "Clear").
		if (onReset != null)
		{
			chip.setAction(1, "Reset");
		}
		chip.setOnOpListener((JavaScriptCallback) e ->
		{
			if (e.getOp() == 2 && onReset != null)
			{
				onReset.run();
			}
			else
			{
				onCycle.run(e);
			}
		});
		chip.revalidate();
	}

	/** Truncates {@code value} with "..." so {@code prefix + value} fits in {@code width} px. */
	private static String fitValue(FontTypeFace font, String prefix, String value, int width)
	{
		if (textWidth(font, prefix + value) <= width)
		{
			return value;
		}
		String v = value;
		while (v.length() > 1 && textWidth(font, prefix + v + "...") > width)
		{
			v = v.substring(0, v.length() - 1).trim();
		}
		return v + "...";
	}

	/** Renders one accordion task row; returns the vertical space it consumed. */
	private int renderTaskRow(Widget items, ClogTaskModel.TaskRow row, int y, int textWidth)
	{
		int statusColor = colorFor(row.status);
		boolean expanded = row.tileId == expandedTileId;
		boolean hasDesc = row.description != null && !row.description.isEmpty();

		Widget icon = items.createChild(-1, WidgetType.GRAPHIC);
		if (row.itemId > 0)
		{
			icon.setItemId(row.itemId);
			icon.setItemQuantityMode(ItemQuantityMode.NEVER);
		}
		else
		{
			// Skill tiles get their stats-tab skill icon; everything else without an item
			// (bosses, kills, diaries, unknown skills) keeps the clog-book stand-in.
			int skillSprite = row.kind == ClogTaskModel.Kind.SKILL ? skillSpriteId(row.skillName) : -1;
			icon.setSpriteId(skillSprite != -1 ? skillSprite : ClogIds.STAT_TILE_SPRITE);
		}
		place(icon, 2, y + (ClogIds.ROW_H - ClogIds.ROW_ICON) / 2, ClogIds.ROW_ICON, ClogIds.ROW_ICON);
		icon.setOpacity(row.status == ClogTaskModel.Status.NOT_STARTED ? 120 : 0);
		// Pure visual — no listener/name, so hovering an icon doesn't pop a tooltip.
		icon.revalidate();

		Widget name = items.createChild(-1, WidgetType.TEXT);
		name.setFontId(FONT_PLAIN);
		FontTypeFace font = name.getFont();
		// Long labels don't fit one line — collapsed rows ellipsize, expanded rows wrap the
		// label onto a second line (still capped at two so no row can swallow the pane). A
		// truncated label makes the row expandable even without a description; measure with
		// the plain "+ " stand-in since col tags take no render space.
		boolean truncated = textWidth(font, "+ " + row.label) > textWidth;
		boolean expandable = hasDesc || truncated;
		String prefix = expandable ? "<col=ffcc33>" + (expanded ? "-" : "+") + "</col> " : "";
		String prefixPlain = expandable ? "+ " : "";
		int extraTitleH = 0;
		String firstLine = null;
		if (expanded && truncated)
		{
			List<String> lines = wrapText(font, row.label, textWidth - textWidth(font, prefixPlain));
			// A single unbreakable word can't wrap (greedy wrap only splits between words) —
			// fall through to the ellipsized single line for that case.
			if (lines.size() > 1)
			{
				firstLine = prefix + lines.get(0);
				String rest = String.join(" ", lines.subList(1, lines.size()));
				Widget cont = items.createChild(-1, WidgetType.TEXT);
				cont.setText(fitValue(font, "", rest, textWidth));
				cont.setTextColor(statusColor);
				cont.setTextShadowed(true);
				cont.setFontId(FONT_PLAIN);
				place(cont, ClogIds.ROW_TEXT_X, y + 3 + TITLE_LINE_H, textWidth, 16);
				cont.setHasListener(true);
				cont.setAction(0, "Collapse");
				cont.setOnOpListener((JavaScriptCallback) e -> toggleExpand(row.tileId));
				cont.revalidate();
				extraTitleH = TITLE_LINE_H;
			}
		}
		if (firstLine == null)
		{
			firstLine = prefix + fitValue(font, prefixPlain, row.label, textWidth);
		}
		name.setText(firstLine);
		name.setTextColor(statusColor);
		name.setTextShadowed(true);
		place(name, ClogIds.ROW_TEXT_X, y + 3, textWidth, 16);
		name.setHasListener(true);
		name.setAction(0, expanded ? "Collapse" : "Expand");
		// Second op: right-click → Inspect opens the shared tile-detail page (what counts + who's
		// completed it) while left-click keeps the quick inline "+" description expand — both, as asked.
		name.setAction(1, "Inspect");
		name.setOnOpListener((JavaScriptCallback) e -> {
			if (e.getOp() == 2)
			{
				openTaskTile(row.tileId);
			}
			else
			{
				toggleExpand(row.tileId);
			}
		});
		name.revalidate();

		StringBuilder sub = new StringBuilder();
		StringBuilder subPlain = new StringBuilder(); // tag-free copy for width measurement
		if (row.points > 0)
		{
			sub.append("Reward: <col=ffcc33>").append(row.points).append(" points</col>");
			subPlain.append("Reward: ").append(row.points).append(" points");
		}
		if (row.goal > 0)
		{
			if (sub.length() > 0)
			{
				sub.append("  <col=666666>·</col>  ");
				subPlain.append("  ·  ");
			}
			// progressText is set by kinds whose progress isn't a plain count — a cumulative value
			// tile measures in gp, where the raw numbers are unreadable ("12500000/50000000").
			String progress = row.progressText != null ? row.progressText : row.current + "/" + row.goal;
			sub.append("<col=").append(hex(statusColor)).append(">").append(progress).append("</col>");
			subPlain.append(progress);
		}
		Widget subText = items.createChild(-1, WidgetType.TEXT);
		subText.setFontId(FONT_PLAIN);
		// Shrink a step before a long "Reward … · cur/goal" clips — keeps the exact numbers, no ellipsis.
		if (textWidth(subText.getFont(), subPlain.toString()) > textWidth)
		{
			subText.setFontId(FONT_PLAIN_SMALL);
		}
		subText.setText(sub.toString());
		subText.setTextColor(0x999999);
		subText.setTextShadowed(true);
		place(subText, ClogIds.ROW_TEXT_X, y + 18 + extraTitleH, textWidth, 14);
		subText.revalidate();

		int height = ClogIds.ROW_H + extraTitleH;
		if (expanded && hasDesc)
		{
			height += renderDescription(items, row.description, ClogIds.ROW_TEXT_X, y + ClogIds.ROW_H + extraTitleH, textWidth) + 2;
		}
		return height;
	}

	private void toggleExpand(int tileId)
	{
		expandedTileId = (expandedTileId == tileId) ? -1 : tileId;
		clientThread.invokeLater(this::renderItems);
	}

	// ---- Schedule section: upcoming bingo events + weekly competitions (from config.schedule) ----

	private static final int SECTION_HEADER_H = 22;
	// One schedule entry: a 16px title line + a 14px sub-line, plus the gap that separates
	// consecutive entries. scheduleRow() returns this, so bumping the gap re-spaces the whole list.
	private static final int SCHED_ROW_GAP = 12;
	private static final int SCHED_ROW_H = 30 + SCHED_ROW_GAP;

	/** Faint dark-green panel + bright full-height left accent that contains the "Live now" block. */
	private void groupPanel(Widget items, int x, int y, int w, int h)
	{
		Widget bg = items.createChild(-1, WidgetType.RECTANGLE);
		bg.setFilled(true);
		bg.setTextColor(0x16240f);
		bg.setOpacity(200); // 0=opaque, 255=transparent — a gentle tint over the brown clog
		place(bg, x, y, w, h);
		bg.revalidate();

		Widget bar = items.createChild(-1, WidgetType.RECTANGLE);
		bar.setFilled(true);
		bar.setTextColor(0x4caf50);
		bar.setOpacity(40);
		place(bar, x, y, 3, h);
		bar.revalidate();
	}

	/** A small coloured section header ("Live now" / "Upcoming"); returns its height. */
	private int sectionHeader(Widget items, String label, int color, int y, int paneWidth)
	{
		Widget t = items.createChild(-1, WidgetType.TEXT);
		t.setText("<col=" + hex(color) + ">" + label + "</col>");
		t.setFontId(FONT_PLAIN);
		t.setTextShadowed(true);
		place(t, 6, y + 3, paneWidth - 12, 16);
		t.revalidate();
		return SECTION_HEADER_H;
	}

	private void renderScheduleHome()
	{
		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		if (header != null)
		{
			header.deleteAllChildren();
			bannerTitle(header, "Schedule");
			bannerLine(header, "Your events & upcoming competitions", 0xaaaaaa, 16);
			header.revalidate();
		}

		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (items == null)
		{
			return;
		}
		items.deleteAllChildren();
		int paneWidth = items.getWidth() > 0 ? items.getWidth() : 250;
		boolean showBingo = eventTypeFilter.isEmpty() || eventTypeFilter.equals("bingo");
		int y = BODY_TOP;

		// Your active, openable bingo event is the headliner of the "Live now" block. Shown whenever
		// you're enrolled in a live event, even a manual classic grid with no tracked tiles.
		PluginConfigResponse activeCfg = plugin.getPluginConfig();
		boolean haveActiveEvent = activeCfg != null && activeCfg.event != null;
		boolean hasPinned = showBingo && haveActiveEvent;
		int pinnedEventId = hasPinned ? activeEventId() : -1;
		// ...but "your event" is not the same as "your event is running". The config resolves the
		// event you're ENROLLED in, which is handed over the moment sign-ups open — so a bingo two
		// months out was being printed under "Live now", next to a weekly that genuinely was.
		boolean pinnedLive = hasPinned && AnvilOverlay.isEventActive(activeCfg.event);

		// Collect schedule entries (excluding the pinned event), then split into live vs upcoming.
		List<SchedEntry> entries = new ArrayList<>();
		PluginConfigResponse cfg = plugin.getPluginConfig();
		BingoApiClient.ScheduleResponse sched = cfg != null ? cfg.schedule : null;
		if (sched != null)
		{
			if (showBingo && sched.bingos != null)
			{
				for (BingoApiClient.ScheduledBingo b : sched.bingos)
				{
					if (b != null && b.id != pinnedEventId)
					{
						entries.add(new SchedEntry(b.id, "Bingo", b.title, bingoKindLabel(b.format, b.scoringMode),
							b.status, b.startDate, b.endDate, false, b.format, b.scoringMode));
					}
				}
			}
			if (sched.weeklies != null)
			{
				for (BingoApiClient.ScheduledWeekly w : sched.weeklies)
				{
					if (w != null && matchesWeeklyType(w.type))
					{
						String kind = ConnectionView.WeeklyView.kindLabel(w.type);
						entries.add(new SchedEntry(w.id, w.type, w.title, kind, w.status, w.startDate, w.endDate, true, null, null));
					}
				}
			}
		}
		List<SchedEntry> live = new ArrayList<>();
		List<SchedEntry> upcoming = new ArrayList<>();
		for (SchedEntry en : entries)
		{
			(en.active() ? live : upcoming).add(en);
		}
		live.sort(SCHED_ORDER);
		upcoming.sort(SCHED_ORDER);

		// ---- Live now: pinned event + any live weeklies, wrapped in a green-accented panel so the
		// active block reads as one cohesive, currently-running section. ----
		if (pinnedLive || !live.isEmpty())
		{
			int rows = (pinnedLive ? 1 : 0) + live.size();
			// The last row's trailing gap isn't inside the panel — trade it for an even bottom pad.
			int sectionH = SECTION_HEADER_H + rows * SCHED_ROW_H - SCHED_ROW_GAP + 6;
			groupPanel(items, 0, y, paneWidth, sectionH);
			y += sectionHeader(items, "Live now", 0x4caf50, y, paneWidth);
			if (pinnedLive)
			{
				String name = eventName() != null ? eventName() : "Bingo";
				y += scheduleRow(items, "> " + name, bingoKindLabel(eventFormat(), eventScoringMode()),
					"active", pinnedProgressLabel(eventFormat(), eventScoringMode()), null, y, paneWidth, this::openBingo);
			}
			for (SchedEntry en : live)
			{
				Runnable onOpen = en.weekly ? (() -> openLeaderboard(en.id)) : (() -> openScheduledBingo(en));
				y += scheduleRow(items, en.title, en.kind, en.status, stateLabel(en.status),
					dateRange(en.start, en.end), y, paneWidth, onOpen);
			}
			y += 8;
		}

		// ---- Upcoming: plain list, visually secondary to the live block. ----
		if (!upcoming.isEmpty() || (hasPinned && !pinnedLive))
		{
			y += sectionHeader(items, "Upcoming", 0x9a9a9a, y, paneWidth);
			if (hasPinned && !pinnedLive)
			{
				// Still first, still openable — it IS their event. It just hasn't started, so it
				// carries its dates instead of a progress figure that would read as 0% done.
				String name = eventName() != null ? eventName() : "Bingo";
				y += scheduleRow(items, "> " + name, bingoKindLabel(eventFormat(), eventScoringMode()),
					"upcoming", stateLabel("upcoming"),
					dateRange(activeCfg.event.startDate, activeCfg.event.endDate), y, paneWidth, this::openBingo);
			}
			for (SchedEntry en : upcoming)
			{
				Runnable onOpen = en.weekly ? (() -> openLeaderboard(en.id)) : (() -> openScheduledBingo(en));
				y += scheduleRow(items, en.title, en.kind, en.status, stateLabel(en.status),
					dateRange(en.start, en.end), y, paneWidth, onOpen);
			}
		}

		if (y == BODY_TOP)
		{
			Widget empty = items.createChild(-1, WidgetType.TEXT);
			empty.setText(sched == null ? "Loading events..." : "No events match this filter.");
			empty.setTextColor(0xaaaaaa);
			empty.setFontId(FONT_PLAIN);
			place(empty, 0, BODY_TOP, paneWidth, 20);
			empty.revalidate();
			y = ClogIds.ROW_H;
		}

		items.setScrollHeight(y + 6);
		items.revalidateScroll();
		updateScrollbar(items);
	}

	/** A unified schedule entry (bingo or weekly) so the home list can be sorted across both. */
	private static final class SchedEntry
	{
		final int id;
		final String type;   // bingo: "Bingo"; weekly: "boss" | "skill"
		final String title;
		final String kind;   // display label
		final String status;
		final String start;
		final String end;
		final boolean weekly;
		final String format; // bingo event layout ("bingo" | "tilerace"); null for weeklies
		final String scoringMode; // bingo scoring ("tiles" | "points"); null for weeklies

		SchedEntry(int id, String type, String title, String kind, String status, String start, String end,
			boolean weekly, String format, String scoringMode)
		{
			this.id = id;
			this.type = type;
			this.title = title;
			this.kind = kind;
			this.status = status;
			this.start = start;
			this.end = end;
			this.weekly = weekly;
			this.format = format;
			this.scoringMode = scoringMode;
		}

		boolean active()
		{
			return "active".equalsIgnoreCase(status);
		}
	}

	// Live first, then by soonest start date (ISO strings sort chronologically); blanks last.
	private static final java.util.Comparator<SchedEntry> SCHED_ORDER = (a, b) -> {
		if (a.active() != b.active())
		{
			return a.active() ? -1 : 1;
		}
		String sa = a.start == null ? "" : a.start;
		String sb = b.start == null ? "" : b.start;
		if (sa.isEmpty() != sb.isEmpty())
		{
			return sa.isEmpty() ? 1 : -1;
		}
		return sa.compareTo(sb);
	};

	// ---- Leaderboard section: BOTW/SOTW ranked standings (fetched from the site) ----

	private void renderLeaderboardView()
	{
		BingoApiClient.WeeklyLeaderboard lb = cachedLeaderboard;

		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		countdownLine = null;
		if (header != null)
		{
			header.deleteAllChildren();
			if (lb != null && lb.competition != null)
			{
				String kind = ConnectionView.WeeklyView.kindLabel(lb.competition.type);
				bannerTitle(header, lb.competition.title == null ? kind : lb.competition.title);
				// The site's own label, not the raw key: an EHP week read "ehp" here, and a boss week
				// read "PhosanisNightmare" — the hiscores spelling, apostrophe and all missing.
				bannerLine(header, kind + "  <col=666666>·</col>  "
					+ nz(ConnectionView.WeeklyView.metricLabel(lb.competition.type, lb.competition.metric,
						lb.competition.metricLabel)), 0xffffff, BANNER_LINE_3);
				// Live countdown instead of a plain date range — onGameTick refreshes this one line.
				countdownStart = lb.competition.startDate;
				countdownEnd = lb.competition.endDate;
				countdownSuffix = "  <col=666666>·</col>  " + lb.total + " players";
				countdownText = countdownLabel(countdownStart, countdownEnd);
				countdownLine = bannerLine(header, countdownText + countdownSuffix, 0xaaaaaa, BANNER_LINE_3 * 2);
			}
			else
			{
				bannerTitle(header, "Leaderboard");
				bannerLine(header, loadingLeaderboard ? "Loading..." : "Unavailable", 0xaaaaaa, 16);
			}
			header.revalidate();
		}

		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (items == null)
		{
			return;
		}
		items.deleteAllChildren();
		int paneWidth = items.getWidth() > 0 ? items.getWidth() : 250;
		int y = BODY_TOP;

		if (lb == null || lb.entries == null)
		{
			Widget m = items.createChild(-1, WidgetType.TEXT);
			m.setText(loadingLeaderboard ? "Loading leaderboard..." : "Couldn't load the leaderboard.");
			m.setTextColor(0xaaaaaa);
			m.setFontId(FONT_PLAIN);
			place(m, 4, y, paneWidth - 8, 16);
			m.revalidate();
			y += ClogIds.ROW_H;
		}
		else if (lb.entries.isEmpty())
		{
			Widget m = items.createChild(-1, WidgetType.TEXT);
			m.setText("No participants yet.");
			m.setTextColor(0xaaaaaa);
			m.setFontId(FONT_PLAIN);
			place(m, 4, y, paneWidth - 8, 16);
			m.revalidate();
			y += ClogIds.ROW_H;
		}
		else
		{
			String me = normalizeRsn(localRsn());
			for (BingoApiClient.LeaderboardEntry e : lb.entries)
			{
				if (e == null)
				{
					continue;
				}
				// Match on whitespace-normalized names — OSRS display names use non-breaking
				// spaces, so a raw equalsIgnoreCase can miss the local player (and mis-flag).
				boolean isMe = !me.isEmpty() && me.equals(normalizeRsn(e.rsn));
				// EHP/EHB gains are milli-hours — "+12.40 hrs", not "+12,400".
				y += leaderboardRow(items, e.rank, e.rsn, gainText(lb.competition, e.gained), isMe, y, paneWidth);
			}
		}

		items.setScrollHeight(y + 6);
		items.revalidateScroll();
		updateScrollbar(items);
	}

	/**
	 * A weekly gain as the row shows it: "+1,234" for XP/KC, "+12.40 hrs" for an EHP/EHB comp, whose
	 * values travel in milli-hours. Null competition (shouldn't happen) falls back to the plain count.
	 */
	private static String gainText(BingoApiClient.WeeklyComp comp, long gained)
	{
		long safe = Math.max(0, gained);
		if (comp != null && "efficiency".equalsIgnoreCase(comp.type))
		{
			return "+" + ConnectionView.WeeklyView.formatGainValue(comp.type, safe) + " "
				+ ConnectionView.WeeklyView.unitNoun(comp.type);
		}
		return "+" + String.format("%,d", safe);
	}

	private int leaderboardRow(Widget items, int rank, String rsn, String gainedText, boolean isMe, int y, int paneWidth)
	{
		int nameColor = isMe ? 0xffcc33
			: (rank <= 3 ? (ClogIds.COMPLETE_COLOR.getRGB() & 0xFFFFFF) : 0xe0e0e0);

		int ty = y + 4; // vertical padding inside the taller row

		Widget rk = items.createChild(-1, WidgetType.TEXT);
		rk.setText("<col=999999>" + rank + "</col>");
		rk.setFontId(FONT_PLAIN);
		rk.setTextShadowed(true);
		place(rk, 8, ty, 28, 16);
		rk.setXTextAlignment(ALIGN_RIGHT);
		rk.revalidate();

		Widget nm = items.createChild(-1, WidgetType.TEXT);
		nm.setText((rsn == null ? "?" : rsn) + (isMe ? "  <col=8a8a8a>(you)</col>" : ""));
		nm.setTextColor(nameColor);
		nm.setFontId(FONT_PLAIN);
		nm.setTextShadowed(true);
		place(nm, 44, ty, paneWidth - 44 - 92, 16);
		nm.revalidate();

		Widget gn = items.createChild(-1, WidgetType.TEXT);
		gn.setText("<col=ffcc33>" + gainedText + "</col>");
		gn.setFontId(FONT_PLAIN);
		gn.setTextShadowed(true);
		place(gn, paneWidth - 90, ty, 84, 16);
		gn.setXTextAlignment(ALIGN_RIGHT);
		gn.revalidate();
		return 24;
	}

	// ---- ladder: DMM-All-Stars-style missions board (format=ladder) ----

	/**
	 * The live missions board for a ladder event: your rank, a per-second countdown to the next drop,
	 * the currently-open missions with a live grow/decay value each, and the individual leaderboard with
	 * an All-time / This-month toggle. The countdown + values refresh in place from onGameTick
	 * (tickLadderView) — no board polling; everything rides the already-refreshed config.
	 */
	private void renderLadderView()
	{
		if (!clogOpen || !bingoTabActive)
		{
			return;
		}
		ladderRows.clear();
		ladderCountdownLine = null;
		PluginConfigResponse cfg = plugin.getPluginConfig();
		PluginConfigResponse.EventInfo ev = cfg == null ? null : cfg.event;
		ladderNextRevealAt = ev == null ? null : ev.nextRevealAt;
		ladderDecay = ev == null ? null : ev.decay;
		final long now = System.currentTimeMillis();

		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		if (header != null)
		{
			header.deleteAllChildren();
			String title = ev != null && ev.name != null && !ev.name.isEmpty() ? ev.name : "Ladder";
			bannerTitle(header, title);
			bannerLine(header, ladderRankLine(ev), 0xffffff, BANNER_LINE_3);
			ladderCountdownText = ladderCountdownText(now);
			ladderCountdownLine = bannerLine(header, ladderCountdownText, 0xff9040, BANNER_LINE_3 * 2);
			header.revalidate();
		}

		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (items == null)
		{
			return;
		}
		items.deleteAllChildren();
		int paneWidth = items.getWidth() > 0 ? items.getWidth() : 250;
		int y = BODY_TOP;

		// Active missions (revealed + still open), each with a live value.
		y += ladderSectionLabel(items, "ACTIVE MISSIONS", y, paneWidth);
		if (ev == null || ev.missions == null || ev.missions.isEmpty())
		{
			y += ladderInfoRow(items, "Waiting for the next mission to drop...", y, paneWidth);
		}
		else
		{
			for (PluginConfigResponse.Mission m : ev.missions)
			{
				if (m != null)
				{
					y += ladderMissionRow(items, m, now, y, paneWidth);
				}
			}
		}
		y += 6;

		// Individual leaderboard with an All-time / This-month toggle.
		y += ladderToggle(items, y, paneWidth);
		PluginConfigResponse.Standings st = ev == null ? null : (ladderShowMonth ? ev.monthlyStandings : ev.standings);
		if (st == null || st.entries == null || st.entries.isEmpty())
		{
			y += ladderInfoRow(items, ladderShowMonth ? "No points this month yet." : "No points yet — be first on the board.", y, paneWidth);
		}
		else
		{
			String me = normalizeRsn(localRsn());
			for (PluginConfigResponse.StandingEntry e : st.entries)
			{
				if (e == null)
				{
					continue;
				}
				boolean isMe = !me.isEmpty() && me.equals(normalizeRsn(e.rsn));
				y += leaderboardRow(items, e.rank, e.rsn, String.format("%,d", Math.max(0, e.points)), isMe, y, paneWidth);
			}
		}

		items.setScrollHeight(y + 6);
		items.revalidateScroll();
		updateScrollbar(items);
	}

	/** Per-tick refresh (onGameTick) of the ladder countdown + each mission's live value, in place. */
	private void tickLadderView()
	{
		final long now = System.currentTimeMillis();
		if (ladderCountdownLine != null)
		{
			String text = ladderCountdownText(now);
			if (!text.equals(ladderCountdownText))
			{
				ladderCountdownText = text;
				ladderCountdownLine.setText(text);
				ladderCountdownLine.revalidate();
			}
		}
		for (LadderRowRef r : ladderRows)
		{
			long val = LadderMissions.liveValue(r.face, r.revealedAtIso, r.decay, now);
			String text = LadderMissions.valueLabel(r.face, val);
			if (!text.equals(r.lastText))
			{
				r.lastText = text;
				r.widget.setText(text);
				r.widget.setTextColor(ladderValueColor(r.face, val));
				r.widget.revalidate();
			}
		}
	}

	/** "You: #4 this month · 1,240 pts · #12 all-time", or an encouraging line when unranked. */
	private static String ladderRankLine(PluginConfigResponse.EventInfo ev)
	{
		PluginConfigResponse.Standings month = ev == null ? null : ev.monthlyStandings;
		PluginConfigResponse.Standings all = ev == null ? null : ev.standings;
		int mr = month != null ? month.yourRank : 0;
		long mp = month != null ? month.yourPoints : 0;
		int ar = all != null ? all.yourRank : 0;
		if (mr <= 0)
		{
			return "You: unranked  <col=666666>·</col>  finish a mission to score";
		}
		String s = "You: #" + mr + " this month  <col=666666>·</col>  " + String.format("%,d", mp) + " pts";
		if (ar > 0)
		{
			s += "  <col=666666>·</col>  #" + ar + " all-time";
		}
		return s;
	}

	/** "NEXT MISSION IN  12:34" / "New mission dropping..." / "Next mission drops on a claim" (bounty). */
	private String ladderCountdownText(long now)
	{
		String cd = LadderMissions.countdown(ladderNextRevealAt, now);
		if (cd == null)
		{
			return "Next mission drops on a claim";
		}
		return "now".equals(cd) ? "New mission dropping..." : "NEXT MISSION IN  " + cd;
	}

	/** Gold for an unchanged value, green when it grew, orange when it's decaying. */
	private static int ladderValueColor(long face, long current)
	{
		if (current == face)
		{
			return 0xffcc33;
		}
		return current > face ? (ClogIds.COMPLETE_COLOR.getRGB() & 0xFFFFFF) : COL_ORANGE;
	}

