package com.anvil;

import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.File;
import java.io.FileOutputStream;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;

@Slf4j
@Singleton
public class PendingSubmissionStore
{
	private static final File PENDING_DIR = new File(RuneLite.RUNELITE_DIR, "osrs-bingo-pending");

	// Garbage-collect pending submissions older than this. Prevents unbounded disk growth
	// when retries keep failing (e.g. site URL permanently wrong) and the user never clears.
	private static final long MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000; // 7 days

	private final Gson gson;

	@Inject
	public PendingSubmissionStore(Gson gson)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	public static class PendingSubmission
	{
		public int eventId;
		public int tileId;
		public int teamId;
		public int playerId;
		public int amount;
		public String label;
		public String note;
		public String screenshotFile; // filename of PNG in pending dir
		public long timestamp;
		public Integer itemId; // specific item ID for per-item tracking (nullable)
		public Integer durationSeconds; // timed-tile clear time in seconds (nullable; non-null routes to submitTimed)
		public String capturedRsn; // character the drop was obtained on; only re-submitted while on it
		// A proof the plugin can't auto-submit to a specific tile (pet drop, duplicate Champion's
		// scroll — the "would have received" line names no item), captured so the player has a ready
		// screenshot to attach when they submit by hand on the site. The retry loop skips these.
		public boolean manual;
	}

	public void init()
	{
		if (!PENDING_DIR.exists())
		{
			PENDING_DIR.mkdirs();
		}
	}

	public String save(PendingSubmission sub, byte[] pngBytes)
	{
		init();
		String id = sub.tileId + "-" + sub.timestamp;

		File pngFile = new File(PENDING_DIR, id + ".png");
		try (FileOutputStream fos = new FileOutputStream(pngFile))
		{
			fos.write(pngBytes);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending screenshot: {}", e.getMessage());
			return null;
		}

		sub.screenshotFile = id + ".png";
		File jsonFile = new File(PENDING_DIR, id + ".json");
		try (Writer w = new FileWriter(jsonFile))
		{
			gson.toJson(sub, w);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending submission metadata: {}", e.getMessage());
			pngFile.delete();
			return null;
		}

		log.info("Saved pending submission: {} (tile '{}')", id, sub.label);
		return id;
	}

	public List<PendingSubmission> loadAll()
	{
		init();
		List<PendingSubmission> result = new ArrayList<>();
		File[] jsonFiles = PENDING_DIR.listFiles((dir, name) -> name.endsWith(".json"));
		if (jsonFiles == null)
		{
			return result;
		}
		long now = System.currentTimeMillis();
		for (File f : jsonFiles)
		{
			try (Reader r = new FileReader(f))
			{
				PendingSubmission sub = gson.fromJson(r, PendingSubmission.class);
				if (sub != null && sub.timestamp > 0 && (now - sub.timestamp) > MAX_AGE_MS)
				{
					log.info("Pruning expired pending submission '{}' ({} days old)",
						sub.label, (now - sub.timestamp) / (24 * 60 * 60 * 1000));
					remove(sub);
					continue;
				}
				result.add(sub);
			}
			catch (Exception e)
			{
				log.warn("Failed to read pending submission {}: {}", f.getName(), e.getMessage());
			}
		}
		return result;
	}

	public byte[] readScreenshot(PendingSubmission sub)
	{
		File pngFile = new File(PENDING_DIR, sub.screenshotFile);
		try
		{
			return Files.readAllBytes(pngFile.toPath());
		}
		catch (IOException e)
		{
			log.error("Failed to read pending screenshot {}: {}", sub.screenshotFile, e.getMessage());
			return null;
		}
	}

	public void remove(PendingSubmission sub)
	{
		String baseName = sub.screenshotFile.replace(".png", "");
		new File(PENDING_DIR, baseName + ".png").delete();
		new File(PENDING_DIR, baseName + ".json").delete();
		log.info("Removed pending submission: {} (tile '{}')", baseName, sub.label);
	}

	/** Number of submissions still waiting to upload (cheap — a directory listing, no parsing). */
	public int count()
	{
		init();
		String[] names = PENDING_DIR.list((dir, name) -> name.endsWith(".json"));
		return names == null ? 0 : names.length;
	}

	/** Opens the pending-proofs folder in the OS file manager, off the calling thread. */
	public void copyFolderPath()
	{
		init();
		// LinkBrowser::open is restricted for hub releases, so the path goes on the clipboard and the
		// player pastes it wherever they were going to open it.
		Clipboards.copy(PENDING_DIR.getAbsolutePath());
	}
}

package com.anvil;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.File;
import java.io.IOException;
import java.io.RandomAccessFile;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * One-click support-log export. Members who hit a problem (a drop that never submits, login trouble)
 * shouldn't have to hunt for {@code .runelite/logs/client.log} by hand. This bundles a caller-supplied
 * diagnostic header with the Anvil-relevant slice of RuneLite's client.log into a single shareable
 * .txt in {@code .runelite/anvil-debug/}, copies its path to the clipboard, and opens the folder so
 * they can just drag the file into Discord. All file work runs off the client thread by the caller.
 */
@Slf4j
@Singleton
public class DebugLogExporter
{
	private static final File OUT_DIR = new File(RuneLite.RUNELITE_DIR, "anvil-debug");
	private static final File LOG_FILE = new File(new File(RuneLite.RUNELITE_DIR, "logs"), "client.log");

	// Read at most the tail of client.log — the file can be many MB across a long session and only the
	// recent end is relevant to a just-now problem.
	private static final long MAX_LOG_TAIL_BYTES = 512 * 1024;
	// Keep the raw tail bounded so the bundle stays small enough to share easily.
	private static final int RAW_TAIL_LINES = 200;

	private static final DateTimeFormatter FILE_TS = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	@Inject
	public DebugLogExporter()
	{
	}

	public static class Result
	{
		public final File file;
		public final int anvilLineCount;
		public final boolean clientLogFound;

		Result(File file, int anvilLineCount, boolean clientLogFound)
		{
			this.file = file;
			this.anvilLineCount = anvilLineCount;
			this.clientLogFound = clientLogFound;
		}
	}

	/**
	 * Write the bundle, copy its path to the clipboard, and open the folder. Never throws — on failure
	 * it returns null and logs, so the caller can show a friendly fallback message.
	 */
	public Result export(String header)
	{
		try
		{
			if (!OUT_DIR.exists() && !OUT_DIR.mkdirs())
			{
				log.warn("Anvil: could not create debug-export dir {}", OUT_DIR);
			}

			List<String> anvilLines = new ArrayList<>();
			List<String> rawTail = new ArrayList<>();
			boolean logFound = readLogTail(anvilLines, rawTail);

			String nl = System.lineSeparator();
			StringBuilder sb = new StringBuilder();
			sb.append(header).append(nl).append(nl);
			sb.append("=== Anvil log lines (").append(anvilLines.size()).append(") ===").append(nl);
			if (anvilLines.isEmpty())
			{
				sb.append(logFound
					? "(no Anvil lines found in the recent log — the action may not have run, or logs rotated)"
					: "(client.log not found at " + LOG_FILE + ")").append(nl);
			}
			else
			{
				for (String l : anvilLines)
				{
					sb.append(l).append(nl);
				}
			}
			sb.append(nl).append("=== Recent client.log tail (last ").append(rawTail.size())
				.append(" lines) ===").append(nl);
			for (String l : rawTail)
			{
				sb.append(l).append(nl);
			}

			File out = new File(OUT_DIR, "anvil-debug-" + LocalDateTime.now().format(FILE_TS) + ".txt");
			Files.write(out.toPath(), sb.toString().getBytes(StandardCharsets.UTF_8));

			copyToClipboard(out.getAbsolutePath());

			log.info("Anvil: exported debug log to {} ({} Anvil lines)", out, anvilLines.size());
			return new Result(out, anvilLines.size(), logFound);
		}
		catch (Exception e)
		{
			log.warn("Anvil: debug log export failed: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * Reads the tail of client.log into {@code rawTail} (last {@link #RAW_TAIL_LINES}) and every
	 * Anvil-related line into {@code anvilLines}. Matching on "anvil" catches the logger name
	 * (com.anvil.*) that logback prefixes onto every plugin log line. Returns false if no log file.
	 */
	private boolean readLogTail(List<String> anvilLines, List<String> rawTail)
	{
		if (!LOG_FILE.isFile())
		{
			return false;
		}
		try (RandomAccessFile raf = new RandomAccessFile(LOG_FILE, "r"))
		{
			long len = raf.length();
			long from = Math.max(0, len - MAX_LOG_TAIL_BYTES);
			raf.seek(from);
			byte[] buf = new byte[(int) (len - from)];
			raf.readFully(buf);
			String text = new String(buf, StandardCharsets.UTF_8);
			// If we started mid-file, drop the first partial line.
			if (from > 0)
			{
				int firstNl = text.indexOf('\n');
				if (firstNl >= 0)
				{
					text = text.substring(firstNl + 1);
				}
			}
			String[] lines = text.split("\r?\n");
			for (String line : lines)
			{
				if (line.toLowerCase().contains("anvil"))
				{
					anvilLines.add(line);
				}
			}
			int start = Math.max(0, lines.length - RAW_TAIL_LINES);
			for (int i = start; i < lines.length; i++)
			{
				rawTail.add(lines[i]);
			}
			return true;
		}
		catch (IOException e)
		{
			log.warn("Anvil: could not read client.log: {}", e.getMessage());
			return false;
		}
	}

	private void copyToClipboard(String value)
	{
		Clipboards.copy(value);
	}

}

package com.anvil;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import lombok.extern.slf4j.Slf4j;

/**
 * Putting a path on the clipboard, which is as far as a hub plugin may go toward "open this folder".
 *
 * <p>RuneLite's LinkBrowser::open — the sanctioned way to hand a local path to the OS — is a
 * restricted API for plugin-hub releases, so the folder buttons can't launch a file manager. Copying
 * the path is the honest substitute: one paste into a file manager or a terminal, and nothing about
 * the plugin reaches outside its own directory.
 */
@Slf4j
final class Clipboards
{
	private Clipboards()
	{
	}

	/** True when the text made it onto the clipboard, so a caller can say so rather than assume. */
	static boolean copy(String value)
	{
		if (value == null || value.isEmpty())
		{
			return false;
		}
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(value), null);
			return true;
		}
		catch (Exception e)
		{
			// A headless or locked-down desktop has no clipboard; the path still gets said out loud.
			log.debug("Anvil: clipboard copy skipped: {}", e.getMessage());
			return false;
		}
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * The account's best times, kept locally and pushed to the clan site.
 *
 * <p>Two ways in, because neither alone is enough:
 * <ul>
 *   <li><b>Live</b> — the completion messages the plugin already reads for timed tiles also carry
 *       "(new personal best)" / "Personal best: 7:59". Free: no extra chat parsing, and no waiting.</li>
 *   <li><b>Seed</b> — RuneLite's own chat-commands plugin has been recording these into its config
 *       for years. Importing that once turns a blank profile into a complete one on first login,
 *       which is what makes this feel like a sync rather than a slow accrual. The plugin reads it;
 *       this class only receives the numbers ({@link #seed}).</li>
 * </ul>
 *
 * <p>Times are centiseconds — the game separates runs by hundredths and so should a leaderboard.
 *
 * <p>The activity is supplied by the caller from the "Your X kill count is: N" line it already
 * parses, so a PB costs no additional regex on the chat hot path. Correlation works in both
 * directions because the game is inconsistent about ordering: the Inferno prints the duration
 * before the kill count, most bosses print it after.
 *
 * <p>RuneLite-free, so the correlation and flush rules are unit-testable without a client.
 */
final class PersonalBests
{
	/** How long a kill-count line and a duration line can be apart and still be the same kill. */
	static final long CORRELATION_MS = 6_000;
	/** Settle time before a push — a raid prints several lines at once. */
	static final long QUIET_MS = 3_000;

	/** Best known time per activity, keyed lowercase. Lower is better; that's the whole model. */
	private final Map<String, Integer> best = new HashMap<>();
	/** What the server already has, so an unchanged PB is never re-sent. */
	private final Map<String, Integer> sent = new HashMap<>();
	/** Activities whose best has moved since the last successful push. */
	private final Set<String> dirty = new LinkedHashSet<>();

	/** The most recent activity name from a kill-count line, and when we saw it. */
	private String recentActivity;
	private long recentActivityAt;
	/** A PB that arrived before its activity did (Inferno ordering), awaiting a name. */
	private int orphanCentis;
	private long orphanAt;

	private long lastChangeAt;

	/** The activity a kill-count line just named. Cheap: two field writes, no parsing. */
	void onActivitySeen(String activity, long now)
	{
		if (activity == null || activity.isEmpty())
		{
			return;
		}
		recentActivity = activity.toLowerCase();
		recentActivityAt = now;
		// A duration that arrived first now has its name.
		if (orphanCentis > 0 && now - orphanAt <= CORRELATION_MS)
		{
			record(recentActivity, orphanCentis, now);
			orphanCentis = 0;
		}
	}

	/**
	 * Offer a chat line. Returns true when it produced a new best.
	 *
	 * <p>Lines with no personal best in them cost one {@code indexOf} — this runs on every line of
	 * chat, so the negative path is the one that has to be free.
	 */
	boolean onChatLine(String message, long now)
	{
		Integer centis = PersonalBestParser.parseCentis(message);
		if (centis == null)
		{
			return false;
		}
		if (recentActivity != null && now - recentActivityAt <= CORRELATION_MS)
		{
			return record(recentActivity, centis, now);
		}
		// No name yet — hold it for the kill-count line that's about to arrive.
		orphanCentis = centis;
		orphanAt = now;
		return false;
	}

	/**
	 * Import times recorded by another source (RuneLite's chat-commands store).
	 *
	 * @return how many were adopted as new bests
	 */
	int seed(Map<String, Integer> centisByActivity, long now)
	{
		if (centisByActivity == null || centisByActivity.isEmpty())
		{
			return 0;
		}
		int adopted = 0;
		for (Map.Entry<String, Integer> e : centisByActivity.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			if (record(e.getKey().toLowerCase(), e.getValue(), now))
			{
				adopted++;
			}
		}
		return adopted;
	}

	/** Keep the fastest. A PB only ever goes down, so a slower number is noise, not an update. */
	private boolean record(String activity, int centis, long now)
	{
		if (activity == null || activity.isEmpty() || centis <= 0)
		{
			return false;
		}
		Integer current = best.get(activity);
		if (current != null && current <= centis)
		{
			return false;
		}
		best.put(activity, centis);
		dirty.add(activity);
		lastChangeAt = now;
		return true;
	}

	boolean isDue(long now)
	{
		return !dirty.isEmpty() && now - lastChangeAt >= QUIET_MS;
	}

	/** The pending bests, activity → centiseconds. */
	Map<String, Integer> nextBatch()
	{
		Map<String, Integer> batch = new LinkedHashMap<>(dirty.size());
		for (String activity : dirty)
		{
			Integer centis = best.get(activity);
			if (centis != null)
			{
				batch.put(activity, centis);
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Anything that improved again mid-flight stays dirty, so the better
	 * time is sent next round rather than being silently dropped.
	 */
	void onSent(Map<String, Integer> batch)
	{
		for (Map.Entry<String, Integer> e : batch.entrySet())
		{
			sent.put(e.getKey(), e.getValue());
			Integer current = best.get(e.getKey());
			if (current != null && current.equals(e.getValue()))
			{
				dirty.remove(e.getKey());
			}
		}
	}

	int knownCount()
	{
		return best.size();
	}

	int pendingCount()
	{
		return dirty.size();
	}

	/** Forget everything — the next account's bests are not this one's. */
	void reset()
	{
		best.clear();
		sent.clear();
		dirty.clear();
		recentActivity = null;
		orphanCentis = 0;
		lastChangeAt = 0;
	}

	/**
	 * The delivered bests as one config string: {@code <centis>|<activity>} per line.
	 *
	 * <p>Value first for the same reason as the collection log's state: activity names contain
	 * colons and spaces, an integer can't contain a pipe, so the parse needs no escaping.
	 */
	String serializeState()
	{
		StringBuilder out = new StringBuilder(sent.size() * 20);
		for (Map.Entry<String, Integer> e : sent.entrySet())
		{
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('\n');
			}
			out.append(e.getValue()).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/**
	 * Restore delivered state. These count as known bests too — otherwise every login would re-push
	 * the whole set to tell the server what it already stored.
	 */
	void restoreState(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		for (String line : raw.split("\n"))
		{
			int pipe = line.indexOf('|');
			if (pipe <= 0 || pipe == line.length() - 1)
			{
				continue;
			}
			try
			{
				int centis = Integer.parseInt(line.substring(0, pipe));
				String activity = line.substring(pipe + 1);
				if (centis > 0)
				{
					sent.put(activity, centis);
					Integer current = best.get(activity);
					if (current == null || current > centis)
					{
						best.put(activity, centis);
					}
				}
			}
			catch (NumberFormatException e)
			{
				// Truncated or hand-edited: drop the line and let the next kill re-establish it.
			}
		}
	}
}

package com.anvil;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Collects a WHOLE collection log, as the server transmits it.
 *
 * <p>The client normally holds one page — whichever the player last drew — which is why the page
 * reader ({@link ClogPageReader}) can only ever report what someone has clicked through. But opening
 * the log and toggling its Search makes the server transmit EVERY entry, one script fire per item.
 * That's the whole log in one go, with no paging and nothing for the player to do but open the
 * interface. (The technique is WikiSync's; RuneProfile uses it too.)
 *
 * <p>This class is the accumulator and the "have they stopped arriving yet" policy. It is
 * RuneLite-free on purpose: the awkward parts are the quiet period and the guards against half a
 * transmit being sent as if it were a log, and both are worth testing without a client.
 *
 * <p>Item ids only — no page names. The site owns the catalogue (src/data/clog.json) and maps ids to
 * pages on the way in, so a game update that shuffles pages is a dataset rebuild rather than a
 * plugin release.
 */
final class ClogFullSync
{
	/**
	 * Items land over several ticks; wait this long after the last one before calling it complete.
	 * Two ticks and change — long enough that a transmit arriving in bursts isn't cut in half, short
	 * enough that a player who pressed a button isn't left watching an ellipsis.
	 */
	static final long QUIET_MS = 1_200;

	/**
	 * A transmit that yields fewer items than this is treated as noise rather than a log. The point
	 * is not to validate someone's collection — a genuinely empty log is possible — but to refuse to
	 * REPLACE a stored log with the tail end of an interrupted transmit (they closed the interface
	 * mid-flight, or another plugin's own search toggle fired one item).
	 */
	static final int MIN_ITEMS = 5;

	/** itemId -> quantity, in arrival order so a batch reads like the log does. */
	private final Map<Integer, Integer> items = new LinkedHashMap<>();

	private long lastItemAt;
	private boolean receiving;
	/** Set when the player asked for this explicitly, so a no-change sync still gets sent + reported. */
	private boolean manual;

	/** A transmit is starting (the log was opened / the button was pressed). Clears anything stale. */
	void begin(boolean manualRequest)
	{
		items.clear();
		receiving = true;
		manual = manual || manualRequest;
		lastItemAt = 0;
	}

	/** One item, straight off the transmit script. Ignored unless a transmit is actually in flight. */
	void onItem(int itemId, int quantity, long now)
	{
		if (!receiving || itemId <= 0)
		{
			return;
		}
		items.put(itemId, Math.max(1, quantity));
		lastItemAt = now;
	}

	/**
	 * Has a complete-looking transmit settled? True once nothing has arrived for {@link #QUIET_MS}
	 * and enough items landed to be a log rather than a fragment.
	 */
	boolean isDue(long now)
	{
		return receiving
			&& lastItemAt > 0
			&& items.size() >= MIN_ITEMS
			&& now - lastItemAt >= QUIET_MS;
	}

	/** True when the player pressed the button, so the caller can report the result in chat. */
	boolean isManual()
	{
		return manual;
	}

	/** Everything received, as an unmodifiable snapshot. Does not clear — see {@link #onSent}. */
	Map<Integer, Integer> snapshot()
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(items));
	}

	int size()
	{
		return items.size();
	}

	/**
	 * A cheap fingerprint of what was received, so an unchanged log isn't pushed twice.
	 *
	 * <p>The transmit re-sends everything every time the log is opened, and most opens change
	 * nothing. Order-independent (the game's transmit order is not ours to rely on) and includes
	 * quantities, so a second of the same item still counts as a change.
	 */
	synchronized long fingerprint()
	{
		long hash = items.size();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			// Mixed per entry then XORed in: adding an item changes it, and reordering doesn't.
			long h = e.getKey() * 0x9E3779B97F4A7C15L + e.getValue();
			hash ^= h ^ (h >>> 29);
		}
		return hash;
	}

	/** The push landed: drop the batch and stand down until the next transmit. */
	void onSent()
	{
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}

	/**
	 * The push failed. Keeps the items so the next tick can retry, but stops the clock restarting —
	 * a site that is down must not cost the player their transmit.
	 */
	void onSendFailed(long now)
	{
		lastItemAt = now;
	}

	/** Account switch / logout: a half-received log belongs to nobody. */
	void reset()
	{
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}
}

package com.anvil;

/**
 * How long to wait before trying a failed push again.
 *
 * <p>The profile syncs run off a fixed 30s tick, so a push that keeps failing is a request every 30
 * seconds for as long as the player stays logged in — against a site that has already said no. That
 * is rude to a clan's server and pointless for the player: the two cases are "your site is down"
 * (which wants patience) and "your site doesn't accept this" (which wants stopping altogether).
 *
 * <p>This covers the first: doubling waits from 30s to a 10-minute ceiling, reset by any success.
 * The second is the caller's job — a permanent failure drops the batch instead of backing off.
 */
final class SyncBackoff
{
	static final long FIRST_MS = 30_000L;
	static final long MAX_MS = 600_000L;

	private long nextAttemptAt;
	private long waitMs;

	/** Is a push allowed right now? True until something fails. */
	boolean ready(long now)
	{
		return now >= nextAttemptAt;
	}

	/** A push worked — back to normal cadence. */
	void onSuccess()
	{
		nextAttemptAt = 0;
		waitMs = 0;
	}

	/** A push failed for a reason that might clear on its own. Waits twice as long each time. */
	void onFailure(long now)
	{
		waitMs = waitMs == 0 ? FIRST_MS : Math.min(MAX_MS, waitMs * 2);
		nextAttemptAt = now + waitMs;
	}

	/** Seconds until the next attempt, for a log line that explains the silence. */
	long secondsUntilReady(long now)
	{
		return Math.max(0, (nextAttemptAt - now + 999) / 1000);
	}

	void reset()
	{
		onSuccess();
	}
}

