package com.anvil;

import org.junit.Test;
import static com.anvil.DeviceSignIn.isConfiguredHomeUrl;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The sign-in browser pin: only the CONFIGURED home origin + /link-device may ever open (§8 shape,
 * anchored to the member-typed Site URL instead of a hardcoded host). */
public class DeviceSignInTest
{
	private static final String HOME = "https://clan.anvilosrs.com";

	@Test
	public void acceptsOwnLinkDevicePage()
	{
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device"));
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device?code=ABCD-EFGH"));
	}

	@Test
	public void refusesForeignHosts()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com.evil.com/link-device"));
	}

	@Test
	public void refusesLookalikeAuthorityTricks()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com@evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com:8443/link-device")); // port mismatch
	}

	@Test
	public void refusesOtherPathsOnOwnHost()
	{
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/"));
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/profile"));
	}

	@Test
	public void refusesSchemeDowngrade()
	{
		// A https home never opens a http page; a deliberate http dev home may open its own http page.
		assertFalse(isConfiguredHomeUrl(HOME, "http://clan.anvilosrs.com/link-device"));
		assertTrue(isConfiguredHomeUrl("http://localhost:3000", "http://localhost:3000/link-device"));
	}

	@Test
	public void refusesGarbage()
	{
		assertFalse(isConfiguredHomeUrl(HOME, null));
		assertFalse(isConfiguredHomeUrl(HOME, ""));
		assertFalse(isConfiguredHomeUrl(HOME, "javascript:alert(1)"));
		assertFalse(isConfiguredHomeUrl(null, HOME + "/link-device"));
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PB capture: correlating a time with the activity that earned it, and never letting a slower run
 * overwrite a record.
 *
 * <p>Both message orderings are tested because the game uses both — the Inferno prints its duration
 * before the kill count, most bosses print it after.
 */
public class PersonalBestsTest
{
	@Test
	public void killCountThenDuration()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 1_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void durationThenKillCount()
	{
		PersonalBests pbs = new PersonalBests();
		// The Inferno's ordering: the time lands with nothing to attach it to yet.
		assertFalse(pbs.onChatLine("Duration: 2:58.03 (new personal best)", 1_000));
		assertTrue(pbs.nextBatch().isEmpty());
		pbs.onActivitySeen("TzKal-Zuk", 1_200);
		assertEquals(Integer.valueOf(17803), pbs.nextBatch().get("tzkal-zuk"));
	}

	@Test
	public void aStaleActivityIsNotCredited()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		// Ten minutes later, an unrelated PB line must not be filed under Zulrah.
		assertFalse(pbs.onChatLine("Duration: 1:00 (new personal best)", 600_000));
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void anOrphanTimeExpiresRatherThanAttachingToTheNextBoss()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onChatLine("Duration: 1:00 (new personal best)", 0);
		// A different boss, long after: the loose time must not land on it.
		pbs.onActivitySeen("Vorkath", 600_000);
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void onlyFasterTimesReplaceARecord()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Vorkath", 0);
		assertTrue(pbs.onChatLine("Fight duration: 1:30 (new personal best)", 10));
		pbs.onActivitySeen("Vorkath", 1_000);
		// A slower run reported as an explicit PB line still can't raise the record.
		assertFalse(pbs.onChatLine("Fight duration: 2:00. Personal best: 1:30.", 1_010));
		assertEquals(Integer.valueOf(9000), pbs.nextBatch().get("vorkath"));
		// A faster one does.
		pbs.onActivitySeen("Vorkath", 2_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:12 (new personal best)", 2_010));
		assertEquals(Integer.valueOf(7200), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void seedingAdoptsOnlyImprovements()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);

		Map<String, Integer> imported = new HashMap<>();
		imported.put("Zulrah", 12000);  // slower than what we have — ignored
		imported.put("Vorkath", 8000);  // new — adopted
		assertEquals(1, pbs.seed(imported, 100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void flushWaitsForQuiet()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_000);
		assertFalse(pbs.isDue(1_000 + PersonalBests.QUIET_MS - 1));
		assertTrue(pbs.isDue(1_000 + PersonalBests.QUIET_MS));
	}

	@Test
	public void stateSurvivesARestartAndIsNotResent()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Chambers of Xeric: Challenge Mode", 0);
		pbs.onChatLine("Duration: 40:00 (new personal best)", 10);
		pbs.onSent(pbs.nextBatch());
		String state = pbs.serializeState();

		PersonalBests restarted = new PersonalBests();
		restarted.restoreState(state);
		assertEquals(1, restarted.knownCount());
		assertEquals(0, restarted.pendingCount());
		// A slower run after the restart is still not a record.
		restarted.onActivitySeen("Chambers of Xeric: Challenge Mode", 100);
		assertFalse(restarted.onChatLine("Duration: 45:00 (new personal best)", 110));
	}

	@Test
	public void anImprovementMidFlightStaysPending()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);
		Map<String, Integer> inFlight = pbs.nextBatch();
		// A better time lands while the request is on the wire.
		pbs.onActivitySeen("Zulrah", 20);
		pbs.onChatLine("Fight duration: 1:20 (new personal best)", 30);
		pbs.onSent(inFlight);
		assertEquals(1, pbs.pendingCount());
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void ordinaryChatCostsNothingAndRecordsNothing()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		assertFalse(pbs.onChatLine("Your Zulrah kill count is: 1,204.", 10));
		assertFalse(pbs.onChatLine("Oh dear, you are dead!", 20));
		assertNull(pbs.nextBatch().get("zulrah"));
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Exercises the real {@link AnvilSidebarDataSource} without a network: an unconfigured
 * {@link BingoApiClient} makes {@code fetchActivity} return null, so we drive the config→ConnectionView
 * shaping — summary, nearest tiles, and the "Active now" attribution from config deltas + local signal.
 */
public class AnvilSidebarDataSourceTest
{
	/** Assert the connection has exactly one active task, on {@code tileId}, credited to {@code worker}. */
	private static void assertSingleActive(ConnectionView c, int tileId, boolean self, String worker)
	{
		assertEquals(1, c.activeNow.size());
		ConnectionView.ActiveTask t = c.activeNow.get(0);
		assertEquals(tileId, t.tile.tileId);
		assertEquals(self, t.includesSelf);
		assertEquals(worker, t.workers.get(0));
	}

	private static PluginConfigResponse.TrackedDrop drop(int id, String label, int cur, int req)
	{
		PluginConfigResponse.TrackedDrop d = new PluginConfigResponse.TrackedDrop();
		d.tileId = id;
		d.label = label;
		d.currentAmount = cur;
		d.requiredAmount = req;
		d.itemIds = new ArrayList<>();
		return d;
	}

	private static PluginConfigResponse.TrackedStat stat(int id, String label, String statName, int cur, int goal)
	{
		PluginConfigResponse.TrackedStat s = new PluginConfigResponse.TrackedStat();
		s.tileId = id;
		s.label = label;
		s.statName = statName;
		s.statType = "skill";
		s.currentAmount = cur;
		s.goalAmount = goal;
		return s;
	}

	private static PluginConfigResponse eventConfig()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.id = 5;
		cfg.event.name = "Summer Bingo";
		cfg.team = new PluginConfigResponse.TeamInfo();
		cfg.team.name = "Team Molten";
		cfg.trackedDrops = new ArrayList<>(Arrays.asList(
			drop(101, "500 Zulrah KC", 5, 10),     // 50% — incomplete
			drop(102, "Dragon warhammer", 1, 1),   // complete
			drop(103, "Any barrows item", 4, 5)    // 80% — nearest
		));
		return cfg;
	}

	/** {@link #eventConfig()} plus one skill-XP stat tile at 50%. */
	private static PluginConfigResponse statConfig()
	{
		PluginConfigResponse cfg = eventConfig();
		cfg.trackedStats = new ArrayList<>(Arrays.asList(
			stat(201, "2M Fishing XP", "fishing", 1_000_000, 2_000_000)));
		return cfg;
	}

	private static BingoApiClient unconfigured()
	{
		return new BingoApiClient(new Gson(), new OkHttpClient());
	}

	private static AnvilSidebarDataSource newSource(java.util.function.Supplier<PluginConfigResponse> cfg)
	{
		return new AnvilSidebarDataSource(cfg, unconfigured());
	}

	@Test
	public void noEventYieldsHomeStubCard() throws Exception
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.clanName = "The AFK Spot";
		AnvilSidebarDataSource ds = newSource(() -> cfg);

		// No member-scoped event still renders a HOME card (clan name, no board) — an empty list
		// would make the home clan vanish from a federated sidebar.
		List<ConnectionView> conns = ds.fetchConnections();
		assertEquals(1, conns.size());
		assertEquals("The AFK Spot", conns.get(0).clanName);
		assertEquals(0, conns.get(0).tilesTotal);
		assertNull(conns.get(0).statusNote); // no unlinked event → the generic "No active event yet."
	}

