	/** A client that serves a canned leaderboard offline and counts the reads (for the throttle test). */
	private static final class StubWeeklyClient extends BingoApiClient
	{
		final List<Integer> reads = new ArrayList<>();
		final WeeklyLeaderboard board;

		StubWeeklyClient(WeeklyLeaderboard board)
		{
			super(new Gson(), new OkHttpClient());
			this.board = board;
		}

		@Override
		public WeeklyLeaderboard fetchWeeklyLeaderboard(Integer competitionId)
		{
			reads.add(competitionId);
			return board;
		}
	}

	private static BingoApiClient.LeaderboardEntry entry(int rank, String rsn, long gained)
	{
		BingoApiClient.LeaderboardEntry e = new BingoApiClient.LeaderboardEntry();
		e.rank = rank;
		e.rsn = rsn;
		e.gained = gained;
		return e;
	}

	/** A 12-deep board with the caller sitting at #12, below the sidebar's top-10 cut. */
	private static BingoApiClient.WeeklyLeaderboard deepBoard()
	{
		BingoApiClient.WeeklyLeaderboard lb = new BingoApiClient.WeeklyLeaderboard();
		lb.total = 30;
		lb.entries = new ArrayList<>();
		for (int i = 1; i <= 11; i++)
		{
			lb.entries.add(entry(i, "Player " + i, 1_000_000L - i));
		}
		// OSRS display names carry non-breaking spaces — the "you" match must see through that.
		lb.entries.add(entry(12, "Ahmed Two", 4200));
		lb.competition = new BingoApiClient.WeeklyComp();
		return lb;
	}

	@Test
	public void standingsFoldInTheCallersRowEvenBelowTheCut() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(new PluginConfigResponse(),
			weekly(7, "Mining Madness", "skill", "mining", "active"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> "ahmed two");

		ConnectionView.WeeklyView w = ds.fetchConnections().get(0).weeklies.get(0);
		assertEquals(12, w.yourRank);
		assertEquals(4200, w.yourGained);
		assertEquals(30, w.participants);
		// Top 10 + the caller's own out-of-view row, and only that row is flagged as theirs.
		assertEquals(11, w.top.size());
		assertEquals(12, w.top.get(10).rank);
		assertTrue(w.top.get(10).self);
		assertFalse(w.top.get(0).self);
	}

	@Test
	public void standingsAreThrottledAcrossPollsButRefreshForcesARead() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(new PluginConfigResponse(),
			weekly(7, "Mining Madness", "skill", "mining", "active"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> null);

		ds.fetchConnections();   // first read
		ds.fetchConnections();   // 15 s poll — must reuse the cached board
		ds.fetchConnections();
		assertEquals(1, client.reads.size());

		ds.fetchConnections(true); // the member clicked Refresh — read now
		assertEquals(2, client.reads.size());
		// The cached standings survive the throttled polls, so the card never goes blank between reads.
		assertEquals(30, ds.fetchConnections().get(0).weeklies.get(0).participants);
		assertEquals(2, client.reads.size());
	}

	@Test
	public void anUpcomingWeeklyIsAnnouncedButNeverRead() throws Exception
	{
		PluginConfigResponse cfg = withSchedule(eventConfig(),
			weekly(9, "Next week's comp", "skill", "fishing", "upcoming"));
		StubWeeklyClient client = new StubWeeklyClient(deepBoard());
		AnvilSidebarDataSource ds = new AnvilSidebarDataSource(() -> cfg, client,
			java.util.Collections::emptyMap, () -> "ahmed two");

		ConnectionView.WeeklyView w = ds.fetchConnections().get(0).weeklies.get(0);
		assertTrue(w.upcoming);
		// Nothing has happened in it yet, so there's no leaderboard worth a request.
		assertTrue(client.reads.isEmpty());
		assertTrue(w.top.isEmpty());
		assertEquals(0, w.yourRank);
	}

	@Test
	public void noWeekliesAtAllYieldsNoWeeklyEvents() throws Exception
	{
		assertTrue(newSource(AnvilSidebarDataSourceTest::eventConfig)
			.fetchConnections().get(0).weeklies.isEmpty());
	}

	@Test
	public void otherAndUpcomingBingosRideAlongWithoutYourOwn() throws Exception
	{
		PluginConfigResponse cfg = eventConfig();   // the caller's own event is id 5
		cfg.schedule = new BingoApiClient.ScheduleResponse();
		cfg.schedule.bingos = new ArrayList<>(Arrays.asList(
			bingo(9, "Autumn Bingo", "upcoming", "2026-09-01T00:00:00Z"),
			bingo(5, "Summer Bingo", "active", "2026-07-01T00:00:00Z"),   // the caller's own board
			bingo(6, "Someone else's", "active", "2026-07-20T00:00:00Z")));

		List<ConnectionView.ScheduledView> scheduled = newSource(() -> cfg).fetchConnections().get(0).scheduled;
		// Own event dropped (the board card IS that event); live first, then soonest upcoming.
		assertEquals(2, scheduled.size());
		assertEquals(6, scheduled.get(0).id);
		assertTrue(scheduled.get(0).live);
		assertEquals(9, scheduled.get(1).id);
		assertFalse(scheduled.get(1).live);
	}

	@Test
	public void eventEndingResetsToEmpty() throws Exception
	{
		PluginConfigResponse cfg = eventConfig();
		final PluginConfigResponse[] holder = { cfg };
		AnvilSidebarDataSource ds = newSource(() -> holder[0]);

		assertEquals(1, ds.fetchConnections().size());
		holder[0] = new PluginConfigResponse();      // event ended
		// Post-event the home still renders — as the board-less stub card, not an empty sidebar.
		ConnectionView after = ds.fetchConnections().get(0);
		assertEquals(0, after.tilesTotal);
		assertTrue(after.nearestTiles.isEmpty());
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What the side panel is allowed to offer, per clan.
 *
 * The rule that matters: a roster is scraped from the clan channel this account is standing in, so
 * it can never be synced for a clan you aren't in — admin or not — because you cannot see it.
 */
public class SidebarActionsTest
{
	private static AnvilSidebarDataSource source()
	{
		return new AnvilSidebarDataSource(() -> new PluginConfigResponse(),
			new BingoApiClient(new Gson(), new OkHttpClient()));
	}

	@Test
	public void offersNothingForAnotherClan()
	{
		SidebarDataSource.PanelActions remote = source().actionsFor("some-other-clan");
		assertFalse("a roster you can't see is not a button", remote.canSyncRoster);
		assertFalse("and there is no wire to send a profile there yet", remote.canSyncProfile);
		assertNull(remote.rosterNote);
	}

	@Test
	public void offersNothingWithNoPluginBound()
	{
		// Tests and the pre-wiring window: the panel must render rather than blow up.
		SidebarDataSource.PanelActions home = source().actionsFor(AnvilSidebarDataSource.LOCAL_INSTANCE_ID);
		assertFalse(home.canSyncRoster);
		assertFalse(home.canSyncProfile);
	}

	@Test
	public void theFederatedSourcePassesActionsThrough()
	{
		AnvilSidebarDataSource home = source();
		SidebarDataSource relayed = new FederationSidebarDataSource(
			new BingoApiClient(new Gson(), new OkHttpClient()), home, url -> true, (step, delayMs) -> step.run());
		// Same answer either way — the actions belong to the home clan, not to the relay layer.
		assertEquals(home.actionsFor(AnvilSidebarDataSource.LOCAL_INSTANCE_ID).canSyncRoster,
			relayed.actionsFor(AnvilSidebarDataSource.LOCAL_INSTANCE_ID).canSyncRoster);
		assertTrue(relayed.bannerSounds().isEmpty());
	}

	@Test
	public void bannerSoundCallsAreSafeWithoutAPlugin()
	{
		AnvilSidebarDataSource ds = source();
		ds.toggleBannerSound("nope.wav");
		ds.copyBannerSoundsPath();
		ds.importBannerSounds();
		assertFalse(ds.bannerSoundOn("nope.wav"));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The Hallowed Sepulchre announces itself in its own shape rather than the "Your &lt;X&gt; count
 * is: N" one every other activity uses, so agility tiles targeting it rest entirely on these two
 * patterns. Both lines carry a running total that must stay OUT of the credit path — one line is
 * one credit, so a player arriving with 4,000 coffins already opened starts an event on zero.
 */
public class SepulchreLineTest
{
	private static String floorOf(String line)
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(line);
		return m.find() ? m.group(1) : null;
	}

	@Test
	public void parsesFloorCompletion()
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(
			"You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 1,234.");
		assertTrue(m.find());
		assertEquals("3", m.group(1));
		assertEquals("1,234", m.group(2));
	}

	/** Every floor announces separately — a full 1→5 run emits five lines, so five credits. */
	@Test
	public void parsesEveryFloor()
	{
		for (int floor = 1; floor <= 5; floor++)
		{
			String line = "You have completed Floor " + floor
				+ " of the Hallowed Sepulchre! Total completions: 7.";
			assertEquals(String.valueOf(floor), floorOf(line));
		}
	}

	@Test
	public void parsesGrandHallowedCoffinPlural()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	/** The first-ever coffin says "1 time!", not "1 times!" — the optional s is load-bearing. */
	@Test
	public void parsesGrandHallowedCoffinSingular()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 1 time!").find());
	}

	/**
	 * The Sepulchre lines must not also match the generic KC parser: a double match would credit a
	 * floor twice on clients where a tile happens to carry both name shapes.
	 */
	@Test
	public void sepulchreLinesDoNotMatchTheGenericKcParser()
	{
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertEquals(null, floorOf("You have completed the Hallowed Sepulchre course."));
		assertFalse(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the coffin.").find());
	}

	// ---- Hunter Guild rumours -------------------------------------------------------------

	@Test
	public void parsesRumourCompletion()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 42 rumours for the Hunter Guild.").find());
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1,250 rumours for the Hunter Guild.").find());
	}

	/** The first hand-in reads "1 rumour" — the optional s is load-bearing, as with the coffin. */
	@Test
	public void parsesSingularRumour()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1 rumour for the Hunter Guild.").find());
	}

	@Test
	public void rumourLineIsNotConfusedWithTheSepulchreFloorLine()
	{
		assertFalse(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertEquals(null, floorOf("You have completed 42 rumours for the Hunter Guild."));
	}

	// ---- Woodcutting Guild egg offerings --------------------------------------------------

	@Test
	public void parsesEggOfferings()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 7 offerings.").find());
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 1,024 offerings.").find());
	}

	/** The first offering reads "one offering", spelled out — not a digit. */
	@Test
	public void parsesFirstEggOfferingSpelledOut()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made one offering.").find());
	}

	/**
	 * The offering line never names the activity, so the trailing full stop is the only thing
	 * stopping it from swallowing longer sentences that merely start the same way.
	 */
	@Test
	public void offeringLineDoesNotSwallowLongerSentences()
	{
		assertFalse(AnvilPlugin.EGG_OFFERING_PATTERN
			.matcher("You have made 3 offerings to the shrine and received nothing").find());
	}

	// ---- Brimhaven Agility Arena ----------------------------------------------------------

	/**
	 * Brimhaven counts TICKETS, and its counter word is two words long. Without it in the pattern
	 * the arena's name parses as "Agility Arena Total Ticket" and matches no tile.
	 */
	@Test
	public void brimhavenTicketCounterWordStaysOutOfTheName()
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("Your Agility Arena Total Ticket count is: 480.");
		assertTrue(m.find());
		assertEquals("Agility Arena", m.group(1).trim());
		assertEquals("480", m.group(2));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AnvilActivityLogTest
{
	private static ActivityEntry sub(String id, String ts, String player, String label, int amount, boolean self)
	{
		return new ActivityEntry(id, ts, player, 1, label, ActivityEntry.Kind.PROGRESS, amount, self);
	}

	private static ActivityEntry done(String id, String ts, String player, String label)
	{
		return new ActivityEntry(id, ts, player, 1, label, ActivityEntry.Kind.COMPLETE, 0, false);
	}

	@Test
	public void ingestPutsNewestOnTop()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		// Server sends ascending (oldest→newest).
		int added = log.ingest("s3_c0", Arrays.asList(
			sub("s1", "t1", "A", "x", 1, false),
			sub("s2", "t2", "B", "y", 1, false),
			sub("s3", "t3", "C", "z", 1, false)));
		assertEquals(3, added);
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s3", snap.get(0).id); // newest first
		assertEquals("s2", snap.get(1).id);
		assertEquals("s1", snap.get(2).id);
		assertEquals("s3_c0", log.getCursor());
	}

	@Test
	public void dedupsByIdAcrossOverlappingBatches()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		assertEquals(2, log.ingest("s2_c0", Arrays.asList(sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "B", "y", 1, false))));
		// The client re-sends an overlapping batch until its cursor advances — s2 must not double.
		assertEquals(1, log.ingest("s3_c0", Arrays.asList(sub("s2", "t", "B", "y", 1, false),
			sub("s3", "t", "C", "z", 1, false))));
		assertEquals(3, log.size());
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s3", snap.get(0).id);
		assertEquals("s2", snap.get(1).id);
		assertEquals("s1", snap.get(2).id);
	}

	@Test
	public void evictsOldestBeyondCapacity()
	{
		AnvilActivityLog log = new AnvilActivityLog(3);
		log.ingest("s5_c0", Arrays.asList(
			sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "A", "x", 1, false),
			sub("s3", "t", "A", "x", 1, false),
			sub("s4", "t", "A", "x", 1, false),
			sub("s5", "t", "A", "x", 1, false)));
		assertEquals(3, log.size());
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s5", snap.get(0).id);
		assertEquals("s4", snap.get(1).id);
		assertEquals("s3", snap.get(2).id); // s1, s2 evicted
	}

	@Test
	public void evictedIdCanReappear()
	{
		AnvilActivityLog log = new AnvilActivityLog(2);
		log.ingest("s3_c0", Arrays.asList(
			sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "A", "x", 1, false),
			sub("s3", "t", "A", "x", 1, false))); // s1 evicted, seenIds must drop it too
		// If seenIds were leaked, this would be treated as a dup (added 0); it must be re-added.
		assertEquals(1, log.ingest("s3_c0", Collections.singletonList(sub("s1", "t", "A", "x", 1, false))));
	}

	@Test
	public void nullCursorLeavesCursorUnchanged()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		log.ingest("s7_c2", Collections.singletonList(sub("s7", "t", "A", "x", 1, false)));
		log.ingest(null, Collections.<ActivityEntry>emptyList());
		assertEquals("s7_c2", log.getCursor());
	}

	@Test
	public void resetClearsEverything()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		log.ingest("s2_c1", Arrays.asList(sub("s1", "t", "A", "x", 1, false), done("c1", "t", "B", "y")));
		log.reset();
		assertTrue(log.isEmpty());
		assertEquals(AnvilActivityLog.EMPTY_CURSOR, log.getCursor());
	}

	@Test
	public void nullAndBlankIdsAreIgnored()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		int added = log.ingest("s1_c0", Arrays.asList(
			sub("", "t", "A", "x", 1, false),
			(ActivityEntry) null,
			sub("s1", "t", "A", "x", 1, false)));
		assertEquals(1, added);
		assertEquals(1, log.size());
	}

	@Test
	public void summaryReadsLikeAFeedLine()
	{
		assertEquals("You +3 · Dragon warhammer",
			sub("s1", "t", "Bob", "Dragon warhammer", 3, true).summary());
		assertEquals("Kayle +1 · Zulrah unique",
			sub("s2", "t", "Kayle", "Zulrah unique", 1, false).summary());
		assertEquals("Kayle completed Tanzanite fang",
			done("c1", "t", "Kayle", "Tanzanite fang").summary());
		// Unattributed completion falls back to the team.
		assertEquals("Team completed Some stat tile",
			done("c2", "t", null, "Some stat tile").summary());
	}

	@Test
	public void selfCompletionSaysYou()
	{
		ActivityEntry e = new ActivityEntry("c9", "t", "Me", 1, "Inferno cape",
			ActivityEntry.Kind.COMPLETE, 0, true);
		assertEquals("You completed Inferno cape", e.summary());
	}

	@Test
	public void kindFromWireMapsServerStrings()
	{
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("complete"));
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("COMPLETE"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("progress"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire(null));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("garbage"));
	}

	@Test
	public void aggregateForDisplayFoldsAGrindByWorkerAndTile()
	{
		// Newest-first: 3 of Kayle's "+1" kills on tile 5, a completion, then one of YOUR kills on tile 5.
		List<ActivityEntry> feed = Arrays.asList(
			new ActivityEntry("s30", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("s29", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("c9", "t", "Sara", 6, "Complete 25 ToA", ActivityEntry.Kind.COMPLETE, 0, false),
			new ActivityEntry("s28", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("s27", "t", "You", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 2, true));

		List<ActivityEntry> agg = AnvilActivityLog.aggregateForDisplay(feed);

		assertEquals(3, agg.size());                       // 3 Kayle kills fold to 1; completion; your line stays
		assertEquals("s30", agg.get(0).id);                // newest occurrence's metadata kept
		assertEquals("Kayle +3 · Kill 500 Dust devils", agg.get(0).summary());
		assertTrue(agg.get(1).isCompletion());             // completion preserved in place
		assertEquals(2, agg.get(2).amount);                // your own tile-5 grind is a separate line
		assertTrue(agg.get(2).self);
	}
}

package com.anvil;

import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The ladder missions board's pure math ({@link LadderMissions}): the grow/decay ramp mirrors the
 * server's completionAward formula ({@code face * (1 - (1 - targetPct/100) * frac)}), and the
 * per-second countdown. Kept in lockstep with Anvil.Site/src/lib/eventRules.ts.
 */
public class LadderMissionsTest
{
	private static PluginConfigResponse.Decay decay(int targetPct, int hours)
	{
		PluginConfigResponse.Decay d = new PluginConfigResponse.Decay();
		d.targetPct = targetPct;
		d.hours = hours;
		return d;
	}

	private static String isoAgo(long ms)
	{
		return Instant.ofEpochMilli(System.currentTimeMillis() - ms).toString();
	}

	@Test
	public void faceWhenNoDecayOrNoRevealTime()
	{
		long now = System.currentTimeMillis();
		assertEquals(100, LadderMissions.liveValue(100, isoAgo(0), null, now));
		assertEquals(100, LadderMissions.liveValue(100, null, decay(50, 24), now));
		assertEquals(100, LadderMissions.liveValue(100, "not-a-time", decay(50, 24), now));
	}

	@Test
	public void decaysLinearlyToTargetOverTheWindow()
	{
		long now = System.currentTimeMillis();
		// 200-pt mission, decays to 50% over 24h. At reveal → 200; half-way (12h) → 150; full → 100; past → 100.
		PluginConfigResponse.Decay d = decay(50, 24);
		assertEquals(200, LadderMissions.liveValue(200, isoAgo(0), d, now));
		assertEquals(150, LadderMissions.liveValue(200, isoAgo(12L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(24L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(48L * 3_600_000), d, now)); // clamps at the floor
	}

	@Test
	public void growsToTargetAboveFace()
	{
		long now = System.currentTimeMillis();
		// 100-pt mission that GROWS to 200% over 10h. Half-way → 150; full → 200; capped after.
		PluginConfigResponse.Decay d = decay(200, 10);
		assertEquals(150, LadderMissions.liveValue(100, isoAgo(5L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(10L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(20L * 3_600_000), d, now));
	}

	@Test
	public void valueLabelShowsMovementOnly()
	{
		assertEquals("120", LadderMissions.valueLabel(120, 120));
		assertEquals("120 -> 90", LadderMissions.valueLabel(120, 90));
		assertEquals("120 -> 200", LadderMissions.valueLabel(120, 200));
	}

	@Test
	public void countdownFormatsMinuteSecondAndDue()
	{
		long now = System.currentTimeMillis();
		assertEquals("12:34", LadderMissions.countdown(Instant.ofEpochMilli(now + (12 * 60 + 34) * 1000L).toString(), now));
		assertEquals("0:09", LadderMissions.countdown(Instant.ofEpochMilli(now + 9_000L).toString(), now));
		assertEquals("1:02:03", LadderMissions.countdown(Instant.ofEpochMilli(now + (3600 + 2 * 60 + 3) * 1000L).toString(), now));
		assertEquals("now", LadderMissions.countdown(Instant.ofEpochMilli(now - 1000L).toString(), now));
		assertNull(LadderMissions.countdown(null, now));
		assertNull(LadderMissions.countdown("", now));
	}

	@Test
	public void isLadderMatchesOnlyLadder()
	{
		assertTrue(LadderMissions.isLadder("ladder"));
		assertTrue(LadderMissions.isLadder("Ladder"));
		assertTrue(!LadderMissions.isLadder("bingo"));
		assertTrue(!LadderMissions.isLadder(null));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Verifies the Jagex kill-count chat-line parsing that drives real-time boss-KC pushes, KC-line
 * kill crediting, and the KC shown on rare-drop posts. The captured boss name must exactly match
 * the server's trackedKcNames watch-list (after shared normalization), so counter words that vary
 * by activity ("completion", "chest", "success", …) and the "subdued"/"completed" prefixes must
 * never leak into it — the Gauntlet's "completion count" wording did exactly that and silently
 * killed its real-time tracking.
 */
public class KillCountLineTest
{
	/** Runs a line through the plugin's KC parse: [bossName, count], or null when it doesn't match. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		return new String[]{m.group(1).trim(), m.group(2)};
	}

	@Test
	public void parsesPlainKillCount()
	{
		String[] r = parse("Your Leviathan kill count is: 42.");
		assertEquals("Leviathan", r[0]);
		assertEquals("42", r[1]);
	}

	@Test
	public void parsesRaidCompletedVariant()
	{
		String[] r = parse("Your completed Chambers of Xeric count is: 125.");
		assertEquals("Chambers of Xeric", r[0]);
		assertEquals("125", r[1]);
	}

	@Test
	public void parsesRaidModeVariantWithColon()
	{
		String[] r = parse("Your completed Tombs of Amascut: Expert Mode count is: 8.");
		assertEquals("Tombs of Amascut: Expert Mode", r[0]);
		assertEquals("8", r[1]);
	}

	@Test
	public void completionCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Gauntlet completion count is: 15.");
		assertEquals("Gauntlet", r[0]);
		assertEquals("15", r[1]);
	}

	@Test
	public void corruptedGauntletCompletionVariant()
	{
		String[] r = parse("Your Corrupted Gauntlet completion count is: 3.");
		assertEquals("Corrupted Gauntlet", r[0]);
		assertEquals("3", r[1]);
	}

	@Test
	public void subduedPrefixStaysOutOfName()
	{
		String[] r = parse("Your subdued Wintertodt count is: 200.");
		assertEquals("Wintertodt", r[0]);
		assertEquals("200", r[1]);
	}

	@Test
	public void chestCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Barrows chest count is: 310.");
		assertEquals("Barrows", r[0]);
		assertEquals("310", r[1]);
	}

	@Test
	public void successCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Zalcano success count is: 61.");
		assertEquals("Zalcano", r[0]);
		assertEquals("61", r[1]);
	}

	@Test
	public void parsesThousandsSeparators()
	{
		String[] r = parse("Your Zulrah kill count is: 1,250.");
		assertEquals("Zulrah", r[0]);
		assertEquals("1,250", r[1]);
	}

	/**
	 * Agility-lap tiles are kill tiles whose targets are course names, so the whole kind rests on
	 * the "lap" counter word staying out of the captured name. A course whose name reaches the
	 * index as "Ardougne Rooftop lap" matches nothing and the tile counts zero for a whole event.
	 */
	@Test
	public void lapCounterWordStaysOutOfCourseName()
	{
		String[] r = parse("Your Gnome Stronghold Agility lap count is: 1.");
		assertEquals("Gnome Stronghold Agility", r[0]);
		assertEquals("1", r[1]);
	}

	@Test
	public void parsesRooftopLapCountWithApostropheAndThousands()
	{
		String[] r = parse("Your Seers' Village Rooftop lap count is: 1,234.");
		assertEquals("Seers' Village Rooftop", r[0]);
		assertEquals("1,234", r[1]);
	}

	/** The Colossal Wyrm courses parenthesise their tier — the brackets are part of the name. */
	@Test
	public void parsesParenthesisedCourseTier()
	{
		String[] r = parse("Your Colossal Wyrm Agility Course (Advanced) lap count is: 5.");
		assertEquals("Colossal Wyrm Agility Course (Advanced)", r[0]);
		assertEquals("5", r[1]);
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertNull(parse("Your heart is racing."));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the timed-clear chat parsing against REAL in-game completion messages. These are the
 * fragile, game-version-specific bits — if Jagex changes a string, a test here goes red and tells
 * you exactly which activity's auto-detect broke (the site's manual time submit is the fallback).
 */
public class TimedClearParserTest
{
	@Test
	public void parsesDurationWithFractionalSeconds()
	{
		// Inferno
		assertEquals(Integer.valueOf(178), TimedClearParser.parseDurationSeconds("Duration: 2:58.03 (new personal best)"));
		// TzHaar-Ket-Rak's challenge
		assertEquals(Integer.valueOf(534), TimedClearParser.parseDurationSeconds("Challenge duration: 8:54.00 (new personal best)"));
		// Fortis Colosseum (final wave time)
		assertEquals(Integer.valueOf(2012), TimedClearParser.parseDurationSeconds("Wave 12 completed! Wave duration: 33:32.40"));
	}

	@Test
	public void parsesPlainDuration()
	{
		// Nightmare
		assertEquals(Integer.valueOf(1475), TimedClearParser.parseDurationSeconds("Team size: Solo Fight duration: 24:35 (new personal best)"));
		// Chambers of Xeric raid-complete message
		assertEquals(Integer.valueOf(939), TimedClearParser.parseDurationSeconds("Congratulations - your raid is complete! Duration: 15:39"));
	}

	@Test
	public void parsesHourLongDuration()
	{
		assertEquals(Integer.valueOf(3750), TimedClearParser.parseDurationSeconds("Theatre of Blood total completion time: 1:02:30"));
	}

	@Test
	public void parsesThreeDigitMinuteDurations()
	{
		// Slow Inferno/Zuk clears print raw minutes past 99 — real formats captured by RuneLite's
		// chat-commands tests: "Duration: 172:18. Personal best: 134:52".
		assertEquals(Integer.valueOf(10338), TimedClearParser.parseDurationSeconds("Duration: 172:18. Personal best: 134:52"));
		assertEquals(Integer.valueOf(6271), TimedClearParser.parseDurationSeconds("Duration: 104:31 (new personal best)"));
	}

	@Test
	public void parsesTimeColonFormats()
	{
		// Sailing Barracuda Trials
		assertEquals(Integer.valueOf(364), TimedClearParser.parseDurationSeconds("Time: 6:04.20 (new personal best)."));
		// Hallowed Sepulchre floor + overall lines
		assertEquals(Integer.valueOf(407), TimedClearParser.parseDurationSeconds("Floor 5 time: 6:47.40 (new personal best)"));
		assertEquals(Integer.valueOf(1599), TimedClearParser.parseDurationSeconds("Overall time: 26:39.20 (new personal best)"));
	}

	@Test
	public void usesRaidTotalTimeNotRoomOrChallengeSubTimes()
	{
		// The raid clear time is the "total completion time" line — accept it (ToA + ToB).
		assertEquals(Integer.valueOf(2090), TimedClearParser.parseDurationSeconds(
			"Tombs of Amascut: Expert Mode total completion time: 34:50. Personal best: 18:31"));
		assertEquals(Integer.valueOf(3750), TimedClearParser.parseDurationSeconds(
			"Theatre of Blood total completion time: 1:02:30"));
		// ToA sub-times must NOT parse — crediting the 7:05 final room let a 34:50 raid pass a
		// 25-minute tile. Reject the per-room, per-challenge, and rooms-only aggregate lines.
		assertNull(TimedClearParser.parseDurationSeconds("Challenge complete: The Wardens. Duration: 7:05"));
		assertNull(TimedClearParser.parseDurationSeconds("Challenge time: 10:23"));
		assertNull(TimedClearParser.parseDurationSeconds(
			"Tombs of Amascut: Expert Mode challenge completion time: 30:16. Personal best: 16:08"));
		// But "Challenge duration:" (Gauntlet / Corrupted Gauntlet / TzHaar-Ket-Rak) is a real
		// clear time and must still parse.
		assertEquals(Integer.valueOf(534), TimedClearParser.parseDurationSeconds("Challenge duration: 8:54.00 (new personal best)"));
		assertEquals(Integer.valueOf(624), TimedClearParser.parseDurationSeconds("Corrupted challenge duration: 10:24. Personal best: 7:59."));
	}

	@Test
	public void parsesTemporossSubduedFormat()
	{
		assertEquals(Integer.valueOf(392), TimedClearParser.parseDurationSeconds("Subdued in 6:32 (new personal best)."));
	}

	@Test
	public void ignoresMessagesWithoutADurationKeyword()
	{
		// A failed Inferno/TzHaar attempt carries a time but no "duration"/"completion time" keyword.
		assertNull(TimedClearParser.parseDurationSeconds("You survived for 1:16.80 but failed to kill any JalTok-Jads before perishing."));
		assertNull(TimedClearParser.parseDurationSeconds("Your TzKal-Zuk kill count is: 1."));
		assertNull(TimedClearParser.parseDurationSeconds(null));
		// Countdowns aren't clears: "time" without a fused colon must not parse.
		assertNull(TimedClearParser.parseDurationSeconds("Time remaining: 5:00"));
		// Clan broadcast carries the time after "personal best:" — no duration keyword.
		assertNull(TimedClearParser.parseDurationSeconds("Drenvox mdps has achieved a new Maggot King personal best: 1:19"));
	}

	@Test
	public void matchesBarracudaTrialIdentityLines()
	{
		// Specific-course tiles ride the plain fallback — both flanking lines name the course.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Gwenith Glide"));
		assertTrue(TimedClearParser.messageMatchesActivity(
			"You have completed the Gwenith Glide and achieved the Marlin rank.", "The Gwenith Glide"));
		// A generic any-trial tile matches every course via the signature table.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Barracuda Trials"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Tempor Tantrum completion count is: 3", "Barracuda Trials"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Tempor Tantrum"));
	}

	@Test
	public void matchesSepulchreRunsAndFloors()
	{
		// Full-run tiles: the "Overall time" exit line both carries the time and identifies the run.
		assertTrue(TimedClearParser.messageMatchesActivity("Overall time: 26:39.20 (new personal best)", "Hallowed Sepulchre"));
		assertFalse(TimedClearParser.messageMatchesActivity("Floor 5 time: 6:47.40 (new personal best)", "Hallowed Sepulchre"));
		// Floor tiles ride the fallback against the floor line itself.
		assertTrue(TimedClearParser.messageMatchesActivity("Floor 5 time: 6:47.40 (new personal best)", "Floor 5"));
	}

	@Test
	public void matchesActivityFromTheAdjacentIdentityLine()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your TzKal-Zuk kill count is: 1.", "Inferno"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Sol Heredit kill count is: 100.", "Fortis Colosseum"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Chambers of Xeric count is: 306.", "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Nightmare kill count is: 11.", "Nightmare"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completion count for TzHaar-Ket-Rak's Sixth Challenge is: 1.", "TzHaar-Ket-Rak"));
	}

	@Test
	public void doesNotCrossMatchUnrelatedActivities()
	{
		assertFalse(TimedClearParser.messageMatchesActivity("Your Sol Heredit kill count is: 100.", "Inferno"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your TzKal-Zuk kill count is: 1.", "Chambers of Xeric"));
	}

	@Test
	public void matchesArticledBossNamesAgainstArticleFreeKillCountLines()
	{
		// DT2-style bosses: the kill-count line drops the "The".
		assertTrue(TimedClearParser.messageMatchesActivity("Your Leviathan kill count is: 4.", "The Leviathan"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Whisperer kill count is: 12.", "The Whisperer"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Hueycoatl kill count is: 3.", "The Hueycoatl"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Royal Titans kill count is: 8.", "The Royal Titans"));
		// Article-free tile names ride the plain-substring fallback.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Vardorvis kill count is: 20.", "Vardorvis"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Duke Sucellus kill count is: 7.", "Duke Sucellus"));
	}

	@Test
	public void nexOnlyMatchesItsKillCountLine()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your Nex kill count is: 51.", "Nex"));
		// "next" must not credit a Nex tile from an unrelated nearby line.
		assertFalse(TimedClearParser.messageMatchesActivity("The next wave will begin soon.", "Nex"));
	}

	@Test
	public void gauntletMatchesItsCompletionLineButNotCorrupted()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gauntlet completion count is: 45.", "The Gauntlet"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your Corrupted Gauntlet completion count is: 4.", "The Gauntlet"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Corrupted Gauntlet completion count is: 4.", "Corrupted Gauntlet"));
	}

	@Test
	public void forgivingRaidModeSpellingsMatchTheModeCountLine()
	{
		// The game's CoX Challenge Mode count line carries NO colon. Admins type the mode a dozen
		// ways; every reasonable spelling must still match (colons/spacing folded, shorthands aliased).
		String coxCm = "Your completed Chambers of Xeric Challenge Mode count is: 1.";
		for (String activity : new String[] {
			"Chambers of Xeric Challenge Mode",
			"Chambers of Xeric: Challenge Mode",
			"chambers of xeric challenge mode",
			"CoX Challenge Mode",
			"CoX CM",
			"CoX: CM",
			"Chambers of Xeric CM",
		})
		{
			assertTrue(activity, TimedClearParser.messageMatchesActivity(coxCm, activity));
		}

		// ToB Hard Mode + ToA Expert Mode (which DO carry a colon in-game) — same tolerance.
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood: Hard Mode count is: 3.", "ToB HM"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood: Hard Mode count is: 3.", "Theatre of Blood Hard Mode"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Tombs of Amascut: Expert Mode count is: 2.", "ToA Expert"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Tombs of Amascut: Expert Mode count is: 2.", "ToA: Expert Mode"));
	}

	@Test
	public void modeTileNeverCreditsOffABaseClearButBaseMatchesEveryMode()
	{
		String coxBase = "Your completed Chambers of Xeric count is: 306.";
		String coxCm = "Your completed Chambers of Xeric Challenge Mode count is: 1.";

		// A CM tile must NOT complete off a normal Chambers clear (its line lacks "challenge mode").
		assertFalse(TimedClearParser.messageMatchesActivity(coxBase, "CoX CM"));
		assertFalse(TimedClearParser.messageMatchesActivity(coxBase, "Chambers of Xeric: Challenge Mode"));

		// A base Chambers tile keeps matching every harder mode (the mode line contains the base name).
		assertTrue(TimedClearParser.messageMatchesActivity(coxBase, "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity(coxCm, "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity(coxCm, "CoX"));

		// ToB Hard Mode tile likewise doesn't fire on a base Theatre clear.
		assertFalse(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood count is: 5.", "ToB HM"));
	}

	@Test
	public void formatsClock()
	{
		assertEquals("2:58", TimedClearParser.formatClock(178));
		assertEquals("0:09", TimedClearParser.formatClock(9));
		assertEquals("33:32", TimedClearParser.formatClock(2012));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What a clip's caption is allowed to say it caught.
 *
 * <p>The behaviour worth defending is that the window belongs to the FOOTAGE, not to the moment the
 * file turned up. OBS writes a clip whenever it gets round to it — on a busy machine that can be
 * minutes after the hotkey — and the replay buffer holds the seconds BEFORE the press. So a caption
 * built when the file lands describes a stretch of time the clip doesn't contain: the player has
 * killed other things, walked to another boss, taken other drops. Every test here is a version of
 * that.
 */
public class ClipMomentsTest
{
	private static final int WINDOW_SECONDS = 30;

	@Test
	public void namesWhatHappenedInsideTheWindow()
	{
		ClipMoments moments = new ClipMoments();
		moments.record("💀 Zulrah kill 1,204");
		String summary = moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3);
		assertEquals("💀 Zulrah kill 1,204", summary);
	}

	@Test
	public void ignoresWhatHappenedAfterTheClipEnded()
	{
		// The whole bug, in one case: the clip was asked for, OBS took its time, and the player
		// carried on playing. Nothing they did afterwards is in the footage.
		// The clip was asked for ten minutes ago and OBS is only now handing us the file, so "now" and
		// "when the footage ended" are ten minutes apart. That gap is the entire bug, and a test that
		// puts the later moments in the FUTURE doesn't reproduce it — a now-anchored window excludes
		// those for the wrong reason and passes by accident.
		ClipMoments moments = new ClipMoments();
		long now = System.currentTimeMillis();
		long clipRequestedAt = now - 600_000L;
		moments.record("🐉 Vorkath kill 500", clipRequestedAt - 5_000L);

		// …ten minutes of other content, all of it already in the past by the time the file lands.
		moments.record("⚔️ Fighting Zulrah", clipRequestedAt + 60_000L);
		moments.record("💰 Tanzanite fang", now - 2_000L);

		String summary = moments.summarize(clipRequestedAt, WINDOW_SECONDS, 3);
		assertEquals("the caption must describe the clip, not the wait", "🐉 Vorkath kill 500", summary);
	}

	@Test
	public void ignoresWhatHappenedBeforeTheWindowOpened()
	{
		ClipMoments moments = new ClipMoments();
		long now = System.currentTimeMillis();
		// A kill from well before the buffer's start edge isn't in the footage either.
		moments.record("🐉 Vorkath kill 499", now);
		String summary = moments.summarize(now + (WINDOW_SECONDS * 1000L) + 60_000L, WINDOW_SECONDS, 3);
		assertNull(summary);
	}

	@Test
	public void survivesABusyWaitWithoutLosingTheMomentItNeeds()
	{
		// Eviction used to be "keep the newest 40", which a raid fills in well under the time OBS can
		// take to write a file — so the moment the clip was FOR got pushed out by moments that came
		// after it. Retention is by age now, so a long wait doesn't cost the caption.
		ClipMoments moments = new ClipMoments();
		long clipRequestedAt = System.currentTimeMillis();
		moments.record("🏆 Twisted bow", clipRequestedAt - 5_000L);
		for (int i = 0; i < 200; i++)
		{
			moments.record("⚔️ Lizardman shaman kill " + i, clipRequestedAt + 10_000L + i);
		}
		String summary = moments.summarize(clipRequestedAt, WINDOW_SECONDS, 3);
		assertEquals("🏆 Twisted bow", summary);
	}

	@Test
	public void collapsesRepeatsAndSummarisesTheRest()
	{
		ClipMoments moments = new ClipMoments();
		moments.record("⚔️ Goblin kill 1");
		moments.record("⚔️ Goblin kill 1"); // the game announces things more than once
		moments.record("💰 Dragon claws");
		moments.record("📕 New clog slot: Dragon claws");
		moments.record("🐾 Pet");
		String summary = moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 2);
		assertTrue("newest first", summary.startsWith("🐾 Pet"));
		assertTrue("names two then counts the rest", summary.endsWith("…and 2 more"));
	}

	@Test
	public void saysNothingWhenNothingHappened()
	{
		assertNull(new ClipMoments().summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3));
	}

	@Test
	public void blankMomentsAreNotMoments()
	{
		ClipMoments moments = new ClipMoments();
		moments.record(null);
		moments.record("   ");
		assertNull(moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link SyncBackoff} — what stops a refused push becoming a request every 30 seconds for as long as
 * someone stays logged in.
 */
public class SyncBackoffTest
{
	@Test
	public void readyUntilSomethingFails()
	{
		SyncBackoff backoff = new SyncBackoff();
		assertTrue(backoff.ready(0));
		assertTrue(backoff.ready(1_000_000));
	}

	@Test
	public void waitsLongerEachTimeUpToTheCeiling()
	{
		SyncBackoff backoff = new SyncBackoff();
		long now = 10_000;

		backoff.onFailure(now);
		assertFalse(backoff.ready(now + SyncBackoff.FIRST_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));

		backoff.onFailure(now);
		assertFalse("second failure waits twice as long", backoff.ready(now + SyncBackoff.FIRST_MS));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS * 2));

		// However bad it gets, it settles at the ceiling rather than growing forever.
		for (int i = 0; i < 20; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now + SyncBackoff.MAX_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.MAX_MS));
	}

	@Test
	public void oneSuccessClearsTheWholeStreak()
	{
		SyncBackoff backoff = new SyncBackoff();
		long now = 10_000;
		for (int i = 0; i < 5; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now));

		backoff.onSuccess();
		assertTrue(backoff.ready(now));
		// And the next failure starts from the bottom again, not from where the streak left off.
		backoff.onFailure(now);
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));
	}

	@Test
	public void reportsHowLongTheSilenceLasts()
	{
		SyncBackoff backoff = new SyncBackoff();
		backoff.onFailure(0);
		assertEquals(SyncBackoff.FIRST_MS / 1000, backoff.secondsUntilReady(0));
		assertEquals(0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS));
		assertEquals("never negative", 0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS * 10));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ActivityStatsTest
{
	/** A stand-in client: ids we set answer with their value, everything else reads 0. */
	private static IntUnaryOperator reader(Map<Integer, Integer> values)
	{
		return id -> values.getOrDefault(id, 0);
	}

	private static final IntUnaryOperator ZERO = id -> 0;

	@Test
	public void readsAVarbitBackedClueTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 47);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesElite"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(47), out.get("cluesElite"));
	}

	@Test
	public void readsAVarpBackedCounter()
	{
		Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.COLLECTION_COUNT, 548);
		varps.put(VarPlayerID.COLOSSEUM_GLORY, 12_400);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "colosseumGlory"), ZERO, reader(varps));

		assertEquals(Integer.valueOf(548), out.get("collectionsLogged"));
		assertEquals(Integer.valueOf(12_400), out.get("colosseumGlory"));
	}

	@Test
	public void cluesAllSumsEveryTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED, 1);
		varbits.put(VarbitID.COLLECTION_CLUES_EASY_COMPLETED, 2);
		varbits.put(VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED, 4);
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 8);
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 16);
		varbits.put(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, 32);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesAll"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(63), out.get("cluesAll"));
	}

	/** An unsynced collection log reads 0; sending it would be a request that changes nothing. */
	@Test
	public void dropsNonPositiveReads()
	{
		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "cluesAll", "cluesHard"), ZERO, ZERO);

		assertTrue(out.isEmpty());
	}

	/**
	 * The site sends every activity key the board tracks, including the rank-based ones it has no
	 * in-game counter for. Those must fall out here rather than push a wrong number.
	 */
	@Test
	public void skipsKeysTheClientCannotAnswer()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 9);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("lastManStanding", "pvpArena", "bhHunter", "riftsClosed", "soulWarsZeal", "cluesHard"),
			reader(varbits), ZERO);

		assertEquals(1, out.size());
		assertEquals(Integer.valueOf(9), out.get("cluesHard"));
		assertNull(out.get("lastManStanding"));
		assertNull(out.get("soulWarsZeal"));

		assertFalse(ActivityStats.isReadable("riftsClosed"));
		assertTrue(ActivityStats.isReadable("cluesHard"));
		assertTrue(ActivityStats.isReadable("cluesAll"));
	}

	@Test
	public void triggersOnlyOnIdsItReads()
	{
		assertTrue(ActivityStats.isTrigger(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, -1));
		assertTrue(ActivityStats.isTrigger(-1, VarPlayerID.COLLECTION_COUNT));
		assertFalse(ActivityStats.isTrigger(VarbitID.INSIDE_WILDERNESS, -1));
		// RuneLite's "this wasn't a varbit" / "this wasn't a varp" sentinel must never match.
		assertFalse(ActivityStats.isTrigger(-1, -1));
	}

	@Test
	public void readsNothingWhenTheBoardTracksNoActivities()
	{
		assertTrue(ActivityStats.read(null, ZERO, ZERO).isEmpty());
		assertTrue(ActivityStats.read(Collections.emptyList(), ZERO, ZERO).isEmpty());
	}

	@Test
	public void clogProgressReadsLikeTheGameShowsIt()
	{
		Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.COLLECTION_COUNT, 548);
		varps.put(VarPlayerID.COLLECTION_COUNT_MAX, 1712);

		assertEquals("548/1712 (32.0%)", ActivityStats.clogProgress(reader(varps)));
	}

	/** Both varps read 0 until the log syncs — a missing field beats a wrong one in a clan post. */
	@Test
	public void clogProgressIsAbsentRatherThanGuessedAt()
	{
		assertNull(ActivityStats.clogProgress(ZERO));

		Map<Integer, Integer> noTotal = new HashMap<>();
		noTotal.put(VarPlayerID.COLLECTION_COUNT, 548);
		assertNull(ActivityStats.clogProgress(reader(noTotal)));

		// More obtained than exist means we're reading something other than what we think.
		Map<Integer, Integer> impossible = new HashMap<>();
		impossible.put(VarPlayerID.COLLECTION_COUNT, 2000);
		impossible.put(VarPlayerID.COLLECTION_COUNT_MAX, 1712);
		assertNull(ActivityStats.clogProgress(reader(impossible)));
	}
}

package com.anvil;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The highlight queue: what collapses, what survives a failed push, and what gets dropped when a
 * session outruns the site.
 *
 * <p>The behaviour worth defending is the collapsing. The game announces everything more than once —
 * a kill fires two loot events, a pet fires up to three chat lines — so a queue that took each
 * sighting at face value would put the same drop on the clan's feed twice.
 */
public class AnvilMomentsTest
{
	private static AnvilMoments.Moment drop(String source, int itemId, long at)
	{
		return new AnvilMoments.Moment("drop", itemId, "Tanzanite fang", 1, 3_100_000L, source, "npc", 210, at,
			AnvilMoments.keyFor("drop", source, itemId, at));
	}

	@Test
	public void theSameDropSeenTwiceIsOneEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// NpcLootReceived then LootReceived, a tick apart — one drop, not two.
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_000_600L));
		assertEquals(1, moments.size());
	}

	@Test
	public void theSameItemFromTheSameBossMinutesLaterIsANewEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_300_000L));
		assertEquals(2, moments.size());
	}

	@Test
	public void aPetIsNamedAfterTheFactWithoutBecomingASecondEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// The chat line announces a pet without saying which one; the collection-log line follows.
		String key = AnvilMoments.keyFor("pet", "Zulrah", null, 5_000L);
		moments.record(new AnvilMoments.Moment("pet", null, null, 1, null, "Zulrah", "npc", 210, 5_000L, key));
		assertTrue(moments.nameQueued(key, "Pet snakeling", 12921));

		assertEquals(1, moments.size());
		AnvilMoments.Moment queued = moments.nextBatch().get(0);
		assertEquals("Pet snakeling", queued.itemName);
		assertEquals(Integer.valueOf(12921), queued.itemId);
		// Naming must not disturb what the moment already knew.
		assertEquals("Zulrah", queued.source);
		assertEquals(Integer.valueOf(210), queued.kc);
	}

	@Test
	public void namingSomethingThatIsNotQueuedDoesNothing()
	{
		AnvilMoments moments = new AnvilMoments();
		assertFalse(moments.nameQueued("nothing-here", "Beaver", 13322));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchStaysQueuedUntilItIsConfirmed()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		List<AnvilMoments.Moment> batch = moments.nextBatch();
		assertEquals(1, batch.size());
		// The push failed — nothing was confirmed, so nothing is lost.
		assertEquals(1, moments.size());
		moments.onSent(batch);
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchIsCappedAndTheRestWaits()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.BATCH + 5; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.BATCH, moments.nextBatch().size());
	}

	@Test
	public void anOverflowingQueueDropsItsOldestNotItsNewest()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.MAX_QUEUED + 10; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.MAX_QUEUED, moments.size());
		// The pet you just got must not be evicted to keep a loot pile from an hour ago.
		long newest = (AnvilMoments.MAX_QUEUED + 9) * 60_000L;
		boolean holdsNewest = false;
		for (AnvilMoments.Moment m : moments.nextBatch())
		{
			holdsNewest |= m.at == newest;
		}
		// nextBatch() returns the oldest first, so check the whole queue rather than the batch head.
		while (!holdsNewest && !moments.isEmpty())
		{
			List<AnvilMoments.Moment> batch = moments.nextBatch();
			for (AnvilMoments.Moment m : batch)
			{
				holdsNewest |= m.at == newest;
			}
			moments.onSent(batch);
		}
		assertTrue(holdsNewest);
	}

	@Test
	public void aKeylessMomentIsRefused()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(new AnvilMoments.Moment("drop", 12922, "Tanzanite fang", 1, 1L, "Zulrah", "npc", 1, 0L, null));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void resetForgetsEverything()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.reset();
		assertTrue(moments.isEmpty());
	}

	@Test
	public void deathsFromDifferentKillersDoNotShareAKey()
	{
		String olm = AnvilMoments.keyFor("death", "Great Olm", null, 1_000_000L);
		String vasa = AnvilMoments.keyFor("death", "Vasa Nistirio", null, 1_000_000L);
		assertFalse(olm.equals(vasa));
		// An unknown killer still produces a usable key rather than a null one — a death nobody can
		// attribute is still a death, and the site is what decides it belongs nowhere.
		assertTrue(AnvilMoments.keyFor("death", null, null, 1_000_000L).startsWith("death|"));
	}

	@Test
	public void aCombatTaskCarriesItsTaskAndTierAndNothingElse()
	{
		AnvilMoments.Moment m = AnvilMoments.Moment.combatTask("Perfect Zulrah", "Master", 1_000_000L);
		assertEquals("ca", m.kind);
		assertEquals("Perfect Zulrah", m.taskName);
		assertEquals("Master", m.tier);
		// No item, no price, no source: which boss it belongs to is the site's answer, out of its own
		// dataset, so inventing one here would only be something to disagree with later.
		assertNull(m.itemId);
		assertNull(m.itemName);
		assertNull(m.source);
		assertNull(m.valueGp);
		assertTrue(m.key.startsWith("ca|perfect zulrah|"));
	}

	@Test
	public void twoTasksInTheSameTickKeepTheirOwnKeys()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(AnvilMoments.Moment.combatTask("Perfect Zulrah", "Master", 1_000_000L));
		moments.record(AnvilMoments.Moment.combatTask("Zulrah Adept", "Hard", 1_000_000L));
		assertEquals(2, moments.nextBatch().size());
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Provides;
import java.lang.reflect.Method;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards a failure that once made the plugin fail to load: a {@code @Provides} method reading a not-yet-injected
 * {@code this.}-field. Guice may invoke {@link AnvilPlugin#provideSidebarDataSource} before the plugin's own
 * {@code @Inject} fields are populated, so the provider must take its collaborators as PARAMETERS. This boots a
 * real injector, then invokes the real provider on an <em>uninjected</em> {@code new AnvilPlugin()} — the scenario
 * that used to NPE. A regression to {@code this.apiClient} throws here; dropping the param fails {@code getDeclaredMethod}.
 */
public class InjectionSmokeTest
{
	/** Binds just the two roots (Gson + OkHttp); everything else has an {@code @Inject} constructor. */
	private static Injector federationGraph()
	{
		return Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				// All bindings are @Provides methods below; nothing to configure explicitly.
			}

			@Provides
			@Singleton
			Gson gson()
			{
				return new Gson();
			}

			@Provides
			@Singleton
			OkHttpClient okHttp()
			{
				return new OkHttpClient();
			}
		});
	}

	@Test
	public void sidebarGraphResolvesAndProviderTakesDepsAsParams() throws Exception
	{
		Injector inj = federationGraph();

		// The @Inject-constructor graph resolves under a real injector.
		BingoApiClient client = inj.getInstance(BingoApiClient.class);
		assertNotNull(client);

		// getDeclaredMethod fails if the provider drops a param; invoking on an uninjected plugin reproduces the bug.
		AnvilPlugin uninjectedPlugin = new AnvilPlugin();
		Method provider = AnvilPlugin.class.getDeclaredMethod(
			"provideSidebarDataSource", BingoApiClient.class, ScheduledExecutorService.class);
		provider.setAccessible(true);
		Object sds = provider.invoke(uninjectedPlugin, client, Executors.newSingleThreadScheduledExecutor());
		assertNotNull("provider must not read not-yet-injected this.-fields", sds);
		assertTrue(sds instanceof SidebarDataSource);

		// A resolved SidebarDataSource is usable straight away (single-home; unconfigured ⇒ empty).
		assertTrue(((SidebarDataSource) sds).fetchConnections().isEmpty());
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Rank titles go out in clan posts, where a wrong one gets repeated — and the Gilded cutoff is a
 * moving target, so it gets its own coverage.
 */
public class ClogRankTest
{
	/** Slots in the log as of writing. Only used to place Gilded; the rest are fixed cutoffs. */
	private static final int TOTAL = 1712;

	@Test
	public void fixedRanksTakeTheHighestThresholdReached()
	{
		assertEquals("Bronze", ClogRank.forSlots(100, TOTAL));
		assertEquals("Bronze", ClogRank.forSlots(299, TOTAL));
		assertEquals("Iron", ClogRank.forSlots(300, TOTAL));
		assertEquals("Steel", ClogRank.forSlots(613, TOTAL));
		assertEquals("Black", ClogRank.forSlots(855, TOTAL));
		assertEquals("Mithril", ClogRank.forSlots(900, TOTAL));
		assertEquals("Adamant", ClogRank.forSlots(1000, TOTAL));
		assertEquals("Rune", ClogRank.forSlots(1100, TOTAL));
		assertEquals("Dragon", ClogRank.forSlots(1200, TOTAL));
	}

	/** Below the first cutoff, and on an unreadable count, there is no rank to report. */
	@Test
	public void noRankIsBetterThanAWrongOne()
	{
		assertNull(ClogRank.forSlots(99, TOTAL));
		assertNull(ClogRank.forSlots(0, TOTAL));
		assertNull(ClogRank.forSlots(-1, TOTAL));
	}

	/**
	 * Gilded is 90% of the log's total slots rounded down to the nearest 25 — a proportion, not a
	 * number, so it shifts every time slots are added. At 1712 slots that lands on 1525.
	 */
	@Test
	public void gildedTracksTheLogsTotalSize()
	{
		assertEquals(1525, ClogRank.gildedThreshold(1712));
		assertEquals("Dragon", ClogRank.forSlots(1524, TOTAL));
		assertEquals("Gilded", ClogRank.forSlots(1525, TOTAL));
		assertEquals("Gilded", ClogRank.forSlots(1712, TOTAL));

		// A later expansion moves the bar: 2000 slots → 90% = 1800 → already a multiple of 25.
		assertEquals(1800, ClogRank.gildedThreshold(2000));
		assertEquals("Dragon", ClogRank.forSlots(1799, 2000));
		assertEquals("Gilded", ClogRank.forSlots(1800, 2000));
	}

	/** Without a readable total, Gilded is unreachable rather than wrongly awarded to everyone. */
	@Test
	public void anUnknownTotalNeverAwardsGilded()
	{
		assertEquals("Dragon", ClogRank.forSlots(1600, 0));
	}
}

package com.anvil;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class VestigeRollsTest
{
	private static PluginConfigResponse.RollTable duke()
	{
		PluginConfigResponse.RollTable t = new PluginConfigResponse.RollTable();
		t.boss = "Duke Sucellus";
		// Virtus ×3, chromium ingot, Magus vestige, Eye of the duke.
		t.rollItemIds = Arrays.asList(26241, 26243, 26245, 28276, 28281, 28321);
		t.vestigeItemId = 28281;
		t.vestigeName = "Magus vestige";
		t.rollsPerVestige = 3;
		return t;
	}

	@Test
	public void countsRollsAndCallsTheVestigeOneAhead()
	{
		VestigeRolls v = new VestigeRolls();
		VestigeRolls.Result r1 = v.record(duke(), 28276); // chromium ingot
		assertEquals(1, r1.state.rolls);
		assertFalse(r1.vestigeNext);
		assertTrue(r1.line.contains("Roll 1 of 3"));

		VestigeRolls.Result r2 = v.record(duke(), 26241); // Virtus mask
		assertEquals(2, r2.state.rolls);
		assertTrue("two rolls in, the next unique is the vestige", r2.vestigeNext);
		assertTrue(r2.line.contains("Magus vestige"));
	}

	@Test
	public void theVestigeResetsAndAnchorsTheCycle()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		VestigeRolls.Result r = v.record(duke(), 28281); // Magus vestige
		assertTrue(r.vestige);
		assertEquals(0, r.state.rolls);
		assertTrue("a seen vestige anchors the cycle — the count is exact from here", r.state.exact);
		assertTrue(r.line.contains("cycle resets"));
	}

	@Test
	public void countsAreEstimatedUntilAVestigeIsSeen()
	{
		VestigeRolls v = new VestigeRolls();
		assertTrue(v.record(duke(), 28276).line.contains("(estimated)"));
		v.record(duke(), 28281); // vestige seen — anchored
		assertFalse(v.record(duke(), 28276).line.contains("estimated"));
	}

	@Test
	public void aNonVestigeWhereTheVestigeWasDueReAnchorsInsteadOfLying()
	{
		// Two rolls in (so we think the vestige is next), then a non-vestige: our count was wrong,
		// which is what happens when drops landed while the plugin wasn't running.
		VestigeRolls.State was = new VestigeRolls.State(2, true);
		VestigeRolls.Result r = VestigeRolls.advance(was, false, 3, "Magus vestige");
		assertEquals(1, r.state.rolls);
		assertFalse("we can't claim exact after being wrong", r.state.exact);
		assertTrue(r.line.contains("re-anchoring"));
	}

	@Test
	public void itemsOutsideTheRollTableAreNotRolls()
	{
		VestigeRolls v = new VestigeRolls();
		assertNull("the pet is its own roll, not a unique-table one", v.record(duke(), 28250));
		assertNull("awakener's orb likewise", v.record(duke(), 28334));
		assertEquals(0, v.get("Duke Sucellus").rolls);
	}

	@Test
	public void eachBossKeepsItsOwnCycle()
	{
		PluginConfigResponse.RollTable vard = new PluginConfigResponse.RollTable();
		vard.boss = "Vardorvis";
		vard.rollItemIds = Arrays.asList(26241, 28276, 28285, 28319);
		vard.vestigeItemId = 28285;
		vard.vestigeName = "Ultor vestige";
		vard.rollsPerVestige = 3;

		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 26241);
		v.record(vard, 28276);
		assertEquals(2, v.get("Duke Sucellus").rolls);
		assertEquals(1, v.get("Vardorvis").rolls);
	}

	@Test
	public void stateSurvivesASerialiseRoundTrip()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 28281); // vestige — exact
		v.record(duke(), 26241);

		VestigeRolls back = VestigeRolls.parse(v.serialise());
		assertEquals(1, back.get("Duke Sucellus").rolls);
		assertTrue(back.get("duke sucellus").exact);
	}

	@Test
	public void aCorruptedConfigValueLosesOnlyThatBoss()
	{
		VestigeRolls back = VestigeRolls.parse("duke sucellus=2:1;vardorvis=notanumber;the whisperer=1:0");
		assertEquals(2, back.get("Duke Sucellus").rolls);
		assertEquals(0, back.get("Vardorvis").rolls);
		assertEquals(1, back.get("The Whisperer").rolls);
	}

	@Test
	public void anEmptyOrAbsentConfigStartsClean()
	{
		assertEquals(0, VestigeRolls.parse(null).get("Duke Sucellus").rolls);
		assertEquals(0, VestigeRolls.parse("").get("Duke Sucellus").rolls);
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Reveal-policy plumbing (showdown / lucky draw / bounty events): the {@code "reveal"} activity
 * kind and the sidebar's "still hidden" one-liner ({@link AnvilSidebarDataSource#revealNote}).
 */
public class RevealModeTest
{
	@Test
	public void revealKindParsesFromWireAndOldKindsStillMap()
	{
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire("reveal"));
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire(" Reveal "));
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("complete"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("progress"));
		// Forward-compat contract: anything unknown stays a harmless progress row.
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("mystery"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire(null));
	}

	@Test
	public void revealSummaryLeadsWithTheTile()
	{
		ActivityEntry e = new ActivityEntry("r42", "2026-07-24T18:00:00Z", null, 42, "500 Zulrah KC",
			ActivityEntry.Kind.REVEAL, 0, false);
		assertEquals("New tile revealed: 500 Zulrah KC", e.summary());
	}

	private static PluginConfigResponse.EventInfo event(String policy, int hidden, String nextAt)
	{
		PluginConfigResponse.EventInfo ev = new PluginConfigResponse.EventInfo();
		ev.revealPolicy = policy;
		ev.hiddenTileCount = hidden;
		ev.nextRevealAt = nextAt;
		return ev;
	}

	@Test
	public void revealNoteIsNullForClassicBoardsAndWhenNothingIsHidden()
	{
		assertNull(AnvilSidebarDataSource.revealNote(null));
		assertNull(AnvilSidebarDataSource.revealNote(event(null, 5, null)));
		assertNull(AnvilSidebarDataSource.revealNote(event("interval", 0, null)));
	}

	@Test
	public void revealNoteCountsTilesAndBounties()
	{
		String interval = AnvilSidebarDataSource.revealNote(
			event("interval", 4, java.time.Instant.now().plusSeconds(42 * 60 + 30).toString()));
		assertTrue(interval, interval.startsWith("4 tiles hidden"));
		assertTrue(interval, interval.contains("next in 42m"));

		String scheduledNoClock = AnvilSidebarDataSource.revealNote(event("scheduled", 1, null));
		assertEquals("1 tile hidden", scheduledNoClock);

		String bounty = AnvilSidebarDataSource.revealNote(event("bounty", 3, null));
		assertEquals("3 bounties left · next on claim", bounty);

		String lastBounty = AnvilSidebarDataSource.revealNote(event("bounty", 1, null));
		assertEquals("1 bounty left · next on claim", lastBounty);
	}

	@Test
	public void revealNoteHandlesImminentAndFarReveals()
	{
		String imminent = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds(10).toString()));
		assertTrue(imminent, imminent.endsWith("next any minute"));

		String hours = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds((3 * 60 + 10) * 60 + 30).toString()));
		assertTrue(hours, hours.contains("next in 3h 10m"));

		// Malformed server stamp → drop the clock, keep the count.
		String malformed = AnvilSidebarDataSource.revealNote(event("interval", 2, "not-a-time"));
		assertEquals("2 tiles hidden", malformed);
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ClogTaskModelTest
{
	private static PluginConfigResponse.TrackedDrop drop(int id, String label, int cur, int req, Integer... items)
	{
		PluginConfigResponse.TrackedDrop d = new PluginConfigResponse.TrackedDrop();
		d.tileId = id;
		d.label = label;
		d.currentAmount = cur;
		d.requiredAmount = req;
		d.itemIds = new ArrayList<>();
		for (Integer it : items)
		{
			d.itemIds.add(it);
		}
		return d;
	}

	private static PluginConfigResponse.TrackedStat stat(int id, String label, int cur, int goal)
	{
		PluginConfigResponse.TrackedStat s = new PluginConfigResponse.TrackedStat();
		s.tileId = id;
		s.label = label;
		s.currentAmount = cur;
		s.goalAmount = goal;
		return s;
	}

	@Test
	public void multiTagCategoriesSplitAndFilter()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Zuk cape", ClogTaskModel.Type.DROP, 0, 1, -1, 5, null, "Inferno, PvM"));
		rows.add(new ClogTaskModel.TaskRow(2, "99 Slayer", ClogTaskModel.Type.STAT, 0, 1, -1, 5, null, "Skilling"));
		rows.add(new ClogTaskModel.TaskRow(3, "Nex drop", ClogTaskModel.Type.DROP, 0, 1, -1, 5, null, "pvm"));

		// Each tag contributes to the dropdown once, case-insensitively deduped.
		List<String> cats = ClogTaskModel.categories(rows);
		assertEquals(3, cats.size());
		assertTrue(cats.contains("Inferno"));
		assertTrue(cats.contains("Skilling"));
		// "PvM" (first seen) wins over the later "pvm".
		assertTrue(cats.contains("PvM"));

		// Filtering by one tag matches every tile carrying it, whatever its other tags.
		List<ClogTaskModel.TaskRow> pvm = ClogTaskModel.filter(
			rows, ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, "", "PvM");
		assertEquals(2, pvm.size());
		List<ClogTaskModel.TaskRow> inferno = ClogTaskModel.filter(
			rows, ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, "", "Inferno");
		assertEquals(1, inferno.size());
		assertEquals(1, inferno.get(0).tileId);
	}

	@Test
	public void statusDerivation()
	{
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 5));
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, ClogTaskModel.statusOf(2, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(5, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(7, 5));
		// Untargeted tile (goal <= 0): any progress completes it.
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 0));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(1, 0));
	}

	@Test
	public void buildIsNullSafe()
	{
		assertTrue(ClogTaskModel.build(null).isEmpty());
		assertTrue(ClogTaskModel.build(new PluginConfigResponse()).isEmpty());
	}

	@Test
	public void buildMergesDropsAndStatsWithIcons()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
