			new ConnectionView.ScheduledView(1, "Unauthored", null, null, false, 0, 5, "bingo", "tiles", null)
				.sizeLabel());
	}

	@Test
	public void aSiteTooOldToNameTheFormatIsJudgedOnItsGeometry()
