	@Test
	public void endsInLabelCountsDownAndThenReadsEnded()
	{
		long now = System.currentTimeMillis();
		assertEquals("Ends in 2d 0h", AnvilSidebarPanel.endsInLabel(iso(now + 48 * 3600_000L)));
		assertEquals("Ends in 3h 0m", AnvilSidebarPanel.endsInLabel(iso(now + 3 * 3600_000L)));
		assertEquals("Ends in 20m", AnvilSidebarPanel.endsInLabel(iso(now + 20 * 60_000L)));
		assertEquals("Ended", AnvilSidebarPanel.endsInLabel(iso(now - 60_000L)));
		// Missing / unparseable dates simply drop the line rather than printing a bogus one.
		assertNull(AnvilSidebarPanel.endsInLabel(null));
		assertNull(AnvilSidebarPanel.endsInLabel("not-a-date"));
	}

	/** ISO instant, a few seconds late so the truncating countdown lands on the round number. */
	private static String iso(long millis)
	{
		return java.time.Instant.ofEpochMilli(millis + 2000).toString();
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the Combat Achievement completion chat-line parsing. CA bingo tiles credit off this
 * line (including recompletions fired by the in-game "Repeat completion" setting, which append a
 * " (N points)" suffix) — if Jagex changes the string a test here goes red and tells you CA tile
 * auto-detect broke (manual site submission is the fallback).
 */
public class CombatTaskLineTest
{
	/** Runs a line through the same parse the plugin does: match, then strip the points suffix. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		String task = AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim();
		return new String[]{m.group(1), task};
	}

	@Test
	public void parsesFirstCompletion()
	{
		String[] r = parse("Congratulations, you've completed an Elite combat task: Whack-a-Mole.");
		assertEquals("Elite", r[0]);
		assertEquals("Whack-a-Mole", r[1]);
	}

	@Test
	public void parsesRepeatCompletionWithPointsSuffix()
	{
		// The in-game "Repeat completion" setting re-fires the line with a points suffix.
		String[] r = parse("Congratulations, you've completed a Master combat task: Nylocas, On the Rocks (5 points).");
		assertEquals("Master", r[0]);
		assertEquals("Nylocas, On the Rocks", r[1]);
	}

	@Test
	public void parsesSinglePointSuffixAndAArticle()
	{
		String[] r = parse("Congratulations, you've completed an Easy combat task: Noxious Foe (1 point).");
		assertEquals("Easy", r[0]);
		assertEquals("Noxious Foe", r[1]);
	}

	@Test
	public void tierResolvesForEveryGroupOneValue()
	{
		String[] r = parse("Congratulations, you've completed a Grandmaster combat task: The Worst Ranged Weapon.");
		assertEquals(CombatAchievementTier.GRANDMASTER, CombatAchievementTier.byName(r[0]));
	}

	@Test
	public void ignoresUnrelatedCongratulationsLines()
	{
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you just advanced your Mining level. You are now level 99.").find());
	}

	@Test
	public void keepsParenthesesThatAreNotAPointsSuffix()
	{
		// Task names can legitimately end in a parenthesised qualifier — only "(N points)" strips.
		String[] r = parse("Congratulations, you've completed an Elite combat task: Chambers of Xeric: CM (Solo) Speed-Chaser.");
		assertEquals("Chambers of Xeric: CM (Solo) Speed-Chaser", r[1]);
	}

	@Test
	public void matcherRequiresTierWord()
	{
		assertTrue(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you've completed a Hard combat task: Whack-a-Mole.").find());
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"you've completed a combat task").find());
	}
}

package com.anvil;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.atomic.AtomicInteger;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * STARTING SHOT (site lib/startProof) — the plugin half. Covers what the sidebar is allowed to ask
 * for ({@link AnvilSidebarDataSource#startProof()}) and the one retry rule that keeps a real drop
 * from being thrown away while a screenshot is outstanding.
 */
public class StartProofTest
{
	private static PluginConfigResponse liveConfig()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.id = 7;
		cfg.event.name = "Summer Bingo";
		cfg.event.startDate = Instant.now().minus(1, ChronoUnit.HOURS).toString();
		cfg.event.endDate = Instant.now().plus(1, ChronoUnit.DAYS).toString();
		cfg.team = new PluginConfigResponse.TeamInfo();
		cfg.team.name = "Team Molten";
		return cfg;
	}

	private static PluginConfigResponse.StartProof owed()
	{
		PluginConfigResponse.StartProof sp = new PluginConfigResponse.StartProof();
		sp.required = true;
		sp.drawn = true;
		sp.location = "Edgeville bank";
		sp.keyword = "ANVIL-GRAPE-47";
		sp.needsUpload = true;
		return sp;
	}

	private static AnvilSidebarDataSource sourceFor(PluginConfigResponse cfg)
	{
		return new AnvilSidebarDataSource(() -> cfg, new BingoApiClient(new Gson(), new OkHttpClient()));
	}

	@Test
	public void owedShotIsOfferedWhileTheEventIsLive()
	{
		PluginConfigResponse cfg = liveConfig();
		cfg.startProof = owed();

		PluginConfigResponse.StartProof offered = sourceFor(cfg).startProof();
		assertNotNull(offered);
		assertEquals("Edgeville bank", offered.location);
		assertEquals("ANVIL-GRAPE-47", offered.keyword);
	}

	@Test
	public void nothingIsAskedForWhenNothingIsOwed()
	{
		// No starting-shot block at all — an event without the rule, or a site that predates it.
		assertNull(sourceFor(liveConfig()).startProof());

		// Required but not yet drawn: the event hasn't started, so there is no location and no keyword.
		PluginConfigResponse notDrawn = liveConfig();
		notDrawn.startProof = owed();
		notDrawn.startProof.drawn = false;
		assertNull(sourceFor(notDrawn).startProof());

		// Already filed — the server says the obligation is settled.
		PluginConfigResponse filed = liveConfig();
		filed.startProof = owed();
		filed.startProof.needsUpload = false;
		assertNull(sourceFor(filed).startProof());
	}

	@Test
	public void endedEventNeverAsksForAShot()
	{
		PluginConfigResponse over = liveConfig();
		over.startProof = owed();
		over.event.endDate = Instant.now().minus(1, ChronoUnit.MINUTES).toString();
		assertNull(sourceFor(over).startProof());

		PluginConfigResponse forceEnded = liveConfig();
		forceEnded.startProof = owed();
		forceEnded.event.forceEndedAt = Instant.now().toString();
		assertNull(sourceFor(forceEnded).startProof());
	}

	@Test
	public void captureRunsTheBoundActionAndIsSafeWithoutOne()
	{
		AnvilSidebarDataSource ds = sourceFor(liveConfig());
		ds.captureStartProof(); // unbound (tests, or before the plugin wires itself up) — must not throw

		AtomicInteger fired = new AtomicInteger();
		ds.setStartProofCapture(fired::incrementAndGet);
		ds.captureStartProof();
		assertEquals(1, fired.get());
	}

	@Test
	public void federationPassesTheHomeObligationThrough()
	{
		PluginConfigResponse cfg = liveConfig();
		cfg.startProof = owed();
		AnvilSidebarDataSource home = sourceFor(cfg);
		AtomicInteger fired = new AtomicInteger();
		home.setStartProofCapture(fired::incrementAndGet);

		// The relay layer must not swallow it: the shot is owed to the home we authenticate against.
		SidebarDataSource relayed = new FederationSidebarDataSource(
			new BingoApiClient(new Gson(), new OkHttpClient()), home,
			url -> true, (step, delayMs) -> step.run());
		assertNotNull(relayed.startProof());
		relayed.captureStartProof();
		assertEquals(1, fired.get());
	}

	private static PluginConfigResponse.StartProof checked()
	{
		PluginConfigResponse.StartProof sp = owed();
		sp.spot = new PluginConfigResponse.StartProof.Spot();
		sp.spot.x = 3094;
		sp.spot.y = 3491;
		sp.spot.radius = 25;
		sp.maxSessionMinutes = 15;
		return sp;
	}

	private static final long NOW = 1_800_000_000_000L;

	@Test
	public void aShotFromTheSpotOnAFreshSessionIsLetThrough()
	{
		// Six squares out, five minutes into the session: nothing to complain about.
		assertNull(StartProofRules.blockReason(checked(), NOW - 5 * 60_000L, NOW, 3100, 3489));
	}

	@Test
	public void standingSomewhereElseIsRefusedBeforeTheFrameIsGrabbed()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, 2400, 3489);
		assertNotNull(reason);
		// The distance is the useful half of the message — "go to Edgeville bank" alone reads like a
		// bug when you believe you ARE at Edgeville bank.
		assertTrue(reason, reason.contains("694"));
		assertTrue(reason, reason.contains("Edgeville bank"));
	}

	@Test
	public void aSessionOlderThanTheWindowIsRefused()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 130 * 60_000L, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.contains("2h 10m"));
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void notKnowingWhenTheSessionStartedCountsAsStale()
	{
		// Plugin enabled mid-session: we can't vouch for the logout that flushed the hiscores, and
		// "probably fine" is exactly the answer this rule exists to stop giving.
		String reason = StartProofRules.blockReason(checked(), StartProofRules.UNKNOWN_LOGIN, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void checksThatCannotRunNeverBlock()
	{
		// An older site: no pin, no window. Exactly the behaviour before any of this existed.
		assertNull(StartProofRules.blockReason(owed(), StartProofRules.UNKNOWN_LOGIN, NOW, 2400, 3489));

		// Pinned spot, but logged out / no position to read — the distance check simply doesn't run.
		PluginConfigResponse.StartProof spotOnly = checked();
		spotOnly.maxSessionMinutes = 0;
		assertNull(StartProofRules.blockReason(spotOnly, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));

		// Session window on, position unknown, session fresh: still fine.
		assertNull(StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, null, null));

		// And nothing owed at all can't block anything.
		assertNull(StartProofRules.blockReason(null, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));
	}

	@Test
	public void distanceIsMeasuredTheWayTheGameMeasuresIt()
	{
		PluginConfigResponse.StartProof sp = checked();
		// The longer axis wins — 30 east and 4 north is 30 squares away, not 34.
		assertEquals(30, StartProofRules.distance(sp, 3124, 3495));
		assertEquals(0, StartProofRules.distance(sp, 3094, 3491));
		// Nothing to measure against.
		assertEquals(-1, StartProofRules.distance(owed(), 3094, 3491));
		assertEquals(-1, StartProofRules.distance(sp, null, null));
	}

	@Test
	public void describeWindowCountsDownAndThenGivesUp()
	{
		PluginConfigResponse.StartProof sp = owed();
		long now = java.time.Instant.parse("2026-08-16T19:00:00Z").toEpochMilli();
		sp.windowEndsAt = "2026-08-17T00:00:00Z";
		assertEquals("5h 00m", StartProofRules.describeWindow(sp, now));

		// Past the end there is nothing to quote — the ask has lapsed, it hasn't been failed.
		sp.windowEndsAt = "2026-08-16T18:30:00Z";
		assertEquals(null, StartProofRules.describeWindow(sp, now));

		// A site too old to send one, and a stamp we can't read, both say nothing rather than lying.
		sp.windowEndsAt = null;
		assertEquals(null, StartProofRules.describeWindow(sp, now));
		sp.windowEndsAt = "not a date";
		assertEquals(null, StartProofRules.describeWindow(sp, now));
	}

	@Test
	public void awaitingAStartingShotIsRetryable()
	{
		// 409 is normally a permanent 4xx — but this one clears the moment the player files their
		// shot, and the pending drop must survive until then.
		java.io.IOException awaiting = BingoApiClient.submissionErrorForTest(
			"Submission failed", 409, "{\"error\":\"Upload your starting shot first\",\"code\":\"start_proof_required\"}");
		assertTrue(!(awaiting instanceof BingoApiClient.PermanentSubmissionException));

		// Any other 409 stays permanent (tile already complete, etc.) so it can't loop forever.
		java.io.IOException other = BingoApiClient.submissionErrorForTest(
			"Submission failed", 409, "{\"error\":\"Tile already complete\"}");
		assertTrue(other instanceof BingoApiClient.PermanentSubmissionException);
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Luck / troll classification for drop posts — the difference between "spooned" and "finally".
 */
public class DropLuckTest
{
	private static final long BIG_VALUE = 50_000_000L;

	@Test
	public void obtainedShareFollowsTheDropRate()
	{
		// At exactly 1/rate kills, ~63% of players have it (1 - 1/e).
		assertEquals(0.632, DropLuck.obtainedShare(1.0 / 512, 512), 0.005);
		// A single kill at 1/512 is just the drop rate.
		assertEquals(1.0 / 512, DropLuck.obtainedShare(1.0 / 512, 1), 1e-9);
		// Missing inputs never blow up.
		assertEquals(0.0, DropLuck.obtainedShare(0, 100), 1e-9);
		assertEquals(0.0, DropLuck.obtainedShare(1.0 / 512, 0), 1e-9);
	}

	@Test
	public void earlyDropsAreSpoonedAndLongGrindsAreDry()
	{
		// 1/512 on the 20th kill: only ~4% of players are there yet.
		assertEquals(DropLuck.Verdict.SPOONED, DropLuck.classify(1.0 / 512, 20));
		// ~200 kills in: ahead of the pack, not miraculous.
		assertEquals(DropLuck.Verdict.LUCKY, DropLuck.classify(1.0 / 512, 200));
		// Around the drop rate: unremarkable.
		assertEquals(DropLuck.Verdict.TYPICAL, DropLuck.classify(1.0 / 512, 500));
		// Triple the rate: almost everyone had it by now.
		assertEquals(DropLuck.Verdict.DRY, DropLuck.classify(1.0 / 512, 1500));
	}

	@Test
	public void classifyNeedsBothARateAndAKillCount()
	{
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(null, 500));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, null));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, 0));
	}

	@Test
	public void luckLabelOnlySpeaksWhenThereIsSomethingToSay()
	{
		assertTrue(DropLuck.luckLabel(1.0 / 512, 20).startsWith("Top "));
		assertTrue(DropLuck.luckLabel(1.0 / 512, 20).endsWith("spooned"));
		assertTrue(DropLuck.luckLabel(1.0 / 512, 1500).startsWith("Dry"));
		assertNull("typical drops add no field", DropLuck.luckLabel(1.0 / 512, 500));
		assertNull("no kill count, no claim", DropLuck.luckLabel(1.0 / 512, null));
	}

	@Test
	public void trollsAreRareRollsOnWorthlessItems()
	{
		// A 1/10,000 roll on a ~35k item — the joke drop.
		assertTrue(DropLuck.isTrollDrop(1.0 / 10_000, 35_000, 10_000));
		// Same rarity, real money: just a rare drop.
		assertFalse(DropLuck.isTrollDrop(1.0 / 10_000, 5_000_000, 10_000));
		// Cheap but not rare enough to be funny — this is the herb spam we don't want.
		assertFalse(DropLuck.isTrollDrop(1.0 / 2_000, 5_000, 10_000));
		// Qualified on value alone (no rate known).
		assertFalse(DropLuck.isTrollDrop(null, 5_000, 10_000));
	}

	@Test
	public void earnedAwardsAreNeverCalledSpooned()
	{
		assertTrue(DropLuck.isEarnedAward("Infernal cape"));
		assertTrue(DropLuck.isEarnedAward("Dizana's quiver"));
		assertTrue(DropLuck.isEarnedAward("Fire cape"));
		assertFalse(DropLuck.isEarnedAward("Twisted bow"));

		// Even a 1-KC Inferno clear gets no "spooned" line — it was earned, not rolled.
		assertFalse(DropLuck.deservesSpoonLine("Infernal cape", 0, 1.0 / 1, 1, BIG_VALUE));
		// A genuine early roll does.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 20, BIG_VALUE));
		// A dry grind doesn't get called lucky just because the item is worth a lot... unless it's
		// worth *so* much that the drop is a moment on its own.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 1500, BIG_VALUE));
		assertFalse(DropLuck.deservesSpoonLine("Dragon spear", 35_000, 1.0 / 512, 1500, BIG_VALUE));
		// No rate/KC to judge by: value decides.
		assertFalse(DropLuck.deservesSpoonLine("Rune platebody", 38_000, null, null, BIG_VALUE));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Pins the personal-best parsing to REAL in-game completion messages.
 *
 * <p>The case that matters most is the explicit form: "Duration: 172:18. Personal best: 134:52"
 * contains two times, and reading the first one would file a bad run as somebody's record.
 */
public class PersonalBestParserTest
{
	@Test
	public void newPersonalBestTakesTheRunsOwnDuration()
	{
		// Inferno, and the generic boss fight timer.
		assertEquals(Integer.valueOf(17803), PersonalBestParser.parseCentis("Duration: 2:58.03 (new personal best)"));
		assertEquals(Integer.valueOf(9600), PersonalBestParser.parseCentis("Fight duration: 1:36 (new personal best)"));
		// Barracuda Trials print "Time:" instead of "Duration:".
		assertEquals(Integer.valueOf(36420), PersonalBestParser.parseCentis("Time: 6:04.20 (new personal best)."));
	}

	@Test
	public void explicitPersonalBestIgnoresThisRunsSlowerTime()
	{
		// The whole point: 172:18 is this run, 134:52 is the record.
		assertEquals(Integer.valueOf(809200), PersonalBestParser.parseCentis("Duration: 172:18. Personal best: 134:52"));
		assertEquals(Integer.valueOf(47900), PersonalBestParser.parseCentis("Challenge duration: 10:24. Personal best: 7:59."));
	}

	@Test
	public void hoursMinutesSecondsAreReadAsThreeParts()
	{
		// 1:02:03 is an hour and change, not one minute two seconds.
		assertEquals(Integer.valueOf(372300), PersonalBestParser.parseCentis("Duration: 1:02:03 (new personal best)"));
	}

	@Test
	public void fractionsPadToHundredths()
	{
		// ".3" is three tenths — 30 centiseconds, not 3.
		assertEquals(Integer.valueOf(6030), PersonalBestParser.parseCentis("Duration: 1:00.3 (new personal best)"));
		assertEquals(Integer.valueOf(6003), PersonalBestParser.parseCentis("Duration: 1:00.03 (new personal best)"));
	}

	@Test
	public void linesWithoutAPersonalBestAreIgnored()
	{
		// An ordinary clear is not a record, and must not overwrite one.
		assertNull(PersonalBestParser.parseCentis("Duration: 2:58.03"));
		assertNull(PersonalBestParser.parseCentis("Congratulations - your raid is complete! Duration: 15:39"));
		assertNull(PersonalBestParser.parseCentis("Your Zulrah kill count is: 1,204."));
		assertNull(PersonalBestParser.parseCentis(null));
		// The words with no time attached: nothing to record.
		assertNull(PersonalBestParser.parseCentis("You have a new personal best!"));
	}
}

package com.anvil;

import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Whole-log collection sync ({@link ClogFullSync}) — the accumulator behind the "Sync profile"
 * button. The rules that matter are all about NOT sending a fragment: a partial transmit replaces a
 * stored log, so "have the items stopped arriving" and "is this even a log" are the whole job.
 */
public class ClogFullSyncTest
{
	private static ClogFullSync receiving(int items, long at)
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		for (int i = 1; i <= items; i++)
		{
			sync.onItem(1000 + i, 1, at);
		}
		return sync;
	}

	@Test
	public void itemsArriveAndSettleAfterTheQuietPeriod()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertEquals(10, sync.size());
		// Still arriving.
		assertFalse(sync.isDue(1_000));
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void aLateItemRestartsTheClock()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.onItem(9999, 1, 2_500);
		assertFalse("the transmit is still going", sync.isDue(2_500 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(2_500 + ClogFullSync.QUIET_MS));
		assertEquals(11, sync.size());
	}

	@Test
	public void aFragmentIsNeverSent()
	{
		// One stray item — another plugin's search toggle, or an interface closed mid-transmit.
		// Sending this would replace a full stored log with a single row.
		ClogFullSync sync = receiving(ClogFullSync.MIN_ITEMS - 1, 1_000);
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS * 10));
	}

	@Test
	public void nothingIsCollectedUntilATransmitStarts()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.onItem(4151, 1, 1_000); // an item fired while we weren't asking
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void quantityIsKeptAndNeverBelowOne()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		sync.onItem(4151, 3, 1_000);
		sync.onItem(11802, 0, 1_000); // the game reports some slots without a count
		Map<Integer, Integer> snapshot = sync.snapshot();
		assertEquals(Integer.valueOf(3), snapshot.get(4151));
		assertEquals(Integer.valueOf(1), snapshot.get(11802));
	}

	@Test
	public void aSecondTransmitReplacesTheFirst()
	{
		ClogFullSync sync = receiving(10, 1_000);
		// Opening the log again re-transmits everything; the old batch must not linger and inflate it.
		sync.begin(false);
		assertEquals(0, sync.size());
		sync.onItem(4151, 1, 5_000);
		assertEquals(1, sync.size());
	}

	@Test
	public void aFailedPushKeepsTheItemsForTheNextTick()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));

		sync.onSendFailed(4_000);
		assertEquals("a site being down mustn't cost the transmit", 10, sync.size());
		assertFalse(sync.isDue(4_000));
		assertTrue(sync.isDue(4_000 + ClogFullSync.QUIET_MS));

		sync.onSent();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(9_000));
	}

	@Test
	public void aManualRequestSurvivesUntilItIsSent()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(true);
		assertTrue(sync.isManual());
		// Pressing the button, then opening the log (which begins its own transmit), still reports.
		sync.begin(false);
		assertTrue(sync.isManual());
		sync.onSent();
		assertFalse(sync.isManual());
	}

	@Test
	public void theFingerprintIgnoresOrderButNotContent()
	{
		ClogFullSync a = new ClogFullSync();
		a.begin(false);
		a.onItem(4151, 1, 1_000);
		a.onItem(11802, 2, 1_000);

		ClogFullSync b = new ClogFullSync();
		b.begin(false);
		b.onItem(11802, 2, 5_000);
		b.onItem(4151, 1, 5_000);
		assertEquals("the same log in any order is the same log", a.fingerprint(), b.fingerprint());

		// A new item, or another of one you had, is a different log — both must push.
		ClogFullSync more = new ClogFullSync();
		more.begin(false);
		more.onItem(4151, 1, 1_000);
		more.onItem(11802, 2, 1_000);
		more.onItem(20997, 1, 1_000);
		assertNotEquals(a.fingerprint(), more.fingerprint());

		ClogFullSync dupe = new ClogFullSync();
		dupe.begin(false);
		dupe.onItem(4151, 1, 1_000);
		dupe.onItem(11802, 3, 1_000);
		assertNotEquals(a.fingerprint(), dupe.fingerprint());
	}

	@Test
	public void switchingAccountsDropsAHalfReceivedLog()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.reset();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
		// And a stray item after the reset isn't collected either.
		sync.onItem(4151, 1, 2_000);
		assertEquals(0, sync.size());
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The site-relay (§10) sidebar path — the plugin's ONLY federation path — driven against an in-process
 * {@link HttpServer} mock of the home site (JDK built-in, offline). Proves §10: federation traffic is the
 * home site and nothing else. Covers /state render vs. fall back (off/absent), and /connect zero-click vs.
 * self-host login (browser-open seam injected) → polls /state to connected.
 */
public class FederationSidebarDataSourceTest
{
	private static final Gson GSON = new Gson();

	/** A stand-in single-home delegate that returns one recognizable row, so a fallback is provable. */
	private static final class MarkerDelegate implements SidebarDataSource
	{
		static final String ID = "SINGLE-HOME";
		int calls;

		@Override
		public List<ConnectionView> fetchConnections()
		{
			calls++;
			return Collections.singletonList(new ConnectionView(ID, "Home Clan", "Home Event", 1, 3,
				new ArrayList<>()));
		}
	}

	private static BingoApiClient apiClient(String baseUrl)
	{
		BingoApiClient c = new BingoApiClient(GSON, new OkHttpClient());
		c.configure(baseUrl, "tok_test");
		return c;
	}

	// ---- Auto path: render vs. fall back ---------------------------------------------------------

	@Test
	public void autoPathRendersClansFromState() throws Exception
	{
		MockSite site = new MockSite();
		site.stateBody = "{\"enabled\":true,\"connected\":true,\"clans\":[{"
			+ "\"id\":\"uuid-a\",\"name\":\"Clan A\",\"eventName\":\"Summer Bingo\","
			+ "\"board\":{\"tilesComplete\":7,\"tilesTotal\":25,\"nearest\":["
			+ "  {\"name\":\"Any barrows item\",\"current\":4,\"target\":5,\"complete\":false}]},"
			+ "\"activity\":[{\"id\":\"s1\",\"ts\":\"2026-07-14 10:00:00\",\"player\":\"Kayle\","
			+ "  \"tileId\":140,\"tileLabel\":\"Tanzanite fang\",\"kind\":\"complete\",\"self\":false}],"
			+ "\"active\":[{\"tileId\":102,\"label\":\"500 Zulrah KC\",\"current\":420,\"goal\":500,"
			+ "  \"workers\":[\"You\"],\"self\":true}]},{"
			+ "\"id\":\"uuid-b\",\"name\":\"Clan B\",\"board\":{\"tilesComplete\":3,\"tilesTotal\":9}}]}";
		site.start();
		try
		{
			MarkerDelegate delegate = new MarkerDelegate();
			FederationSidebarDataSource ds = source(apiClient(site.baseUrl()), delegate);

			List<ConnectionView> conns = ds.fetchConnections();
			assertEquals("home + both federated clans render", 3, conns.size());
			assertEquals("home renders FIRST", MarkerDelegate.ID, conns.get(0).instanceId);
			assertEquals("uuid-a", conns.get(1).instanceId);
			assertEquals("Clan A", conns.get(1).clanName);
			assertEquals(7, conns.get(1).tilesComplete);
			assertEquals(1, conns.get(1).nearestTiles.size());
			assertEquals(1, conns.get(1).recentActivity.size());
			assertEquals(1, conns.get(1).activeNow.size());
			assertEquals("uuid-b", conns.get(2).instanceId);

			assertEquals("delegate supplies the home render alongside the federated clans", 1, delegate.calls);
			assertTrue(ds.federationStatus().enabled);
			assertFalse(ds.federationStatus().needsConnect());
			assertEquals("only the home site was contacted",
				new ArrayList<>(Collections.singletonList("/api/plugin/federation/state")), site.distinctPaths());
		}
		finally
		{
			site.stop();
		}
	}

	@Test
	public void federationDisabledFallsBackToSingleHome() throws Exception
	{
		MockSite site = new MockSite();
		site.stateBody = "{\"enabled\":false,\"connected\":false,\"clans\":[]}";
		site.start();
		try
		{
			MarkerDelegate delegate = new MarkerDelegate();
			FederationSidebarDataSource ds = source(apiClient(site.baseUrl()), delegate);

			List<ConnectionView> conns = ds.fetchConnections();
			assertEquals(1, conns.size());
			assertEquals("federation off ⇒ single-home render (byte-identical default)", MarkerDelegate.ID, conns.get(0).instanceId);
			assertEquals(1, delegate.calls);
			assertFalse(ds.federationStatus().needsConnect());
		}
		finally
		{
			site.stop();
		}
	}

	@Test
	public void stateEndpointAbsentFallsBackToSingleHome() throws Exception
	{
		MockSite site = new MockSite();
		site.stateStatus = 404; // an older server with no such route
		site.start();
		try
		{
			MarkerDelegate delegate = new MarkerDelegate();
			FederationSidebarDataSource ds = source(apiClient(site.baseUrl()), delegate);

			List<ConnectionView> conns = ds.fetchConnections();
			assertEquals("404 /state ⇒ single-home render", MarkerDelegate.ID, conns.get(0).instanceId);
			assertFalse(ds.federationStatus().enabled);
		}
		finally
		{
			site.stop();
		}
	}

	@Test
	public void unconfiguredClientMakesNoCallAndRendersSingleHome() throws Exception
	{
		// True single-home default: no Site URL/token ⇒ NO /state request, renders straight from the delegate.
		MarkerDelegate delegate = new MarkerDelegate();
		BingoApiClient unconfigured = new BingoApiClient(GSON, new OkHttpClient());
		FederationSidebarDataSource ds = source(unconfigured, delegate);

		List<ConnectionView> conns = ds.fetchConnections();
		assertEquals(MarkerDelegate.ID, conns.get(0).instanceId);
		assertEquals(1, delegate.calls);
		assertFalse(ds.federationStatus().enabled);
	}

	// ---- /connect: zero-click and self-host login-then-poll --------------------------------------

	@Test
	public void connectZeroClickReturnsConnected() throws Exception
	{
		MockSite site = new MockSite();
		site.connectBody = "{\"status\":\"connected\"}";
		site.stateBody = "{\"enabled\":true,\"connected\":true,\"clans\":[]}";
		site.start();
		try
		{
			AtomicReference<String> opened = new AtomicReference<>();
			FederationSidebarDataSource ds = source(apiClient(site.baseUrl()),
				new MarkerDelegate(), url -> { opened.set(url); return true; }, (step, delayMs) -> step.run());

			List<String> statuses = new ArrayList<>();
			FederationStatusSource.ConnectOutcome outcome = connect(ds, statuses::add);

			assertEquals(FederationStatusSource.ConnectOutcome.CONNECTED, outcome);
			assertNull("trusted home = zero-click; no browser opened", opened.get());
			assertTrue(ds.federationStatus().connected);
